};

fn isValidElicitationContent(value: std.json.Value) bool {
    const object = switch (value) {
        .object => |object| object,
        else => return false,
    };
    var fields = object.iterator();
    while (fields.next()) |field| {
        switch (field.value_ptr.*) {
            .string, .integer, .float, .number_string, .bool => {},
            .array => |items| for (items.items) |item| {
                if (item != .string) return false;
            },
            else => return false,
        }
    }
    return true;
}

const EventDelivery = struct {
    id: u64 = 0,
    session_id: []u8,
    generation: u64 = 0,
    event: session_types.SessionEvent,
    diagnostic_frame: ?[]u8 = null,
    automatic_handling_in_progress: bool = false,
    remove_after_automatic_handling: bool = false,

    fn intoEvent(
        self: *EventDelivery,
        allocator: std.mem.Allocator,
    ) session_types.SessionEvent {
        allocator.free(self.session_id);
        if (self.diagnostic_frame) |frame| errors.freeRpcData(allocator, frame);
        const event = self.event;
        self.* = undefined;
        return event;
    }

    fn intoFailure(
        self: *EventDelivery,
        allocator: std.mem.Allocator,
    ) errors.DetailedError!errors.Failure {
        const frame = self.diagnostic_frame.?;
        self.diagnostic_frame = null;
        var event = self.event;
        self.event = undefined;
        defer event.deinit(allocator);
        const session_id = self.session_id;
        self.* = undefined;
        defer errors.freeRpcData(allocator, frame);
        return sessionFailureFromFrame(allocator, session_id, frame);
    }

    fn deinit(self: *EventDelivery, allocator: std.mem.Allocator) void {
        allocator.free(self.session_id);
        if (self.diagnostic_frame) |frame| errors.freeRpcData(allocator, frame);
        self.event.deinit(allocator);
        self.* = undefined;
    }
};

const PendingFailureDetail = union(enum) {
    none,
    unavailable,
    failure: errors.Failure,

    fn deinit(self: *PendingFailureDetail) void {
        switch (self.*) {
            .failure => |*failure| failure.deinit(),
            .none, .unavailable => {},
        }
        self.* = .none;
    }
};

const PendingCall = struct {
