        if (self.detail) |detail| allocator.free(detail);
    }
};

const OwnedFactory = struct {
    name: []u8,
    description: []u8,
    phases: []OwnedFactoryPhase,
    args_schema: ?[]u8,
    limits: ?factory_types.FactoryDeclaredLimits,
    run: *const fn (
        std.mem.Allocator,
        *factory_types.FactoryContext,
        ?*anyopaque,
    ) anyerror!?factory_types.Json,
    context: ?*anyopaque,

    fn init(allocator: std.mem.Allocator, definition: factory_types.AgentFactory) !OwnedFactory {
        const phases = try allocator.alloc(OwnedFactoryPhase, definition.meta.phases.len);
        var initialized: usize = 0;
        errdefer {
            for (phases[0..initialized]) |*phase| phase.deinit(allocator);
            allocator.free(phases);
        }
        for (definition.meta.phases, 0..) |phase, index| {
            const title = try allocator.dupe(u8, phase.title);
            errdefer allocator.free(title);
            phases[index] = .{
                .title = title,
                .detail = if (phase.detail) |detail| try allocator.dupe(u8, detail) else null,
            };
            initialized += 1;
        }
        const name = try allocator.dupe(u8, definition.meta.name);
        errdefer allocator.free(name);
        const description = try allocator.dupe(u8, definition.meta.description);
        errdefer allocator.free(description);
        const args_schema = if (definition.meta.args_schema) |schema|
            try allocator.dupe(u8, schema.bytes)
        else
            null;
        return .{
            .name = name,
            .description = description,
            .phases = phases,
            .args_schema = args_schema,
            .limits = definition.meta.limits,
            .run = definition.run,
            .context = definition.context,
        };
    }

    fn deinit(self: *OwnedFactory, allocator: std.mem.Allocator) void {
        allocator.free(self.name);
        allocator.free(self.description);
        for (self.phases) |*phase| phase.deinit(allocator);
        allocator.free(self.phases);
        if (self.args_schema) |schema| allocator.free(schema);
    }
};

const RuntimeTool = struct {
    name: []u8,
    handler: session_types.ToolHandler,
    context: ?*anyopaque,
};

const ToolHandlerSnapshot = struct {
    handler: session_types.ToolHandler,
    context: ?*anyopaque,
};

const RuntimeCommand = struct {
    name: []u8,
    handler: session_types.CommandHandler,
    context: ?*anyopaque,
};

const WireMcpOAuthInterest = struct {
    handle: []const u8,
};

const OwnedMcpOAuthInterest = struct {
    response: std.json.Parsed(WireMcpOAuthInterest),

    fn handle(self: *const OwnedMcpOAuthInterest) []const u8 {
        return self.response.value.handle;
    }

    fn deinitSecure(self: *OwnedMcpOAuthInterest) void {
        wipeSecret(self.response.value.handle);
        self.response.deinit();
        self.* = undefined;
    }
};

const McpOAuthInterest = union(enum) {
    none,
    registering: enum {
        initial,
        restore,
    },
    registered: OwnedMcpOAuthInterest,
    releasing: OwnedMcpOAuthInterest,
    restore_required,
};

const McpOAuthRuntimeLocation = union(enum) {
    pending,
    committed,
    external: *SessionExtensionRuntime,
};

fn testMcpOAuthInterest(
    allocator: std.mem.Allocator,
    handle: []const u8,
) !McpOAuthInterest {
    const json = try std.fmt.allocPrint(allocator, "{{\"handle\":\"{s}\"}}", .{handle});
    defer allocator.free(json);
    return .{ .registered = .{
        .response = try std.json.parseFromSlice(
            WireMcpOAuthInterest,
            allocator,
            json,
            .{ .allocate = .alloc_always },
        ),
    } };
}

const SessionExtensionRuntime = struct {
    session_id: ?[]u8 = null,
    hooks: ext.SessionHooks,
    mcp_auth_handler: ?ext.McpAuthHandler,
    mcp_auth_context: ?*anyopaque,
    canvases: []OwnedCanvas,
    factories: []OwnedFactory,
    open_canvases: std.ArrayList(ext.OpenCanvas) = .empty,
    capabilities: ext.CapabilitySet = .{},
    mcp_apps_requested: bool,
    event_queue_failure: ?EventQueueFailure = null,
    tools: []RuntimeTool,
    commands: []RuntimeCommand,
    permission_handler: ?session_types.PermissionHandler,
    permission_context: ?*anyopaque,
    managed_settings_enabled: bool,
    user_input_handler: ?session_types.UserInputHandler,
    user_input_context: ?*anyopaque,
    elicitation_handler: ?session_types.ElicitationHandler,
    elicitation_context: ?*anyopaque,
    exit_plan_mode_handler: ?session_types.ExitPlanModeHandler,
    exit_plan_mode_context: ?*anyopaque,
    auto_mode_switch_handler: ?session_types.AutoModeSwitchHandler,
    auto_mode_switch_context: ?*anyopaque,
    git_hub_token_provider: ?session_types.GitHubTokenProvider,
    git_hub_token_registration_id: ?[]u8 = null,
    provider_tokens: ?[]RegisteredProviderToken = null,
    credentials_quarantined: bool = false,
    granted_environment_variables: std.ArrayList(ext.EnvironmentGrant) = .empty,
    mcp_oauth_interest: McpOAuthInterest = .none,

    fn init(
        allocator: std.mem.Allocator,
        session_id: ?[]const u8,
        config: anytype,
        initial_open_canvases: []const ext.OpenCanvas,
    ) !SessionExtensionRuntime {
        return initWithFactories(allocator, session_id, config, initial_open_canvases, &.{});
    }

    fn initWithFactories(
        allocator: std.mem.Allocator,
        session_id: ?[]const u8,
        config: anytype,
        initial_open_canvases: []const ext.OpenCanvas,
        factory_definitions: []const factory_types.AgentFactory,
    ) !SessionExtensionRuntime {
        const features = config.extensions.common;
        var tool_count: usize = 0;
        for (config.tools) |tool| if (tool.handler != null) {
            tool_count += 1;
        };
        const tools = try allocator.alloc(RuntimeTool, tool_count);
        const commands = allocator.alloc(RuntimeCommand, config.commands.len) catch |err| {
            allocator.free(tools);
            return err;
        };
        const canvases = allocator.alloc(OwnedCanvas, features.canvases.len) catch |err| {
            allocator.free(commands);
            allocator.free(tools);
            return err;
        };
        const factories = allocator.alloc(OwnedFactory, factory_definitions.len) catch |err| {
            allocator.free(canvases);
            allocator.free(commands);
            allocator.free(tools);
            return err;
        };
        var result = SessionExtensionRuntime{
            .hooks = features.hooks,
            .mcp_auth_handler = features.mcp.on_auth_request,
            .mcp_auth_context = features.mcp.auth_context,
            .canvases = canvases,
            .factories = factories,
            .mcp_apps_requested = features.experimental.mcp_apps,
            .tools = tools,
            .commands = commands,
            .permission_handler = config.on_permission_request,
            .permission_context = config.permission_context,
            .managed_settings_enabled = managedSettingsEnabled(config),
            .user_input_handler = config.on_user_input_request,
            .user_input_context = config.user_input_context,
            .elicitation_handler = config.on_elicitation_request,
            .elicitation_context = config.elicitation_context,
            .exit_plan_mode_handler = config.on_exit_plan_mode_request,
            .exit_plan_mode_context = config.exit_plan_mode_context,
            .auto_mode_switch_handler = config.on_auto_mode_switch_request,
            .auto_mode_switch_context = config.auto_mode_switch_context,
            .git_hub_token_provider = config.git_hub_token_provider,
        };
        var initialized_tools: usize = 0;
        var initialized_commands: usize = 0;
        var initialized_canvases: usize = 0;
        var initialized_factories: usize = 0;
        errdefer {
            for (result.factories[0..initialized_factories]) |*owned| owned.deinit(allocator);
            allocator.free(result.factories);
            for (result.canvases[0..initialized_canvases]) |*canvas| canvas.deinit(allocator);
            allocator.free(result.canvases);
            for (result.tools[0..initialized_tools]) |tool| allocator.free(tool.name);
            allocator.free(result.tools);
            for (result.commands[0..initialized_commands]) |command| allocator.free(command.name);
            allocator.free(result.commands);
            if (result.session_id) |id| allocator.free(id);
            for (result.open_canvases.items) |canvas| ext.freeOpenCanvas(allocator, canvas);
            result.open_canvases.deinit(allocator);
        }
        for (factory_definitions, 0..) |definition, index| {
            result.factories[index] = try OwnedFactory.init(allocator, definition);
            initialized_factories += 1;
        }
        if (session_id) |id| result.session_id = try allocator.dupe(u8, id);
        for (config.tools) |tool| {
            const handler = tool.handler orelse continue;
            result.tools[initialized_tools] = .{
                .name = try allocator.dupe(u8, tool.name),
                .handler = handler,
                .context = tool.context,
            };
            initialized_tools += 1;
        }
        for (config.commands, 0..) |command, index| {
            result.commands[index] = .{
                .name = try allocator.dupe(u8, command.name),
                .handler = command.handler,
                .context = command.context,
            };
            initialized_commands += 1;
        }
        for (features.canvases, 0..) |canvas, index| {
            const actions = try allocator.alloc(OwnedCanvasAction, canvas.actions.len);
            var initialized_actions: usize = 0;
            errdefer {
                for (actions[0..initialized_actions]) |action| allocator.free(action.name);
                allocator.free(actions);
            }
            for (canvas.actions, 0..) |action, action_index| {
                actions[action_index] = .{
                    .name = try allocator.dupe(u8, action.name),
                    .handler = action.handler,
                };
                initialized_actions += 1;
            }
            result.canvases[index] = .{
                .id = try allocator.dupe(u8, canvas.declaration.id),
                .on_open = canvas.on_open,
                .on_close = canvas.on_close,
                .actions = actions,
                .context = canvas.context,
            };
            initialized_canvases += 1;
        }
        for (initial_open_canvases) |canvas| {
            const clone = try cloneOpenCanvas(allocator, canvas);
            errdefer ext.freeOpenCanvas(allocator, clone);
            try result.open_canvases.append(allocator, clone);
        }
        return result;
    }

    fn deinit(self: *SessionExtensionRuntime, allocator: std.mem.Allocator) void {
        if (self.session_id) |id| allocator.free(id);
        for (self.canvases) |*canvas| canvas.deinit(allocator);
        allocator.free(self.canvases);
        for (self.factories) |*owned| owned.deinit(allocator);
        allocator.free(self.factories);
        for (self.tools) |tool| allocator.free(tool.name);
        allocator.free(self.tools);
        for (self.commands) |command| allocator.free(command.name);
        allocator.free(self.commands);
        if (self.provider_tokens) |provider_tokens| {
            for (provider_tokens) |registered| registered.deinit(allocator);
            allocator.free(provider_tokens);
        }
        if (self.git_hub_token_registration_id) |registration_id| allocator.free(registration_id);
        for (self.open_canvases.items) |canvas| ext.freeOpenCanvas(allocator, canvas);
        self.open_canvases.deinit(allocator);
        for (self.granted_environment_variables.items) |grant| {
            allocator.free(grant.name);
            wipeSecret(grant.value);
            allocator.free(grant.value);
        }
        self.granted_environment_variables.deinit(allocator);
        switch (self.mcp_oauth_interest) {
            .registered, .releasing => |*interest| interest.deinitSecure(),
            .none, .registering, .restore_required => {},
        }
    }

    fn quarantineCredentials(self: *SessionExtensionRuntime, allocator: std.mem.Allocator) void {
        if (self.provider_tokens) |provider_tokens| {
            for (provider_tokens) |registered| registered.deinit(allocator);
            allocator.free(provider_tokens);
            self.provider_tokens = null;
        }
        if (self.git_hub_token_registration_id) |registration_id| {
            allocator.free(registration_id);
            self.git_hub_token_registration_id = null;
        }
        self.git_hub_token_provider = null;
        self.mcp_auth_handler = null;
        self.mcp_auth_context = null;
        self.credentials_quarantined = true;
    }
};

const RegisteredProviderToken = struct {
    provider_name: []u8,
    token_provider: provider.BearerTokenProvider,

    fn deinit(self: RegisteredProviderToken, allocator: std.mem.Allocator) void {
        allocator.free(self.provider_name);
    }
};

const RegisteredProviderTokens = struct {
    session_id: []const u8,
    providers: []RegisteredProviderToken,

    fn deinit(self: RegisteredProviderTokens, allocator: std.mem.Allocator) void {
        for (self.providers) |registered| registered.deinit(allocator);
        allocator.free(self.providers);
    }
};

pub const RpcHandler = *const fn (
    allocator: std.mem.Allocator,
    params_json: ?[]const u8,
    context: ?*anyopaque,
) anyerror![]u8;

const WireModelsListRequest = struct {
    selectionId: ?[]const u8 = null,
    gitHubToken: ?[]const u8 = null,
};

const WireSendRequest = struct {
    sessionId: []const u8,
    prompt: []const u8,
    source: ?[]const u8 = null,
    attachments: ?WireAttachments = null,
    mode: ?session_types.MessageDeliveryMode = null,
    agentMode: ?session_types.AgentMode = null,
    requestHeaders: ?WireRequestHeaders = null,
    displayPrompt: ?[]const u8 = null,
    traceparent: ?[]const u8 = null,
    tracestate: ?[]const u8 = null,
};

const WireAttachments = union(enum) {
    legacy: []const session_types.Attachment,
    stable: []const session_types.MessageAttachment,

    pub fn jsonStringify(self: WireAttachments, writer: anytype) !void {
        try writer.beginArray();
        switch (self) {
            .legacy => |values| for (values) |value|
                try writer.write(WireLegacyAttachment{ .value = value }),
            .stable => |values| for (values) |value|
                try writer.write(WireMessageAttachment{ .value = value }),
        }
        try writer.endArray();
    }
};

const WireMessageAttachment = struct {
    value: session_types.MessageAttachment,

    pub fn jsonStringify(self: WireMessageAttachment, writer: anytype) !void {
        switch (self.value) {
            .file => |value| try writer.write(.{
                .type = "file",
                .path = value.path,
                .displayName = value.display_name,
            }),
            .directory => |value| try writer.write(.{
                .type = "directory",
                .path = value.path,
                .displayName = value.display_name,
            }),
            .selection => |value| try writer.write(.{
                .type = "selection",
                .filePath = value.file_path,
                .displayName = value.display_name,
                .selection = value.selection,
                .text = value.text,
            }),
            .blob => |value| try writer.write(.{
                .type = "blob",
                .data = value.data,
                .mimeType = value.mime_type,
                .displayName = value.display_name,
            }),
        }
    }
};

const WireLegacyAttachment = struct {
    value: session_types.Attachment,

    pub fn jsonStringify(self: WireLegacyAttachment, writer: anytype) !void {
        switch (self.value) {
            .file => |value| try writer.write(.{
                .type = "file",
                .path = value.path,
                .displayName = attachmentDisplayName(value.display_name, value.path),
                .lineRange = value.line_range,
            }),
            .directory => |value| try writer.write(.{
                .type = "directory",
                .path = value.path,
                .displayName = attachmentDisplayName(value.display_name, value.path),
            }),
            .selection => |value| try writer.write(.{
                .type = "selection",
                .filePath = value.file_path,
                .text = value.text,
                .displayName = attachmentDisplayName(value.display_name, value.file_path),
                .selection = value.selection,
            }),
            .blob => |value| try writer.write(.{
                .type = "blob",
                .data = value.data,
                .mimeType = value.mime_type,
                .displayName = nonEmptyDisplayName(value.display_name) orelse "attachment",
            }),
            .github_reference => |value| try writer.write(.{
                .type = "github_reference",
                .number = value.number,
                .title = value.title,
                .referenceType = value.reference_type,
                .state = value.state,
                .url = value.url,
            }),
            .github_commit => |value| try writer.write(.{
                .type = "github_commit",
                .message = value.message,
                .oid = value.oid,
                .repo = wireRepo(value.repo),
                .url = value.url,
            }),
            .github_release => |value| try writer.write(.{
                .type = "github_release",
                .name = value.name,
                .repo = wireRepo(value.repo),
                .tagName = value.tag_name,
                .url = value.url,
            }),
            .github_actions_job => |value| try writer.write(.{
                .type = "github_actions_job",
                .conclusion = value.conclusion,
                .jobId = value.job_id,
                .jobName = value.job_name,
                .repo = wireRepo(value.repo),
                .url = value.url,
                .workflowName = value.workflow_name,
            }),
            .github_repository => |value| try writer.write(.{
                .type = "github_repository",
                .description = value.description,
                .ref = value.git_ref,
                .repo = wireRepo(value.repo),
                .url = value.url,
            }),
            .github_file_diff => |value| switch (value.sides) {
                .added => |head| try writer.write(.{
                    .type = "github_file_diff",
                    .head = wireFileDiffSide(head),
                    .url = value.url,
                }),
                .deleted => |base| try writer.write(.{
                    .type = "github_file_diff",
                    .base = wireFileDiffSide(base),
                    .url = value.url,
                }),
                .modified => |sides| try writer.write(.{
                    .type = "github_file_diff",
                    .base = wireFileDiffSide(sides.base),
                    .head = wireFileDiffSide(sides.head),
                    .url = value.url,
                }),
            },
            .github_tree_comparison => |value| try writer.write(.{
                .type = "github_tree_comparison",
                .base = wireTreeComparisonSide(value.base),
                .head = wireTreeComparisonSide(value.head),
                .url = value.url,
            }),
            .github_url => |value| try writer.write(.{
                .type = "github_url",
                .url = value.url,
            }),
            .github_file => |value| try writer.write(.{
                .type = "github_file",
                .path = value.path,
                .ref = value.git_ref,
                .repo = wireRepo(value.repo),
                .url = value.url,
            }),
            .github_snippet => |value| try writer.write(.{
                .type = "github_snippet",
                .lineRange = value.line_range,
                .path = value.path,
                .ref = value.git_ref,
                .repo = wireRepo(value.repo),
                .url = value.url,
            }),
        }
    }
};

fn nonEmptyDisplayName(display_name: ?[]const u8) ?[]const u8 {
    const value = display_name orelse return null;
    return if (std.mem.trim(u8, value, " \t\r\n").len == 0) null else value;
}

fn attachmentDisplayName(display_name: ?[]const u8, path: []const u8) []const u8 {
    if (nonEmptyDisplayName(display_name)) |value| return value;
    const base_name = std.fs.path.basename(path);
    if (base_name.len != 0) return base_name;
    return if (path.len != 0) path else "attachment";
}

const WireGitHubRepoPointer = struct {
    id: ?i64 = null,
    name: []const u8,
    owner: []const u8,
};

const WireGitHubFileDiffSide = struct {
    path: []const u8,
    ref: []const u8,
    repo: WireGitHubRepoPointer,
};

const WireGitHubTreeComparisonSide = struct {
    repo: WireGitHubRepoPointer,
    revision: []const u8,
};

fn wireRepo(value: session_types.Attachment.GitHubRepoPointer) WireGitHubRepoPointer {
    return .{
        .id = value.id,
        .name = value.name,
        .owner = value.owner,
    };
}

fn wireFileDiffSide(
    value: session_types.Attachment.GitHubFileDiffSide,
) WireGitHubFileDiffSide {
    return .{
        .path = value.path,
        .ref = value.git_ref,
        .repo = wireRepo(value.repo),
    };
}

fn wireTreeComparisonSide(
    value: session_types.Attachment.GitHubTreeComparisonSide,
) WireGitHubTreeComparisonSide {
    return .{
        .repo = wireRepo(value.repo),
        .revision = value.revision,
    };
}

const WireRequestHeaders = struct {
    values: []const session_types.RequestHeader,

    pub fn jsonStringify(self: WireRequestHeaders, writer: anytype) !void {
        try writer.beginObject();
        for (self.values) |header| {
            try writer.objectField(header.name);
            try writer.write(header.value);
        }
        try writer.endObject();
    }
};

fn lowerMessage(
    session_id: []const u8,
    options: session_types.MessageOptions,
    attachments: ?WireAttachments,
    source: ?[]const u8,
    trace_context: runtime_types.TraceContext,
) WireSendRequest {
    return .{
        .sessionId = session_id,
        .prompt = options.prompt,
        .source = source,
        .attachments = attachments,
        .mode = options.mode,
        .agentMode = options.agent_mode,
        .requestHeaders = if (options.request_headers) |values|
            .{ .values = values }
        else
            null,
        .displayPrompt = options.display_prompt,
        .traceparent = trace_context.traceparent,
        .tracestate = trace_context.tracestate,
    };
}

fn validateMessageOptions(
    options: session_types.MessageOptions,
) !?WireAttachments {
    const selected = try selectedAttachments(options);
    if (options.source) |source| switch (source) {
        .agent => |name| if (name.len == 0) return error.InvalidMessageSource,
        else => {},
    };
    if (options.message_attachments) |attachments| {
        for (attachments) |attachment| switch (attachment) {
            .file => |file| if (file.display_name == null)
                return error.MissingAttachmentDisplayName,
            .directory => |directory| if (directory.display_name == null)
                return error.MissingAttachmentDisplayName,
            .selection => |selection| if (selection.selection == null or
                selection.text == null)
            {
                return error.IncompleteSelectionAttachment;
            },
            .blob => {},
        };
    }
    if (options.request_headers) |headers| {
        for (headers, 0..) |header, index| {
            if (!isValidHeaderName(header.name)) return error.InvalidRequestHeaderName;
            for (headers[0..index]) |previous| {
                if (std.ascii.eqlIgnoreCase(previous.name, header.name))
                    return error.DuplicateRequestHeader;
            }
        }
    }
    return selected;
}

fn messageValidationField(
    options: session_types.MessageOptions,
    err: anyerror,
    buffer: []u8,
) []const u8 {
    if (err == error.ConflictingAttachmentInputs) return "attachments";
    if (options.message_attachments) |attachments| {
        for (attachments, 0..) |attachment, index| switch (attachment) {
            .file => |file| if (file.display_name == null and
                err == error.MissingAttachmentDisplayName)
            {
                return std.fmt.bufPrint(
                    buffer,
                    "message_attachments[{d}].file.display_name",
                    .{index},
                ) catch "message_attachments";
            },
            .directory => |directory| if (directory.display_name == null and
                err == error.MissingAttachmentDisplayName)
            {
                return std.fmt.bufPrint(
                    buffer,
                    "message_attachments[{d}].directory.display_name",
                    .{index},
                ) catch "message_attachments";
            },
            .selection => |selection| if ((selection.selection == null or
                selection.text == null) and
                err == error.IncompleteSelectionAttachment)
            {
                return std.fmt.bufPrint(
                    buffer,
                    "message_attachments[{d}].selection",
                    .{index},
                ) catch "message_attachments";
            },
            .blob => {},
        };
    }
    return "message";
}

fn selectedAttachments(
    options: session_types.MessageOptions,
) !?WireAttachments {
    if (options.attachments != null and options.message_attachments != null)
        return error.ConflictingAttachmentInputs;
    if (options.attachments) |values| return .{ .legacy = values };
    if (options.message_attachments) |values| return .{ .stable = values };
    return null;
}

fn isValidHeaderName(name: []const u8) bool {
    if (name.len == 0) return false;
    for (name) |byte| {
        if (std.ascii.isAlphanumeric(byte)) continue;
        switch (byte) {
            '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~' => {},
            else => return false,
        }
    }
    return true;
}

const RegisteredRpcHandler = struct {
    method: []u8,
    handler: RpcHandler,
    context: ?*anyopaque,

    fn deinit(self: RegisteredRpcHandler, allocator: std.mem.Allocator) void {
        allocator.free(self.method);
    }
};

const FileTransport = struct {
    reader: std.Io.File.Reader,
    writer: std.Io.File.Writer,
    reader_buffer: []u8,
    writer_buffer: []u8,
};

const SocketTransport = struct {
    stream: std.Io.net.Stream,
    reader: std.Io.net.Stream.Reader,
    writer: std.Io.net.Stream.Writer,
    reader_buffer: []u8,
    writer_buffer: []u8,
};

const Transport = union(enum) {
    none,
    stdio_child: struct {
        child: std.process.Child,
        io: FileTransport,
    },
    tcp_child: struct {
        child: std.process.Child,
        io: SocketTransport,
        port: u16,
    },
    uri: struct {
        io: SocketTransport,
        port: u16,
    },
    parent_stdio: FileTransport,
    fixture: struct {
        reader: ?*std.Io.File.Reader,
        writer: ?*std.Io.File.Writer,
        reader_buffer: []u8,
        writer_buffer: []u8,
        owns_allocations: bool = false,
        eof_is_idle: bool = false,
    },

    fn reader(self: *Transport) *std.Io.Reader {
        return switch (self.*) {
            .none => unreachable,
            .stdio_child => |*value| &value.io.reader.interface,
            .tcp_child => |*value| &value.io.reader.interface,
            .uri => |*value| &value.io.reader.interface,
            .parent_stdio => |*value| &value.reader.interface,
            .fixture => |value| &value.reader.?.interface,
        };
    }

    fn writer(self: *Transport) *std.Io.Writer {
        return switch (self.*) {
            .none => unreachable,
            .stdio_child => |*value| &value.io.writer.interface,
            .tcp_child => |*value| &value.io.writer.interface,
            .uri => |*value| &value.io.writer.interface,
            .parent_stdio => |*value| &value.writer.interface,
            .fixture => |value| &value.writer.?.interface,
        };
    }

    fn writerBuffer(self: *Transport) []u8 {
        return switch (self.*) {
            .none => &.{},
            .stdio_child => |*value| value.io.writer_buffer,
            .tcp_child => |*value| value.io.writer_buffer,
            .uri => |*value| value.io.writer_buffer,
            .parent_stdio => |*value| value.writer_buffer,
            .fixture => |value| value.writer_buffer,
        };
    }

    fn eofIsIdle(self: *const Transport) bool {
        return switch (self.*) {
            .fixture => |value| value.eof_is_idle,
            else => false,
        };
    }

    fn port(self: *const Transport) ?u16 {
        return switch (self.*) {
            .tcp_child => |value| value.port,
            .uri => |value| value.port,
            .none, .stdio_child, .parent_stdio, .fixture => null,
        };
    }

    fn ownsRuntime(self: *const Transport) bool {
        return switch (self.*) {
            .stdio_child, .tcp_child => true,
            .none, .uri, .parent_stdio, .fixture => false,
        };
    }

    fn close(self: *Transport, allocator: std.mem.Allocator, io: std.Io) void {
        switch (self.*) {
            .none => {},
            .stdio_child => |*value| {
                if (value.child.stdin) |file| file.close(io);
                value.child.stdin = null;
                if (value.child.stdout) |file| file.close(io);
                value.child.stdout = null;
                wipeSecret(value.io.reader_buffer);
                wipeSecret(value.io.writer_buffer);
                allocator.free(value.io.reader_buffer);
                allocator.free(value.io.writer_buffer);
            },
            .tcp_child => |*value| {
                value.io.stream.close(io);
                wipeSecret(value.io.reader_buffer);
                wipeSecret(value.io.writer_buffer);
                allocator.free(value.io.reader_buffer);
                allocator.free(value.io.writer_buffer);
            },
            .uri => |*value| {
                value.io.stream.close(io);
                wipeSecret(value.io.reader_buffer);
                wipeSecret(value.io.writer_buffer);
                allocator.free(value.io.reader_buffer);
                allocator.free(value.io.writer_buffer);
            },
            .parent_stdio => |*value| {
                wipeSecret(value.reader_buffer);
                wipeSecret(value.writer_buffer);
                allocator.free(value.reader_buffer);
                allocator.free(value.writer_buffer);
            },
            .fixture => |value| {
                wipeSecret(value.reader_buffer);
                wipeSecret(value.writer_buffer);
                if (value.owns_allocations) {
                    if (value.reader) |fixture_reader| allocator.destroy(fixture_reader);
                    if (value.writer) |fixture_writer| allocator.destroy(fixture_writer);
                    if (value.reader_buffer.len != 0) allocator.free(value.reader_buffer);
                    if (value.writer_buffer.len != 0) allocator.free(value.writer_buffer);
                }
            },
        }
    }

    fn terminateAndReap(self: *Transport, io: std.Io) void {
        switch (self.*) {
            .stdio_child => |*value| value.child.kill(io),
            .tcp_child => |*value| value.child.kill(io),
            .none, .uri, .parent_stdio, .fixture => {},
        }
        self.* = .none;
    }
};

const ResolvedConnection = union(enum) {
    stdio: struct {
        child: ResolvedChild,
        token: ?[]const u8,
    },
    tcp: struct {
        child: ResolvedChild,
        port: u16,
        token: ?[]const u8,
    },
    uri: struct {
        host: []const u8,
        port: u16,
        token: ?[]const u8,
    },
};

const ResolvedChild = struct {
    executable: []const u8 = "copilot",
    args: []const []const u8 = &.{},
    working_directory: ?[]const u8 = null,
    mode: runtime_types.RuntimeMode = .copilot_cli,
    base_directory: ?[]const u8 = null,
    log_level: ?runtime_types.ClientLogLevel = null,
    environment: ?[]const runtime_types.EnvironmentVariable = null,
    github_token: ?[]const u8 = null,
    use_logged_in_user: bool = true,
    telemetry: ?runtime_types.TelemetryConfig = null,
    session_idle_timeout_seconds: u32 = 0,
    enable_remote_sessions: bool = false,
};

const DefaultConnection = enum {
    stdio,
    inprocess,
};

const ParsedUri = struct {
    host: []const u8,
    port: u16,
};

const managed_environment_keys = [_][]const u8{
    "COPILOT_SDK_AUTH_TOKEN",
    "COPILOT_CONNECTION_TOKEN",
    "COPILOT_HOME",
    "COPILOT_DISABLE_KEYTAR",
    "COPILOT_OTEL_ENABLED",
    "OTEL_EXPORTER_OTLP_ENDPOINT",
    "OTEL_EXPORTER_OTLP_PROTOCOL",
    "COPILOT_OTEL_FILE_EXPORTER_PATH",
    "COPILOT_OTEL_EXPORTER_TYPE",
    "COPILOT_OTEL_SOURCE_NAME",
    "OTEL_INSTRUMENTATION_GENAI_CAPTURE_MESSAGE_CONTENT",
};

const RegisteredSessionFilesystem = struct {
    session_id: []u8,
    provider: runtime_types.SessionFilesystemProvider,

    fn deinit(self: *RegisteredSessionFilesystem, allocator: std.mem.Allocator) void {
        if (self.provider.deinit) |deinit_provider| {
            deinit_provider(self.provider.context);
        }
        allocator.free(self.session_id);
    }
};

const SessionFilesystemRegistry = struct {
    pending: std.ArrayList(RegisteredSessionFilesystem) = .empty,
    committed: std.ArrayList(RegisteredSessionFilesystem) = .empty,

    fn begin(
        self: *SessionFilesystemRegistry,
        allocator: std.mem.Allocator,
        session_id: []const u8,
        factory: runtime_types.SessionFilesystemProviderFactory,
        require_sqlite: bool,
    ) !void {
        if (self.pendingIndex(session_id) != null)
            return error.SessionLifecycleAlreadyInProgress;
        try self.pending.ensureUnusedCapacity(allocator, 1);
        if (self.committedIndex(session_id) == null)
            try self.committed.ensureUnusedCapacity(allocator, 1);
        const owned_session_id = try allocator.dupe(u8, session_id);
        errdefer allocator.free(owned_session_id);
        const filesystem_provider = try factory.handler(
            allocator,
            session_id,
            factory.context,
        );
        if (require_sqlite and filesystem_provider.sqlite == null) {
            if (filesystem_provider.deinit) |deinit_provider|
                deinit_provider(filesystem_provider.context);
            return error.MissingSessionFilesystemSqliteProvider;
        }
        self.pending.appendAssumeCapacity(.{
            .session_id = owned_session_id,
            .provider = filesystem_provider,
        });
    }

    fn resolve(
        self: *SessionFilesystemRegistry,
        session_id: []const u8,
    ) ?runtime_types.SessionFilesystemProvider {
        if (self.pendingIndex(session_id)) |index|
            return self.pending.items[index].provider;
        if (self.committedIndex(session_id)) |index|
            return self.committed.items[index].provider;
        return null;
    }

    fn rollback(
        self: *SessionFilesystemRegistry,
        allocator: std.mem.Allocator,
        session_id: []const u8,
    ) void {
        const index = self.pendingIndex(session_id) orelse return;
        var removed = self.pending.orderedRemove(index);
        removed.deinit(allocator);
    }

    fn commitReplacement(
        self: *SessionFilesystemRegistry,
        allocator: std.mem.Allocator,
        session_id: []const u8,
    ) void {
        const pending_index = self.pendingIndex(session_id) orelse return;
        const replacement = self.pending.orderedRemove(pending_index);
        if (self.committedIndex(session_id)) |committed_index| {
            var displaced = self.committed.items[committed_index];
            self.committed.items[committed_index] = replacement;
            displaced.deinit(allocator);
            return;
        }
        self.committed.appendAssumeCapacity(replacement);
    }

    fn remove(
        self: *SessionFilesystemRegistry,
        allocator: std.mem.Allocator,
        session_id: []const u8,
    ) void {
        self.rollback(allocator, session_id);
        const index = self.committedIndex(session_id) orelse return;
        var removed = self.committed.orderedRemove(index);
        removed.deinit(allocator);
    }

    fn deinit(self: *SessionFilesystemRegistry, allocator: std.mem.Allocator) void {
        for (self.pending.items) |*entry| entry.deinit(allocator);
        self.pending.deinit(allocator);
        for (self.committed.items) |*entry| entry.deinit(allocator);
        self.committed.deinit(allocator);
        self.* = .{};
    }

    fn pendingIndex(self: *const SessionFilesystemRegistry, session_id: []const u8) ?usize {
        for (self.pending.items, 0..) |entry, index|
            if (std.mem.eql(u8, entry.session_id, session_id)) return index;
        return null;
    }

    fn committedIndex(self: *const SessionFilesystemRegistry, session_id: []const u8) ?usize {
        for (self.committed.items, 0..) |entry, index|
            if (std.mem.eql(u8, entry.session_id, session_id)) return index;
        return null;
    }
};

fn parseDefaultConnection(value: ?[]const u8) !DefaultConnection {
    const configured = value orelse return .stdio;
    if (std.ascii.eqlIgnoreCase(configured, "stdio")) return .stdio;
    if (std.ascii.eqlIgnoreCase(configured, "inprocess")) return .inprocess;
    return error.InvalidDefaultConnection;
}

fn resolveConnection(
    options: ClientOptions,
    default_connection: DefaultConnection,
) !ResolvedConnection {
    const effective_login = options.use_logged_in_user orelse
        (options.github_token == null);
    if (options.connection) |connection| {
        return switch (connection) {
            .stdio => |value| .{ .stdio = .{
                .child = resolvedChild(options, value.path, value.args, value.env, effective_login),
                .token = null,
            } },
            .tcp => |value| .{ .tcp = .{
                .child = resolvedChild(options, value.path, value.args, value.env, effective_login),
                .port = value.port,
                .token = value.token,
            } },
            .uri => |value| blk: {
                const parsed = try parseRuntimeUri(value.url);
                break :blk .{ .uri = .{
                    .host = parsed.host,
                    .port = parsed.port,
                    .token = value.token,
                } };
            },
        };
    }
    if (default_connection == .inprocess)
        return error.UnsupportedInProcessConnection;
    return .{ .stdio = .{
        .child = .{
            .executable = options.cli_path,
            .args = options.cli_args,
            .working_directory = options.working_directory,
            .mode = options.mode,
            .base_directory = options.base_directory,
            .log_level = options.log_level,
            .environment = options.env,
            .github_token = options.github_token,
            .use_logged_in_user = effective_login,
            .telemetry = options.telemetry,
            .session_idle_timeout_seconds = options.session_idle_timeout_seconds,
            .enable_remote_sessions = options.enable_remote_sessions,
        },
        .token = options.connection_token,
    } };
}

fn resolvedChild(
    options: ClientOptions,
    path: []const u8,
    args: []const []const u8,
    connection_env: ?[]const runtime_types.EnvironmentVariable,
    effective_login: bool,
) ResolvedChild {
    return .{
        .executable = path,
        .args = args,
        .working_directory = options.working_directory,
        .mode = options.mode,
        .base_directory = options.base_directory,
        .log_level = options.log_level,
        .environment = connection_env orelse options.env,
        .github_token = options.github_token,
        .use_logged_in_user = effective_login,
        .telemetry = options.telemetry,
        .session_idle_timeout_seconds = options.session_idle_timeout_seconds,
        .enable_remote_sessions = options.enable_remote_sessions,
    };
}

fn connectionToken(connection: ResolvedConnection) ?[]const u8 {
    return switch (connection) {
        .stdio => |value| value.token,
        .tcp => |value| value.token,
        .uri => |value| value.token,
    };
}

fn needsGeneratedConnectionToken(connection: ResolvedConnection) bool {
    return switch (connection) {
        .tcp => |value| value.token == null,
        .stdio, .uri => false,
    };
}

fn validateClientOptions(options: ClientOptions) !void {
    if (options.connection != null and
        (!std.mem.eql(u8, options.cli_path, "copilot") or
            options.cli_args.len != 0 or
            options.connection_token != null))
    {
        return error.ConflictingConnectionOptions;
    }
    if (options.connection) |explicit| switch (explicit) {
        .stdio => |value| if (value.env != null and options.env != null)
            return error.ConflictingEnvironmentOptions,
        .tcp => |value| if (value.env != null and options.env != null)
            return error.ConflictingEnvironmentOptions,
        .uri => if (options.github_token != null or options.use_logged_in_user != null)
            return error.UnsupportedUriAuthenticationOptions,
    };

    if (options.builtin_plugin_directories.len > 64)
        return error.TooManyBuiltinPluginDirectories;
    for (options.builtin_plugin_directories, 0..) |directory, index| {
        if (!std.fs.path.isAbsolute(directory) or directory.len > 4096)
            return error.InvalidBuiltinPluginDirectory;
        for (options.builtin_plugin_directories[0..index]) |previous| {
            if (std.mem.eql(u8, previous, directory))
                return error.DuplicateBuiltinPluginDirectory;
        }
    }

    if (options.session_filesystem) |filesystem| {
        if (filesystem.initial_working_directory.len == 0)
            return error.InvalidSessionFilesystemInitialWorkingDirectory;
        if (filesystem.session_state_path.len == 0)
            return error.InvalidSessionFilesystemStatePath;
    }
}

fn validateResolvedConnection(options: ClientOptions, connection: ResolvedConnection) !void {
    switch (connection) {
        .uri => |value| {
            if (value.token) |token| {
                if (token.len == 0) return error.InvalidConnectionToken;
            }
        },
        .stdio => |value| {
            try validateChildRuntime(value.child, options.session_filesystem != null);
        },
        .tcp => |value| {
            try validateChildRuntime(value.child, options.session_filesystem != null);
            if (value.token) |token| {
                if (token.len == 0) return error.InvalidConnectionToken;
            }
        },
    }
}

fn validateChildRuntime(
    child_runtime: ResolvedChild,
    has_session_filesystem: bool,
) !void {
    if (child_runtime.executable.len == 0) return error.InvalidRuntimeExecutable;
    if (child_runtime.base_directory) |directory| {
        if (directory.len == 0) return error.InvalidBaseDirectory;
    }
    if (child_runtime.github_token) |token|
        if (token.len == 0) return error.InvalidGitHubToken;
    if (child_runtime.mode == .empty and
        child_runtime.base_directory == null and
        !has_session_filesystem)
    {
        return error.EmptyModeRequiresPersistence;
    }
    const environment = child_runtime.environment orelse return;
    for (environment, 0..) |entry, index| {
        if (!std.process.Environ.Map.validateKeyForPut(entry.name) or
            std.mem.indexOfScalar(u8, entry.value, 0) != null)
        {
            return error.InvalidEnvironmentVariable;
        }
        for (managed_environment_keys) |managed| {
            if (environmentKeyEql(entry.name, managed))
                return error.ManagedEnvironmentVariable;
        }
        for (environment[0..index]) |previous| {
            if (environmentKeyEql(entry.name, previous.name))
                return error.DuplicateEnvironmentVariable;
        }
    }
}

fn environmentKeyEql(a: []const u8, b: []const u8) bool {
    return if (builtin.os.tag == .windows)
        std.ascii.eqlIgnoreCase(a, b)
    else
        std.mem.eql(u8, a, b);
}

fn parseRuntimeUri(uri: []const u8) !ParsedUri {
    var value = uri;
    if (std.mem.startsWith(u8, value, "http://")) {
        value = value["http://".len..];
    } else if (std.mem.startsWith(u8, value, "https://")) {
        value = value["https://".len..];
    }
    if (value.len == 0 or std.mem.indexOfScalar(u8, value, '/') != null)
        return error.InvalidRuntimeUri;

    if (value[0] == '[') {
        const close = std.mem.indexOfScalar(u8, value, ']') orelse
            return error.InvalidRuntimeUri;
        if (close + 2 > value.len or value[close + 1] != ':')
            return error.InvalidRuntimeUri;
        return .{
            .host = value[1..close],
            .port = try parsePort(value[close + 2 ..]),
        };
    }
    if (std.mem.indexOfScalar(u8, value, ':')) |colon| {
        if (std.mem.indexOfScalarPos(u8, value, colon + 1, ':') != null)
            return error.InvalidRuntimeUri;
        return .{
            .host = if (colon == 0) "localhost" else value[0..colon],
            .port = try parsePort(value[colon + 1 ..]),
        };
    }
    return .{
        .host = "localhost",
        .port = try parsePort(value),
    };
}

fn parsePort(value: []const u8) !u16 {
    if (value.len == 0) return error.InvalidRuntimeUri;
    const port = std.fmt.parseUnsigned(u16, value, 10) catch
        return error.InvalidRuntimeUri;
    if (port == 0) return error.InvalidRuntimeUri;
    return port;
}

fn openTransport(
    allocator: std.mem.Allocator,
    io: std.Io,
    connection: ResolvedConnection,
    effective_token: ?[]const u8,
) !Transport {
    return switch (connection) {
        .stdio => |value| try spawnStdio(
            allocator,
            io,
            value.child,
            effective_token,
        ),
        .tcp => |value| try spawnTcp(
            allocator,
            io,
            value.child,
            value.port,
            effective_token,
        ),
        .uri => |value| blk: {
            const stream = try connectToHostBounded(io, value.host, value.port);
            errdefer stream.close(io);
            break :blk try externalUriTransport(allocator, io, stream, value.port);
        },
    };
}

fn spawnStdio(
    allocator: std.mem.Allocator,
    io: std.Io,
    child_runtime: ResolvedChild,
    connection_token: ?[]const u8,
) !Transport {
    var port_buffer: [5]u8 = undefined;
    var timeout_buffer: [10]u8 = undefined;
    var argv = try buildRuntimeArgv(
        allocator,
        child_runtime,
        .stdio,
        0,
        &port_buffer,
        &timeout_buffer,
    );
    defer argv.deinit(allocator);
    var environment = try buildRuntimeEnvironment(
        allocator,
        child_runtime,
        connection_token,
        io,
    );
    defer deinitEnvironment(&environment);

    var child = try std.process.spawn(io, .{
        .argv = argv.items,
        .cwd = if (child_runtime.working_directory) |cwd| .{ .path = cwd } else .inherit,
        .environ_map = &environment,
        .stdin = .pipe,
        .stdout = .pipe,
        .stderr = .inherit,
    });
    errdefer child.kill(io);

    const reader_buffer = try allocator.alloc(u8, 8192);
    errdefer allocator.free(reader_buffer);
    const writer_buffer = try allocator.alloc(u8, 8192);
    errdefer allocator.free(writer_buffer);
    return .{ .stdio_child = .{
        .child = child,
        .io = .{
            .reader = child.stdout.?.readerStreaming(io, reader_buffer),
            .writer = child.stdin.?.writerStreaming(io, writer_buffer),
            .reader_buffer = reader_buffer,
            .writer_buffer = writer_buffer,
        },
    } };
}

fn spawnTcp(
    allocator: std.mem.Allocator,
    io: std.Io,
    child_runtime: ResolvedChild,
    requested_port: u16,
    connection_token: ?[]const u8,
) !Transport {
    var port_buffer: [5]u8 = undefined;
    var timeout_buffer: [10]u8 = undefined;
    var argv = try buildRuntimeArgv(
        allocator,
        child_runtime,
        .tcp,
        requested_port,
        &port_buffer,
        &timeout_buffer,
    );
    defer argv.deinit(allocator);
    var environment = try buildRuntimeEnvironment(
        allocator,
        child_runtime,
        connection_token,
        io,
    );
    defer deinitEnvironment(&environment);

    var child = try std.process.spawn(io, .{
        .argv = argv.items,
        .cwd = if (child_runtime.working_directory) |cwd| .{ .path = cwd } else .inherit,
        .environ_map = &environment,
        .stdin = .ignore,
        .stdout = .pipe,
        .stderr = .inherit,
    });
    errdefer child.kill(io);

    const announced_port = try readAnnouncedPortBounded(allocator, io, &child);
    child.stdout.?.close(io);
    child.stdout = null;
    if (requested_port != 0 and announced_port != requested_port)
        return error.RuntimePortMismatch;
    const port = announced_port;
    const stream = try connectToHostWithRetry(io, "localhost", port);
    errdefer stream.close(io);
    return ownedTcpTransport(allocator, io, stream, port, child);
}

fn allocateSocketTransport(
    allocator: std.mem.Allocator,
    io: std.Io,
    stream: std.Io.net.Stream,
) !SocketTransport {
    const reader_buffer = try allocator.alloc(u8, 8192);
    errdefer allocator.free(reader_buffer);
    const writer_buffer = try allocator.alloc(u8, 8192);
    errdefer allocator.free(writer_buffer);
    return .{
        .stream = stream,
        .reader = stream.reader(io, reader_buffer),
        .writer = stream.writer(io, writer_buffer),
        .reader_buffer = reader_buffer,
        .writer_buffer = writer_buffer,
    };
}

fn ownedTcpTransport(
    allocator: std.mem.Allocator,
    io: std.Io,
    stream: std.Io.net.Stream,
    port: u16,
    child: std.process.Child,
) !Transport {
    return .{ .tcp_child = .{
        .child = child,
        .io = try allocateSocketTransport(allocator, io, stream),
        .port = port,
    } };
}

fn externalUriTransport(
    allocator: std.mem.Allocator,
    io: std.Io,
    stream: std.Io.net.Stream,
    port: u16,
) !Transport {
    return .{ .uri = .{
        .io = try allocateSocketTransport(allocator, io, stream),
        .port = port,
    } };
}

const RuntimeTransportKind = enum { stdio, tcp };

fn buildRuntimeArgv(
    allocator: std.mem.Allocator,
    child_runtime: ResolvedChild,
    transport_kind: RuntimeTransportKind,
    port: u16,
    port_buffer: *[5]u8,
    timeout_buffer: *[10]u8,
) !std.ArrayList([]const u8) {
    var argv: std.ArrayList([]const u8) = .empty;
    errdefer argv.deinit(allocator);
    try argv.append(allocator, child_runtime.executable);
    try argv.appendSlice(allocator, child_runtime.args);
    try argv.appendSlice(allocator, &.{ "--headless", "--no-auto-update" });
    if (child_runtime.log_level) |level| {
        try argv.appendSlice(allocator, &.{ "--log-level", level.wireValue() });
    }
    switch (transport_kind) {
        .stdio => try argv.append(allocator, "--stdio"),
        .tcp => if (port != 0) {
            const port_text = try std.fmt.bufPrint(port_buffer, "{d}", .{port});
            try argv.appendSlice(allocator, &.{ "--port", port_text });
        },
    }
    if (child_runtime.github_token != null) {
        try argv.appendSlice(allocator, &.{
            "--auth-token-env",
            "COPILOT_SDK_AUTH_TOKEN",
        });
    }
    if (!child_runtime.use_logged_in_user)
        try argv.append(allocator, "--no-auto-login");
    if (child_runtime.session_idle_timeout_seconds != 0) {
        const timeout = try std.fmt.bufPrint(
            timeout_buffer,
            "{d}",
            .{child_runtime.session_idle_timeout_seconds},
        );
        try argv.appendSlice(allocator, &.{ "--session-idle-timeout", timeout });
    }
    if (child_runtime.enable_remote_sessions) {
        try argv.append(allocator, "--remote");
    }
    return argv;
}

fn buildRuntimeEnvironment(
    allocator: std.mem.Allocator,
    child_runtime: ResolvedChild,
    connection_token: ?[]const u8,
    io: std.Io,
) !std.process.Environ.Map {
    var result = if (child_runtime.environment) |_|
        std.process.Environ.Map.init(allocator)
    else
        try inheritedEnvironmentMap(allocator, io);
    errdefer deinitEnvironment(&result);
    if (child_runtime.environment) |environment| {
        for (environment) |entry| {
            try result.put(entry.name, entry.value);
        }
    }
    _ = result.swapRemove("NODE_DEBUG");
    if (child_runtime.github_token) |token|
        try result.put("COPILOT_SDK_AUTH_TOKEN", token);
    if (connection_token) |token| {
        try result.put("COPILOT_CONNECTION_TOKEN", token);
    }
    if (child_runtime.base_directory) |directory| {
        try result.put("COPILOT_HOME", directory);
    }
    if (child_runtime.mode == .empty) {
        try result.put("COPILOT_DISABLE_KEYTAR", "1");
    }
    if (child_runtime.telemetry) |telemetry| {
        try result.put("COPILOT_OTEL_ENABLED", "true");
        if (telemetry.otlp_endpoint) |value|
            try result.put("OTEL_EXPORTER_OTLP_ENDPOINT", value);
        if (telemetry.otlp_protocol) |value|
            try result.put(
                "OTEL_EXPORTER_OTLP_PROTOCOL",
                switch (value) {
                    .http_json => "http/json",
                    .http_protobuf => "http/protobuf",
                },
            );
        if (telemetry.file_path) |value|
            try result.put("COPILOT_OTEL_FILE_EXPORTER_PATH", value);
        if (telemetry.exporter_type) |value|
            try result.put("COPILOT_OTEL_EXPORTER_TYPE", value);
        if (telemetry.source_name) |value|
            try result.put("COPILOT_OTEL_SOURCE_NAME", value);
        if (telemetry.capture_content) |value|
            try result.put(
                "OTEL_INSTRUMENTATION_GENAI_CAPTURE_MESSAGE_CONTENT",
                if (value) "true" else "false",
            );
    }
    return result;
}

fn inheritedEnvironmentMap(
    allocator: std.mem.Allocator,
    io: std.Io,
) !std.process.Environ.Map {
    return switch (builtin.os.tag) {
        .windows, .wasi, .emscripten => std.process.Environ.createMap(
            .{ .block = .global },
            allocator,
        ),
        .linux => blk: {
            const bytes = try std.Io.Dir.cwd().readFileAlloc(
                io,
                "/proc/self/environ",
                allocator,
                .limited(1024 * 1024),
            );
            defer allocator.free(bytes);
            var result = std.process.Environ.Map.init(allocator);
            errdefer result.deinit();
            var entries = std.mem.splitScalar(u8, bytes, 0);
            while (entries.next()) |entry| {
                if (entry.len == 0) continue;
                const separator = std.mem.indexOfScalar(u8, entry, '=') orelse continue;
                try result.put(entry[0..separator], entry[separator + 1 ..]);
            }
            break :blk result;
        },
        else => blk: {
            const entries = std.mem.span(std.c.environ);
            break :blk std.process.Environ.createMap(.{
                .block = .{ .slice = @ptrCast(entries[0..entries.len :null]) },
            }, allocator);
        },
    };
}

fn deinitEnvironment(environment: *std.process.Environ.Map) void {
    for (environment.values()) |value| wipeSecret(value);
    environment.deinit();
}

fn readAnnouncedPort(
    allocator: std.mem.Allocator,
    io: std.Io,
    child: *std.process.Child,
) !u16 {
    const buffer = try allocator.alloc(u8, 4096);
    defer allocator.free(buffer);
    var reader = child.stdout.?.readerStreaming(io, buffer);
    while (try reader.interface.takeDelimiter('\n')) |raw_line| {
        const line = std.mem.trim(u8, raw_line, " \t\r\n");
        const marker = "listening on port ";
        const marker_index = std.ascii.indexOfIgnoreCase(line, marker) orelse continue;
        const port_text = std.mem.trim(
            u8,
            line[marker_index + marker.len ..],
            " \t\r\n",
        );
        return std.fmt.parseUnsigned(u16, port_text, 10) catch
            return error.InvalidRuntimePortAnnouncement;
    }
    return error.MissingRuntimePortAnnouncement;
}

fn readAnnouncedPortBounded(
    allocator: std.mem.Allocator,
    io: std.Io,
    child: *std.process.Child,
) !u16 {
    const Result = union(enum) {
        port: anyerror!u16,
        timeout: anyerror!void,
    };
    var result_buffer: [2]Result = undefined;
    var select = std.Io.Select(Result).init(io, &result_buffer);
    defer select.cancelDiscard();
    select.async(.port, readAnnouncedPort, .{ allocator, io, child });
    select.async(.timeout, std.Io.sleep, .{
        io,
        std.Io.Duration.fromSeconds(10),
        std.Io.Clock.awake,
    });
    return switch (try select.await()) {
        .port => |result| try result,
        .timeout => |result| {
            try result;
            return error.RuntimeStartupTimeout;
        },
    };
}

fn connectToHostWithRetry(io: std.Io, host: []const u8, port: u16) !std.Io.net.Stream {
    var last_error: anyerror = error.ConnectionRefused;
    for (0..100) |_| {
        return connectToHost(io, host, port) catch |err| {
            last_error = err;
            try std.Io.sleep(io, .fromMilliseconds(10), .awake);
            continue;
        };
    }
    return last_error;
}

fn connectToHostBounded(io: std.Io, host: []const u8, port: u16) !std.Io.net.Stream {
    const Result = union(enum) {
        stream: anyerror!std.Io.net.Stream,
        timeout: anyerror!void,
    };
    var result_buffer: [2]Result = undefined;
    var select = std.Io.Select(Result).init(io, &result_buffer);
    defer select.cancelDiscard();
    select.async(.stream, connectToHost, .{ io, host, port });
    select.async(.timeout, std.Io.sleep, .{
        io,
        std.Io.Duration.fromSeconds(10),
        std.Io.Clock.awake,
    });
    return switch (try select.await()) {
        .stream => |result| try result,
        .timeout => |result| {
            try result;
            return error.RuntimeConnectionTimeout;
        },
    };
}

fn connectToHost(io: std.Io, host: []const u8, port: u16) !std.Io.net.Stream {
    if (std.mem.eql(u8, host, "localhost")) {
        const address = std.Io.net.IpAddress{ .ip4 = .loopback(port) };
        return address.connect(io, .{ .mode = .stream, .protocol = .tcp });
    }
    if (std.Io.net.IpAddress.parse(host, port)) |address| {
        return address.connect(io, .{ .mode = .stream, .protocol = .tcp });
    } else |_| {}

    const hostname = try std.Io.net.HostName.init(host);
    var lookup_buffer: [32]std.Io.net.HostName.LookupResult = undefined;
    var lookup_queue: std.Io.Queue(std.Io.net.HostName.LookupResult) = .init(&lookup_buffer);
    try hostname.lookup(io, &lookup_queue, .{ .port = port });
    var last_error: anyerror = error.NoAddressReturned;
    while (lookup_queue.getOne(io)) |result| {
        switch (result) {
            .canonical_name => {},
            .address => |address| {
                return address.connect(io, .{
                    .mode = .stream,
                    .protocol = .tcp,
                }) catch |err| {
                    last_error = err;
                    continue;
                };
            },
        }
    } else |_| {}
    return last_error;
}

const SessionRecord = struct {
    id: ?[]u8 = null,
    generation: u64 = 1,
    workspace_path: ?[]u8 = null,
    removal: enum {
        none,
        draining,
        deferred,
    } = .none,
    replacement_pending: bool = false,

    fn isActive(self: SessionRecord) bool {
        return self.id != null and
            self.removal == .none and
            !self.replacement_pending;
    }

    fn deactivate(self: *SessionRecord, allocator: std.mem.Allocator) void {
        const id = self.id orelse return;
        allocator.free(id);
        if (self.workspace_path) |path| allocator.free(path);
        self.id = null;
        self.workspace_path = null;
        self.removal = .none;
        self.replacement_pending = false;
    }

    fn deinit(self: *SessionRecord, allocator: std.mem.Allocator) void {
        self.deactivate(allocator);
        self.* = undefined;
    }
};

const PendingSessionRecord = struct {
    id: ?[]u8,
    record_index: usize,
    generation: u64,
    workspace_path: ?[]u8 = null,

    fn deinit(self: *PendingSessionRecord, allocator: std.mem.Allocator) void {
        if (self.workspace_path) |path| allocator.free(path);
        if (self.id) |id| allocator.free(id);
        self.* = undefined;
    }
};

const SessionRecordCommit = struct {
    pending: PendingSessionRecord,
    prior_log: ?*event_log.EventLog,
    replacing: bool,
};

const SessionRemoval = struct {
    record_index: usize,
    session_id: []u8,
    generation: u64,
    log: ?*event_log.EventLog,
};

fn nextSessionGeneration(generation: u64) !u64 {
    return std.math.add(u64, generation, 1) catch
        error.SessionGenerationExhausted;
}

const ShutdownOps = struct {
    context: ?*anyopaque,
    disconnect_session_once: *const fn (?*anyopaque, *Client, []const u8) anyerror!void,
    terminate_child_once: *const fn (?*anyopaque, *Client) anyerror!void,
};

const DetailedShutdownOps = struct {
    context: ?*anyopaque,
    disconnect_session_once: *const fn (
        ?*anyopaque,
        *Client,
        []const u8,
    ) errors.DetailedError!errors.DetailedResult(void),
    terminate_child_once: *const fn (?*anyopaque, *Client) anyerror!void,
};

fn runLegacyShutdown(
    client: *Client,
    ops: ShutdownOps,
) ?anyerror {
    var first_error: ?anyerror = null;
    var index = client.sessions.items.len;
    while (index > 0) {
        index -= 1;
        const session_id = client.sessions.items[index].id orelse continue;
        ops.disconnect_session_once(ops.context, client, session_id) catch |err| {
            if (first_error == null) first_error = err;
        };
    }
    ops.terminate_child_once(ops.context, client) catch |err| {
        if (first_error == null) first_error = err;
    };
    return first_error;
}

fn disconnectForShutdown(_: ?*anyopaque, client: *Client, session_id: []const u8) !void {
    const session = try client.sessionForId(session_id);
    return legacyResult(
        void,
        session.disconnectImpl(.legacy),
    );
}

fn disconnectDetailedForShutdown(
    _: ?*anyopaque,
    client: *Client,
    session_id: []const u8,
) errors.DetailedError!errors.DetailedResult(void) {
    const session = client.sessionForId(session_id) catch |err|
        return .{ .failure = try recordInvalidConfig(
            client.allocator,
            "session_id",
            err,
        ) };
    return session.disconnectImpl(.detailed);
}

fn terminateForShutdown(_: ?*anyopaque, client: *Client) !void {
    if (client.transport != .none) {
        client.shutdownOwnedRuntimeBounded();
        client.transport_closed = true;
        client.transport.close(client.allocator, client.io);
        client.transport.terminateAndReap(client.io);
        return;
    }
    client.transport_closed = true;
    client.child_wait = null;
    if (client.child) |*child| {
        if (child.id != null) child.kill(client.io);
    }
}

const real_shutdown_ops = ShutdownOps{
    .context = null,
    .disconnect_session_once = disconnectForShutdown,
    .terminate_child_once = terminateForShutdown,
};

const real_detailed_shutdown_ops = DetailedShutdownOps{
    .context = null,
    .disconnect_session_once = disconnectDetailedForShutdown,
    .terminate_child_once = terminateForShutdown,
};

const ChildWaitOperation = struct {
    context: ?*anyopaque,
    wait: *const fn (?*anyopaque, *Client) anyerror!std.process.Child.Term,
};

fn waitForChild(_: ?*anyopaque, client: *Client) !std.process.Child.Term {
    const child = &(client.child orelse return error.ProcessNotFound);
    if (child.id == null) return error.ProcessNotFound;
    return child.wait(client.io);
}

const real_child_wait = ChildWaitOperation{
    .context = null,
    .wait = waitForChild,
};

const ShutdownCollector = struct {
    allocator: std.mem.Allocator,
    storage: []errors.Failure,
    count: usize = 0,
    dropped: usize = 0,

    fn recordOwned(self: *ShutdownCollector, failure: errors.Failure) void {
        if (self.count == self.storage.len) {
            var dropped_failure = failure;
            dropped_failure.deinit();
            self.dropped += 1;
            return;
        }
        self.storage[self.count] = failure;
        self.count += 1;
    }

    fn recordNative(self: *ShutdownCollector, native_error: anyerror) void {
        if (self.count == self.storage.len) {
            self.dropped += 1;
            return;
        }
        const failure = recordProcessTerminate(
            self.allocator,
            null,
            native_error,
        ) catch |err| switch (err) {
            error.OutOfMemory => {
                self.dropped += 1;
                return;
            },
        };
        self.recordOwned(failure);
    }
};

fn runDetailedShutdown(
    client: *Client,
    ops: DetailedShutdownOps,
    collector: *ShutdownCollector,
) ?anyerror {
    var first_error: ?anyerror = null;
    var index = client.sessions.items.len;
    while (index > 0) {
        index -= 1;
        const session_id = client.sessions.items[index].id orelse continue;
        const result = ops.disconnect_session_once(
            ops.context,
            client,
            session_id,
        ) catch |err| {
            if (first_error == null) first_error = err;
            collector.dropped += 1;
            continue;
        };
        switch (result) {
            .success => {},
            .failure => |failure| {
                if (first_error == null) first_error = failure.native_error;
                collector.recordOwned(failure);
            },
        }
    }
    ops.terminate_child_once(ops.context, client) catch |err| {
        if (first_error == null) first_error = err;
        collector.recordNative(err);
    };
    return first_error;
}

pub const Client = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    transport: Transport = .none,
    on_list_models: ?runtime_types.ModelListCallback = null,
    on_get_trace_context: ?runtime_types.TraceContextCallback = null,
    session_filesystem: ?runtime_types.SessionFilesystemConfig = null,
    mode: runtime_types.RuntimeMode = .copilot_cli,
    session_filesystems: SessionFilesystemRegistry = .{},
    child: ?std.process.Child = null,
    child_wait: ?ChildWaitOperation = null,
    last_exit: ?errors.ProcessExit = null,
    transport_closed: bool = false,
    reader: *std.Io.File.Reader = undefined,
    writer: *std.Io.File.Writer = undefined,
    reader_buffer: []u8 = &.{},
    writer_buffer: []u8 = &.{},
    next_request_id: u64 = 1,
    sessions: std.ArrayList(SessionRecord) = .empty,
    sessions_mutex: std.Io.Mutex = .init,
    pending_session: ?PendingSessionRecord = null,
    events: std.ArrayList(EventDelivery) = .empty,
    events_mutex: std.Io.Mutex = .init,
    event_logs: std.ArrayList(*event_log.EventLog) = .empty,
    event_logs_mutex: std.Io.Mutex = .init,
    pending_calls: std.ArrayList(*PendingCall) = .empty,
    pending_call_admission_probe: ?*PendingCallAdmissionProbe = null,
    retained_responses: std.ArrayList(RetainedResponse) = .empty,
    abandoned_response_ids: std.ArrayList(u64) = .empty,
    pending_mutex: std.Io.Mutex = .init,
    direct_call_active: bool = false,
    direct_call_owner: ?std.Thread.Id = null,
    direct_call_depth: usize = 0,
    direct_call_done: std.Io.Event = .is_set,
    writer_mutex: std.Io.Mutex = .init,
    pump_future: ?std.Io.Future(void) = null,
    pump_closing: bool = false,
    pump_read_gate: ?*std.Io.Event = null,
    pump_failure: ?errors.Failure = null,
    pump_terminal_error: ?anyerror = null,
    send_operations: std.ArrayList(*SendOperation) = .empty,
    send_operations_mutex: std.Io.Mutex = .init,
    factory_jobs: std.ArrayList(*FactoryExecuteJob) = .empty,
    factory_jobs_mutex: std.Io.Mutex = .init,
    event_queue: std.ArrayList(QueuedLogEvent) = .empty,
    event_queue_mutex: std.Io.Mutex = .init,
    event_queue_ready: std.Io.Event = .unset,
    event_worker_future: ?std.Io.Future(void) = null,
    event_worker_closing: bool = false,
    next_queued_event_id: u64 = 1,
    lifecycle_events: admin.LifecycleQueue = .{},
    lifecycle_events_mutex: std.Io.Mutex = .init,
    lifecycle_event_ready: std.Io.Event = .unset,
    tools: std.ArrayList(RegisteredTool) = .empty,
    user_input_handlers: std.ArrayList(RegisteredUserInputHandler) = .empty,
    permission_handlers: std.ArrayList(RegisteredPermissionHandler) = .empty,
    extension_runtimes: std.ArrayList(SessionExtensionRuntime) = .empty,
    extension_runtimes_mutex: std.Io.Mutex = .init,
    runtime_callbacks_drained: std.Io.Event = .is_set,
    runtime_callbacks_ready: std.Io.Event = .is_set,
    runtime_callback_count: usize = 0,
    runtime_callbacks_blocked: bool = false,
    runtime_rollback_pending: bool = false,
    pending_extension_runtime: ?SessionExtensionRuntime = null,
    provider_tokens: std.ArrayList(RegisteredProviderTokens) = .empty,
    pending_provider_tokens: ?RegisteredProviderTokens = null,
    rpc_handlers: std.ArrayList(RegisteredRpcHandler) = .empty,
    rpc_handler_owner: ?std.Thread.Id = null,
    rpc_handler_depth: usize = 0,
    direct_request_ids: [8]u64 = undefined,
    direct_request_count: usize = 0,
    buffered_responses: std.ArrayList(BufferedResponse) = .empty,
    rpc_ready: bool = false,

    pub fn init(
        allocator: std.mem.Allocator,
        io: std.Io,
        options: ClientOptions,
    ) !Client {
        return legacyResult(Client, initEngine(.legacy, allocator, io, options));
    }

    pub fn initDetailed(
        allocator: std.mem.Allocator,
        io: std.Io,
        options: ClientOptions,
    ) errors.DetailedError!errors.DetailedResult(Client) {
        return initEngine(.detailed, allocator, io, options);
    }

    fn initEngine(
        comptime failure_policy: FailurePolicy,
        allocator: std.mem.Allocator,
        io: std.Io,
        options: ClientOptions,
    ) errors.DetailedError!PolicyResult(failure_policy, Client) {
        var ambient_environment = if (options.connection == null)
            inheritedEnvironmentMap(allocator, io) catch |err| {
                if (err == error.OutOfMemory) return error.OutOfMemory;
                return .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordClientIo,
                    .{ allocator, .connect, err },
                ) };
            }
        else
            null;
        defer if (ambient_environment) |*value| deinitEnvironment(value);
        const default_connection = parseDefaultConnection(
            if (ambient_environment) |*value|
                value.get("COPILOT_SDK_DEFAULT_CONNECTION")
            else
                null,
        ) catch |err| return .{ .failure = try policyFailure(
            failure_policy,
            err,
            recordInvalidConfig,
            .{ allocator, "COPILOT_SDK_DEFAULT_CONNECTION", err },
        ) };
        validateClientOptions(options) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ allocator, "options", err },
            ) };
        const connection = resolveConnection(options, default_connection) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ allocator, "connection", err },
            ) };
        validateResolvedConnection(options, connection) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ allocator, "connection", err },
            ) };
        var generated_token: ?[]u8 = null;
        defer if (generated_token) |token| {
            wipeSecret(token);
            allocator.free(token);
        };
        if (needsGeneratedConnectionToken(connection)) {
            generated_token = generateSessionId(allocator, io) catch |err| {
                if (err == error.OutOfMemory) return error.OutOfMemory;
                return .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordInvalidConfig,
                    .{ allocator, "connection_token", err },
                ) };
            };
        }
        const token = connectionToken(connection) orelse generated_token;
        const transport = openTransport(allocator, io, connection, token) catch |err| {
            if (err == error.OutOfMemory) return error.OutOfMemory;
            return switch (connection) {
                .stdio => |stdio| .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordProcessSpawn,
                    .{ allocator, stdio.child.executable, err },
                ) },
                .tcp => |tcp| .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordProcessSpawn,
                    .{ allocator, tcp.child.executable, err },
                ) },
                .uri => .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordClientIo,
                    .{ allocator, .connect, err },
                ) },
            };
        };
        var client = Client{
            .allocator = allocator,
            .io = io,
            .transport = transport,
            .on_list_models = options.on_list_models,
            .on_get_trace_context = options.on_get_trace_context,
            .session_filesystem = options.session_filesystem,
            .mode = options.mode,
        };
        errdefer client.deinit();
        switch (try client.connect(failure_policy, token, options.client_info)) {
            .success => {},
            .failure => |failure| {
                client.deinit();
                return .{ .failure = failure };
            },
        }
        client.rpc_ready = true;
        client.setBuiltinPluginDirectories(options.builtin_plugin_directories) catch |err| {
            if (err == error.OutOfMemory) return error.OutOfMemory;
            const failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ allocator, "builtin_plugin_directories", err },
            );
            client.deinit();
            return .{ .failure = failure };
        };
        client.setSessionFilesystemProvider() catch |err| {
            if (err == error.OutOfMemory) return error.OutOfMemory;
            const failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ allocator, "session_filesystem", err },
            );
            client.deinit();
            return .{ .failure = failure };
        };
        return .{ .success = client };
    }

    pub fn initParent(allocator: std.mem.Allocator, io: std.Io) !Client {
        return legacyResult(Client, initParentEngine(.legacy, allocator, io));
    }

    pub fn initParentDetailed(
        allocator: std.mem.Allocator,
        io: std.Io,
    ) errors.DetailedError!errors.DetailedResult(Client) {
        return initParentEngine(.detailed, allocator, io);
    }

    fn initParentEngine(
        comptime failure_policy: FailurePolicy,
        allocator: std.mem.Allocator,
        io: std.Io,
    ) errors.DetailedError!PolicyResult(failure_policy, Client) {
        const reader_buffer = try allocator.alloc(u8, 8192);
        errdefer allocator.free(reader_buffer);
        const writer_buffer = try allocator.alloc(u8, 8192);
        errdefer allocator.free(writer_buffer);

        var client = Client{
            .allocator = allocator,
            .io = io,
            .transport = .{ .parent_stdio = .{
                .reader = std.Io.File.stdin().readerStreaming(io, reader_buffer),
                .writer = std.Io.File.stdout().writerStreaming(io, writer_buffer),
                .reader_buffer = reader_buffer,
                .writer_buffer = writer_buffer,
            } },
        };
        errdefer client.deinit();
        switch (try client.connect(failure_policy, null, null)) {
            .success => {},
            .failure => |failure| {
                client.deinit();
                return .{ .failure = failure };
            },
        }
        client.rpc_ready = true;
        return .{ .success = client };
    }

    pub fn deinit(self: *Client) void {
        self.releaseInterestsAndDetachSessionsBounded();
        self.stopEventWorker();
        self.shutdownOwnedRuntimeBounded();
        self.finishFactoryJobs();
        self.stopPump();
        self.finishSendOperations();
        if (self.transport == .none and !self.transport_closed) {
            if (self.child) |*child| {
                if (child.id != null) child.kill(self.io);
            }
            self.allocator.destroy(self.reader);
            self.allocator.destroy(self.writer);
            self.wipeTransportBuffers();
            self.allocator.free(self.reader_buffer);
            self.allocator.free(self.writer_buffer);
        } else {
            self.transport.close(self.allocator, self.io);
            self.transport.terminateAndReap(self.io);
        }
        self.session_filesystems.deinit(self.allocator);
        for (self.events.items) |*event| event.deinit(self.allocator);
        self.events.deinit(self.allocator);
        for (self.event_logs.items) |log| {
            log.close();
            log.deinit();
            self.allocator.destroy(log);
        }
        self.event_logs.deinit(self.allocator);
        for (self.retained_responses.items) |response| {
            wipeSecret(response.body);
            self.allocator.free(response.body);
        }
        self.retained_responses.deinit(self.allocator);
        self.abandoned_response_ids.deinit(self.allocator);
        self.pending_calls.deinit(self.allocator);
        if (self.pump_failure) |*failure| failure.deinit();
        self.send_operations.deinit(self.allocator);
        self.factory_jobs.deinit(self.allocator);
        self.event_queue.deinit(self.allocator);
        self.lifecycle_events.deinit();
        for (self.tools.items) |tool| tool.deinit(self.allocator);
        self.tools.deinit(self.allocator);
        self.user_input_handlers.deinit(self.allocator);
        self.permission_handlers.deinit(self.allocator);
        if (self.pending_extension_runtime) |*runtime| {
            runtime.deinit(self.allocator);
        }
        for (self.extension_runtimes.items) |*runtime| {
            runtime.deinit(self.allocator);
        }
        self.extension_runtimes.deinit(self.allocator);
        if (self.pending_provider_tokens) |registered| {
            registered.deinit(self.allocator);
        }
        for (self.provider_tokens.items) |registered| registered.deinit(self.allocator);
        self.provider_tokens.deinit(self.allocator);
        for (self.rpc_handlers.items) |handler| handler.deinit(self.allocator);
        self.rpc_handlers.deinit(self.allocator);
        for (self.buffered_responses.items) |*response| response.deinit(self.allocator);
        self.buffered_responses.deinit(self.allocator);
        if (self.pending_session) |*pending| pending.deinit(self.allocator);
        for (self.sessions.items) |*session| session.deinit(self.allocator);
        self.sessions.deinit(self.allocator);
        self.* = undefined;
    }

    fn shutdownOwnedRuntimeBounded(self: *Client) void {
        if (!self.rpc_ready or !self.transport.ownsRuntime()) return;
        const Result = union(enum) {
            shutdown: anyerror!void,
            timeout: anyerror!void,
        };
        var result_buffer: [2]Result = undefined;
        var select = std.Io.Select(Result).init(self.io, &result_buffer);
        defer select.cancelDiscard();
        select.async(.shutdown, Client.requestRuntimeShutdown, .{self});
        select.async(.timeout, std.Io.sleep, .{
            self.io,
            runtime_shutdown_timeout,
            std.Io.Clock.awake,
        });
        switch (select.await() catch return) {
            .shutdown => |result| result catch {},
            .timeout => |result| result catch {},
        }
    }

    fn requestRuntimeShutdown(self: *Client) !void {
        const parsed = try self.call(std.json.Value, "runtime.shutdown", .{});
        defer parsed.deinit();
        if (parsed.value != .null) return error.InvalidRuntimeShutdownResponse;
    }

    fn releaseInterestsAndDetachSessionsBounded(self: *Client) void {
        if (!self.hasMcpOAuthInterests() and !self.hasActiveSessions()) return;
        const Result = union(enum) {
            released: void,
            timeout: anyerror!void,
        };
        var result_buffer: [2]Result = undefined;
        var select = std.Io.Select(Result).init(self.io, &result_buffer);
        defer select.cancelDiscard();
        select.async(.released, Client.releaseInterestsAndDetachSessions, .{self});
        select.async(.timeout, std.Io.sleep, .{
            self.io,
            teardown_oauth_release_timeout,
            std.Io.Clock.awake,
        });
        switch (select.await() catch return) {
            .released => {},
            .timeout => |result| result catch {},
        }
    }

    fn hasMcpOAuthInterests(self: *const Client) bool {
        if (self.pending_extension_runtime) |runtime| {
            if (runtime.mcp_oauth_interest != .none) return true;
        }
        for (self.extension_runtimes.items) |runtime| {
            if (runtime.mcp_oauth_interest != .none) return true;
        }
        return false;
    }

    fn hasActiveSessions(self: *const Client) bool {
        for (self.sessions.items) |session| {
            if (session.isActive()) return true;
        }
        return false;
    }

    fn releaseInterestsAndDetachSessions(self: *Client) void {
        if (self.pending_extension_runtime) |*runtime| {
            self.releaseMcpOAuthInterest(runtime) catch {};
        }
        for (self.extension_runtimes.items) |*runtime| {
            self.releaseMcpOAuthInterest(runtime) catch {};
        }
        for (self.sessions.items) |session| {
            if (session.id) |id| self.detachSessionBestEffort(id);
        }
    }

    pub fn stop(self: *Client) !void {
        if (runLegacyShutdown(self, real_shutdown_ops)) |err| return err;
    }

    pub fn stopDetailed(self: *Client) errors.DetailedResult(void) {
        return stopDetailedWithOps(
            self,
            real_detailed_shutdown_ops,
            self.transport.ownsRuntime() or
                (if (self.child) |child| child.id != null else false),
        );
    }

    fn stopDetailedWithOps(
        self: *Client,
        ops: DetailedShutdownOps,
        child_attempted: bool,
    ) errors.DetailedResult(void) {
        var session_count: usize = 0;
        for (self.sessions.items) |record| {
            session_count += @intFromBool(record.isActive());
        }
        const storage: []errors.Failure = self.allocator.alloc(
            errors.Failure,
            session_count + @intFromBool(child_attempted),
        ) catch &.{};
        var collector = ShutdownCollector{
            .allocator = self.allocator,
            .storage = storage,
        };
        const native_error = runDetailedShutdown(self, ops, &collector) orelse {
            if (collector.storage.len != 0) self.allocator.free(collector.storage);
            return .{ .success = {} };
        };
        return .{ .failure = .{
            .allocator = self.allocator,
            .native_error = native_error,
            .detail = .{ .shutdown = .{
                .sessions_attempted = session_count,
                .child_termination_attempted = child_attempted,
                .failure_storage = collector.storage,
                .failure_count = collector.count,
                .diagnostics_dropped = collector.dropped,
            } },
        } };
    }

    fn recordReadFailure(
        self: *Client,
        cause: anyerror,
    ) errors.DetailedError!errors.Failure {
        if (cause == error.OutOfMemory) return error.OutOfMemory;
        if (cause == error.EndOfStream) {
            self.transport_closed = true;
            if (self.last_exit) |exit| {
                return recordProcessExit(self.allocator, exit);
            }
            if (self.child_wait) |operation| {
                self.child_wait = null;
                const term = operation.wait(operation.context, self) catch |wait_error| {
                    return recordClientIo(self.allocator, .read, wait_error);
                };
                const exit = processExit(term);
                self.last_exit = exit;
                return recordProcessExit(self.allocator, exit);
            }
        }
        return recordClientIo(self.allocator, .read, cause);
    }

    fn handleLegacyTransportEof(self: *Client) void {
        var failure = self.recordReadFailure(error.EndOfStream) catch return;
        failure.deinit();
    }

    fn readTransportFrame(
        self: *Client,
        comptime failure_policy: FailurePolicy,
    ) errors.DetailedError!PolicyResult(failure_policy, []u8) {
        if (comptime failure_policy == .legacy) {
            return switch (try json_rpc.readFrameTransport(
                self.allocator,
                self.transportReader(),
            )) {
                .success => |body| .{ .success = body },
                .clean_eof => {
                    self.handleLegacyTransportEof();
                    return .{ .failure = .{ .native_error = error.MissingContentLength } };
                },
                .failure => |native_error| .{ .failure = .{ .native_error = native_error } },
            };
        }
        return switch (try json_rpc.readFrameDetailedTransport(
            self.allocator,
            self.transportReader(),
        )) {
            .success => |body| .{ .success = body },
            .failure => |failure_value| {
                var frame_failure = failure_value;
                if (isTransportEndOfStream(&frame_failure)) {
                    frame_failure.deinit();
                    if (self.transport.eofIsIdle()) {
                        return .{ .failure = try recordClientIo(
                            self.allocator,
                            .read,
                            error.EndOfStream,
                        ) };
                    }
                    return .{ .failure = try self.recordReadFailure(error.EndOfStream) };
                }
                return .{ .failure = frame_failure };
            },
        };
    }

    fn closedTransportFailure(
        self: *Client,
        comptime failure_policy: FailurePolicy,
    ) errors.DetailedError!PolicyFailure(failure_policy) {
        if (comptime failure_policy == .legacy) {
            return .{ .native_error = error.MissingContentLength };
        }
        if (self.last_exit) |exit| return recordProcessExit(self.allocator, exit);
        return recordClientIo(self.allocator, .read, error.EndOfStream);
    }

    fn connect(
        self: *Client,
        comptime failure_policy: FailurePolicy,
        token: ?[]const u8,
        client_info: ?ClientInfo,
    ) errors.DetailedError!PolicyResult(failure_policy, void) {
        const parsed = switch (try self.callImpl(failure_policy, struct {
            ok: bool,
            protocolVersion: std.json.Value,
            version: []const u8,
        }, "connect", .{
            .token = token,
            .clientInfo = toWireClientInfo(client_info),
        }, .generic)) {
            .success => |value| value,
            .failure => |failure| return .{ .failure = failure },
        };
        defer parsed.deinit();
        if (!parsed.value.ok) return .{ .failure = try policyFailure(
            failure_policy,
            error.ConnectRejected,
            recordConnectRejected,
            .{self.allocator},
        ) };
        const server_version = switch (parsed.value.protocolVersion) {
            .integer => |value| std.math.cast(u64, value) orelse
                return .{ .failure = try policyFailure(
                    failure_policy,
                    error.ProtocolVersionMismatch,
                    recordInvalidProtocolVersion,
                    .{ self.allocator, parsed.value.protocolVersion },
                ) },
            else => return .{ .failure = try policyFailure(
                failure_policy,
                error.ProtocolVersionMismatch,
                recordInvalidProtocolVersion,
                .{ self.allocator, parsed.value.protocolVersion },
            ) },
        };
        if (server_version != protocol.sdk_protocol_version)
            return .{ .failure = try policyFailure(
                failure_policy,
                error.ProtocolVersionMismatch,
                recordProtocolMismatch,
                .{ self.allocator, server_version },
            ) };
        return .{ .success = {} };
    }

    fn setBuiltinPluginDirectories(self: *Client, directories: []const []const u8) !void {
        if (directories.len == 0) return;
        const parsed = try self.call(std.json.Value, "plugins.builtin.set", .{
            .paths = directories,
        });
        parsed.deinit();
    }

    fn setSessionFilesystemProvider(self: *Client) !void {
        const config = self.session_filesystem orelse return;
        const parsed = try self.call(struct {
            success: bool,
        }, "sessionFs.setProvider", .{
            .initialCwd = config.initial_working_directory,
            .sessionStatePath = config.session_state_path,
            .conventions = @tagName(config.conventions),
            .capabilities = .{
                .sqlite = config.capabilities.sqlite,
            },
        });
        defer parsed.deinit();
        if (!parsed.value.success) return error.SessionFilesystemProviderRejected;
    }

    pub fn runtimePort(self: *const Client) ?u16 {
        return self.transport.port();
    }

    fn traceContext(self: *Client) runtime_types.TraceContext {
        const callback = self.on_get_trace_context orelse return .{};
        return callback.handler(callback.context) catch .{};
    }

    fn transportReader(self: *Client) *std.Io.Reader {
        if (self.transport == .none) return &self.reader.interface;
        return self.transport.reader();
    }

    fn transportWriter(self: *Client) *std.Io.Writer {
        if (self.transport == .none) return &self.writer.interface;
        return self.transport.writer();
    }

    fn transportWriterBuffer(self: *Client) []u8 {
        if (self.transport == .none) return self.writer_buffer;
        return self.transport.writerBuffer();
    }

    fn wipeTransportBuffers(self: *Client) void {
        if (self.transport == .none) {
            wipeSecret(self.reader_buffer);
            wipeSecret(self.writer_buffer);
            return;
        }
        switch (self.transport) {
            .none => {},
            .stdio_child => |*value| {
                wipeSecret(value.io.reader_buffer);
                wipeSecret(value.io.writer_buffer);
            },
            .tcp_child => |*value| {
                wipeSecret(value.io.reader_buffer);
                wipeSecret(value.io.writer_buffer);
            },
            .uri => |*value| {
                wipeSecret(value.io.reader_buffer);
                wipeSecret(value.io.writer_buffer);
            },
            .parent_stdio => |*value| {
                wipeSecret(value.reader_buffer);
                wipeSecret(value.writer_buffer);
            },
            .fixture => |value| {
                wipeSecret(value.reader_buffer);
                wipeSecret(value.writer_buffer);
            },
        }
    }

    pub fn createSession(
        self: *Client,
        config: session_types.CreateSessionConfig,
    ) !Session {
        return legacyResult(Session, self.createSessionEngine(.legacy, config));
    }

    pub fn createSessionDetailed(
        self: *Client,
        config: session_types.CreateSessionConfig,
    ) errors.DetailedError!errors.DetailedResult(Session) {
        return self.createSessionEngine(.detailed, config);
    }

    fn createSessionEngine(
        self: *Client,
        comptime failure_policy: FailurePolicy,
        config: session_types.CreateSessionConfig,
    ) errors.DetailedError!PolicyResult(failure_policy, Session) {
        validateLifecycleConfig(config) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "github_authentication", err },
            ) };
        validateSessionMode(self.mode, config.available_tools) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "available_tools", err },
            ) };
        self.validateSessionFilesystemFactory(
            config.create_session_filesystem_provider,
        ) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "create_session_filesystem_provider", err },
            ) };
        validateCustomAgents(config.custom_agents, config.agent) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "custom_agents", err },
            ) };
        ext.validate(config.extensions.common) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "extensions", err },
            ) };
        validateCustomAgentMcpServers(config.custom_agents) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "custom_agents", err },
            ) };
        provider.validateCapabilities(config.model_capabilities) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "model_capabilities", err },
            ) };

        var prepared_providers = provider.prepareSessionProviders(
            self.allocator,
            config.provider,
            config.providers,
            config.models,
        ) catch |err| {
            if (err == error.OutOfMemory) return error.OutOfMemory;
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "providers", err },
            ) };
        };
        defer prepared_providers.deinit(self.allocator);

        const server_assigned = config.cloud != null and config.session_id == null;
        const owned_session_id = if (config.session_id) |requested|
            try self.allocator.dupe(u8, requested)
        else if (server_assigned)
            null
        else
            generateSessionId(self.allocator, self.io) catch |err| {
                if (err == error.OutOfMemory) return error.OutOfMemory;
                return .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordClientIo,
                    .{ self.allocator, .write, err },
                ) };
            };
        if (owned_session_id) |session_id| {
            if (self.hasSession(session_id)) {
                self.allocator.free(session_id);
                return .{ .failure = try policyFailure(
                    failure_policy,
                    error.SessionAlreadyActive,
                    recordInvalidConfig,
                    .{ self.allocator, "session_id", error.SessionAlreadyActive },
                ) };
            }
        }
        self.beginSessionRecord(owned_session_id, null) catch |err| {
            if (err == error.OutOfMemory) return error.OutOfMemory;
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "session_id", err },
            ) };
        };
        var lifecycle_committed = false;
        var lifecycle_rpc_dispatched = false;
        var owned_detach_on_failure: ?[]u8 = null;
        defer if (owned_detach_on_failure) |id| self.allocator.free(id);
        var detach_on_failure: ?[]const u8 = owned_session_id;
        defer if (!lifecycle_committed) {
            self.rollbackProviderTokens();
            self.rollbackExtensionRuntime();
            if (lifecycle_rpc_dispatched) {
                if (detach_on_failure) |detach_id|
                    self.detachSessionBestEffort(detach_id);
            }
            self.rollbackSessionRecord();
        };

        var extension_values = ExtensionWireValues.init(self.allocator);
        defer extension_values.deinit();
        extension_values.lowerCustomAgents(config.custom_agents) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "custom_agents", err },
            ) };
        var parsed_parameters: std.ArrayList(std.json.Parsed(std.json.Value)) = .empty;
        defer {
            for (parsed_parameters.items) |parsed| parsed.deinit();
            parsed_parameters.deinit(self.allocator);
        }
        var tools: std.ArrayList(WireTool) = .empty;
        defer tools.deinit(self.allocator);
        appendWireTools(self.allocator, config.tools, &parsed_parameters, &tools) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "tools", err },
            ) };

        extension_values.lower(config.extensions.common) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "extensions", err },
            ) };
        extension_values.lowerHostInjection(
            config.feature_flags,
            config.exp_assignments,
        ) catch |err| return .{ .failure = try policyFailure(
            failure_policy,
            err,
            recordInvalidConfig,
            .{ self.allocator, "host_injection", err },
        ) };
        if (owned_session_id) |session_id| {
            self.beginProviderTokens(session_id, prepared_providers.token_bindings) catch |err|
                return .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordInvalidConfig,
                    .{ self.allocator, "providers", err },
                ) };
            errdefer self.rollbackProviderTokens();
        }
        self.beginExtensionRuntime(owned_session_id, config, &.{}) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "extensions", err },
            ) };
        errdefer self.rollbackExtensionRuntime();
        self.installGitHubTokenProvider(&extension_values) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "git_hub_token_provider", err },
            ) };
        var filesystem_session_id: ?[]const u8 = owned_session_id;
        if (filesystem_session_id) |session_id| {
            self.beginSessionFilesystem(
                session_id,
                config.create_session_filesystem_provider,
            ) catch |err|
                return .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordInvalidConfig,
                    .{ self.allocator, "create_session_filesystem_provider", err },
                ) };
        }
        defer if (!lifecycle_committed) {
            if (filesystem_session_id) |session_id|
                self.session_filesystems.rollback(self.allocator, session_id);
        };

        var request = buildPreparedCreateSessionRequest(
            owned_session_id,
            config,
            tools.items,
            &extension_values,
            prepared_providers,
            self.mode,
        ) catch |err| return .{ .failure = try policyFailure(
            failure_policy,
            err,
            recordInvalidConfig,
            .{ self.allocator, "session", err },
        ) };
        const trace_context = self.traceContext();
        request.traceparent = trace_context.traceparent;
        request.tracestate = trace_context.tracestate;
        const parsed = switch (try self.callImplTrackingDispatch(
            failure_policy,
            WireSessionLifecycleResponse,
            "session.create",
            request,
            if (owned_session_id) |session_id|
                .{ .session = .{ .session_id = session_id } }
            else
                .generic,
            &lifecycle_rpc_dispatched,
            null,
            null,
        )) {
            .success => |value| value,
            .failure => |failure| {
                if (isRpcRejection(failure_policy, failure))
                    lifecycle_rpc_dispatched = false;
                return .{ .failure = failure };
            },
        };
        defer {
            wipeLifecycleResponseSecrets(parsed.value);
            parsed.deinit();
        }
        const returned_id = parsed.value.sessionId orelse
            return .{ .failure = try policyFailure(
                failure_policy,
                error.MissingSessionId,
                recordInvalidConfig,
                .{ self.allocator, "sessionId", error.MissingSessionId },
            ) };
        if (owned_session_id) |session_id| {
            if (!std.mem.eql(u8, session_id, returned_id)) {
                if (!self.hasSession(returned_id)) {
                    owned_detach_on_failure = try self.allocator.dupe(u8, returned_id);
                    detach_on_failure = owned_detach_on_failure;
                }
                return .{ .failure = try policyFailure(
                    failure_policy,
                    error.SessionIdMismatch,
                    recordInvalidConfig,
                    .{ self.allocator, "sessionId", error.SessionIdMismatch },
                ) };
            }
        } else {
            if (returned_id.len == 0 or self.hasSession(returned_id))
                return .{ .failure = try policyFailure(
                    failure_policy,
                    error.InvalidServerAssignedSessionId,
                    recordInvalidConfig,
                    .{ self.allocator, "sessionId", error.InvalidServerAssignedSessionId },
                ) };
        }
        self.prepareSessionCommit(returned_id, parsed.value.workspacePath) catch |err| {
            if (err == error.OutOfMemory) return error.OutOfMemory;
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "workspacePath", err },
            ) };
        };
        const runtime_session_id = self.pending_session.?.id.?;
        detach_on_failure = runtime_session_id;
        if (server_assigned) {
            self.bindPendingRuntimeSessionId(runtime_session_id) catch |err|
                return .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordInvalidConfig,
                    .{ self.allocator, "sessionId", err },
                ) };
            self.beginProviderTokens(
                runtime_session_id,
                prepared_providers.token_bindings,
            ) catch |err| return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "providers", err },
            ) };
            self.beginSessionFilesystem(
                runtime_session_id,
                config.create_session_filesystem_provider,
            ) catch |err| return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "create_session_filesystem_provider", err },
            ) };
            filesystem_session_id = runtime_session_id;
        }
        switch (try self.updateSessionOptionsForMode(
            failure_policy,
            runtime_session_id,
            config,
        )) {
            .success => {},
            .failure => |failure| return .{ .failure = failure },
        }
        self.prepareExtensionRuntimeCommit(runtime_session_id, parsed.value, &.{}) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "extensions", err },
            ) };
        const session_index = self.commitSessionRecord() catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "extensions", err },
            ) };
        self.session_filesystems.commitReplacement(self.allocator, runtime_session_id);
        self.commitProviderTokens();
        lifecycle_committed = true;
        return .{ .success = self.sessionHandle(session_index) };
    }

    pub fn resumeSession(
        self: *Client,
        session_id: []const u8,
        config: session_types.ResumeSessionConfig,
    ) !Session {
        return legacyResult(
            Session,
            self.resumeSessionWithEnvironment(.legacy, session_id, config, &.{}),
        );
    }

    pub fn resumeSessionDetailed(
        self: *Client,
        session_id: []const u8,
        config: session_types.ResumeSessionConfig,
    ) errors.DetailedError!errors.DetailedResult(Session) {
        return self.resumeSessionWithEnvironment(.detailed, session_id, config, &.{});
    }

    /// Deprecated compatibility wrapper. Use `resumeSession`.
    pub fn joinSession(
        self: *Client,
        session_id: []const u8,
        config: session_types.SessionConfig,
    ) !Session {
        return self.resumeSession(session_id, resumeConfigFromCreate(config));
    }

    /// Deprecated compatibility wrapper. Use `resumeSessionDetailed`.
    pub fn joinSessionDetailed(
        self: *Client,
        session_id: []const u8,
        config: session_types.SessionConfig,
    ) errors.DetailedError!errors.DetailedResult(Session) {
        return self.resumeSessionWithEnvironment(
            .detailed,
            session_id,
            resumeConfigFromCreate(config),
            &.{},
        );
    }

    fn resumeSessionWithEnvironment(
        self: *Client,
        comptime failure_policy: FailurePolicy,
        session_id: []const u8,
        config: session_types.ResumeSessionConfig,
        requested_environment_variables: []const []const u8,
    ) errors.DetailedError!PolicyResult(failure_policy, Session) {
        return self.resumeSessionWithEnvironmentAndFactories(
            failure_policy,
            session_id,
            config,
            requested_environment_variables,
            null,
        );
    }

    fn resumeSessionWithEnvironmentAndFactories(
        self: *Client,
        comptime failure_policy: FailurePolicy,
        session_id: []const u8,
        config: session_types.ResumeSessionConfig,
        requested_environment_variables: []const []const u8,
        factories: ?[]const factory_types.AgentFactory,
    ) errors.DetailedError!PolicyResult(failure_policy, Session) {
        validateLifecycleConfig(config) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "github_authentication", err },
            ) };
        validateSessionMode(self.mode, config.available_tools) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "available_tools", err },
            ) };
        validateCustomAgents(config.custom_agents, config.agent) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "custom_agents", err },
            ) };
        self.validateSessionFilesystemFactory(
            config.create_session_filesystem_provider,
        ) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "create_session_filesystem_provider", err },
            ) };
        ext.validate(config.extensions.common) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "extensions", err },
            ) };
        if (factories) |definitions| {
            factory_types.validateFactories(definitions) catch |err|
                return .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordInvalidConfig,
                    .{ self.allocator, "extensions.factories", err },
                ) };
        }
        validateCustomAgentMcpServers(config.custom_agents) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "custom_agents", err },
            ) };
        provider.validateCapabilities(config.model_capabilities) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "model_capabilities", err },
            ) };

        var prepared_providers = provider.prepareSessionProviders(
            self.allocator,
            config.provider,
            config.providers,
            config.models,
        ) catch |err| {
            if (err == error.OutOfMemory) return error.OutOfMemory;
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "providers", err },
            ) };
        };
        defer prepared_providers.deinit(self.allocator);

        const existing_session_index = self.findSessionIndex(session_id);
        const candidate_session_id = try self.allocator.dupe(u8, session_id);
        self.beginSessionRecord(candidate_session_id, existing_session_index) catch |err| {
            if (err == error.OutOfMemory) return error.OutOfMemory;
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "session_id", err },
            ) };
        };
        const runtime_session_id = self.pending_session.?.id.?;
        var lifecycle_committed = false;
        var lifecycle_rpc_dispatched = false;
        var owned_detach_on_failure: ?[]u8 = null;
        defer if (owned_detach_on_failure) |id| self.allocator.free(id);
        var detach_on_failure: ?[]const u8 =
            if (existing_session_index == null) runtime_session_id else null;
        defer if (!lifecycle_committed) {
            if (lifecycle_rpc_dispatched)
                self.quarantineSessionCredentials(runtime_session_id);
            self.rollbackProviderTokens();
            self.rollbackExtensionRuntime();
            if (lifecycle_rpc_dispatched) {
                if (detach_on_failure) |detach_id|
                    self.detachSessionBestEffort(detach_id);
            }
            self.rollbackSessionRecord();
        };

        var extension_values = ExtensionWireValues.init(self.allocator);
        defer extension_values.deinit();
        extension_values.lowerCustomAgents(config.custom_agents) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "custom_agents", err },
            ) };
        var parsed_parameters: std.ArrayList(std.json.Parsed(std.json.Value)) = .empty;
        defer {
            for (parsed_parameters.items) |parsed| parsed.deinit();
            parsed_parameters.deinit(self.allocator);
        }
        var tools: std.ArrayList(WireTool) = .empty;
        defer tools.deinit(self.allocator);
        appendWireTools(self.allocator, config.tools, &parsed_parameters, &tools) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "tools", err },
            ) };

        extension_values.lower(config.extensions.common) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "extensions", err },
            ) };
        extension_values.lowerFactories(factories) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "extensions.factories", err },
            ) };
        extension_values.lowerHostInjection(
            config.feature_flags,
            config.exp_assignments,
        ) catch |err| return .{ .failure = try policyFailure(
            failure_policy,
            err,
            recordInvalidConfig,
            .{ self.allocator, "host_injection", err },
        ) };

        self.beginProviderTokens(runtime_session_id, prepared_providers.token_bindings) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "providers", err },
            ) };
        self.beginExtensionRuntimeWithFactories(
            runtime_session_id,
            config,
            config.extensions.open_canvases orelse &.{},
            factories orelse &.{},
        ) catch |err| return .{ .failure = try policyFailure(
            failure_policy,
            err,
            recordInvalidConfig,
            .{ self.allocator, "extensions", err },
        ) };
        errdefer self.rollbackExtensionRuntime();
        self.installGitHubTokenProvider(&extension_values) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "git_hub_token_provider", err },
            ) };
        self.beginSessionFilesystem(
            runtime_session_id,
            config.create_session_filesystem_provider,
        ) catch |err| return .{ .failure = try policyFailure(
            failure_policy,
            err,
            recordInvalidConfig,
            .{ self.allocator, "create_session_filesystem_provider", err },
        ) };
        defer if (!lifecycle_committed)
            self.session_filesystems.rollback(self.allocator, runtime_session_id);

        var request = buildPreparedResumeSessionRequest(
            runtime_session_id,
            config,
            tools.items,
            &extension_values,
            requested_environment_variables,
            prepared_providers,
            self.mode,
        ) catch |err| return .{ .failure = try policyFailure(
            failure_policy,
            err,
            recordInvalidConfig,
            .{ self.allocator, "session", err },
        ) };
        const trace_context = self.traceContext();
        request.traceparent = trace_context.traceparent;
        request.tracestate = trace_context.tracestate;
        const parsed = switch (try self.callImplTrackingDispatch(
            failure_policy,
            WireSessionLifecycleResponse,
            "session.resume",
            request,
            .{ .session = .{ .session_id = session_id } },
            &lifecycle_rpc_dispatched,
            null,
            null,
        )) {
            .success => |value| value,
            .failure => |failure| {
                if (isRpcRejection(failure_policy, failure))
                    lifecycle_rpc_dispatched = false;
                return .{ .failure = failure };
            },
        };
        defer {
            wipeLifecycleResponseSecrets(parsed.value);
            parsed.deinit();
        }
        const returned_id = parsed.value.sessionId orelse
            return .{ .failure = try policyFailure(
                failure_policy,
                error.MissingSessionId,
                recordInvalidConfig,
                .{ self.allocator, "sessionId", error.MissingSessionId },
            ) };
        if (!std.mem.eql(u8, runtime_session_id, returned_id)) {
            if (!self.hasSession(returned_id)) {
                owned_detach_on_failure = try self.allocator.dupe(u8, returned_id);
                detach_on_failure = owned_detach_on_failure;
            }
            return .{ .failure = try policyFailure(
                failure_policy,
                error.SessionIdMismatch,
                recordInvalidConfig,
                .{ self.allocator, "sessionId", error.SessionIdMismatch },
            ) };
        }
        self.prepareSessionCommit(runtime_session_id, parsed.value.workspacePath) catch |err| {
            if (err == error.OutOfMemory) return error.OutOfMemory;
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.allocator, "workspacePath", err },
            ) };
        };
        switch (try self.updateSessionOptionsForMode(
            failure_policy,
            runtime_session_id,
            config,
        )) {
            .success => {},
            .failure => |failure| return .{ .failure = failure },
        }
        self.prepareExtensionRuntimeCommit(
            runtime_session_id,
            parsed.value,
            requested_environment_variables,
        ) catch |err| return .{ .failure = try policyFailure(
            failure_policy,
            err,
            recordInvalidConfig,
            .{ self.allocator, "extensions", err },
        ) };
        const session_index = self.commitSessionRecord() catch |err|
            if (err == error.ReentrantRpcCall)
                return .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordReentrant,
                    .{ self.allocator, "session.resume" },
                ) }
            else
                return .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordInvalidConfig,
                    .{ self.allocator, "extensions", err },
                ) };
        self.session_filesystems.commitReplacement(self.allocator, runtime_session_id);
        self.commitProviderTokens();
        lifecycle_committed = true;
        return .{ .success = self.sessionHandle(session_index) };
    }

    fn updateSessionOptionsForMode(
        self: *Client,
        comptime failure_policy: FailurePolicy,
        session_id: []const u8,
        config: anytype,
    ) errors.DetailedError!PolicyResult(failure_policy, void) {
        if (self.mode != .empty and
            config.coauthor_enabled == null and
            config.manage_schedule_enabled == null)
        {
            return .{ .success = {} };
        }
        const empty_mode = self.mode == .empty;
        const parsed = switch (try self.callImpl(
            failure_policy,
            struct { success: bool },
            "session.options.update",
            SessionOptionsUpdateRequest{
                .sessionId = session_id,
                .skipCustomInstructions = if (empty_mode)
                    config.skip_custom_instructions orelse true
                else
                    null,
                .customAgentsLocalOnly = if (empty_mode)
                    config.custom_agents_local_only orelse true
                else
                    null,
                .coauthorEnabled = if (empty_mode) false else config.coauthor_enabled,
                .manageScheduleEnabled = if (empty_mode) false else config.manage_schedule_enabled,
                .installedPlugins = if (empty_mode) &.{} else null,
                .includedBuiltinSkills = if (empty_mode)
                    config.extensions.common.skills.included_builtin orelse &.{}
                else
                    null,
            },
            .{ .session = .{ .session_id = session_id } },
        )) {
            .success => |value| value,
            .failure => |failure| return .{ .failure = failure },
        };
        defer parsed.deinit();
        if (!parsed.value.success) return .{ .failure = try policyFailure(
            failure_policy,
            error.SessionOptionsUpdateRejected,
            recordInvalidConfig,
            .{ self.allocator, "session.options.update", error.SessionOptionsUpdateRejected },
        ) };
        return .{ .success = {} };
    }

    fn detachSessionBestEffort(self: *Client, session_id: []const u8) void {
        const parsed = self.call(struct {
            success: bool,
            @"error": ?[]const u8 = null,
        }, "session.detach", .{
            .sessionId = session_id,
        }) catch return;
        parsed.deinit();
    }

    fn beginExtensionRuntime(
        self: *Client,
        session_id: ?[]const u8,
        config: anytype,
        open_canvases: []const ext.OpenCanvas,
    ) !void {
        return self.beginExtensionRuntimeWithFactories(
            session_id,
            config,
            open_canvases,
            &.{},
        );
    }

    fn beginExtensionRuntimeWithFactories(
        self: *Client,
        session_id: ?[]const u8,
        config: anytype,
        open_canvases: []const ext.OpenCanvas,
        factories: []const factory_types.AgentFactory,
    ) !void {
        if (self.pending_extension_runtime != null)
            return error.SessionLifecycleAlreadyInProgress;
        self.pending_extension_runtime = try SessionExtensionRuntime.initWithFactories(
            self.allocator,
            session_id,
            config,
            open_canvases,
            factories,
        );
    }

    fn installGitHubTokenProvider(
        self: *Client,
        values: *ExtensionWireValues,
    ) !void {
        const extension_runtime = if (self.pending_extension_runtime) |*value|
            value
        else
            return error.MissingExtensionRuntime;
        if (extension_runtime.git_hub_token_provider == null) return;
        const registration_id = try generateSessionId(self.allocator, self.io);
        extension_runtime.git_hub_token_registration_id = registration_id;
        values.git_hub_token_registration_id = registration_id;
    }

    fn rollbackExtensionRuntime(self: *Client) void {
        if (isCurrentRuntimeCallback(self)) {
            self.extension_runtimes_mutex.lockUncancelable(self.io);
            self.runtime_callbacks_blocked = true;
            self.runtime_callbacks_ready.reset();
            self.runtime_rollback_pending = true;
            self.extension_runtimes_mutex.unlock(self.io);
            return;
        }
        self.blockRuntimeCallbacks();
        defer self.unblockRuntimeCallbacks();
        self.rollbackExtensionRuntimeNow();
    }

    fn rollbackExtensionRuntimeNow(self: *Client) void {
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        var pending = self.pending_extension_runtime;
        self.pending_extension_runtime = null;
        self.extension_runtimes_mutex.unlock(self.io);
        if (pending) |*runtime| {
            runtime.quarantineCredentials(self.allocator);
            self.releaseMcpOAuthInterest(runtime) catch |err|
                std.log.warn("failed to release MCP OAuth interest during rollback: {s}", .{@errorName(err)});
            runtime.deinit(self.allocator);
        }
        if (self.pending_provider_tokens) |provider_tokens| {
            self.pending_provider_tokens = null;
            provider_tokens.deinit(self.allocator);
        }
    }

    fn quarantinePendingCredentials(self: *Client) void {
        self.blockRuntimeCallbacks();
        defer self.unblockRuntimeCallbacks();
        if (self.pending_extension_runtime) |*runtime| {
            runtime.quarantineCredentials(self.allocator);
        }
        if (self.pending_provider_tokens) |pending| {
            self.pending_provider_tokens = null;
            pending.deinit(self.allocator);
        }
    }

    fn beginRuntimeCallback(
        self: *Client,
        scope: *RuntimeCallbackScope,
    ) void {
        while (true) {
            self.extension_runtimes_mutex.lockUncancelable(self.io);
            if (!self.runtime_callbacks_blocked) {
                self.runtime_callback_count += 1;
                self.runtime_callbacks_drained.reset();
                self.extension_runtimes_mutex.unlock(self.io);
                scope.* = .{
                    .client = self,
                    .previous = active_runtime_callback,
                };
                active_runtime_callback = scope;
                return;
            }
            self.extension_runtimes_mutex.unlock(self.io);
            self.runtime_callbacks_ready.waitUncancelable(self.io);
        }
    }

    fn acquireTransferredRuntimeCallback(self: *Client) void {
        while (true) {
            self.extension_runtimes_mutex.lockUncancelable(self.io);
            if (!self.runtime_callbacks_blocked) {
                self.runtime_callback_count += 1;
                self.runtime_callbacks_drained.reset();
                self.extension_runtimes_mutex.unlock(self.io);
                return;
            }
            self.extension_runtimes_mutex.unlock(self.io);
            self.runtime_callbacks_ready.waitUncancelable(self.io);
        }
    }

    fn enterTransferredRuntimeCallback(
        self: *Client,
        scope: *RuntimeCallbackScope,
    ) void {
        scope.* = .{ .client = self, .previous = active_runtime_callback };
        active_runtime_callback = scope;
    }

    fn endRuntimeCallback(
        self: *Client,
        scope: *RuntimeCallbackScope,
    ) void {
        std.debug.assert(active_runtime_callback == scope);
        active_runtime_callback = scope.previous;
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        std.debug.assert(self.runtime_callback_count != 0);
        self.runtime_callback_count -= 1;
        const finish_rollback =
            self.runtime_callback_count == 0 and self.runtime_rollback_pending;
        if (self.runtime_callback_count == 0)
            self.runtime_callbacks_drained.set(self.io);
        self.extension_runtimes_mutex.unlock(self.io);
        if (finish_rollback) {
            self.rollbackExtensionRuntimeNow();
            self.extension_runtimes_mutex.lockUncancelable(self.io);
            self.runtime_rollback_pending = false;
            self.runtime_callbacks_blocked = false;
            self.runtime_callbacks_ready.set(self.io);
            self.extension_runtimes_mutex.unlock(self.io);
        }
    }

    fn blockRuntimeCallbacks(self: *Client) void {
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        self.runtime_callbacks_blocked = true;
        self.runtime_callbacks_ready.reset();
        while (self.runtime_callback_count != 0) {
            self.extension_runtimes_mutex.unlock(self.io);
            self.runtime_callbacks_drained.waitUncancelable(self.io);
            self.extension_runtimes_mutex.lockUncancelable(self.io);
        }
        self.extension_runtimes_mutex.unlock(self.io);
    }

    fn unblockRuntimeCallbacks(self: *Client) void {
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        self.runtime_callbacks_blocked = false;
        self.runtime_callbacks_ready.set(self.io);
        self.extension_runtimes_mutex.unlock(self.io);
    }

    fn isCurrentRuntimeCallback(self: *Client) bool {
        var current = active_runtime_callback;
        while (current) |scope| {
            if (scope.client == self) return true;
            current = scope.previous;
        }
        return false;
    }

    fn quarantineSessionCredentials(self: *Client, session_id: []const u8) void {
        for (self.extension_runtimes.items) |*runtime| {
            if (runtime.session_id != null and
                std.mem.eql(u8, runtime.session_id.?, session_id))
            {
                runtime.quarantineCredentials(self.allocator);
                break;
            }
        }
        var index: usize = 0;
        while (index < self.provider_tokens.items.len) {
            if (std.mem.eql(u8, self.provider_tokens.items[index].session_id, session_id)) {
                const registered = self.provider_tokens.orderedRemove(index);
                registered.deinit(self.allocator);
            } else {
                index += 1;
            }
        }
        self.quarantinePendingCredentials();
    }

    fn bindPendingRuntimeSessionId(self: *Client, session_id: []const u8) !void {
        const runtime = if (self.pending_extension_runtime) |*value|
            value
        else
            return error.MissingExtensionRuntime;
        if (runtime.session_id) |registered_id| {
            if (!std.mem.eql(u8, registered_id, session_id))
                return error.UnexpectedSessionId;
            return;
        }
        runtime.session_id = try self.allocator.dupe(u8, session_id);
    }

    fn beginSessionFilesystem(
        self: *Client,
        session_id: []const u8,
        supplied_factory: ?runtime_types.SessionFilesystemProviderFactory,
    ) !void {
        const config = self.session_filesystem orelse return;
        const factory = supplied_factory orelse unreachable;
        try self.session_filesystems.begin(
            self.allocator,
            session_id,
            factory,
            config.capabilities.sqlite,
        );
    }

    fn validateSessionFilesystemFactory(
        self: *const Client,
        supplied_factory: ?runtime_types.SessionFilesystemProviderFactory,
    ) !void {
        if (self.session_filesystem != null and supplied_factory == null)
            return error.MissingSessionFilesystemProviderFactory;
    }

    fn prepareExtensionRuntimeCommit(
        self: *Client,
        session_id: []const u8,
        response: WireSessionLifecycleResponse,
        requested_environment_variables: []const []const u8,
    ) !void {
        const runtime = if (self.pending_extension_runtime) |*value| value else return error.MissingExtensionRuntime;
        if (runtime.session_id) |id| {
            if (!std.mem.eql(u8, id, session_id)) return error.UnexpectedSessionId;
        } else {
            runtime.session_id = try self.allocator.dupe(u8, session_id);
        }
        runtime.capabilities = parseCapabilities(response.capabilities);
        if (response.openCanvases) |canvases| {
            for (runtime.open_canvases.items) |canvas| ext.freeOpenCanvas(self.allocator, canvas);
            runtime.open_canvases.clearRetainingCapacity();
            for (canvases) |canvas| {
                const clone = try cloneWireOpenCanvas(self.allocator, canvas);
                errdefer ext.freeOpenCanvas(self.allocator, clone);
                try runtime.open_canvases.append(self.allocator, clone);
            }
        }
        if (response.grantedEnvironmentVariables) |grants_value| {
            const grants = switch (grants_value) {
                .object => |value| value,
                else => return error.InvalidGrantedEnvironmentVariables,
            };
            var iterator = grants.iterator();
            while (iterator.next()) |entry| {
                var requested = false;
                for (requested_environment_variables) |name| {
                    if (std.mem.eql(u8, name, entry.key_ptr.*)) {
                        requested = true;
                        break;
                    }
                }
                if (!requested) continue;
                const value = switch (entry.value_ptr.*) {
                    .string => |item| item,
                    else => return error.InvalidGrantedEnvironmentVariables,
                };
                const name_copy = try self.allocator.dupe(u8, entry.key_ptr.*);
                errdefer self.allocator.free(name_copy);
                const value_copy = try self.allocator.dupe(u8, value);
                errdefer {
                    wipeSecret(value_copy);
                    self.allocator.free(value_copy);
                }
                try runtime.granted_environment_variables.append(self.allocator, .{
                    .name = name_copy,
                    .value = value_copy,
                });
            }
        }
        try self.finishExtensionRuntimeCommit(session_id);
    }

    fn finishExtensionRuntimeCommit(
        self: *Client,
        session_id: []const u8,
    ) !void {
        const owned_session_id = try self.allocator.dupe(u8, session_id);
        defer self.allocator.free(owned_session_id);
        const runtime = if (self.pending_extension_runtime) |*value| value else return error.MissingExtensionRuntime;
        const runtime_session_id = runtime.session_id orelse return error.MissingSessionId;
        if (!std.mem.eql(u8, runtime_session_id, owned_session_id))
            return error.UnexpectedSessionId;
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        const existing_index = self.findCommittedExtensionRuntimeIndex(owned_session_id);
        const existing_interest = if (existing_index) |index|
            std.meta.activeTag(self.extension_runtimes.items[index].mcp_oauth_interest)
        else
            null;
        if (existing_index == null)
            self.extension_runtimes.ensureUnusedCapacity(self.allocator, 1) catch |err| {
                self.extension_runtimes_mutex.unlock(self.io);
                return err;
            };
        self.extension_runtimes_mutex.unlock(self.io);
        if (runtime.mcp_auth_handler != null and
            (existing_interest == null or existing_interest.? == .none))
        {
            try self.registerMcpOAuthInterest(runtime);
        }
        if (runtime.mcp_auth_handler == null and existing_index != null)
            try self.releaseCommittedMcpOAuthInterest(owned_session_id);
    }

    fn commitPreparedExtensionRuntimeLocked(
        self: *Client,
        owned_session_id: []const u8,
    ) void {
        const pending = &self.pending_extension_runtime.?;
        const pending_session_id = pending.session_id.?;
        std.debug.assert(std.mem.eql(u8, pending_session_id, owned_session_id));
        const existing_index = self.findCommittedExtensionRuntimeIndex(owned_session_id);
        if (existing_index == null) {
            const committed = self.pending_extension_runtime.?;
            self.pending_extension_runtime = null;
            self.extension_runtimes.appendAssumeCapacity(committed);
            return;
        }
        const existing = &self.extension_runtimes.items[existing_index.?];
        if (pending.mcp_auth_handler != null and pending.mcp_oauth_interest == .none) {
            pending.mcp_oauth_interest = existing.mcp_oauth_interest;
            existing.mcp_oauth_interest = .none;
        }
        pending.event_queue_failure = existing.event_queue_failure;
        const replacement = self.pending_extension_runtime.?;
        self.pending_extension_runtime = null;
        existing.deinit(self.allocator);
        self.extension_runtimes.items[existing_index.?] = replacement;
    }

    fn releaseCommittedMcpOAuthInterest(
        self: *Client,
        session_id: []const u8,
    ) !void {
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        const index = self.findCommittedExtensionRuntimeIndex(session_id) orelse {
            self.extension_runtimes_mutex.unlock(self.io);
            return error.MissingExtensionRuntime;
        };
        const runtime = &self.extension_runtimes.items[index];
        var interest = switch (runtime.mcp_oauth_interest) {
            .none => {
                self.extension_runtimes_mutex.unlock(self.io);
                return;
            },
            .restore_required => {
                self.extension_runtimes_mutex.unlock(self.io);
                return error.EventInterestRestoreRequired;
            },
            .registering, .releasing => {
                self.extension_runtimes_mutex.unlock(self.io);
                return error.EventInterestOperationInProgress;
            },
            .registered => |owned| owned,
        };
        runtime.mcp_oauth_interest = .none;
        self.extension_runtimes_mutex.unlock(self.io);
        self.releaseMcpOAuthInterestOwner(session_id, &interest) catch |err| {
            self.extension_runtimes_mutex.lockUncancelable(self.io);
            if (self.findCommittedExtensionRuntime(session_id)) |current| {
                if (current.mcp_oauth_interest == .none) {
                    current.mcp_oauth_interest = .{ .registered = interest };
                    self.extension_runtimes_mutex.unlock(self.io);
                    return err;
                }
            }
            self.extension_runtimes_mutex.unlock(self.io);
            interest.deinitSecure();
            return err;
        };
        interest.deinitSecure();
    }

    fn registerMcpOAuthInterest(
        self: *Client,
        runtime: *SessionExtensionRuntime,
    ) !void {
        if (runtime.mcp_oauth_interest == .registered) return;
        const prior_state: @TypeOf(@as(McpOAuthInterest, undefined).registering) =
            switch (runtime.mcp_oauth_interest) {
                .none => .initial,
                .restore_required => .restore,
                .registering, .releasing => return error.EventInterestOperationInProgress,
                .registered => unreachable,
            };
        const session_id = runtime.session_id orelse return error.MissingSessionId;
        const runtime_location = self.mcpOAuthRuntimeLocation(runtime);
        const owned_session_id = try self.allocator.dupe(u8, session_id);
        defer self.allocator.free(owned_session_id);
        runtime.mcp_oauth_interest = .{ .registering = prior_state };
        errdefer if (self.resolveMcpOAuthRuntime(owned_session_id, runtime_location)) |current| {
            if (current.mcp_oauth_interest == .registering) {
                current.mcp_oauth_interest = switch (prior_state) {
                    .initial => .none,
                    .restore => .restore_required,
                };
            }
        };
        const parsed = try self.call(WireMcpOAuthInterest, "session.eventLog.registerInterest", .{
            .sessionId = owned_session_id,
            .eventType = "mcp.oauth_required",
        });
        try self.adoptMcpOAuthInterest(
            owned_session_id,
            runtime_location,
            parsed,
        );
    }

    fn adoptMcpOAuthInterest(
        self: *Client,
        session_id: []const u8,
        runtime_location: McpOAuthRuntimeLocation,
        parsed: std.json.Parsed(WireMcpOAuthInterest),
    ) !void {
        var interest = OwnedMcpOAuthInterest{ .response = parsed };
        const current = self.resolveMcpOAuthRuntime(
            session_id,
            runtime_location,
        ) orelse {
            interest.deinitSecure();
            return error.MissingExtensionRuntime;
        };
        std.debug.assert(current.mcp_oauth_interest == .registering);
        current.mcp_oauth_interest = .{ .registered = interest };
    }

    fn releaseMcpOAuthInterest(
        self: *Client,
        runtime: *SessionExtensionRuntime,
    ) !void {
        const interest = switch (runtime.mcp_oauth_interest) {
            .none => return,
            .restore_required => return error.EventInterestRestoreRequired,
            .registering, .releasing => return error.EventInterestOperationInProgress,
            .registered => |owned| owned,
        };
        const session_id = runtime.session_id orelse
            return error.MissingSessionId;
        const runtime_location = self.mcpOAuthRuntimeLocation(runtime);
        const owned_session_id = try self.allocator.dupe(u8, session_id);
        defer self.allocator.free(owned_session_id);
        runtime.mcp_oauth_interest = .{ .releasing = interest };
        errdefer if (self.resolveMcpOAuthRuntime(owned_session_id, runtime_location)) |current| {
            if (current.mcp_oauth_interest == .releasing) {
                const retained = current.mcp_oauth_interest.releasing;
                current.mcp_oauth_interest = .{ .registered = retained };
            }
        };
        try self.releaseMcpOAuthInterestOwner(
            owned_session_id,
            &interest,
        );
        const current = self.resolveMcpOAuthRuntime(
            owned_session_id,
            runtime_location,
        ) orelse return error.MissingExtensionRuntime;
        std.debug.assert(current.mcp_oauth_interest == .releasing);
        var released = current.mcp_oauth_interest.releasing;
        current.mcp_oauth_interest = .none;
        released.deinitSecure();
    }

    fn releaseMcpOAuthInterestOwner(
        self: *Client,
        session_id: []const u8,
        interest: *const OwnedMcpOAuthInterest,
    ) !void {
        const parsed = try self.call(struct {
            success: bool,
        }, "session.eventLog.releaseInterest", .{
            .sessionId = session_id,
            .handle = interest.handle(),
        });
        defer parsed.deinit();
        if (!parsed.value.success) return error.EventInterestNotReleased;
    }

    fn resolveMcpOAuthRuntime(
        self: *Client,
        session_id: []const u8,
        location: McpOAuthRuntimeLocation,
    ) ?*SessionExtensionRuntime {
        switch (location) {
            .pending => {
                const pending = if (self.pending_extension_runtime) |*runtime|
                    runtime
                else
                    return null;
                const pending_session_id = pending.session_id orelse return null;
                if (!std.mem.eql(u8, pending_session_id, session_id)) return null;
                return pending;
            },
            .committed => {
                for (self.extension_runtimes.items) |*runtime| {
                    const runtime_session_id = runtime.session_id orelse continue;
                    if (std.mem.eql(u8, runtime_session_id, session_id)) return runtime;
                }
                return null;
            },
            .external => |runtime| return runtime,
        }
    }

    fn mcpOAuthRuntimeLocation(
        self: *Client,
        runtime: *SessionExtensionRuntime,
    ) McpOAuthRuntimeLocation {
        if (self.pending_extension_runtime) |*pending| {
            if (pending == runtime) return .pending;
        }
        for (self.extension_runtimes.items) |*committed| {
            if (committed == runtime) return .committed;
        }
        return .{ .external = runtime };
    }

    /// Joins a parent-selected extension session. The session id is injected by
    /// the parent runtime and is intentionally explicit in Zig's `initParent`
    /// API because `Client` does not own process-environment state.
    pub fn joinParentSession(
        self: *Client,
        session_id: []const u8,
        config: session_types.JoinSessionConfig,
    ) !JoinedSession {
        const owned_session_id = try self.allocator.dupe(u8, session_id);
        defer self.allocator.free(owned_session_id);
        const resume_config = resumeConfigFromJoin(config);
        const session = try legacyResult(
            Session,
            self.resumeSessionWithEnvironmentAndFactories(
                .legacy,
                owned_session_id,
                resume_config,
                config.extensions.requested_environment_variables,
                config.extensions.factories,
            ),
        );
        const grants = session.snapshotEnvironmentGrants(self.allocator) catch |err| {
            session.disconnect() catch |cleanup_err| {
                if (self.findExtensionRuntime(owned_session_id)) |runtime| {
                    self.releaseMcpOAuthInterest(runtime) catch |release_err|
                        std.log.warn("failed to release MCP OAuth interest after join cleanup: {s}", .{@errorName(release_err)});
                }
                self.removeSessionExpected(
                    session.record_index,
                    owned_session_id,
                    session.generation,
                ) catch |remove_err| switch (remove_err) {
                    error.SessionNotActive => {},
                    else => return remove_err,
                };
                return cleanup_err;
            };
            return err;
        };
        if (config.extensions.factories) |factories| {
            if (factories.len != 0) try self.ensurePump();
        }
        return .{
            .session = session,
            .grants = grants,
        };
    }

