    fn callCancelable(
        self: *Client,
        comptime Result: type,
        method: []const u8,
        params: anytype,
        cancellation: *std.Io.Event,
        dispatch_mutex: ?*std.Io.Mutex,
    ) !std.json.Parsed(Result) {
        if (cancellation.isSet()) return error.FactoryCancelled;
        try self.ensurePump();
        return legacyResult(
            std.json.Parsed(Result),
            self.callImplTrackingDispatch(
                .legacy,
                Result,
                method,
                params,
                .generic,
                null,
                cancellation,
                dispatch_mutex,
            ),
        );
    }

    fn callImpl(
        self: *Client,
        comptime failure_policy: FailurePolicy,
        comptime Result: type,
        method: []const u8,
        params: anytype,
        context: OperationContext,
    ) errors.DetailedError!PolicyResult(failure_policy, std.json.Parsed(Result)) {
        return self.callImplTrackingDispatch(
            failure_policy,
            Result,
            method,
            params,
            context,
            null,
            null,
            null,
        );
    }

    fn callImplTrackingDispatch(
        self: *Client,
        comptime failure_policy: FailurePolicy,
        comptime Result: type,
        method: []const u8,
        params: anytype,
        context: OperationContext,
        dispatched: ?*bool,
        cancellation: ?*std.Io.Event,
        dispatch_mutex: ?*std.Io.Mutex,
    ) errors.DetailedError!PolicyResult(failure_policy, std.json.Parsed(Result)) {
        if (self.isRpcHandlerThread())
            return .{ .failure = try policyFailure(
                failure_policy,
                error.ReentrantRpcCall,
                recordReentrant,
                .{ self.allocator, method },
            ) };
        if (self.transport_closed)
            return .{ .failure = try self.closedTransportFailure(failure_policy) };
        const id = self.nextRequestId();

        const request = json_rpc.encodeRequest(self.allocator, id, method, params) catch |err| {
            if (err == error.OutOfMemory) return error.OutOfMemory;
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordClientJson,
                .{ self.allocator, .write, err },
            ) };
        };
        defer {
            wipeSecret(request);
            self.allocator.free(request);
        }
        if (self.beginRpcCall()) {
            return self.callPumped(
                failure_policy,
                Result,
                id,
                method,
                request,
                context,
                dispatched,
                cancellation,
                dispatch_mutex,
            );
        }
        defer self.endDirectRpcCall();
        if (self.direct_request_count == self.direct_request_ids.len)
            return .{ .failure = try policyFailure(
                failure_policy,
                error.ReentrantRpcCall,
                recordReentrant,
                .{ self.allocator, method },
            ) };
        self.direct_request_ids[self.direct_request_count] = id;
        self.direct_request_count += 1;
        defer {
            std.debug.assert(self.direct_request_count != 0);
            std.debug.assert(self.direct_request_ids[self.direct_request_count - 1] == id);
            self.direct_request_count -= 1;
            self.discardBufferedResponse(id);
        }
        if (dispatched) |value| value.* = true;
        writeFrameAndWipe(
            self.transportWriter(),
            self.transportWriterBuffer(),
            request,
        ) catch |err| return .{ .failure = try policyFailure(
            failure_policy,
            err,
            recordClientIo,
            .{ self.allocator, .write, err },
        ) };

        while (true) {
            const body = self.takeBufferedResponse(id) orelse
                switch (try self.readTransportFrame(failure_policy)) {
                    .success => |value| value,
                    .failure => |failure| return .{ .failure = failure },
                };
            var body_owned = true;
            defer if (body_owned) {
                wipeSecret(body);
                self.allocator.free(body);
            };
            const value = std.json.parseFromSlice(
                std.json.Value,
                self.allocator,
                body,
                .{},
            ) catch |err| {
                if (err == error.OutOfMemory) return error.OutOfMemory;
                return .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordInvalidJson,
                    .{ self.allocator, err },
                ) };
            };
            defer {
                wipeJsonStrings(value.value);
                value.deinit();
            }
            const inbound = switch (try parseInboundMessage(
                failure_policy,
                self.allocator,
                value.value,
            )) {
                .success => |message| message,
                .failure => |failure| return .{ .failure = failure },
            };

            switch (inbound) {
                .request => |inbound_request| {
                    var operation: errors.ClientOperation = .callback;
                    self.dispatchServerRequestTracked(
                        self.transportWriter(),
                        inbound_request.id,
                        inbound_request.method,
                        inbound_request.params,
                        &operation,
                    ) catch |err| {
                        if (err == error.OutOfMemory) return error.OutOfMemory;
                        return .{ .failure = try policyFailure(
                            failure_policy,
                            err,
                            recordClientIo,
                            .{ self.allocator, operation, err },
                        ) };
                    };
                    continue;
                },
                .notification => |notification| {
                    switch (try self.routeNotification(
                        failure_policy,
                        body,
                        notification.method,
                        notification.params,
                        value.value,
                    )) {
                        .success => |disposition| body_owned = switch (disposition) {
                            .reader_releases_frame => true,
                            .router_retains_frame => false,
                        },
                        .failure => |failure| return .{ .failure = failure },
                    }
                    continue;
                },
                .response => |response| {
                    if (response.id != id) {
                        if (self.isDirectRequestActive(response.id) and
                            !self.hasBufferedResponse(response.id))
                        {
                            try self.buffered_responses.append(self.allocator, .{
                                .id = response.id,
                                .body = body,
                            });
                            body_owned = false;
                            continue;
                        }
                        return .{ .failure = try policyFailure(
                            failure_policy,
                            error.UnexpectedResponse,
                            recordUnexpectedResponse,
                            .{ self.allocator, id, response.id_value },
                        ) };
                    }
                    if (response.rpc_error) |rpc_error| {
                        const rpc_failure = switch (validateRpcFailure(
                            method,
                            id,
                            context,
                            rpc_error,
                        )) {
                            .valid => |failure| failure,
                            .invalid => |reason| return .{ .failure = try policyFailure(
                                failure_policy,
                                envelopeError(reason),
                                recordEnvelope,
                                .{ self.allocator, reason, value.value },
                            ) },
                        };
                        return .{ .failure = try policyFailure(
                            failure_policy,
                            error.JsonRpcError,
                            recordRpcFailure,
                            .{ self.allocator, rpc_failure },
                        ) };
                    }
                    const result = response.result orelse
                        return .{ .failure = try policyFailure(
                            failure_policy,
                            envelopeError(.missing_result_and_error),
                            recordEnvelope,
                            .{ self.allocator, .missing_result_and_error, value.value },
                        ) };
                    const result_json = try std.json.Stringify.valueAlloc(
                        self.allocator,
                        result,
                        .{},
                    );
                    defer {
                        wipeSecret(result_json);
                        self.allocator.free(result_json);
                    }
                    const parsed = std.json.parseFromSlice(Result, self.allocator, result_json, .{
                        .allocate = .alloc_always,
                        .ignore_unknown_fields = true,
                    }) catch |err| {
                        if (err == error.OutOfMemory) return error.OutOfMemory;
                        return .{ .failure = try policyFailure(
                            failure_policy,
                            err,
                            recordClientJson,
                            .{ self.allocator, .read, err },
                        ) };
                    };
                    return .{ .success = parsed };
                },
            }
        }
    }

    fn callPumped(
        self: *Client,
        comptime failure_policy: FailurePolicy,
        comptime Result: type,
        id: u64,
        method: []const u8,
        request: []const u8,
        context: OperationContext,
        dispatched: ?*bool,
        cancellation: ?*std.Io.Event,
        dispatch_mutex: ?*std.Io.Mutex,
    ) errors.DetailedError!PolicyResult(failure_policy, std.json.Parsed(Result)) {
        if (dispatch_mutex) |mutex| mutex.lockUncancelable(self.io);
        var dispatch_locked = dispatch_mutex != null;
        defer if (dispatch_locked) dispatch_mutex.?.unlock(self.io);
        var pending = PendingCall{
            .id = id,
            .wants_detail = failure_policy == .detailed,
        };
        self.pending_mutex.lockUncancelable(self.io);
        if (self.pump_terminal_error) |native_error| {
            if (comptime failure_policy == .detailed) {
                if (self.pump_failure) |*failure| {
                    const owned = failure.clone(self.allocator) catch |err| {
                        self.pending_mutex.unlock(self.io);
                        return err;
                    };
                    self.pending_mutex.unlock(self.io);
                    return .{ .failure = owned };
                }
            }
            self.pending_mutex.unlock(self.io);
            return .{ .failure = try policyFailure(
                failure_policy,
                native_error,
                recordClientIo,
                .{ self.allocator, .read, native_error },
            ) };
        }
        self.pending_calls.append(self.allocator, &pending) catch |err| {
            self.pending_mutex.unlock(self.io);
            return err;
        };
        if (builtin.is_test) {
            if (self.pending_call_admission_probe) |probe| {
                if (self.pending_calls.items.len >= probe.target) {
                    probe.ready.set(self.io);
                    if (probe.release) |release| release.set(self.io);
                }
            }
        }
        for (self.retained_responses.items, 0..) |retained, index| {
            if (retained.id != id) continue;
            pending.response = retained.body;
            _ = self.retained_responses.orderedRemove(index);
            pending.completed.set(self.io);
            break;
        }
        if (cancellation != null and cancellation.?.isSet()) {
            for (self.pending_calls.items, 0..) |candidate, index| {
                if (candidate == &pending) {
                    _ = self.pending_calls.orderedRemove(index);
                    break;
                }
            }
            self.pending_mutex.unlock(self.io);
            return .{ .failure = try policyFailure(
                failure_policy,
                error.FactoryCancelled,
                recordClientIo,
                .{ self.allocator, .read, error.FactoryCancelled },
            ) };
        }
        self.pending_mutex.unlock(self.io);
        defer {
            if (self.removePendingCallAndTakeResponse(&pending)) |response| {
                wipeSecret(response);
                self.allocator.free(response);
            }
            pending.failure_detail.deinit();
        }

        self.ensurePump() catch |err| return .{ .failure = try policyFailure(
            failure_policy,
            err,
            recordClientIo,
            .{ self.allocator, .read, err },
        ) };

        if (dispatched) |value| value.* = true;
        self.writer_mutex.lockUncancelable(self.io);
        const write_result = writeFrameAndWipe(
            self.transportWriter(),
            self.transportWriterBuffer(),
            request,
        );
        self.writer_mutex.unlock(self.io);
        if (dispatch_locked) {
            dispatch_mutex.?.unlock(self.io);
            dispatch_locked = false;
        }
        write_result catch |err| return .{ .failure = try policyFailure(
            failure_policy,
            err,
            recordClientIo,
            .{ self.allocator, .write, err },
        ) };

        if (cancellation) |cancel| {
            // Some I/O backends cannot cancel a losing Event.wait future reliably.
            while (!pending.completed.isSet() and !cancel.isSet()) {
                std.Io.sleep(
                    self.io,
                    .fromMilliseconds(1),
                    .awake,
                ) catch |err| return .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordClientIo,
                    .{ self.allocator, .read, err },
                ) };
            }
            if (!pending.completed.isSet()) {
                self.pending_mutex.lockUncancelable(self.io);
                for (self.pending_calls.items, 0..) |candidate, index| {
                    if (candidate != &pending) continue;
                    _ = self.pending_calls.orderedRemove(index);
                    if (pending.response == null)
                        self.abandoned_response_ids.append(
                            self.allocator,
                            id,
                        ) catch {};
                    break;
                }
                const abandoned_response = pending.response;
                pending.response = null;
                self.pending_mutex.unlock(self.io);
                if (abandoned_response) |response| {
                    wipeSecret(response);
                    self.allocator.free(response);
                }
                return .{ .failure = try policyFailure(
                    failure_policy,
                    error.FactoryCancelled,
                    recordClientIo,
                    .{ self.allocator, .read, error.FactoryCancelled },
                ) };
            }
        } else {
            pending.completed.wait(self.io) catch |err| return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordClientIo,
                .{ self.allocator, .read, err },
            ) };
        }
        self.pending_mutex.lockUncancelable(self.io);
        const response = pending.response;
        pending.response = null;
        const native_failure = pending.failure;
        var detailed_failure = pending.failure_detail;
        pending.failure_detail = .none;
        self.pending_mutex.unlock(self.io);
        if (native_failure) |err| {
            if (comptime failure_policy == .detailed) {
                switch (detailed_failure) {
                    .failure => |failure| return .{ .failure = failure },
                    .unavailable => return error.OutOfMemory,
                    .none => {},
                }
            } else {
                detailed_failure.deinit();
            }
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordClientIo,
                .{ self.allocator, .read, err },
            ) };
        }
        detailed_failure.deinit();
        const body = response orelse
            return .{ .failure = try policyFailure(
                failure_policy,
                error.MissingResponse,
                recordClientIo,
                .{ self.allocator, .read, error.MissingResponse },
            ) };
        defer {
            wipeSecret(body);
            self.allocator.free(body);
        }
        return self.parseCallResponse(failure_policy, Result, id, method, context, body);
    }

    fn parseCallResponse(
        self: *Client,
        comptime failure_policy: FailurePolicy,
        comptime Result: type,
        id: u64,
        method: []const u8,
        context: OperationContext,
        body: []const u8,
    ) errors.DetailedError!PolicyResult(failure_policy, std.json.Parsed(Result)) {
        const value = std.json.parseFromSlice(
            std.json.Value,
            self.allocator,
            body,
            .{},
        ) catch |err| {
            if (err == error.OutOfMemory) return error.OutOfMemory;
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidJson,
                .{ self.allocator, err },
            ) };
        };
        defer {
            wipeJsonStrings(value.value);
            value.deinit();
        }
        const inbound = switch (try parseInboundMessage(
            failure_policy,
            self.allocator,
            value.value,
        )) {
            .success => |message| message,
            .failure => |failure| return .{ .failure = failure },
        };
        const response = switch (inbound) {
            .response => |response| response,
            else => return .{ .failure = try policyFailure(
                failure_policy,
                error.UnexpectedResponse,
                recordUnexpectedResponse,
                .{ self.allocator, id, value.value },
            ) },
        };
        if (response.id != id)
            return .{ .failure = try policyFailure(
                failure_policy,
                error.UnexpectedResponse,
                recordUnexpectedResponse,
                .{ self.allocator, id, response.id_value },
            ) };
        if (response.rpc_error) |rpc_error| {
            const rpc_failure = switch (validateRpcFailure(
                method,
                id,
                context,
                rpc_error,
            )) {
                .valid => |failure| failure,
                .invalid => |reason| return .{ .failure = try policyFailure(
                    failure_policy,
                    envelopeError(reason),
                    recordEnvelope,
                    .{ self.allocator, reason, value.value },
                ) },
            };
            return .{ .failure = try policyFailure(
                failure_policy,
                error.JsonRpcError,
                recordRpcFailure,
                .{ self.allocator, rpc_failure },
            ) };
        }
        const result = response.result orelse
            return .{ .failure = try policyFailure(
                failure_policy,
                envelopeError(.missing_result_and_error),
                recordEnvelope,
                .{ self.allocator, .missing_result_and_error, value.value },
            ) };
        const result_json = try std.json.Stringify.valueAlloc(self.allocator, result, .{});
        defer {
            wipeSecret(result_json);
            self.allocator.free(result_json);
        }
        const parsed = std.json.parseFromSlice(Result, self.allocator, result_json, .{
            .allocate = .alloc_always,
            .ignore_unknown_fields = true,
        }) catch |err| {
            if (err == error.OutOfMemory) return error.OutOfMemory;
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordClientJson,
                .{ self.allocator, .read, err },
            ) };
        };
        return .{ .success = parsed };
    }

    fn ensurePump(
        self: *Client,
    ) error{ OutOfMemory, ClientDeinitialized, ReentrantRpcCall }!void {
        const current_thread = std.Thread.getCurrentId();
        while (true) {
            self.pending_mutex.lockUncancelable(self.io);
            if (self.pump_closing) {
                self.pending_mutex.unlock(self.io);
                return error.ClientDeinitialized;
            }
            if (self.pump_future != null) {
                self.pending_mutex.unlock(self.io);
                return;
            }
            if (self.direct_call_active) {
                if (self.direct_call_owner == current_thread) {
                    self.pending_mutex.unlock(self.io);
                    return error.ReentrantRpcCall;
                }
                self.pending_mutex.unlock(self.io);
                self.direct_call_done.waitUncancelable(self.io);
                continue;
            }
            self.pump_future = self.io.concurrent(pumpMain, .{self}) catch {
                self.pending_mutex.unlock(self.io);
                return error.OutOfMemory;
            };
            self.pending_mutex.unlock(self.io);
            return;
        }
    }

    fn isPumpRunning(self: *Client) bool {
        self.pending_mutex.lockUncancelable(self.io);
        defer self.pending_mutex.unlock(self.io);
        return self.pump_future != null and !self.pump_closing;
    }

    fn isRpcHandlerThread(self: *Client) bool {
        self.pending_mutex.lockUncancelable(self.io);
        defer self.pending_mutex.unlock(self.io);
        return self.rpc_handler_depth != 0 and
            self.rpc_handler_owner == std.Thread.getCurrentId();
    }

    fn beginRpcHandler(self: *Client) void {
        const current_thread = std.Thread.getCurrentId();
        self.pending_mutex.lockUncancelable(self.io);
        defer self.pending_mutex.unlock(self.io);
        std.debug.assert(
            self.rpc_handler_owner == null or self.rpc_handler_owner == current_thread,
        );
        self.rpc_handler_owner = current_thread;
        self.rpc_handler_depth += 1;
    }

    fn endRpcHandler(self: *Client) void {
        self.pending_mutex.lockUncancelable(self.io);
        defer self.pending_mutex.unlock(self.io);
        std.debug.assert(self.rpc_handler_owner == std.Thread.getCurrentId());
        std.debug.assert(self.rpc_handler_depth != 0);
        self.rpc_handler_depth -= 1;
        if (self.rpc_handler_depth == 0) self.rpc_handler_owner = null;
    }

    fn beginRpcCall(self: *Client) bool {
        const current_thread = std.Thread.getCurrentId();
        while (true) {
            self.pending_mutex.lockUncancelable(self.io);
            if (self.pump_future != null) {
                self.pending_mutex.unlock(self.io);
                return true;
            }
            if (self.direct_call_owner == current_thread) {
                self.direct_call_depth += 1;
                self.pending_mutex.unlock(self.io);
                return false;
            }
            if (!self.direct_call_active) {
                self.direct_call_active = true;
                self.direct_call_owner = current_thread;
                self.direct_call_depth = 1;
                self.direct_call_done.reset();
                self.pending_mutex.unlock(self.io);
                return false;
            }
            self.pending_mutex.unlock(self.io);
            self.direct_call_done.waitUncancelable(self.io);
        }
    }

    fn endDirectRpcCall(self: *Client) void {
        self.pending_mutex.lockUncancelable(self.io);
        std.debug.assert(self.direct_call_owner == std.Thread.getCurrentId());
        std.debug.assert(self.direct_call_depth > 0);
        self.direct_call_depth -= 1;
        if (self.direct_call_depth != 0) {
            self.pending_mutex.unlock(self.io);
            return;
        }
        self.direct_call_active = false;
        self.direct_call_owner = null;
        self.direct_call_done.set(self.io);
        self.pending_mutex.unlock(self.io);
    }

    fn stopPump(self: *Client) void {
        self.pending_mutex.lockUncancelable(self.io);
        self.pump_closing = true;
        var future = self.pump_future;
        self.pump_future = null;
        self.pending_mutex.unlock(self.io);
        if (future) |*pump| pump.cancel(self.io);
        self.finishPumpWithoutDetail(error.ClientDeinitialized);
    }

    fn removePendingCallAndTakeResponse(
        self: *Client,
        pending: *PendingCall,
    ) ?[]u8 {
        self.pending_mutex.lockUncancelable(self.io);
        defer self.pending_mutex.unlock(self.io);
        for (self.pending_calls.items, 0..) |candidate, index| {
            if (candidate != pending) continue;
            _ = self.pending_calls.orderedRemove(index);
            const response = pending.response;
            pending.response = null;
            return response;
        }
        return null;
    }

    fn pumpMain(self: *Client) void {
        if (builtin.is_test) {
            if (self.pump_read_gate) |gate| gate.wait(self.io) catch return;
        }
        while (true) {
            const read = self.readTransportFrame(.detailed) catch |err| {
                self.finishPumpNative(err);
                return;
            };
            const body = switch (read) {
                .success => |value| value,
                .failure => |failure| {
                    if (self.transport.eofIsIdle() and
                        (failure.native_error == error.EndOfStream or
                            failure.native_error == error.MissingContentLength))
                    {
                        var ignored = failure;
                        ignored.deinit();
                        return;
                    }
                    self.finishPumpFailure(failure);
                    return;
                },
            };
            var body_owned = true;
            defer if (body_owned) {
                wipeSecret(body);
                self.allocator.free(body);
            };
            const value = std.json.parseFromSlice(
                std.json.Value,
                self.allocator,
                body,
                .{},
            ) catch |err| {
                const failure = recordInvalidJson(self.allocator, err) catch {
                    self.finishPumpWithoutDetail(err);
                    return;
                };
                self.finishPumpFailure(failure);
                return;
            };
            defer {
                wipeJsonStrings(value.value);
                value.deinit();
            }
            const inbound = parseInboundMessage(
                .detailed,
                self.allocator,
                value.value,
            ) catch |err| {
                self.finishPumpNative(err);
                return;
            };
            switch (inbound) {
                .failure => |failure| {
                    self.finishPumpFailure(failure);
                    return;
                },
                .success => |message| switch (message) {
                    .request => |request| {
                        if (std.mem.eql(u8, request.method, "factory.execute")) {
                            self.startFactoryExecuteJob(request.id, request.params) catch |err| {
                                const id_json = std.json.Stringify.valueAlloc(
                                    self.allocator,
                                    request.id,
                                    .{},
                                ) catch {
                                    self.finishPumpNative(err);
                                    return;
                                };
                                defer self.allocator.free(id_json);
                                self.writeFactoryError(
                                    id_json,
                                    if (err == error.FactoryNotFound or
                                        err == error.InvalidFactoryRequest)
                                        -32602
                                    else
                                        -32603,
                                    if (err == error.FactoryNotFound)
                                        "factory not found"
                                    else if (err == error.InvalidFactoryRequest)
                                        "invalid factory request"
                                    else
                                        "failed to start factory",
                                ) catch |write_err| {
                                    self.finishPumpNative(write_err);
                                    return;
                                };
                            };
                            continue;
                        }
                        if (std.mem.eql(u8, request.method, "factory.abort")) {
                            self.abortFactoryExecution(request.params) catch {
                                self.writer_mutex.lockUncancelable(self.io);
                                const write_result = self.writeServerRequestError(
                                    self.transportWriter(),
                                    request.id,
                                    -32602,
                                    "invalid factory abort request",
                                );
                                self.writer_mutex.unlock(self.io);
                                write_result catch |write_err| {
                                    self.finishPumpNative(write_err);
                                    return;
                                };
                                continue;
                            };
                            self.writer_mutex.lockUncancelable(self.io);
                            const write_result = self.writeRpcSuccess(
                                self.transportWriter(),
                                request.id,
                                struct {}{},
                            );
                            self.writer_mutex.unlock(self.io);
                            write_result catch |err| {
                                self.finishPumpNative(err);
                                return;
                            };
                            continue;
                        }
                        self.writer_mutex.lockUncancelable(self.io);
                        var operation: errors.ClientOperation = .callback;
                        const result = self.dispatchServerRequestTracked(
                            self.transportWriter(),
                            request.id,
                            request.method,
                            request.params,
                            &operation,
                        );
                        self.writer_mutex.unlock(self.io);
                        result catch |err| {
                            self.finishPumpNative(err);
                            return;
                        };
                    },
                    .notification => |notification| {
                        const routed = self.routeNotification(
                            .detailed,
                            body,
                            notification.method,
                            notification.params,
                            value.value,
                        ) catch |err| {
                            self.finishPumpNative(err);
                            return;
                        };
                        switch (routed) {
                            .failure => |failure| {
                                self.finishPumpFailure(failure);
                                return;
                            },
                            .success => |disposition| {
                                body_owned = disposition == .reader_releases_frame;
                            },
                        }
                    },
                    .response => |response| {
                        const owned = self.allocator.dupe(u8, body) catch |err| {
                            self.finishPumpNative(err);
                            return;
                        };
                        self.routePumpedResponse(response.id, owned) catch |err| {
                            wipeSecret(owned);
                            self.allocator.free(owned);
                            self.finishPumpNative(err);
                            return;
                        };
                    },
                },
            }
        }
    }

    fn routePumpedResponse(self: *Client, id: u64, body: []u8) !void {
        self.pending_mutex.lockUncancelable(self.io);
        defer self.pending_mutex.unlock(self.io);
        for (self.abandoned_response_ids.items, 0..) |abandoned_id, index| {
            if (abandoned_id != id) continue;
            _ = self.abandoned_response_ids.orderedRemove(index);
            wipeSecret(body);
            self.allocator.free(body);
            return;
        }
        for (self.pending_calls.items) |pending| {
            if (pending.id != id) continue;
            if (pending.response != null or pending.failure != null) {
                wipeSecret(body);
                self.allocator.free(body);
                return;
            }
            pending.response = body;
            pending.completed.set(self.io);
            return;
        }
        if (self.retained_responses.items.len >= retained_response_limit)
            return error.TooManyRetainedResponses;
        try self.retained_responses.append(self.allocator, .{ .id = id, .body = body });
    }

    fn finishPumpNative(self: *Client, err: anyerror) void {
        const failure = recordClientIo(self.allocator, .read, err) catch {
            self.finishPumpWithoutDetail(err);
            return;
        };
        self.finishPumpFailure(failure);
    }

    fn finishPumpWrite(self: *Client, err: anyerror) void {
        const failure = recordClientIo(self.allocator, .write, err) catch {
            self.finishPumpWithoutDetail(err);
            return;
        };
        self.finishPumpFailure(failure);
    }

    fn finishPumpWithoutDetail(self: *Client, err: anyerror) void {
        self.pending_mutex.lockUncancelable(self.io);
        if (self.pump_terminal_error == null) self.pump_terminal_error = err;
        for (self.pending_calls.items) |pending| {
            if (pending.response == null) pending.failure = err;
            pending.completed.set(self.io);
        }
        self.pending_mutex.unlock(self.io);
        self.lifecycle_event_ready.set(self.io);
        self.failEventLogs(err);
    }

    fn finishPumpFailure(self: *Client, failure_value: errors.Failure) void {
        var failure = failure_value;
        const native_error = failure.native_error;
        self.pending_mutex.lockUncancelable(self.io);
        if (self.pump_terminal_error == null) self.pump_terminal_error = native_error;
        if (self.pump_failure == null) {
            self.pump_failure = failure;
        } else {
            failure.deinit();
        }
        const retained_failure = &self.pump_failure.?;
        const terminal_error = retained_failure.native_error;
        for (self.pending_calls.items) |pending| {
            if (pending.response == null) {
                pending.failure = terminal_error;
                if (pending.wants_detail) {
                    pending.failure_detail.deinit();
                    pending.failure_detail = if (retained_failure.clone(self.allocator)) |detail|
                        .{ .failure = detail }
                    else |_|
                        .unavailable;
                }
            }
            pending.completed.set(self.io);
        }
        self.pending_mutex.unlock(self.io);
        self.lifecycle_event_ready.set(self.io);
        self.failEventLogsDetailed(retained_failure);
    }

    fn failEventLogsDetailed(self: *Client, failure: *const errors.Failure) void {
        self.event_logs_mutex.lockUncancelable(self.io);
        defer self.event_logs_mutex.unlock(self.io);
        for (self.event_logs.items) |log| {
            var terminal_failure = failure.clone(self.allocator) catch {
                log.fail(failure.native_error);
                continue;
            };
            const turn_failure = failure.clone(self.allocator) catch {
                terminal_failure.deinit();
                log.fail(failure.native_error);
                continue;
            };
            log.failPumpDetailed(terminal_failure, turn_failure) catch {
                log.fail(failure.native_error);
            };
        }
    }

    fn failEventLogs(self: *Client, err: anyerror) void {
        self.event_logs_mutex.lockUncancelable(self.io);
        defer self.event_logs_mutex.unlock(self.io);
        for (self.event_logs.items) |log| log.fail(err);
    }

    fn clonePumpFailure(self: *Client) !?errors.Failure {
        self.pending_mutex.lockUncancelable(self.io);
        defer self.pending_mutex.unlock(self.io);
        const failure = if (self.pump_failure) |*value| value else return null;
        return try failure.clone(self.allocator);
    }

    fn startSendOperation(
        self: *Client,
        lease: EventLogLease,
        receipt: turn_tracker.ReceiptToken,
        options: session_types.MessageOptions,
        attachments: ?WireAttachments,
        source: ?[]const u8,
        trace_context: runtime_types.TraceContext,
    ) !*SendOperation {
        self.reapSendOperations();
        const request_id = self.nextRequestId();
        const request = try json_rpc.encodeRequest(
            self.allocator,
            request_id,
            "session.send",
            lowerMessage(
                lease.log.session_id,
                options,
                attachments,
                source,
                trace_context,
            ),
        );
        errdefer {
            wipeSecret(request);
            self.allocator.free(request);
        }
        const operation = try self.allocator.create(SendOperation);
        errdefer self.allocator.destroy(operation);
        operation.* = .{
            .client = self,
            .log_lease = lease.clone(),
            .receipt = receipt,
            .request_id = request_id,
            .request = request,
        };
        errdefer operation.log_lease.deinit();
        self.send_operations_mutex.lockUncancelable(self.io);
        if (self.send_operations.items.len >= detached_send_limit) {
            self.send_operations_mutex.unlock(self.io);
            return error.TooManyPendingSends;
        }
        self.send_operations.append(self.allocator, operation) catch |err| {
            self.send_operations_mutex.unlock(self.io);
            return err;
        };
        self.send_operations_mutex.unlock(self.io);
        const future = self.io.concurrent(sendOperationMain, .{operation}) catch |err| {
            self.send_operations_mutex.lockUncancelable(self.io);
            for (self.send_operations.items, 0..) |candidate, index| {
                if (candidate == operation) {
                    _ = self.send_operations.orderedRemove(index);
                    break;
                }
            }
            self.send_operations_mutex.unlock(self.io);
            return err;
        };
        self.send_operations_mutex.lockUncancelable(self.io);
        operation.future = future;
        operation.future_published = true;
        self.send_operations_mutex.unlock(self.io);
        return operation;
    }

    fn nextRequestId(self: *Client) u64 {
        self.pending_mutex.lockUncancelable(self.io);
        defer self.pending_mutex.unlock(self.io);
        const id = self.next_request_id;
        self.next_request_id += 1;
        return id;
    }

    fn sendOperationMain(operation: *SendOperation) void {
        defer operation.completed.set(operation.client.io);
        const result = operation.client.callPumped(
            .detailed,
            struct { messageId: []const u8 },
            operation.request_id,
            "session.send",
            operation.request,
            .{ .session = .{ .session_id = operation.log_lease.log.session_id } },
            null,
            null,
            null,
        ) catch |err| {
            operation.log_lease.log.failTurn(operation.receipt, err);
            return;
        };
        switch (result) {
            .failure => |failure| {
                operation.failure = failure;
                operation.log_lease.log.failTurn(operation.receipt, failure.native_error);
            },
            .success => |parsed_value| {
                var parsed = parsed_value;
                defer parsed.deinit();
                operation.log_lease.log.bindTurnMessage(
                    operation.receipt,
                    parsed.value.messageId,
                ) catch |err| {
                    operation.failure = recordClientIo(
                        operation.client.allocator,
                        .read,
                        err,
                    ) catch null;
                    operation.log_lease.log.failTurn(operation.receipt, err);
                };
            },
        }
    }

    fn reapSendOperations(self: *Client) void {
        while (true) {
            self.send_operations_mutex.lockUncancelable(self.io);
            var completed: ?*SendOperation = null;
            for (self.send_operations.items, 0..) |operation, index| {
                if (!operation.detached or
                    !operation.future_published or
                    !operation.completed.isSet())
                {
                    continue;
                }
                completed = self.send_operations.orderedRemove(index);
                break;
            }
            self.send_operations_mutex.unlock(self.io);
            const operation = completed orelse return;
            self.destroySendOperation(operation);
        }
    }

    fn claimSendOperation(self: *Client, operation: *SendOperation) ?*SendOperation {
        self.send_operations_mutex.lockUncancelable(self.io);
        defer self.send_operations_mutex.unlock(self.io);
        for (self.send_operations.items, 0..) |candidate, index| {
            if (candidate != operation or candidate.detached or
                !candidate.future_published or
                !candidate.completed.isSet()) continue;
            return self.send_operations.orderedRemove(index);
        }
        return null;
    }

    fn isDirectRequestActive(self: *const Client, id: u64) bool {
        for (self.direct_request_ids[0..self.direct_request_count]) |active_id| {
            if (active_id == id) return true;
        }
        return false;
    }

    fn hasBufferedResponse(self: *const Client, id: u64) bool {
        for (self.buffered_responses.items) |response| {
            if (response.id == id) return true;
        }
        return false;
    }

    fn takeBufferedResponse(self: *Client, id: u64) ?[]u8 {
        for (self.buffered_responses.items, 0..) |response, index| {
            if (response.id == id) return self.buffered_responses.orderedRemove(index).body;
        }
        return null;
    }

    fn discardBufferedResponse(self: *Client, id: u64) void {
        const body = self.takeBufferedResponse(id) orelse return;
        wipeSecret(body);
        self.allocator.free(body);
    }

    fn detachSendOperation(self: *Client, operation: *SendOperation) void {
        self.send_operations_mutex.lockUncancelable(self.io);
        defer self.send_operations_mutex.unlock(self.io);
        for (self.send_operations.items) |candidate| {
            if (candidate == operation) {
                candidate.detached = true;
                return;
            }
        }
    }

    fn destroySendOperation(self: *Client, operation: *SendOperation) void {
        if (operation.future) |*future| future.await(self.io);
        if (operation.failure) |*failure| failure.deinit();
        wipeSecret(operation.request);
        self.allocator.free(operation.request);
        operation.log_lease.deinit();
        self.allocator.destroy(operation);
    }

    fn finishSendOperations(self: *Client) void {
        while (true) {
            self.send_operations_mutex.lockUncancelable(self.io);
            const operation = if (self.send_operations.items.len == 0)
                null
            else
                self.send_operations.orderedRemove(0);
            self.send_operations_mutex.unlock(self.io);
            const value = operation orelse return;
            self.destroySendOperation(value);
        }
    }

    fn writeFactorySuccess(
        self: *Client,
        id_json: []const u8,
        result: anytype,
    ) !void {
        const id = try std.json.parseFromSlice(
            std.json.Value,
            self.allocator,
            id_json,
            .{},
        );
        defer id.deinit();
        self.writer_mutex.lockUncancelable(self.io);
        defer self.writer_mutex.unlock(self.io);
        try self.writeRpcSuccess(self.transportWriter(), id.value, result);
    }

    fn writeFactoryError(
        self: *Client,
        id_json: []const u8,
        code: i64,
        message: []const u8,
    ) !void {
        const id = try std.json.parseFromSlice(
            std.json.Value,
            self.allocator,
            id_json,
            .{},
        );
        defer id.deinit();
        self.writer_mutex.lockUncancelable(self.io);
        defer self.writer_mutex.unlock(self.io);
        try self.writeServerRequestError(self.transportWriter(), id.value, code, message);
    }

    fn findFactoryCallback(
        self: *Client,
        session_id: []const u8,
        name: []const u8,
    ) ?struct {
        run: *const fn (
            std.mem.Allocator,
            *factory_types.FactoryContext,
            ?*anyopaque,
        ) anyerror!?factory_types.Json,
        context: ?*anyopaque,
    } {
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        defer self.extension_runtimes_mutex.unlock(self.io);
        const runtime = self.findExtensionRuntime(session_id) orelse return null;
        for (runtime.factories) |definition| {
            if (std.mem.eql(u8, definition.name, name))
                return .{ .run = definition.run, .context = definition.context };
        }
        return null;
    }

    fn startFactoryExecuteJob(
        self: *Client,
        id: std.json.Value,
        params: ?std.json.Value,
    ) !void {
        const object = switch (params orelse return error.InvalidFactoryRequest) {
            .object => |object| object,
            else => return error.InvalidFactoryRequest,
        };
        try validateObjectFields(
            object,
            &.{ "sessionId", "name", "runId", "executionToken", "args" },
        );
        const session_id = try jsonRequiredString(object, "sessionId");
        const name = try jsonRequiredString(object, "name");
        const run_id = try jsonRequiredString(object, "runId");
        const execution_token = try jsonRequiredString(object, "executionToken");
        if (session_id.len == 0 or name.len == 0 or run_id.len == 0 or execution_token.len == 0)
            return error.InvalidFactoryRequest;
        const args = try jsonRequiredValue(object, "args");

        self.acquireTransferredRuntimeCallback();
        errdefer {
            var scope: RuntimeCallbackScope = undefined;
            self.enterTransferredRuntimeCallback(&scope);
            self.endRuntimeCallback(&scope);
        }
        const callback = self.findFactoryCallback(session_id, name) orelse
            return error.FactoryNotFound;
        self.reapFactoryJobs();
        const owned_session_id = try self.allocator.dupe(u8, session_id);
        errdefer self.allocator.free(owned_session_id);
        const owned_run_id = try self.allocator.dupe(u8, run_id);
        errdefer self.allocator.free(owned_run_id);
        const owned_execution_token = try self.allocator.dupe(u8, execution_token);
        errdefer self.allocator.free(owned_execution_token);
        const args_json = try std.json.Stringify.valueAlloc(self.allocator, args, .{});
        errdefer self.allocator.free(args_json);
        const id_json = try std.json.Stringify.valueAlloc(self.allocator, id, .{});
        errdefer self.allocator.free(id_json);
        const job = try self.allocator.create(FactoryExecuteJob);
        errdefer self.allocator.destroy(job);
        job.* = .{
            .client = self,
            .session_id = owned_session_id,
            .run_id = owned_run_id,
            .execution_token = owned_execution_token,
            .args_json = args_json,
            .id_json = id_json,
            .run = callback.run,
            .context = callback.context,
        };
        self.factory_jobs_mutex.lockUncancelable(self.io);
        self.factory_jobs.append(self.allocator, job) catch |err| {
            self.factory_jobs_mutex.unlock(self.io);
            return err;
        };
        self.factory_jobs_mutex.unlock(self.io);
        job.future = self.io.concurrent(factoryExecuteJobMain, .{job}) catch |err| {
            self.factory_jobs_mutex.lockUncancelable(self.io);
            for (self.factory_jobs.items, 0..) |candidate, index| {
                if (candidate == job) {
                    _ = self.factory_jobs.orderedRemove(index);
                    break;
                }
            }
            self.factory_jobs_mutex.unlock(self.io);
            return err;
        };
    }

    fn abortFactoryExecution(self: *Client, params: ?std.json.Value) !void {
        const object = switch (params orelse return error.InvalidFactoryRequest) {
            .object => |object| object,
            else => return error.InvalidFactoryRequest,
        };
        try validateObjectFields(object, &.{ "sessionId", "runId", "executionToken" });
        const session_id = try jsonRequiredString(object, "sessionId");
        const run_id = try jsonRequiredString(object, "runId");
        const execution_token = try jsonRequiredString(object, "executionToken");
        self.factory_jobs_mutex.lockUncancelable(self.io);
        defer self.factory_jobs_mutex.unlock(self.io);
        for (self.factory_jobs.items) |job| {
            if (std.mem.eql(u8, job.session_id, session_id) and
                std.mem.eql(u8, job.run_id, run_id) and
                std.mem.eql(u8, job.execution_token, execution_token))
            {
                job.dispatch_mutex.lockUncancelable(self.io);
                job.cancelled.set(self.io);
                job.dispatch_mutex.unlock(self.io);
                return;
            }
        }
    }

    fn reapFactoryJobs(self: *Client) void {
        while (true) {
            self.factory_jobs_mutex.lockUncancelable(self.io);
            var finished: ?*FactoryExecuteJob = null;
            for (self.factory_jobs.items, 0..) |job, index| {
                if (!job.completed.isSet()) continue;
                finished = self.factory_jobs.orderedRemove(index);
                break;
            }
            self.factory_jobs_mutex.unlock(self.io);
            const job = finished orelse return;
            self.destroyFactoryJob(job);
        }
    }

    fn cancelFactoryJobsForSession(self: *Client, session_id: []const u8) void {
        self.factory_jobs_mutex.lockUncancelable(self.io);
        defer self.factory_jobs_mutex.unlock(self.io);
        for (self.factory_jobs.items) |job|
            if (std.mem.eql(u8, job.session_id, session_id)) job.cancelled.set(self.io);
    }

    fn finishFactoryJobs(self: *Client) void {
        self.factory_jobs_mutex.lockUncancelable(self.io);
        for (self.factory_jobs.items) |job| job.cancelled.set(self.io);
        self.factory_jobs_mutex.unlock(self.io);
        while (true) {
            self.factory_jobs_mutex.lockUncancelable(self.io);
            const job = if (self.factory_jobs.items.len == 0)
                null
            else
                self.factory_jobs.orderedRemove(0);
            self.factory_jobs_mutex.unlock(self.io);
            const value = job orelse return;
            self.destroyFactoryJob(value);
        }
    }

    fn destroyFactoryJob(self: *Client, job: *FactoryExecuteJob) void {
        if (job.future) |*future| future.await(self.io);
        self.allocator.free(job.session_id);
        self.allocator.free(job.run_id);
        self.allocator.free(job.execution_token);
        wipeSecret(job.args_json);
        self.allocator.free(job.args_json);
        self.allocator.free(job.id_json);
        self.allocator.destroy(job);
    }

    fn factoryAgent(
        state_pointer: *anyopaque,
        allocator: std.mem.Allocator,
        prompt: []const u8,
        options: factory_types.FactoryAgentOptions,
    ) !?factory_types.Json {
        const state: *FactoryExecutionState = @ptrCast(@alignCast(state_pointer));
        const job = state.job;
        if (job.cancelled.isSet()) return error.FactoryCancelled;
        const schema = if (options.schema) |schema|
            try std.json.parseFromSlice(
                std.json.Value,
                job.client.allocator,
                schema.bytes,
                .{ .allocate = .alloc_always },
            )
        else
            null;
        defer if (schema) |parsed| parsed.deinit();
        const parsed = job.client.callCancelable(std.json.Value, "session.factory.agent", .{
            .sessionId = job.session_id,
            .factoryRunId = job.run_id,
            .executionToken = job.execution_token,
            .prompt = prompt,
            .opts = WireFactoryAgentOptions{
                .label = options.label,
                .schema = if (schema) |value| value.value else null,
                .model = options.model,
                .reasoningEffort = options.reasoning_effort,
                .contextTier = if (options.context_tier) |value| @tagName(value) else null,
                .agent = options.agent,
            },
        }, &job.cancelled, &job.dispatch_mutex) catch |err|
            return mapFactoryRpcError(err, false);
        defer parsed.deinit();
        if (job.cancelled.isSet()) return error.FactoryCancelled;
        const object = switch (parsed.value) {
            .object => |object| object,
            else => return error.FactoryTransportFailure,
        };
        const result = object.get("result") orelse return null;
        return try factory_types.Json.initValue(allocator, result);
    }

    fn factoryJournalGet(
        state_pointer: *anyopaque,
        allocator: std.mem.Allocator,
        key: []const u8,
    ) !factory_types.JournalLookup {
        const state: *FactoryExecutionState = @ptrCast(@alignCast(state_pointer));
        const job = state.job;
        if (job.cancelled.isSet()) return error.FactoryCancelled;
        const parsed = job.client.callCancelable(std.json.Value, "session.factory.journal.get", .{
            .sessionId = job.session_id,
            .runId = job.run_id,
            .executionToken = job.execution_token,
            .key = key,
        }, &job.cancelled, &job.dispatch_mutex) catch |err|
            return mapFactoryRpcError(err, true);
        defer parsed.deinit();
        if (job.cancelled.isSet()) return error.FactoryCancelled;
        const object = switch (parsed.value) {
            .object => |object| object,
            else => return error.FactoryDurableFailure,
        };
        if (!(jsonRequiredBool(object, "hit") catch return error.FactoryDurableFailure))
            return .miss;
        const result = object.get("resultJson") orelse
            return error.FactoryDurableFailure;
        return .{ .value = try factory_types.Json.initValue(allocator, result) };
    }

    fn factoryJournalPut(
        state_pointer: *anyopaque,
        key: []const u8,
        value: factory_types.JsonView,
    ) !void {
        const state: *FactoryExecutionState = @ptrCast(@alignCast(state_pointer));
        const job = state.job;
        if (job.cancelled.isSet()) return error.FactoryCancelled;
        const result = try std.json.parseFromSlice(
            std.json.Value,
            job.client.allocator,
            value.bytes,
            .{ .allocate = .alloc_always },
        );
        defer result.deinit();
        const parsed = job.client.callCancelable(std.json.Value, "session.factory.journal.put", .{
            .sessionId = job.session_id,
            .runId = job.run_id,
            .executionToken = job.execution_token,
            .key = key,
            .resultJson = result.value,
        }, &job.cancelled, &job.dispatch_mutex) catch |err|
            return mapFactoryRpcError(err, true);
        if (job.cancelled.isSet()) {
            parsed.deinit();
            return error.FactoryCancelled;
        }
        parsed.deinit();
    }

    fn factoryPauseAtCheckpoint(
        state_pointer: *anyopaque,
        key: []const u8,
    ) !void {
        const state: *FactoryExecutionState = @ptrCast(@alignCast(state_pointer));
        const job = state.job;
        if (job.cancelled.isSet()) return error.FactoryCancelled;
        const parsed = job.client.callCancelable(struct {
            action: []const u8,
        }, "session.factory.pauseAtCheckpoint", .{
            .sessionId = job.session_id,
            .runId = job.run_id,
            .executionToken = job.execution_token,
            .key = key,
        }, &job.cancelled, &job.dispatch_mutex) catch |err|
            return mapFactoryRpcError(err, true);
        defer parsed.deinit();
        if (job.cancelled.isSet()) return error.FactoryCancelled;
        if (std.mem.eql(u8, parsed.value.action, "continue")) return;
        if (!std.mem.eql(u8, parsed.value.action, "pause"))
            return error.FactoryDurableFailure;
        job.cancelled.set(job.client.io);
        return error.FactoryCancelled;
    }

    fn factoryProgress(
        state_pointer: *anyopaque,
        kind: factory_types.FactoryLogKind,
        message: []const u8,
    ) !void {
        const state: *FactoryExecutionState = @ptrCast(@alignCast(state_pointer));
        const job = state.job;
        if (job.cancelled.isSet()) return error.FactoryCancelled;
        job.progress_mutex.lockUncancelable(job.client.io);
        defer job.progress_mutex.unlock(job.client.io);
        const sequence = job.next_progress_seq;
        job.next_progress_seq += 1;
        const parsed = job.client.callCancelable(std.json.Value, "session.factory.log", .{
            .sessionId = job.session_id,
            .runId = job.run_id,
            .executionToken = job.execution_token,
            .lines = &.{WireFactoryLogLine{
                .seq = sequence,
                .kind = @tagName(kind),
                .text = message,
            }},
        }, &job.cancelled, &job.dispatch_mutex) catch |err|
            return mapFactoryRpcError(err, true);
        if (job.cancelled.isSet()) {
            parsed.deinit();
            return error.FactoryCancelled;
        }
        parsed.deinit();
    }

    fn mapFactoryRpcError(err: anyerror, durable: bool) anyerror {
        return switch (err) {
            error.OutOfMemory, error.FactoryCancelled => err,
            else => if (durable)
                error.FactoryDurableFailure
            else
                error.FactoryTransportFailure,
        };
    }

    fn factoryExecuteJobMain(job: *FactoryExecuteJob) void {
        defer job.completed.set(job.client.io);
        var scope: RuntimeCallbackScope = undefined;
        job.client.enterTransferredRuntimeCallback(&scope);
        defer job.client.endRuntimeCallback(&scope);
        var state = FactoryExecutionState{ .job = job };
        var context = factory_types.FactoryContext{
            .run_id = job.run_id,
            .args = .{ .bytes = job.args_json },
            .cancel = .{ .event = &job.cancelled, .io = job.client.io },
            .execution = .{
                .state = &state,
                .io = job.client.io,
                .agent_fn = factoryAgent,
                .journal_get_fn = factoryJournalGet,
                .journal_put_fn = factoryJournalPut,
                .pause_fn = factoryPauseAtCheckpoint,
                .progress_fn = factoryProgress,
            },
        };
        var result = job.run(job.client.allocator, &context, job.context) catch |err| {
            job.client.writeFactoryError(job.id_json, -32000, @errorName(err)) catch |write_err| {
                job.client.finishPumpWrite(write_err);
            };
            return;
        };
        defer if (result) |*value| value.deinit();
        if (result) |value| {
            const parsed = std.json.parseFromSlice(
                std.json.Value,
                job.client.allocator,
                value.bytes,
                .{},
            ) catch {
                job.client.writeFactoryError(
                    job.id_json,
                    -32603,
                    "invalid factory callback result",
                ) catch |write_err| {
                    job.client.finishPumpWrite(write_err);
                };
                return;
            };
            defer parsed.deinit();
            job.client.writeFactorySuccess(job.id_json, .{ .result = parsed.value }) catch |err| {
                job.client.finishPumpWrite(err);
            };
            return;
        }
        job.client.writeFactorySuccess(job.id_json, struct {}{}) catch |err| {
            job.client.finishPumpWrite(err);
        };
    }

    fn findCommittedExtensionRuntimeIndex(
        self: *const Client,
        session_id: []const u8,
    ) ?usize {
        for (self.extension_runtimes.items, 0..) |runtime, index| {
            if (runtime.session_id) |id| {
                if (std.mem.eql(u8, id, session_id)) return index;
            }
        }
        return null;
    }

    fn rejectServerRequest(
        self: *Client,
        writer: *std.Io.Writer,
        id: std.json.Value,
    ) !void {
        const response = try json_rpc.encodeErrorResponse(
            self.allocator,
            id,
            -32601,
            "method not found",
        );
        defer {
            wipeSecret(response);
            self.allocator.free(response);
        }
        try json_rpc.writeFrame(writer, response);
    }

    fn dispatchServerRequest(
        self: *Client,
        writer: *std.Io.Writer,
        id: std.json.Value,
        method: []const u8,
        params: ?std.json.Value,
    ) !void {
        var operation: errors.ClientOperation = .callback;
        return self.dispatchServerRequestTracked(writer, id, method, params, &operation);
    }

    fn dispatchServerRequestTracked(
        self: *Client,
        writer: *std.Io.Writer,
        id: std.json.Value,
        method: []const u8,
        params: ?std.json.Value,
        failure_operation: *errors.ClientOperation,
    ) !void {
        const typed_request = typedServerRequest(method);
        if (typed_request) |request| {
            var lifetime = try self.acquireServerRequestLifetime(params);
            if (lifetime == .inactive)
                return self.writeServerRequestError(
                    writer,
                    id,
                    -32602,
                    "inactive session",
                );
            defer if (lifetime == .active) {
                var lease = &lifetime.active;
                self.finishSessionIngress(lease.log);
                lease.deinit();
            };
            var ingress_scope: SessionIngressScope = undefined;
            if (lifetime == .active)
                beginSessionIngressScope(&ingress_scope, lifetime.active.log);
            defer if (lifetime == .active)
                endSessionIngressScope(&ingress_scope);
            var runtime_scope: RuntimeCallbackScope = undefined;
            self.beginRuntimeCallback(&runtime_scope);
            defer self.endRuntimeCallback(&runtime_scope);
            if (self.hasApplicableTypedRegistration(request, method, params)) {
                return self.dispatchTypedServerRequest(
                    request,
                    writer,
                    id,
                    method,
                    params,
                    failure_operation,
                );
            }
        }
        if (std.mem.startsWith(u8, method, "sessionFs.")) {
            return self.dispatchSessionFilesystemRequest(writer, id, method, params);
        }
        const registered = self.findRpcHandler(method) orelse {
            if (typed_request) |request| {
                if (request != .user_input) {
                    return self.dispatchTypedServerRequest(
                        request,
                        writer,
                        id,
                        method,
                        params,
                        failure_operation,
                    );
                }
            }
            failure_operation.* = .write;
            try self.rejectServerRequest(writer, id);
            return;
        };
        const params_json = try stringifyRpcParams(self.allocator, params);
        defer if (params_json) |json| {
            wipeSecret(json);
            self.allocator.free(json);
        };

        self.beginRpcHandler();
        defer self.endRpcHandler();
        const result_json = registered.handler(
            self.allocator,
            params_json,
            registered.context,
        ) catch |err| {
            const response = try json_rpc.encodeErrorResponse(
                self.allocator,
                id,
                -32000,
                @errorName(err),
            );
            defer {
                wipeSecret(response);
                self.allocator.free(response);
            }
            failure_operation.* = .write;
            try json_rpc.writeFrame(writer, response);
            return;
        };
        defer {
            wipeSecret(result_json);
            self.allocator.free(result_json);
        }

        const result = std.json.parseFromSlice(
            std.json.Value,
            self.allocator,
            result_json,
            .{},
        ) catch {
            const response = try json_rpc.encodeErrorResponse(
                self.allocator,
                id,
                -32603,
                "invalid handler result",
            );
            defer {
                wipeSecret(response);
                self.allocator.free(response);
            }
            failure_operation.* = .write;
            try json_rpc.writeFrame(writer, response);
            return;
        };
        defer {
            wipeJsonStrings(result.value);
            result.deinit();
        }
        const response = try json_rpc.encodeSuccessResponse(self.allocator, id, result.value);
        defer {
            wipeSecret(response);
            self.allocator.free(response);
        }
        failure_operation.* = .write;
        try json_rpc.writeFrame(writer, response);
    }

    fn acquireServerRequestLifetime(
        self: *Client,
        params: ?std.json.Value,
    ) !ServerRequestLifetime {
        const object = switch (params orelse return .unscoped) {
            .object => |value| value,
            else => return .unscoped,
        };
        const session_id = jsonString(object, "sessionId") orelse return .unscoped;
        const admission = try self.acquireActiveEventIngress(session_id, true);
        switch (admission) {
            .active => |lease| return .{ .active = lease },
            .unavailable => return .inactive,
            .unknown => {},
        }
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        if (self.pending_extension_runtime) |*pending| {
            if (pending.session_id == null or
                std.mem.eql(u8, pending.session_id.?, session_id))
            {
                self.extension_runtimes_mutex.unlock(self.io);
                return .pending;
            }
        }
        self.extension_runtimes_mutex.unlock(self.io);
        self.sessions_mutex.lockUncancelable(self.io);
        defer self.sessions_mutex.unlock(self.io);
        for (self.sessions.items) |record| {
            const id = record.id orelse continue;
            if (std.mem.eql(u8, id, session_id)) return .inactive;
        }
        return .unscoped;
    }

    fn findSessionFilesystem(
        self: *Client,
        session_id: []const u8,
    ) ?runtime_types.SessionFilesystemProvider {
        return self.session_filesystems.resolve(session_id);
    }

    fn dispatchSessionFilesystemRequest(
        self: *Client,
        writer: *std.Io.Writer,
        id: std.json.Value,
        method: []const u8,
        params: ?std.json.Value,
    ) !void {
        const params_value = params orelse {
            try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
            return;
        };
        const object = switch (params_value) {
            .object => |value| value,
            else => {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            },
        };
        const session_id = jsonRequiredString(object, "sessionId") catch {
            try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
            return;
        };
        const filesystem_provider = self.findSessionFilesystem(session_id) orelse {
            try self.writeServerRequestError(writer, id, -32602, "unknown session filesystem");
            return;
        };

        self.beginRpcHandler();
        defer self.endRpcHandler();

        if (std.mem.eql(u8, method, "sessionFs.readFile")) {
            validateObjectFields(object, &.{ "sessionId", "path" }) catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const path = jsonRequiredString(object, "path") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const content = filesystem_provider.read_file(
                self.allocator,
                path,
                filesystem_provider.context,
            ) catch |err| {
                try self.writeTypedSuccess(writer, id, WireReadFileResult{
                    .content = "",
                    .@"error" = filesystemError(err),
                });
                return;
            };
            defer {
                wipeSecret(content);
                self.allocator.free(content);
            }
            if (!std.unicode.utf8ValidateSlice(content)) {
                try self.writeServerRequestError(writer, id, -32603, "invalid session filesystem callback result");
                return;
            }
            try self.writeTypedSuccess(writer, id, WireReadFileResult{
                .content = content,
            });
            return;
        }
        if (std.mem.eql(u8, method, "sessionFs.writeFile") or
            std.mem.eql(u8, method, "sessionFs.appendFile"))
        {
            validateObjectFields(object, &.{ "sessionId", "path", "content", "mode" }) catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const path = jsonRequiredString(object, "path") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const content = jsonRequiredString(object, "content") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const mode = jsonOptionalU32(object, "mode") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const operation = if (std.mem.eql(u8, method, "sessionFs.writeFile"))
                filesystem_provider.write_file(path, content, mode, filesystem_provider.context)
            else
                filesystem_provider.append_file(path, content, mode, filesystem_provider.context);
            operation catch |err| {
                try self.writeRpcSuccess(writer, id, filesystemError(err));
                return;
            };
            try self.writeRpcSuccess(writer, id, @as(?FilesystemError, null));
            return;
        }
        if (std.mem.eql(u8, method, "sessionFs.exists")) {
            validateObjectFields(object, &.{ "sessionId", "path" }) catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const path = jsonRequiredString(object, "path") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const exists = filesystem_provider.exists(
                path,
                filesystem_provider.context,
            ) catch false;
            try self.writeRpcSuccess(writer, id, .{ .exists = exists });
            return;
        }
        if (std.mem.eql(u8, method, "sessionFs.stat")) {
            validateObjectFields(object, &.{ "sessionId", "path" }) catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const path = jsonRequiredString(object, "path") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const info = filesystem_provider.stat(path, filesystem_provider.context) catch |err| {
                try self.writeTypedSuccess(writer, id, WireStatResult{
                    .isFile = false,
                    .isDirectory = false,
                    .size = 0,
                    .mtime = "1970-01-01T00:00:00.000Z",
                    .birthtime = "1970-01-01T00:00:00.000Z",
                    .@"error" = filesystemError(err),
                });
                return;
            };
            if (!validDateTime(info.mtime) or !validDateTime(info.birthtime)) {
                try self.writeServerRequestError(writer, id, -32603, "invalid session filesystem callback result");
                return;
            }
            try self.writeTypedSuccess(writer, id, WireStatResult{
                .isFile = info.is_file,
                .isDirectory = info.is_directory,
                .size = info.size,
                .mtime = info.mtime,
                .birthtime = info.birthtime,
            });
            return;
        }
        if (std.mem.eql(u8, method, "sessionFs.mkdir")) {
            validateObjectFields(object, &.{ "sessionId", "path", "recursive", "mode" }) catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const path = jsonRequiredString(object, "path") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const recursive = (jsonOptionalNonNullBool(object, "recursive") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            }) orelse false;
            const mode = jsonOptionalU32(object, "mode") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            filesystem_provider.make_directory(
                path,
                recursive,
                mode,
                filesystem_provider.context,
            ) catch |err| {
                try self.writeRpcSuccess(writer, id, filesystemError(err));
                return;
            };
            try self.writeRpcSuccess(writer, id, @as(?FilesystemError, null));
            return;
        }
        if (std.mem.eql(u8, method, "sessionFs.readdir")) {
            validateObjectFields(object, &.{ "sessionId", "path" }) catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const path = jsonRequiredString(object, "path") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const result = filesystem_provider.read_directory(
                self.allocator,
                path,
                filesystem_provider.context,
            ) catch |err| {
                try self.writeTypedSuccess(writer, id, WireReadDirectoryResult{
                    .entries = &.{},
                    .@"error" = filesystemError(err),
                });
                return;
            };
            defer {
                wipeStrings(result.value.entries);
                result.deinit();
            }
            if (!validStrings(result.value.entries)) {
                try self.writeServerRequestError(writer, id, -32603, "invalid session filesystem callback result");
                return;
            }
            try self.writeTypedSuccess(writer, id, WireReadDirectoryResult{
                .entries = result.value.entries,
            });
            return;
        }
        if (std.mem.eql(u8, method, "sessionFs.readdirWithTypes")) {
            validateObjectFields(object, &.{ "sessionId", "path" }) catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const path = jsonRequiredString(object, "path") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const result = filesystem_provider.read_directory_with_types(
                self.allocator,
                path,
                filesystem_provider.context,
            ) catch |err| {
                try self.writeRpcSuccess(writer, id, .{
                    .entries = &.{},
                    .@"error" = filesystemError(err),
                });
                return;
            };
            defer {
                wipeFilesystemEntries(result.value.entries);
                result.deinit();
            }
            if (!validFilesystemEntries(result.value.entries)) {
                try self.writeServerRequestError(writer, id, -32603, "invalid session filesystem callback result");
                return;
            }
            try self.writeRpcSuccess(writer, id, WireFilesystemEntries{
                .entries = result.value.entries,
            });
            return;
        }
        if (std.mem.eql(u8, method, "sessionFs.rm")) {
            validateObjectFields(object, &.{ "sessionId", "path", "recursive", "force" }) catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const path = jsonRequiredString(object, "path") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const recursive = (jsonOptionalNonNullBool(object, "recursive") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            }) orelse false;
            const force = (jsonOptionalNonNullBool(object, "force") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            }) orelse false;
            filesystem_provider.remove(
                path,
                recursive,
                force,
                filesystem_provider.context,
            ) catch |err| {
                try self.writeRpcSuccess(writer, id, filesystemError(err));
                return;
            };
            try self.writeRpcSuccess(writer, id, @as(?FilesystemError, null));
            return;
        }
        if (std.mem.eql(u8, method, "sessionFs.rename")) {
            validateObjectFields(object, &.{ "sessionId", "src", "dest" }) catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const source = jsonRequiredString(object, "src") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const destination = jsonRequiredString(object, "dest") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            filesystem_provider.rename(
                source,
                destination,
                filesystem_provider.context,
            ) catch |err| {
                try self.writeRpcSuccess(writer, id, filesystemError(err));
                return;
            };
            try self.writeRpcSuccess(writer, id, @as(?FilesystemError, null));
            return;
        }
        if (std.mem.eql(u8, method, "sessionFs.sqliteExists")) {
            validateObjectFields(object, &.{"sessionId"}) catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const sqlite = filesystem_provider.sqlite orelse {
                try self.writeRpcSuccess(writer, id, .{ .exists = false });
                return;
            };
            const exists = sqlite.exists(filesystem_provider.context) catch |err| {
                try self.writeServerRequestError(writer, id, -32000, @errorName(err));
                return;
            };
            try self.writeRpcSuccess(writer, id, .{ .exists = exists });
            return;
        }
        if (std.mem.eql(u8, method, "sessionFs.sqliteQuery")) {
            validateObjectFields(object, &.{ "sessionId", "queryType", "query", "params" }) catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const sqlite = filesystem_provider.sqlite orelse {
                try self.writeServerRequestError(writer, id, -32601, "SQLite is not supported by this provider");
                return;
            };
            const query_type = parseSqliteQueryType(object.get("queryType")) catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const query = jsonRequiredString(object, "query") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const sqlite_params = jsonOptionalObjectValue(object, "params") catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const result = sqlite.query(
                self.allocator,
                query_type,
                query,
                sqlite_params,
                filesystem_provider.context,
            ) catch |err| {
                try self.writeServerRequestError(writer, id, -32000, @errorName(err));
                return;
            };
            defer {
                wipeSqliteQueryResult(result.value);
                result.deinit();
            }
            if (!validSqliteQueryResult(result.value)) {
                try self.writeServerRequestError(writer, id, -32603, "invalid session filesystem callback result");
                return;
            }
            try self.writeRpcSuccess(writer, id, WireSqliteQueryResult{
                .value = result.value,
            });
            return;
        }
        if (std.mem.eql(u8, method, "sessionFs.sqliteTransaction")) {
            validateObjectFields(object, &.{ "sessionId", "statements" }) catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            const sqlite = filesystem_provider.sqlite orelse {
                try self.writeServerRequestError(writer, id, -32601, "SQLite is not supported by this provider");
                return;
            };
            const transaction = sqlite.transaction orelse {
                try self.writeRpcSuccess(writer, id, .{
                    .results = &.{},
                    .@"error" = .{
                        .errorClass = "fatal",
                        .message = "SQLite transactions are not supported by this provider",
                    },
                });
                return;
            };
            var statements = parseSqliteStatements(self.allocator, object.get("statements")) catch {
                try self.writeServerRequestError(writer, id, -32602, "invalid session filesystem request");
                return;
            };
            defer statements.deinit(self.allocator);
            const result = transaction(
                self.allocator,
                statements.items,
                filesystem_provider.context,
            ) catch |err| {
                try self.writeRpcSuccess(writer, id, .{
                    .results = &.{},
                    .@"error" = .{
                        .errorClass = "fatal",
                        .message = @errorName(err),
                    },
                });
                return;
            };
            defer {
                wipeSqliteTransactionResult(result.value);
                result.deinit();
            }
            if (!validSqliteTransactionResult(result.value, statements.items.len)) {
                try self.writeServerRequestError(writer, id, -32603, "invalid session filesystem callback result");
                return;
            }
            try self.writeRpcSuccess(writer, id, WireSqliteTransactionResult{
                .value = result.value,
            });
            return;
        }

        try self.rejectServerRequest(writer, id);
    }

    fn writeRpcSuccess(
        self: *Client,
        writer: *std.Io.Writer,
        id: std.json.Value,
        result: anytype,
    ) !void {
        const response = try json_rpc.encodeSuccessResponse(
            self.allocator,
            id,
            result,
        );
        defer {
            wipeSecret(response);
            self.allocator.free(response);
        }
        try json_rpc.writeFrame(writer, response);
    }

    const TypedServerRequest = enum {
        hook,
        canvas,
        provider_token,
        github_token,
        user_input,
        exit_plan_mode,
        auto_mode_switch,
    };

    fn typedServerRequest(method: []const u8) ?TypedServerRequest {
        if (std.mem.eql(u8, method, "hooks.invoke")) return .hook;
        if (std.mem.eql(u8, method, "canvas.open") or
            std.mem.eql(u8, method, "canvas.close") or
            std.mem.eql(u8, method, "canvas.action.invoke"))
        {
            return .canvas;
        }
        if (std.mem.eql(u8, method, "providerToken.getToken")) return .provider_token;
        if (std.mem.eql(u8, method, "gitHubToken.getToken")) return .github_token;
        if (std.mem.eql(u8, method, "userInput.request")) return .user_input;
        if (std.mem.eql(u8, method, "exitPlanMode.request")) return .exit_plan_mode;
        if (std.mem.eql(u8, method, "autoModeSwitch.request")) return .auto_mode_switch;
        return null;
    }

    fn dispatchTypedServerRequest(
        self: *Client,
        request: TypedServerRequest,
        writer: *std.Io.Writer,
        id: std.json.Value,
        method: []const u8,
        params: ?std.json.Value,
        failure_operation: *errors.ClientOperation,
    ) !void {
        return switch (request) {
            .hook => self.dispatchHookRequest(writer, id, params),
            .canvas => self.dispatchCanvasRequest(writer, id, method, params),
            .provider_token => self.dispatchProviderTokenRequest(writer, id, params),
            .github_token => self.dispatchGitHubTokenRequest(writer, id, params),
            .user_input => self.dispatchUserInputRequest(
                writer,
                id,
                params,
                failure_operation,
            ),
            .exit_plan_mode => self.dispatchExitPlanModeRequest(writer, id, params),
            .auto_mode_switch => self.dispatchAutoModeSwitchRequest(writer, id, params),
        };
    }

    fn hasApplicableTypedRegistration(
        self: *Client,
        request: TypedServerRequest,
        method: []const u8,
        params: ?std.json.Value,
    ) bool {
        const object = switch (params orelse return false) {
            .object => |value| value,
            else => return false,
        };
        return switch (request) {
            .hook => self.hasApplicableHookRegistration(object),
            .exit_plan_mode => blk: {
                const session_id = jsonString(object, "sessionId") orelse break :blk false;
                const runtime = self.findExtensionRuntime(session_id) orelse break :blk false;
                break :blk runtime.exit_plan_mode_handler != null;
            },
            .auto_mode_switch => blk: {
                const session_id = jsonString(object, "sessionId") orelse break :blk false;
                const runtime = self.findExtensionRuntime(session_id) orelse break :blk false;
                break :blk runtime.auto_mode_switch_handler != null;
            },
            .canvas => self.hasApplicableCanvasRegistration(method, object),
            .provider_token => self.findProviderTokenFromParams(params) != null,
            .github_token => self.hasApplicableGitHubTokenRegistration(object),
            .user_input => self.findUserInputHandlerFromParams(params) != null,
        };
    }

    fn hasApplicableHookRegistration(
        self: *Client,
        object: std.json.ObjectMap,
    ) bool {
        const session_id = jsonString(object, "sessionId") orelse return false;
        const hook_type = jsonString(object, "hookType") orelse return false;
        const runtime = self.findExtensionRuntime(session_id) orelse return false;
        if (std.mem.eql(u8, hook_type, "preToolUse"))
            return runtime.hooks.on_pre_tool_use != null;
        if (std.mem.eql(u8, hook_type, "preMcpToolCall"))
            return runtime.hooks.on_pre_mcp_tool_call != null;
        if (std.mem.eql(u8, hook_type, "postToolUse"))
            return runtime.hooks.on_post_tool_use != null;
        if (std.mem.eql(u8, hook_type, "postToolUseFailure"))
            return runtime.hooks.on_post_tool_use_failure != null;
        if (std.mem.eql(u8, hook_type, "userPromptSubmitted"))
            return runtime.hooks.on_user_prompt_submitted != null;
        if (std.mem.eql(u8, hook_type, "userPromptTransformed"))
            return runtime.hooks.on_user_prompt_transformed != null;
        if (std.mem.eql(u8, hook_type, "sessionStart"))
            return runtime.hooks.on_session_start != null;
        if (std.mem.eql(u8, hook_type, "sessionEnd"))
            return runtime.hooks.on_session_end != null;
        if (std.mem.eql(u8, hook_type, "errorOccurred"))
            return runtime.hooks.on_error_occurred != null;
        if (std.mem.eql(u8, hook_type, "agentStop"))
            return runtime.hooks.on_agent_stop != null;
        return false;
    }

    fn hasApplicableCanvasRegistration(
        self: *Client,
        method: []const u8,
        object: std.json.ObjectMap,
    ) bool {
        const session_id = jsonString(object, "sessionId") orelse return false;
        const canvas_id = jsonString(object, "canvasId") orelse return false;
        const runtime = self.findExtensionRuntime(session_id) orelse return false;
        for (runtime.canvases) |canvas| {
            if (!std.mem.eql(u8, canvas.id, canvas_id)) continue;
            if (!std.mem.eql(u8, method, "canvas.action.invoke")) return true;
            const action_name = jsonString(object, "actionName") orelse return false;
            for (canvas.actions) |action| {
                if (std.mem.eql(u8, action.name, action_name)) return true;
            }
            return false;
        }
        return false;
    }

    fn hasApplicableGitHubTokenRegistration(
        self: *Client,
        object: std.json.ObjectMap,
    ) bool {
        const registration_id = jsonString(object, "registrationId") orelse return false;
        const runtime = self.findGitHubTokenRuntime(registration_id) orelse return false;
        if (runtime.git_hub_token_provider == null) return false;
        if (runtime.session_id) |registered_session_id| {
            const requested_session_id = jsonString(object, "sessionId") orelse return false;
            return std.mem.eql(u8, registered_session_id, requested_session_id);
        }
        return object.get("sessionId") == null;
    }

    fn jsonString(object: std.json.ObjectMap, name: []const u8) ?[]const u8 {
        return switch (object.get(name) orelse return null) {
            .string => |value| value,
            else => null,
        };
    }

    fn writeTypedSuccess(
        self: *Client,
        writer: *std.Io.Writer,
        id: std.json.Value,
        result: anytype,
    ) !void {
        const result_json = try std.json.Stringify.valueAlloc(self.allocator, result, .{
            .emit_null_optional_fields = false,
        });
        defer {
            wipeSecret(result_json);
            self.allocator.free(result_json);
        }
        const parsed = try std.json.parseFromSlice(std.json.Value, self.allocator, result_json, .{});
        defer {
            wipeJsonStrings(parsed.value);
            parsed.deinit();
        }
        const response = try json_rpc.encodeSuccessResponse(self.allocator, id, parsed.value);
        defer {
            wipeSecret(response);
            self.allocator.free(response);
        }
        try json_rpc.writeFrame(writer, response);
    }

    fn writeNullSuccess(
        self: *Client,
        writer: *std.Io.Writer,
        id: std.json.Value,
    ) !void {
        const result: std.json.Value = .null;
        const response = try json_rpc.encodeSuccessResponse(self.allocator, id, result);
        defer {
            wipeSecret(response);
            self.allocator.free(response);
        }
        try json_rpc.writeFrame(writer, response);
    }

    fn dispatchHookRequest(
        self: *Client,
        writer: *std.Io.Writer,
        id: std.json.Value,
        params: ?std.json.Value,
    ) !void {
        const object = switch (params orelse
            return self.writeServerRequestError(writer, id, -32602, "invalid hook request")) {
            .object => |value| value,
            else => return self.writeServerRequestError(writer, id, -32602, "invalid hook request"),
        };
        const session_id = jsonRequiredString(object, "sessionId") catch
            return self.writeServerRequestError(writer, id, -32602, "invalid hook request");
        const hook_type = jsonRequiredString(object, "hookType") catch
            return self.writeServerRequestError(writer, id, -32602, "invalid hook request");
        const input = switch (object.get("input") orelse
            return self.writeServerRequestError(writer, id, -32602, "invalid hook request")) {
            .object => |value| value,
            else => return self.writeServerRequestError(writer, id, -32602, "invalid hook request"),
        };
        const runtime = self.findExtensionRuntime(session_id) orelse
            return self.writeServerRequestError(writer, id, -32000, "session not registered");
        const base = parseHookBase(input) catch
            return self.writeServerRequestError(writer, id, -32602, "invalid hook input");
        if (!std.mem.eql(u8, session_id, base.runtime_session_id))
            return self.writeServerRequestError(writer, id, -32602, "invalid hook input");
        const invocation = ext.HookInvocation{ .session_id = session_id };
        self.beginRpcHandler();
        defer self.endRpcHandler();

        if (std.mem.eql(u8, hook_type, "preToolUse")) {
            const handler = runtime.hooks.on_pre_tool_use orelse
                return self.writeTypedSuccess(writer, id, .{});
            const args = try stringifyJsonValue(
                self.allocator,
                jsonRequiredValue(input, "toolArgs") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
            );
            defer self.allocator.free(args);
            const output = handler(self.allocator, .{
                .base = base,
                .tool_name = jsonRequiredString(input, "toolName") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
                .tool_args_json = args,
            }, invocation, runtime.hooks.context) catch |err|
                return self.writeServerRequestError(writer, id, -32000, @errorName(err));
            const modified = parseOptionalJson(
                self.allocator,
                output.modified_args_json,
            ) catch return self.writeServerRequestError(
                writer,
                id,
                -32603,
                "invalid hook output",
            );
            defer if (modified) |value| value.deinit();
            return self.writeTypedSuccess(writer, id, .{ .output = .{
                .permissionDecision = output.permission_decision,
                .permissionDecisionReason = output.permission_decision_reason,
                .modifiedArgs = if (modified) |value| value.value else null,
                .additionalContext = output.additional_context,
                .suppressOutput = output.suppress_output,
            } });
        }
        if (std.mem.eql(u8, hook_type, "preMcpToolCall")) {
            const handler = runtime.hooks.on_pre_mcp_tool_call orelse
                return self.writeTypedSuccess(writer, id, .{});
            const arguments = try stringifyJsonValue(
                self.allocator,
                jsonRequiredValue(input, "arguments") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
            );
            defer self.allocator.free(arguments);
            const meta = if (input.get("_meta")) |value|
                try stringifyJsonValue(self.allocator, value)
            else
                null;
            defer if (meta) |value| self.allocator.free(value);
            const output = handler(self.allocator, .{
                .base = base,
                .tool_call_id = jsonOptionalString(input, "toolCallId") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
                .server_name = jsonRequiredString(input, "serverName") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
                .tool_name = jsonRequiredString(input, "toolName") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
                .arguments_json = arguments,
                .meta_json = meta,
            }, invocation, runtime.hooks.context) catch |err|
                return self.writeServerRequestError(writer, id, -32000, @errorName(err));
            const meta_value = parseOptionalJson(
                self.allocator,
                output.meta_to_use_json,
            ) catch return self.writeServerRequestError(
                writer,
                id,
                -32603,
                "invalid hook output",
            );
            defer if (meta_value) |value| value.deinit();
            return self.writeTypedSuccess(writer, id, .{ .output = .{
                .metaToUse = if (output.omit_meta)
                    std.json.Value.null
                else if (meta_value) |value|
                    value.value
                else
                    null,
            } });
        }
        if (std.mem.eql(u8, hook_type, "postToolUse")) {
            const handler = runtime.hooks.on_post_tool_use orelse
                return self.writeTypedSuccess(writer, id, .{});
            const args = try stringifyJsonValue(
                self.allocator,
                jsonRequiredValue(input, "toolArgs") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
            );
            defer self.allocator.free(args);
            const tool_result = try stringifyJsonValue(
                self.allocator,
                jsonRequiredValue(input, "toolResult") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
            );
            defer self.allocator.free(tool_result);
            const output = handler(self.allocator, .{
                .base = base,
                .tool_name = jsonRequiredString(input, "toolName") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
                .tool_args_json = args,
                .tool_result_json = tool_result,
            }, invocation, runtime.hooks.context) catch |err|
                return self.writeServerRequestError(writer, id, -32000, @errorName(err));
            const modified = parseOptionalJson(
                self.allocator,
                output.modified_result_json,
            ) catch return self.writeServerRequestError(
                writer,
                id,
                -32603,
                "invalid hook output",
            );
            defer if (modified) |value| value.deinit();
            return self.writeTypedSuccess(writer, id, .{ .output = .{
                .modifiedResult = if (modified) |value| value.value else null,
                .additionalContext = output.additional_context,
                .suppressOutput = output.suppress_output,
            } });
        }
        if (std.mem.eql(u8, hook_type, "postToolUseFailure")) {
            const handler = runtime.hooks.on_post_tool_use_failure orelse
                return self.writeTypedSuccess(writer, id, .{});
            const args = try stringifyJsonValue(
                self.allocator,
                jsonRequiredValue(input, "toolArgs") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
            );
            defer self.allocator.free(args);
            const output = handler(self.allocator, .{
                .base = base,
                .tool_name = jsonRequiredString(input, "toolName") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
                .tool_args_json = args,
                .message = jsonRequiredString(input, "error") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
            }, invocation, runtime.hooks.context) catch |err|
                return self.writeServerRequestError(writer, id, -32000, @errorName(err));
            return self.writeTypedSuccess(writer, id, .{ .output = .{
                .additionalContext = output.additional_context,
            } });
        }
        if (std.mem.eql(u8, hook_type, "userPromptSubmitted")) {
            const handler = runtime.hooks.on_user_prompt_submitted orelse
                return self.writeTypedSuccess(writer, id, .{});
            const output = handler(self.allocator, .{
                .base = base,
                .prompt = jsonRequiredString(input, "prompt") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
            }, invocation, runtime.hooks.context) catch |err|
                return self.writeServerRequestError(writer, id, -32000, @errorName(err));
            return self.writeTypedSuccess(writer, id, .{ .output = .{
                .modifiedPrompt = output.modified_prompt,
                .additionalContext = output.additional_context,
                .suppressOutput = output.suppress_output,
            } });
        }
        if (std.mem.eql(u8, hook_type, "userPromptTransformed")) {
            const handler = runtime.hooks.on_user_prompt_transformed orelse
                return self.writeTypedSuccess(writer, id, .{});
            const output = handler(self.allocator, .{
                .base = base,
                .prompt = jsonRequiredString(input, "prompt") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
                .transformed_prompt = jsonRequiredString(input, "transformedPrompt") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
            }, invocation, runtime.hooks.context) catch |err|
                return self.writeServerRequestError(writer, id, -32000, @errorName(err));
            return self.writeTypedSuccess(writer, id, .{ .output = .{
                .modifiedTransformedPrompt = output.modified_transformed_prompt,
            } });
        }
        if (std.mem.eql(u8, hook_type, "sessionStart")) {
            const handler = runtime.hooks.on_session_start orelse
                return self.writeTypedSuccess(writer, id, .{});
            const source_string = jsonRequiredString(input, "source") catch
                return self.writeServerRequestError(writer, id, -32602, "invalid hook input");
            const source: @TypeOf(@as(ext.SessionStartInput, undefined).source) =
                if (std.mem.eql(u8, source_string, "startup"))
                    .startup
                else if (std.mem.eql(u8, source_string, "resume"))
                    .resumed
                else if (std.mem.eql(u8, source_string, "new"))
                    .created
                else
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input");
            const output = handler(self.allocator, .{
                .base = base,
                .source = source,
                .initial_prompt = jsonOptionalString(input, "initialPrompt") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
            }, invocation, runtime.hooks.context) catch |err|
                return self.writeServerRequestError(writer, id, -32000, @errorName(err));
            const modified = parseOptionalJson(
                self.allocator,
                output.modified_config_json,
            ) catch return self.writeServerRequestError(
                writer,
                id,
                -32603,
                "invalid hook output",
            );
            defer if (modified) |value| value.deinit();
            return self.writeTypedSuccess(writer, id, .{ .output = .{
                .additionalContext = output.additional_context,
                .modifiedConfig = if (modified) |value| value.value else null,
            } });
        }
        if (std.mem.eql(u8, hook_type, "sessionEnd")) {
            const handler = runtime.hooks.on_session_end orelse
                return self.writeTypedSuccess(writer, id, .{});
            const reason_string = jsonRequiredString(input, "reason") catch
                return self.writeServerRequestError(writer, id, -32602, "invalid hook input");
            const reason: @TypeOf(@as(ext.SessionEndInput, undefined).reason) =
                std.meta.stringToEnum(
                    @TypeOf(@as(ext.SessionEndInput, undefined).reason),
                    reason_string,
                ) orelse
                return self.writeServerRequestError(writer, id, -32602, "invalid hook input");
            const output = handler(self.allocator, .{
                .base = base,
                .reason = reason,
                .final_message = jsonOptionalString(input, "finalMessage") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
                .message = jsonOptionalString(input, "error") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
            }, invocation, runtime.hooks.context) catch |err|
                return self.writeServerRequestError(writer, id, -32000, @errorName(err));
            return self.writeTypedSuccess(writer, id, .{ .output = .{
                .suppressOutput = output.suppress_output,
                .cleanupActions = output.cleanup_actions,
                .sessionSummary = output.session_summary,
            } });
        }
        if (std.mem.eql(u8, hook_type, "errorOccurred")) {
            const handler = runtime.hooks.on_error_occurred orelse
                return self.writeTypedSuccess(writer, id, .{});
            const context_string = jsonRequiredString(input, "errorContext") catch
                return self.writeServerRequestError(writer, id, -32602, "invalid hook input");
            const context: @TypeOf(@as(ext.ErrorOccurredInput, undefined).context) =
                std.meta.stringToEnum(
                    @TypeOf(@as(ext.ErrorOccurredInput, undefined).context),
                    context_string,
                ) orelse
                return self.writeServerRequestError(writer, id, -32602, "invalid hook input");
            const output = handler(self.allocator, .{
                .base = base,
                .message = jsonRequiredString(input, "error") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
                .context = context,
                .recoverable = jsonRequiredBool(input, "recoverable") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
            }, invocation, runtime.hooks.context) catch |err|
                return self.writeServerRequestError(writer, id, -32000, @errorName(err));
            return self.writeTypedSuccess(writer, id, .{ .output = .{
                .suppressOutput = output.suppress_output,
                .errorHandling = output.handling,
                .retryCount = output.retry_count,
                .userNotification = output.user_notification,
            } });
        }
        if (std.mem.eql(u8, hook_type, "agentStop")) {
            const handler = runtime.hooks.on_agent_stop orelse
                return self.writeTypedSuccess(writer, id, .{});
            const output = handler(self.allocator, .{
                .base = base,
                .stop_reason = jsonOptionalString(input, "stopReason") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
                .transcript_path = jsonOptionalString(input, "transcriptPath") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input"),
                .stop_hook_active = (jsonOptionalBool(input, "stop_hook_active") catch
                    return self.writeServerRequestError(writer, id, -32602, "invalid hook input")) orelse false,
            }, invocation, runtime.hooks.context) catch |err|
                return self.writeServerRequestError(writer, id, -32000, @errorName(err));
            return self.writeTypedSuccess(writer, id, .{ .output = .{
                .decision = if (output.block) "block" else null,
                .reason = output.reason,
            } });
        }
        return self.writeServerRequestError(writer, id, -32602, "unknown hook type");
    }

    fn dispatchCanvasRequest(
        self: *Client,
        writer: *std.Io.Writer,
        id: std.json.Value,
        method: []const u8,
        params: ?std.json.Value,
    ) !void {
        const object = switch (params orelse
            return self.writeServerRequestError(writer, id, -32602, "invalid canvas request")) {
            .object => |value| value,
            else => return self.writeServerRequestError(writer, id, -32602, "invalid canvas request"),
        };
        const session_id = jsonRequiredString(object, "sessionId") catch
            return self.writeServerRequestError(writer, id, -32602, "invalid canvas request");
        const runtime = self.findExtensionRuntime(session_id) orelse
            return self.writeServerRequestError(writer, id, -32000, "session not registered");
        const canvas_id = jsonRequiredString(object, "canvasId") catch
            return self.writeServerRequestError(writer, id, -32602, "invalid canvas request");
        var canvas: ?*OwnedCanvas = null;
        for (runtime.canvases) |*candidate| {
            if (std.mem.eql(u8, candidate.id, canvas_id)) {
                canvas = candidate;
                break;
            }
        }
        const registered = canvas orelse
            return self.writeServerRequestError(writer, id, -32000, "canvas not registered");
        const extension_id = jsonRequiredString(object, "extensionId") catch
            return self.writeServerRequestError(writer, id, -32602, "invalid canvas request");
        const instance_id = jsonRequiredString(object, "instanceId") catch
            return self.writeServerRequestError(writer, id, -32602, "invalid canvas request");
        const host_json = if (object.get("host")) |value|
            try stringifyJsonValue(self.allocator, value)
        else
            null;
        defer if (host_json) |value| self.allocator.free(value);
        const session_json = if (object.get("session")) |value|
            try stringifyJsonValue(self.allocator, value)
        else
            null;
        defer if (session_json) |value| self.allocator.free(value);
        self.beginRpcHandler();
        defer self.endRpcHandler();

        if (std.mem.eql(u8, method, "canvas.open")) {
            const input_json = if (object.get("input")) |value|
                try stringifyJsonValue(self.allocator, value)
            else
                null;
            defer if (input_json) |value| {
                wipeSecret(value);
                self.allocator.free(value);
            };
            const output = registered.on_open(self.allocator, .{
                .extension_id = extension_id,
                .canvas_id = canvas_id,
                .instance_id = instance_id,
                .input_json = input_json,
                .host_json = host_json,
                .session_json = session_json,
            }, registered.context) catch |err|
                return self.writeServerRequestError(writer, id, -32000, @errorName(err));
            return self.writeTypedSuccess(writer, id, output);
        }
        if (std.mem.eql(u8, method, "canvas.close")) {
            if (registered.on_close) |handler| {
                handler(.{
                    .extension_id = extension_id,
                    .canvas_id = canvas_id,
                    .instance_id = instance_id,
                    .host_json = host_json,
                    .session_json = session_json,
                }, registered.context) catch |err|
                    return self.writeServerRequestError(writer, id, -32000, @errorName(err));
            }
            return self.writeNullSuccess(writer, id);
        }
        const action_name = jsonRequiredString(object, "actionName") catch
            return self.writeServerRequestError(writer, id, -32602, "invalid canvas request");
        for (registered.actions) |action| {
            if (!std.mem.eql(u8, action.name, action_name)) continue;
            const input_json = if (object.get("input")) |value|
                try stringifyJsonValue(self.allocator, value)
            else
                null;
            defer if (input_json) |value| self.allocator.free(value);
            const output_json = action.handler(self.allocator, .{
                .extension_id = extension_id,
                .canvas_id = canvas_id,
                .instance_id = instance_id,
                .action_name = action_name,
                .input_json = input_json,
                .host_json = host_json,
                .session_json = session_json,
            }, registered.context) catch |err|
                return self.writeServerRequestError(writer, id, -32000, @errorName(err));
            defer {
                wipeSecret(output_json);
                self.allocator.free(output_json);
            }
            const output = std.json.parseFromSlice(
                std.json.Value,
                self.allocator,
                output_json,
                .{},
            ) catch return self.writeServerRequestError(
                writer,
                id,
                -32603,
                "invalid canvas action result",
            );
            defer {
                wipeJsonStrings(output.value);
                output.deinit();
            }
            const response = try json_rpc.encodeSuccessResponse(self.allocator, id, output.value);
            defer {
                wipeSecret(response);
                self.allocator.free(response);
            }
            return json_rpc.writeFrame(writer, response);
        }
        return self.writeServerRequestError(writer, id, -32000, "canvas action not registered");
    }

    fn dispatchProviderTokenRequest(
        self: *Client,
        writer: *std.Io.Writer,
        id: std.json.Value,
        params: ?std.json.Value,
    ) !void {
        const value = params orelse
            return self.writeServerRequestError(writer, id, -32602, "invalid provider token request");
        const parsed = std.json.parseFromValue(
            WireProviderTokenRequest,
            self.allocator,
            value,
            .{},
        ) catch {
            return self.writeServerRequestError(writer, id, -32602, "invalid provider token request");
        };
        defer parsed.deinit();

        const token_provider = self.findProviderToken(
            parsed.value.sessionId,
            parsed.value.providerName,
        ) orelse return self.writeServerRequestError(
            writer,
            id,
            -32000,
            "bearer token provider not registered",
        );

        self.beginRpcHandler();
        defer self.endRpcHandler();
        const token = token_provider.callback(self.allocator, .{
            .session_id = parsed.value.sessionId,
            .provider_name = parsed.value.providerName,
        }, token_provider.context) catch |err| {
            return self.writeServerRequestError(writer, id, -32000, @errorName(err));
        };
        defer {
            wipeSecret(token);
            self.allocator.free(token);
        }

        const response = try json_rpc.encodeSuccessResponse(self.allocator, id, .{ .token = token });
        defer {
            wipeSecret(response);
            self.allocator.free(response);
        }
        try json_rpc.writeFrame(writer, response);
    }

    fn findGitHubTokenRuntime(
        self: *Client,
        registration_id: []const u8,
    ) ?*SessionExtensionRuntime {
        if (self.pending_extension_runtime) |*runtime| {
            if (runtime.git_hub_token_registration_id) |candidate| {
                if (std.mem.eql(u8, candidate, registration_id)) return runtime;
            }
        }
        for (self.extension_runtimes.items) |*runtime| {
            if (runtime.git_hub_token_registration_id) |candidate| {
                if (std.mem.eql(u8, candidate, registration_id)) return runtime;
            }
        }
        return null;
    }

    fn dispatchGitHubTokenRequest(
        self: *Client,
        writer: *std.Io.Writer,
        id: std.json.Value,
        params: ?std.json.Value,
    ) !void {
        const value = params orelse
            return self.writeServerRequestError(writer, id, -32602, "invalid GitHub token request");
        const parsed = std.json.parseFromValue(
            WireGitHubTokenRequest,
            self.allocator,
            value,
            .{ .ignore_unknown_fields = false },
        ) catch
            return self.writeServerRequestError(writer, id, -32602, "invalid GitHub token request");
        defer parsed.deinit();
        if (value.object.get("sessionId")) |session_id| {
            if (session_id != .string)
                return self.writeServerRequestError(writer, id, -32602, "invalid GitHub token request");
        }

        const runtime = self.findGitHubTokenRuntime(parsed.value.registrationId) orelse
            return self.writeServerRequestError(writer, id, -32602, "unknown GitHub token registration");
        if (runtime.session_id) |registered_session_id| {
            const requested_session_id = parsed.value.sessionId orelse
                return self.writeServerRequestError(writer, id, -32602, "GitHub token registration mismatch");
            if (!std.mem.eql(u8, registered_session_id, requested_session_id))
                return self.writeServerRequestError(writer, id, -32602, "GitHub token registration mismatch");
        } else if (parsed.value.sessionId != null) {
            return self.writeServerRequestError(writer, id, -32602, "GitHub token registration mismatch");
        }
        const provider_config = runtime.git_hub_token_provider orelse
            return self.writeServerRequestError(writer, id, -32602, "unknown GitHub token registration");

        self.beginRpcHandler();
        defer self.endRpcHandler();
        var result = provider_config.callback(self.allocator, .{
            .host = parsed.value.host,
            .session_id = parsed.value.sessionId orelse runtime.session_id,
            .reason = parsed.value.reason,
        }, provider_config.context) catch |err|
            return self.writeServerRequestError(writer, id, -32000, @errorName(err));
        defer switch (result) {
            .token => |*token| token.deinitSecure(self.allocator),
            .cancelled => {},
        };

        switch (result) {
            .cancelled => return self.writeTypedSuccess(writer, id, .{ .kind = "cancelled" }),
            .token => |token| {
                if (token.expires_in_seconds < 3601)
                    return self.writeServerRequestError(writer, id, -32603, "invalid GitHub token result");
                return self.writeTypedSuccess(writer, id, .{
                    .kind = "token",
                    .accessToken = token.access_token,
                    .tokenType = token.token_type,
                    .expiresIn = token.expires_in_seconds,
                });
            },
        }
    }

    fn dispatchExitPlanModeRequest(
        self: *Client,
        writer: *std.Io.Writer,
        id: std.json.Value,
        params: ?std.json.Value,
    ) !void {
        const value = params orelse
            return self.writeServerRequestError(writer, id, -32602, "invalid exit plan mode request");
        const parsed = std.json.parseFromValue(
            WireExitPlanModeRequest,
            self.allocator,
            value,
            .{},
        ) catch return self.writeServerRequestError(
            writer,
            id,
            -32602,
            "invalid exit plan mode request",
        );
        defer parsed.deinit();
        const runtime = self.findExtensionRuntime(parsed.value.sessionId) orelse
            return self.writeServerRequestError(writer, id, -32602, "unknown exit plan mode session");
        const handler = runtime.exit_plan_mode_handler orelse
            return self.writeTypedSuccess(writer, id, .{ .approved = true });
        self.beginRpcHandler();
        defer self.endRpcHandler();
        const result = handler(.{
            .session_id = parsed.value.sessionId,
            .summary = parsed.value.summary,
            .plan_content = parsed.value.planContent,
            .actions = parsed.value.actions,
            .recommended_action = parsed.value.recommendedAction,
        }, runtime.exit_plan_mode_context) catch |err|
            return self.writeServerRequestError(writer, id, -32000, @errorName(err));
        if (result.selected_action) |selected| {
            var found = false;
            for (parsed.value.actions) |action| {
                if (action == selected) {
                    found = true;
                    break;
                }
            }
            if (!found)
                return self.writeServerRequestError(writer, id, -32603, "invalid exit plan mode result");
        }
        return self.writeTypedSuccess(writer, id, .{
            .approved = result.approved,
            .selectedAction = result.selected_action,
            .feedback = result.feedback,
        });
    }

    fn dispatchAutoModeSwitchRequest(
        self: *Client,
        writer: *std.Io.Writer,
        id: std.json.Value,
        params: ?std.json.Value,
    ) !void {
        const value = params orelse
            return self.writeServerRequestError(writer, id, -32602, "invalid auto mode switch request");
        const parsed = std.json.parseFromValue(
            WireAutoModeSwitchRequest,
            self.allocator,
            value,
            .{},
        ) catch return self.writeServerRequestError(
            writer,
            id,
            -32602,
            "invalid auto mode switch request",
        );
        defer parsed.deinit();
        const runtime = self.findExtensionRuntime(parsed.value.sessionId) orelse
            return self.writeServerRequestError(writer, id, -32602, "unknown auto mode switch session");
        const handler = runtime.auto_mode_switch_handler orelse
            return self.writeTypedSuccess(writer, id, .{ .response = session_types.AutoModeSwitchResponse.no });

        self.beginRpcHandler();
        defer self.endRpcHandler();
        const response = handler(.{
            .session_id = parsed.value.sessionId,
            .error_code = parsed.value.errorCode,
            .retry_after_seconds = parsed.value.retryAfterSeconds,
        }, runtime.auto_mode_switch_context) catch |err|
            return self.writeServerRequestError(writer, id, -32000, @errorName(err));
        return self.writeTypedSuccess(writer, id, .{ .response = response });
    }

    fn findRpcHandler(self: *Client, method: []const u8) ?RegisteredRpcHandler {
        for (self.rpc_handlers.items) |registered| {
            if (std.mem.eql(u8, registered.method, method)) return registered;
        }
        return null;
    }

    fn dispatchUserInputRequest(
        self: *Client,
        writer: *std.Io.Writer,
        id: std.json.Value,
        params: ?std.json.Value,
        failure_operation: *errors.ClientOperation,
    ) !void {
        const value = params orelse
            return self.writeServerRequestError(writer, id, -32602, "invalid user input request");
        const parsed = std.json.parseFromValue(
            WireUserInputRequest,
            self.allocator,
            value,
            .{ .ignore_unknown_fields = true },
        ) catch {
            failure_operation.* = .write;
            return self.writeServerRequestError(writer, id, -32602, "invalid user input request");
        };
        defer parsed.deinit();

        const registered = self.findUserInputHandler(parsed.value.sessionId) orelse
            {
                failure_operation.* = .write;
                return self.writeServerRequestError(
                    writer,
                    id,
                    -32000,
                    "user input handler not registered",
                );
            };

        self.beginRpcHandler();
        defer self.endRpcHandler();
        const response = registered.handler(self.allocator, .{
            .session_id = parsed.value.sessionId,
            .question = parsed.value.question,
            .choices = parsed.value.choices,
            .allow_freeform = parsed.value.allowFreeform,
        }, registered.context) catch |err| {
            failure_operation.* = .write;
            return self.writeServerRequestError(writer, id, -32000, @errorName(err));
        };
        defer {
            wipeSecret(response.answer);
            self.allocator.free(response.answer);
        }

        const frame = try json_rpc.encodeSuccessResponse(
            self.allocator,
            id,
            .{
                .answer = response.answer,
                .wasFreeform = response.was_freeform,
            },
        );
        defer {
            wipeSecret(frame);
            self.allocator.free(frame);
        }
        failure_operation.* = .write;
        try json_rpc.writeFrame(writer, frame);
    }

    fn writeServerRequestError(
        self: *Client,
        writer: *std.Io.Writer,
        id: std.json.Value,
        code: i64,
        message: []const u8,
    ) !void {
        const response = try json_rpc.encodeErrorResponse(
            self.allocator,
            id,
            code,
            message,
        );
        defer {
            wipeSecret(response);
            self.allocator.free(response);
        }
        try json_rpc.writeFrame(writer, response);
    }

    fn sessionAgentWireView(event_value: std.json.Value) SessionEventWireError!?SessionAgentWireView {
        const event_object = switch (event_value) {
            .object => |object| object,
            else => return error.MalformedFieldType,
        };
        const event_type = switch (event_object.get("type") orelse
            return error.MissingField) {
            .string => |value| value,
            else => return error.MalformedFieldType,
        };
        if (!std.mem.eql(u8, event_type, "session.error")) return null;
        const data = switch (event_object.get("data") orelse
            return error.MissingField) {
            .object => |object| object,
            else => return error.MalformedFieldType,
        };
        return .{
            .error_type = try requiredWireString(data, "errorType"),
            .error_code = try optionalWireString(data, "errorCode"),
            .message = try requiredWireString(data, "message"),
            .status_code = try optionalWireStatusCode(data, "statusCode"),
            .provider_call_id = try optionalWireString(data, "providerCallId"),
            .service_request_id = try optionalWireString(data, "serviceRequestId"),
            .remediation = data.get("remediation"),
            .url = try optionalWireString(data, "url"),
            .stack = try optionalWireString(data, "stack"),
            .eligible_for_auto_switch = try optionalWireBool(data, "eligibleForAutoSwitch"),
        };
    }

    fn queueSessionEvent(
        self: *Client,
        comptime failure_policy: FailurePolicy,
        frame: []u8,
        params_value: std.json.Value,
    ) errors.DetailedError!PolicyResult(failure_policy, bool) {
        const params = switch (params_value) {
            .object => |object| object,
            else => return .{ .failure = try policyFailure(
                failure_policy,
                error.InvalidJsonRpc,
                recordInvalidEnvelope,
                .{
                    self.allocator,
                    error.InvalidJsonRpc,
                    .malformed_field_type,
                    params_value,
                },
            ) },
        };
        const session_id_value = params.get("sessionId") orelse
            return .{ .failure = try policyFailure(
                failure_policy,
                error.InvalidJsonRpc,
                recordInvalidEnvelope,
                .{ self.allocator, error.InvalidJsonRpc, .missing_params, params_value },
            ) };
        const session_id = switch (session_id_value) {
            .string => |id| id,
            else => return .{ .failure = try policyFailure(
                failure_policy,
                error.InvalidJsonRpc,
                recordInvalidEnvelope,
                .{
                    self.allocator,
                    error.InvalidJsonRpc,
                    .malformed_field_type,
                    params_value,
                },
            ) },
        };
        const owned_session_id = try self.allocator.dupe(u8, session_id);
        var transferred = false;
        defer if (!transferred) self.allocator.free(owned_session_id);
        const event_value = params.get("event") orelse
            return .{ .failure = try policyFailure(
                failure_policy,
                error.InvalidJsonRpc,
                recordInvalidEnvelope,
                .{ self.allocator, error.InvalidJsonRpc, .missing_params, params_value },
            ) };
        const agent_view = sessionAgentWireView(event_value) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                error.InvalidSessionEvent,
                recordInvalidEvent,
                .{ self.allocator, sessionEventViolation(err), event_value },
            ) };
        var event = event: {
            const parsed_event = session_types.parseEventClassified(
                self.allocator,
                event_value,
            ) catch |err| {
                if (agent_view) |view| {
                    const data_value = event_value.object.get("data").?;
                    break :event ownFallbackSessionErrorEvent(
                        self.allocator,
                        view,
                        data_value,
                    ) catch |fallback_err| {
                        if (fallback_err == error.OutOfMemory) return error.OutOfMemory;
                        return .{ .failure = try policyFailure(
                            failure_policy,
                            error.InvalidSessionEvent,
                            recordInvalidEvent,
                            .{ self.allocator, .malformed_field_type, event_value },
                        ) };
                    };
                }
                switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.MissingField, error.MalformedFieldType => return .{
                        .failure = try policyFailure(
                            failure_policy,
                            error.InvalidSessionEvent,
                            recordInvalidEvent,
                            .{
                                self.allocator,
                                if (err == error.MissingField)
                                    errors.EnvelopeViolation.missing_params
                                else
                                    errors.EnvelopeViolation.malformed_field_type,
                                event_value,
                            },
                        ),
                    },
                }
            };
            break :event parsed_event;
        };
        defer if (!transferred) event.deinit(self.allocator);
        const admission = self.acquireActiveEventIngress(
            owned_session_id,
            true,
        ) catch |err| return .{ .failure = try policyFailure(
            failure_policy,
            err,
            recordClientIo,
            .{ self.allocator, .read, err },
        ) };
        var active_lease: ?EventLogLease = switch (admission) {
            .unknown => null,
            .unavailable => return .{ .success = false },
            .active => |lease| lease,
        };
        defer if (active_lease) |*lease| lease.deinit();
        const ingress_admitted = active_lease != null;
        var ingress_transferred = false;
        defer if (ingress_admitted and !ingress_transferred)
            self.finishSessionIngress(active_lease.?.log);
        const pump_running = self.isPumpRunning();
        if (ingress_admitted) try self.applyExtensionEvent(owned_session_id, &event);
        const diagnostic_frame = if (agent_view != null) frame else null;
        const event_id = self.next_queued_event_id;
        self.next_queued_event_id +%= 1;
        if (self.next_queued_event_id == 0) self.next_queued_event_id = 1;
        const delivery_class: EventDeliveryClass = switch (event) {
            .command_execute, .elicitation_requested => .automatic,
            .mcp_oauth_required => if (ingress_admitted and
                self.extensionRuntimeHandlesMcpAuth(owned_session_id))
                .automatic
            else
                .observation,
            .permission_requested => .permission_request,
            .external_tool_requested => .external_tool_request,
            else => .observation,
        };
        const active_log = if (active_lease) |lease| lease.log else null;
        const generation = if (active_log) |log| log.generation else 0;
        const worker_async = pump_running and
            (active_log != null or
                (delivery_class == .automatic and ingress_admitted));
        if (!worker_async and delivery_class == .automatic and ingress_admitted) {
            var ingress_scope: SessionIngressScope = undefined;
            beginSessionIngressScope(&ingress_scope, active_log.?);
            defer endSessionIngressScope(&ingress_scope);
            self.handleAutomaticSessionEvent(
                owned_session_id,
                .{ .transient = &event },
            );
        }
        var log_delivery: ?EventDelivery = if (worker_async)
            self.cloneEventDelivery(
                event_id,
                owned_session_id,
                generation,
                event,
                diagnostic_frame,
                delivery_class == .automatic,
            ) catch |err| return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidEvent,
                .{ self.allocator, .malformed_field_type, event_value },
            ) }
        else
            null;
        defer if (log_delivery) |*delivery| delivery.deinit(self.allocator);

        const prior_queue_failure = if (ingress_admitted)
            self.sessionEventQueueFailure(owned_session_id)
        else
            null;
        self.events_mutex.lockUncancelable(self.io);
        if (prior_queue_failure != null or
            self.queuedEventCount(owned_session_id, generation) >= max_queued_events)
        {
            self.events_mutex.unlock(self.io);
            if (ingress_admitted) {
                self.handleUnretainedEvent(
                    owned_session_id,
                    &event,
                    delivery_class,
                    .capacity_exceeded,
                );
            }
            return .{ .success = false };
        }
        self.events.append(self.allocator, .{
            .id = event_id,
            .session_id = owned_session_id,
            .generation = generation,
            .event = event,
            .diagnostic_frame = diagnostic_frame,
            .automatic_handling_in_progress = worker_async,
        }) catch {
            self.events_mutex.unlock(self.io);
            if (ingress_admitted) {
                self.handleUnretainedEvent(
                    owned_session_id,
                    &event,
                    delivery_class,
                    .allocation_failed,
                );
            }
            return .{ .success = false };
        };
        transferred = true;
        self.events_mutex.unlock(self.io);

        if (active_log) |log| {
            if (worker_async) {
                self.enqueueLogEvent(.{
                    .log = log,
                    .event_id = event_id,
                    .delivery = log_delivery.?,
                    .delivery_class = delivery_class,
                }) catch |err| {
                    if (err == error.SessionDisconnected) {
                        if (delivery_class == .automatic)
                            self.setAutomaticDeliveryFailure(event_id, err)
                        else
                            self.finishRetainedEvent(event_id, event, false);
                        return .{ .success = agent_view != null };
                    }
                    self.removeQueuedEvent(event_id);
                    return .{ .failure = try policyFailure(
                        failure_policy,
                        err,
                        recordClientIo,
                        .{ self.allocator, .read, err },
                    ) };
                };
                ingress_transferred = true;
                log_delivery = null;
            } else {
                var cloned = session_types.cloneEvent(self.allocator, event) catch |err| {
                    self.removeQueuedEvent(event_id);
                    return .{ .failure = try policyFailure(
                        failure_policy,
                        err,
                        recordInvalidEvent,
                        .{ self.allocator, .malformed_field_type, event_value },
                    ) };
                };
                var cloned_owned = true;
                defer if (cloned_owned) cloned.deinit(self.allocator);
                log.observeTurnEvent(cloned) catch |err| {
                    self.removeQueuedEvent(event_id);
                    return .{ .failure = try policyFailure(
                        failure_policy,
                        err,
                        recordClientIo,
                        .{ self.allocator, .read, err },
                    ) };
                };
                log.appendCompatibilityConsumed(cloned) catch |err| {
                    self.removeQueuedEvent(event_id);
                    return .{ .failure = try policyFailure(
                        failure_policy,
                        err,
                        recordClientIo,
                        .{ self.allocator, .read, err },
                    ) };
                };
                cloned_owned = false;
            }
        } else if (worker_async) {
            self.enqueueLogEvent(.{
                .log = null,
                .event_id = event_id,
                .delivery = log_delivery.?,
                .delivery_class = delivery_class,
            }) catch |err| {
                if (err == error.SessionDisconnected) {
                    self.setAutomaticDeliveryFailure(event_id, err);
                    return .{ .success = agent_view != null };
                }
                self.removeQueuedEvent(event_id);
                return .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordClientIo,
                    .{ self.allocator, .read, err },
                ) };
            };
            log_delivery = null;
        }
        return .{ .success = agent_view != null };
    }

    fn removeQueuedEvent(self: *Client, event_id: u64) void {
        self.events_mutex.lockUncancelable(self.io);
        defer self.events_mutex.unlock(self.io);
        for (self.events.items, 0..) |queued, index| {
            if (queued.id != event_id) continue;
            var removed = self.events.orderedRemove(index);
            removed.diagnostic_frame = null;
            removed.deinit(self.allocator);
            return;
        }
    }

    fn cloneEventDelivery(
        self: *Client,
        id: u64,
        session_id: []const u8,
        generation: u64,
        event: session_types.SessionEvent,
        diagnostic_frame: ?[]const u8,
        automatic_handling_in_progress: bool,
    ) !EventDelivery {
        const owned_session_id = try self.allocator.dupe(u8, session_id);
        errdefer self.allocator.free(owned_session_id);
        var owned_event = try session_types.cloneEvent(self.allocator, event);
        errdefer owned_event.deinit(self.allocator);
        const owned_frame = if (diagnostic_frame) |frame|
            try self.allocator.dupe(u8, frame)
        else
            null;
        return .{
            .id = id,
            .session_id = owned_session_id,
            .generation = generation,
            .event = owned_event,
            .diagnostic_frame = owned_frame,
            .automatic_handling_in_progress = automatic_handling_in_progress,
        };
    }

    fn ensureEventLog(
        self: *Client,
        session_id: []const u8,
        generation: u64,
    ) error{ OutOfMemory, TooManyRetainedSessionLogs }!*event_log.EventLog {
        self.event_logs_mutex.lockUncancelable(self.io);
        defer self.event_logs_mutex.unlock(self.io);
        return self.ensureEventLogLocked(session_id, generation);
    }

    fn ensureEventLogLease(
        self: *Client,
        session_id: []const u8,
        generation: u64,
    ) error{ OutOfMemory, TooManyRetainedSessionLogs }!EventLogLease {
        self.event_logs_mutex.lockUncancelable(self.io);
        defer self.event_logs_mutex.unlock(self.io);
        const log = try self.ensureEventLogLocked(session_id, generation);
        log.retainOperation();
        return .{ .client = self, .log = log };
    }

    fn ensureEventLogLocked(
        self: *Client,
        session_id: []const u8,
        generation: u64,
    ) error{ OutOfMemory, TooManyRetainedSessionLogs }!*event_log.EventLog {
        for (self.event_logs.items) |log| {
            if (log.generation == generation and
                std.mem.eql(u8, log.session_id, session_id))
            {
                return log;
            }
        }
        self.reclaimClosedEventLogsLocked();
        if (self.event_logs.items.len >= retained_log_limit)
            return error.TooManyRetainedSessionLogs;
        const log = try self.allocator.create(event_log.EventLog);
        errdefer self.allocator.destroy(log);
        log.* = event_log.EventLog.init(
            self.allocator,
            self.io,
            session_id,
            generation,
            retained_event_limit,
            event_subscriber_limit,
        ) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            else => unreachable,
        };
        errdefer log.deinit();
        try self.event_logs.append(self.allocator, log);
        return log;
    }

    fn findEventLog(
        self: *Client,
        session_id: []const u8,
        generation: u64,
    ) ?*event_log.EventLog {
        self.event_logs_mutex.lockUncancelable(self.io);
        defer self.event_logs_mutex.unlock(self.io);
        for (self.event_logs.items) |log| {
            if (log.generation == generation and
                std.mem.eql(u8, log.session_id, session_id))
            {
                return log;
            }
        }
        return null;
    }

    fn acquireEventLog(
        self: *Client,
        session_id: []const u8,
        generation: u64,
    ) !EventLogLease {
        self.event_logs_mutex.lockUncancelable(self.io);
        defer self.event_logs_mutex.unlock(self.io);
        for (self.event_logs.items) |log| {
            if (log.generation != generation or
                !std.mem.eql(u8, log.session_id, session_id)) continue;
            log.retainOperation();
            return .{ .client = self, .log = log };
        }
        return error.SessionDisconnected;
    }

    fn acquireLatestEventLog(
        self: *Client,
        session_id: []const u8,
    ) ?EventLogLease {
        self.event_logs_mutex.lockUncancelable(self.io);
        defer self.event_logs_mutex.unlock(self.io);
        var index = self.event_logs.items.len;
        while (index != 0) {
            index -= 1;
            const log = self.event_logs.items[index];
            if (!std.mem.eql(u8, log.session_id, session_id)) continue;
            if (!log.retainOperationIfAccepting()) continue;
            return .{ .client = self, .log = log };
        }
        return null;
    }

    fn reclaimClosedEventLogs(self: *Client) void {
        self.event_logs_mutex.lockUncancelable(self.io);
        defer self.event_logs_mutex.unlock(self.io);
        self.reclaimClosedEventLogsLocked();
    }

    fn reclaimClosedEventLogsLocked(self: *Client) void {
        var index: usize = 0;
        while (index < self.event_logs.items.len) {
            const log = self.event_logs.items[index];
            if (!log.isDiscardableClosed()) {
                index += 1;
                continue;
            }
            _ = self.event_logs.orderedRemove(index);
            log.deinit();
            self.allocator.destroy(log);
        }
    }

    fn closeEventLog(self: *Client, session_id: []const u8, generation: u64) void {
        const target = self.beginCloseEventLog(session_id, generation);
        if (target) |log| log.drainAndClose();
    }

    fn beginCloseEventLog(
        self: *Client,
        session_id: []const u8,
        generation: u64,
    ) ?*event_log.EventLog {
        self.event_logs_mutex.lockUncancelable(self.io);
        var target: ?*event_log.EventLog = null;
        for (self.event_logs.items) |log| {
            if (log.generation == generation and
                std.mem.eql(u8, log.session_id, session_id))
            {
                log.beginClose();
                target = log;
                break;
            }
        }
        self.event_logs_mutex.unlock(self.io);
        return target;
    }

    fn finishSessionIngress(self: *Client, log: *event_log.EventLog) void {
        log.retainOperation();
        defer {
            log.releaseOperation();
            self.reclaimClosedEventLogs();
        }
        log.finishIngress();
        if (!log.ingress_drained.isSet()) return;
        self.completeDeferredSessionRemoval(log);
    }

    fn completeDeferredSessionRemoval(
        self: *Client,
        log: *event_log.EventLog,
    ) void {
        self.sessions_mutex.lockUncancelable(self.io);
        defer self.sessions_mutex.unlock(self.io);
        const record_index = self.findSessionRecordIndex(
            log.session_id,
            log.generation,
        ) orelse return;
        const record = &self.sessions.items[record_index];
        if (record.removal != .deferred) return;
        log.drainAndClose();
        self.removeSessionState(log.session_id, log.generation);
        record.deactivate(self.allocator);
    }

    fn enqueueLogEvent(
        self: *Client,
        work: QueuedLogEvent,
    ) !void {
        self.event_queue_mutex.lockUncancelable(self.io);
        defer self.event_queue_mutex.unlock(self.io);
        if (self.event_worker_closing) return error.SessionDisconnected;
        try self.event_queue.append(self.allocator, work);
        if (self.event_worker_future == null) {
            self.event_worker_future = self.io.concurrent(eventWorkerMain, .{self}) catch |err| {
                _ = self.event_queue.pop();
                return err;
            };
        }
        self.event_queue_ready.set(self.io);
    }

    fn eventWorkerMain(self: *Client) void {
        while (true) {
            self.event_queue_mutex.lockUncancelable(self.io);
            if (self.event_queue.items.len == 0) {
                if (self.event_worker_closing) {
                    self.event_queue_mutex.unlock(self.io);
                    return;
                }
                self.event_queue_ready.reset();
                self.event_queue_mutex.unlock(self.io);
                self.event_queue_ready.waitUncancelable(self.io);
                continue;
            }
            var work = self.event_queue.orderedRemove(0);
            self.event_queue_mutex.unlock(self.io);
            var ingress_scope: SessionIngressScope = undefined;
            if (work.log) |log|
                beginSessionIngressScope(&ingress_scope, log);
            defer if (work.log) |log| {
                endSessionIngressScope(&ingress_scope);
                self.finishSessionIngress(log);
            };
            if (work.delivery_class == .automatic) {
                self.handleAutomaticSessionEvent(
                    work.delivery.session_id,
                    .{ .transient = &work.delivery.event },
                );
            }
            if (work.delivery_class == .permission_request or
                work.delivery_class == .external_tool_request)
            {
                const session = self.sessionForId(work.delivery.session_id) catch {
                    self.finishRetainedEvent(
                        work.event_id,
                        .{ .session_idle = .{} },
                        false,
                    );
                    work.delivery.deinit(self.allocator);
                    continue;
                };
                const processed = session.processEventDelivery(
                    .legacy,
                    work.delivery,
                ) catch |err| {
                    self.finishRetainedEvent(
                        work.event_id,
                        .{ .session_idle = .{} },
                        false,
                    );
                    if (work.log) |log| log.failAdmitted(err);
                    continue;
                };
                work.delivery = switch (processed) {
                    .success => |delivery| delivery,
                    .failure => |failure| {
                        self.finishRetainedEvent(
                            work.event_id,
                            .{ .session_idle = .{} },
                            false,
                        );
                        if (work.log) |log| log.failAdmitted(failure.native_error);
                        continue;
                    },
                };
            }
            const log = work.log orelse {
                self.finishRetainedEvent(
                    work.event_id,
                    work.delivery.event,
                    false,
                );
                work.delivery.deinit(self.allocator);
                continue;
            };
            if (work.delivery.event == .session_error and
                work.delivery.diagnostic_frame != null)
            {
                var event = session_types.cloneEvent(
                    self.allocator,
                    work.delivery.event,
                ) catch |err| {
                    self.finishRetainedEvent(
                        work.event_id,
                        work.delivery.event,
                        false,
                    );
                    work.delivery.deinit(self.allocator);
                    log.failAdmitted(err);
                    continue;
                };
                log.append(event) catch |err| {
                    self.finishRetainedEvent(
                        work.event_id,
                        work.delivery.event,
                        false,
                    );
                    event.deinit(self.allocator);
                    work.delivery.deinit(self.allocator);
                    log.failAdmitted(err);
                    continue;
                };
                self.finishRetainedEvent(work.event_id, event, true);
                const failure = work.delivery.intoFailure(self.allocator) catch |err| {
                    log.failAdmitted(err);
                    continue;
                };
                log.failTurnsDetailed(failure) catch |err| {
                    log.failAdmitted(err);
                };
                continue;
            }
            var event = work.delivery.intoEvent(self.allocator);
            log.observeTurnEvent(event) catch |err| {
                self.finishRetainedEvent(work.event_id, event, false);
                event.deinit(self.allocator);
                log.failAdmitted(err);
                continue;
            };
            log.append(event) catch |err| {
                self.finishRetainedEvent(work.event_id, event, false);
                event.deinit(self.allocator);
                log.failAdmitted(err);
                continue;
            };
            self.finishRetainedEvent(work.event_id, event, true);
        }
    }

    fn stopEventWorker(self: *Client) void {
        self.event_queue_mutex.lockUncancelable(self.io);
        self.event_worker_closing = true;
        self.event_queue_ready.set(self.io);
        var future = self.event_worker_future;
        self.event_worker_future = null;
        self.event_queue_mutex.unlock(self.io);
        if (future) |*worker| worker.cancel(self.io);
        while (self.event_queue.items.len != 0) {
            var work = self.event_queue.orderedRemove(0);
            if (work.delivery_class == .automatic)
                self.setAutomaticDeliveryFailure(work.event_id, error.Canceled)
            else
                self.finishRetainedEvent(work.event_id, work.delivery.event, false);
            work.delivery.deinit(self.allocator);
            if (work.log) |log| self.finishSessionIngress(log);
        }
    }

    fn finishRetainedEvent(
        self: *Client,
        event_id: u64,
        processed: session_types.SessionEvent,
        remove: bool,
    ) void {
        self.events_mutex.lockUncancelable(self.io);
        defer self.events_mutex.unlock(self.io);
        for (self.events.items, 0..) |*queued, index| {
            if (queued.id != event_id) continue;
            if (queued.remove_after_automatic_handling) {
                var removed = self.events.orderedRemove(index);
                removed.deinit(self.allocator);
                return;
            }
            switch (processed) {
                .command_execute => |value| queued.event.command_execute.automatic_handling =
                    value.automatic_handling,
                .elicitation_requested => |value| queued.event.elicitation_requested.automatic_handling =
                    value.automatic_handling,
                .mcp_oauth_required => |value| queued.event.mcp_oauth_required.automatic_handling =
                    value.automatic_handling,
                .permission_requested => |value| queued.event.permission_requested.automatic_handling =
                    value.automatic_handling,
                else => {},
            }
            if (remove) {
                var removed = self.events.orderedRemove(index);
                removed.deinit(self.allocator);
            } else {
                queued.automatic_handling_in_progress = false;
            }
            return;
        }
    }

    fn queuedEventCount(
        self: *const Client,
        session_id: []const u8,
        generation: u64,
    ) usize {
        var count: usize = 0;
        for (self.events.items) |queued| {
            if (queued.generation == generation and
                std.mem.eql(u8, queued.session_id, session_id))
            {
                count += 1;
            }
        }
        return count;
    }

    fn sessionEventQueueFailure(
        self: *Client,
        session_id: []const u8,
    ) ?EventQueueFailure {
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        defer self.extension_runtimes_mutex.unlock(self.io);
        var failure: ?EventQueueFailure = null;
        if (self.pending_extension_runtime) |*runtime| {
            if (runtime.session_id) |runtime_session_id| {
                if (std.mem.eql(u8, runtime_session_id, session_id)) {
                    failure = runtime.event_queue_failure;
                }
            }
        }
        for (self.extension_runtimes.items) |*runtime| {
            const runtime_session_id = runtime.session_id orelse continue;
            if (!std.mem.eql(u8, runtime_session_id, session_id)) continue;
            if (runtime.event_queue_failure == .rejection_failed)
                return .rejection_failed;
            if (failure == null) failure = runtime.event_queue_failure;
        }
        return failure;
    }

    fn recordEventQueueFailure(
        self: *Client,
        session_id: []const u8,
        failure: EventQueueFailure,
    ) void {
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        defer self.extension_runtimes_mutex.unlock(self.io);
        if (self.pending_extension_runtime) |*runtime| {
            if (runtime.session_id) |runtime_session_id| {
                if (std.mem.eql(u8, runtime_session_id, session_id) and
                    (runtime.event_queue_failure == null or failure == .rejection_failed))
                {
                    runtime.event_queue_failure = failure;
                }
            }
        }
        for (self.extension_runtimes.items) |*runtime| {
            const runtime_session_id = runtime.session_id orelse continue;
            if (std.mem.eql(u8, runtime_session_id, session_id) and
                (runtime.event_queue_failure == null or failure == .rejection_failed))
            {
                runtime.event_queue_failure = failure;
            }
        }
    }

    fn handleUnretainedEvent(
        self: *Client,
        session_id: []const u8,
        event: *session_types.SessionEvent,
        delivery_class: EventDeliveryClass,
        failure: EventQueueFailure,
    ) void {
        self.recordEventQueueFailure(session_id, failure);
        switch (delivery_class) {
            .observation => {},
            .automatic => self.handleAutomaticSessionEvent(
                session_id,
                .{ .transient = event },
            ),
            .permission_request => {
                const request_id = event.permission_requested.request_id;
                const session = self.sessionForId(session_id) catch {
                    self.recordEventQueueFailure(session_id, .rejection_failed);
                    return;
                };
                session.rejectPermission(
                    request_id,
                    event_queue_capacity_message,
                ) catch self.recordEventQueueFailure(
                    session_id,
                    .rejection_failed,
                );
            },
            .external_tool_request => {
                const request_id = event.external_tool_requested.request_id;
                const session = self.sessionForId(session_id) catch {
                    self.recordEventQueueFailure(session_id, .rejection_failed);
                    return;
                };
                session.respondToToolError(
                    request_id,
                    event_queue_capacity_message,
                ) catch self.recordEventQueueFailure(
                    session_id,
                    .rejection_failed,
                );
            },
        }
    }

    fn queueLifecycleEvent(
        self: *Client,
        comptime failure_policy: FailurePolicy,
        params_value: std.json.Value,
    ) errors.DetailedError!PolicyResult(failure_policy, void) {
        const event = admin.parseLifecycleEvent(self.allocator, params_value) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            error.MissingField, error.MalformedFieldType => return .{
                .failure = try policyFailure(
                    failure_policy,
                    error.InvalidSessionEvent,
                    recordInvalidEvent,
                    .{
                        self.allocator,
                        if (err == error.MissingField)
                            errors.EnvelopeViolation.missing_params
                        else
                            errors.EnvelopeViolation.malformed_field_type,
                        params_value,
                    },
                ),
            },
        };
        self.lifecycle_events_mutex.lockUncancelable(self.io);
        self.lifecycle_events.push(event);
        self.lifecycle_event_ready.set(self.io);
        self.lifecycle_events_mutex.unlock(self.io);
        return .{ .success = {} };
    }

    const NotificationFrameDisposition = enum {
        reader_releases_frame,
        router_retains_frame,
    };

    fn routeNotification(
        self: *Client,
        comptime failure_policy: FailurePolicy,
        frame: []u8,
        method: []const u8,
        params: ?std.json.Value,
        envelope: std.json.Value,
    ) errors.DetailedError!PolicyResult(
        failure_policy,
        NotificationFrameDisposition,
    ) {
        if (!std.mem.eql(u8, method, "session.event") and
            !std.mem.eql(u8, method, "session.lifecycle"))
        {
            return .{ .success = .reader_releases_frame };
        }
        const params_value = params orelse
            return .{ .failure = try policyFailure(
                failure_policy,
                error.InvalidJsonRpc,
                recordInvalidEnvelope,
                .{
                    self.allocator,
                    error.InvalidJsonRpc,
                    .missing_params,
                    envelope,
                },
            ) };
        if (std.mem.eql(u8, method, "session.event")) {
            return switch (try self.queueSessionEvent(failure_policy, frame, params_value)) {
                .success => |retained| .{ .success = if (retained)
                    .router_retains_frame
                else
                    .reader_releases_frame },
                .failure => |failure| .{ .failure = failure },
            };
        }
        return switch (try self.queueLifecycleEvent(failure_policy, params_value)) {
            .success => .{ .success = .reader_releases_frame },
            .failure => |failure| .{ .failure = failure },
        };
    }

    fn handleAutomaticSessionEvent(
        self: *Client,
        session_id: []const u8,
        target: AutomaticEventTarget,
    ) void {
        const event = self.automaticEvent(target) orelse return;
        switch (event.*) {
            .command_execute => self.handleCommandEvent(
                session_id,
                target,
            ),
            .elicitation_requested => self.handleElicitationEvent(
                session_id,
                target,
            ),
            .mcp_oauth_required => self.handleMcpAuthEvent(
                session_id,
                target,
            ),
            else => {},
        }
    }

    fn automaticEvent(
        self: *Client,
        target: AutomaticEventTarget,
    ) ?*session_types.SessionEvent {
        return switch (target) {
            .queued => |id| blk: {
                const queued = self.queuedEvent(id) orelse break :blk null;
                break :blk &queued.event;
            },
            .transient => |event| event,
        };
    }

    fn queuedEvent(self: *Client, id: u64) ?*EventDelivery {
        for (self.events.items) |*queued| {
            if (queued.id == id) return queued;
        }
        return null;
    }

    fn finishAutomaticEvent(self: *Client, target: AutomaticEventTarget) void {
        const id = switch (target) {
            .queued => |id| id,
            .transient => return,
        };
        for (self.events.items, 0..) |*queued, index| {
            if (queued.id != id) continue;
            if (queued.remove_after_automatic_handling) {
                var removed = self.events.orderedRemove(index);
                removed.deinit(self.allocator);
            } else {
                queued.automatic_handling_in_progress = false;
            }
            return;
        }
    }

    fn setCommandAutomaticHandling(
        self: *Client,
        target: AutomaticEventTarget,
        handling: session_types.AutomaticInteractionHandling,
    ) void {
        const event = self.automaticEvent(target) orelse return;
        event.command_execute.automatic_handling = handling;
    }

    fn setElicitationAutomaticHandling(
        self: *Client,
        target: AutomaticEventTarget,
        handling: session_types.AutomaticInteractionHandling,
    ) void {
        const event = self.automaticEvent(target) orelse return;
        event.elicitation_requested.automatic_handling = handling;
    }

    fn setMcpAuthAutomaticHandling(
        self: *Client,
        target: AutomaticEventTarget,
        handling: session_types.AutomaticInteractionHandling,
    ) void {
        const event = self.automaticEvent(target) orelse return;
        event.mcp_oauth_required.automatic_handling = handling;
    }

    fn setAutomaticDeliveryFailure(
        self: *Client,
        event_id: u64,
        err: anyerror,
    ) void {
        self.events_mutex.lockUncancelable(self.io);
        defer self.events_mutex.unlock(self.io);
        const queued = self.queuedEvent(event_id) orelse return;
        switch (queued.event) {
            .command_execute => queued.event.command_execute.automatic_handling =
                .{ .delivery_failed = err },
            .elicitation_requested => queued.event.elicitation_requested.automatic_handling =
                .{ .delivery_failed = err },
            .mcp_oauth_required => queued.event.mcp_oauth_required.automatic_handling =
                .{ .delivery_failed = err },
            else => {},
        }
        queued.automatic_handling_in_progress = false;
    }

    fn handleCommandEvent(
        self: *Client,
        session_id: []const u8,
        target: AutomaticEventTarget,
    ) void {
        const request = (self.automaticEvent(target) orelse return).command_execute;
        if (self.extensionRuntimeCommand(session_id, request.command_name)) |command| {
            command.handler(.{
                .session_id = session_id,
                .command = request.command,
                .command_name = request.command_name,
                .args = request.args,
            }, command.context) catch |handler_error| {
                self.completeCommand(
                    session_id,
                    request.request_id,
                    @errorName(handler_error),
                ) catch |delivery_error| {
                    self.setCommandAutomaticHandling(
                        target,
                        .{ .delivery_failed = delivery_error },
                    );
                    return;
                };
                self.setCommandAutomaticHandling(
                    target,
                    .{ .handler_failed = handler_error },
                );
                return;
            };
            self.completeCommand(session_id, request.request_id, null) catch |err| {
                self.setCommandAutomaticHandling(target, .{ .delivery_failed = err });
                return;
            };
            self.setCommandAutomaticHandling(target, .handled);
            return;
        }
        const message = std.fmt.allocPrint(
            self.allocator,
            "Unknown command: {s}",
            .{request.command_name},
        ) catch |err| {
            self.setCommandAutomaticHandling(target, .{ .delivery_failed = err });
            return;
        };
        defer self.allocator.free(message);
        self.completeCommand(session_id, request.request_id, message) catch |err| {
            self.setCommandAutomaticHandling(target, .{ .delivery_failed = err });
            return;
        };
        self.setCommandAutomaticHandling(target, .handled);
    }

    fn completeCommand(
        self: *Client,
        session_id: []const u8,
        request_id: []const u8,
        command_error: ?[]const u8,
    ) !void {
        const parsed = if (command_error) |message|
            try self.call(
                RpcSuccess,
                "session.commands.handlePendingCommand",
                .{
                    .sessionId = session_id,
                    .requestId = request_id,
                    .@"error" = message,
                },
            )
        else
            try self.call(
                RpcSuccess,
                "session.commands.handlePendingCommand",
                .{
                    .sessionId = session_id,
                    .requestId = request_id,
                },
            );
        defer parsed.deinit();
        if (!parsed.value.success) return error.CommandResultNotAccepted;
    }

    fn handleElicitationEvent(
        self: *Client,
        session_id: []const u8,
        target: AutomaticEventTarget,
    ) void {
        const runtime = self.extensionRuntimeElicitation(session_id) orelse return;
        const payload = (self.automaticEvent(target) orelse return).elicitation_requested;
        const handler = runtime.handler;
        var requested_schema_json: ?[]u8 = null;
        defer if (requested_schema_json) |json| self.allocator.free(json);
        if (payload.requested_schema != null) {
            const parsed_data = std.json.parseFromSlice(
                std.json.Value,
                self.allocator,
                payload.raw.data_json,
                .{},
            ) catch |err| {
                self.setElicitationAutomaticHandling(target, .{ .delivery_failed = err });
                return;
            };
            defer parsed_data.deinit();
            const data_object = switch (parsed_data.value) {
                .object => |object| object,
                else => {
                    self.setElicitationAutomaticHandling(target, .invalid_result);
                    return;
                },
            };
            requested_schema_json = stringifyJsonValue(
                self.allocator,
                data_object.get("requestedSchema") orelse {
                    self.setElicitationAutomaticHandling(target, .invalid_result);
                    return;
                },
            ) catch |err| {
                self.setElicitationAutomaticHandling(target, .{ .delivery_failed = err });
                return;
            };
        }
        var result = handler(self.allocator, .{
            .session_id = session_id,
            .message = payload.message,
            .requested_schema_json = requested_schema_json,
            .mode = payload.mode,
            .elicitation_source = payload.elicitation_source,
            .url = payload.url,
        }, runtime.context) catch |err| {
            self.setElicitationAutomaticHandling(target, .{ .handler_failed = err });
            return;
        };
        defer result.deinit(self.allocator);
        const content = if (result.content_json) |json|
            std.json.parseFromSlice(std.json.Value, self.allocator, json, .{}) catch {
                self.setElicitationAutomaticHandling(target, .invalid_result);
                return;
            }
        else
            null;
        defer if (content) |value| value.deinit();
        if (content) |value| {
            if (!isValidElicitationContent(value.value)) {
                self.setElicitationAutomaticHandling(target, .invalid_result);
                return;
            }
        }
        self.completeElicitation(session_id, payload.request_id, .{ .result = .{
            .action = result.action,
            .content = if (content) |value| value.value else null,
        } }) catch |err| {
            self.setElicitationAutomaticHandling(target, .{ .delivery_failed = err });
            return;
        };
        self.setElicitationAutomaticHandling(target, .handled);
    }

    fn completeElicitation(
        self: *Client,
        session_id: []const u8,
        response_id: []const u8,
        result: ElicitationResponse,
    ) !void {
        const parsed = switch (result) {
            .cancelled => try self.call(
                RpcSuccess,
                "session.ui.handlePendingElicitation",
                .{
                    .sessionId = session_id,
                    .requestId = response_id,
                    .result = .{ .action = session_types.ElicitationAction.cancel },
                },
            ),
            .result => |value| try self.call(
                RpcSuccess,
                "session.ui.handlePendingElicitation",
                .{
                    .sessionId = session_id,
                    .requestId = response_id,
                    .result = value,
                },
            ),
        };
        defer parsed.deinit();
        if (!parsed.value.success) return error.ElicitationResultNotAccepted;
    }

    fn handleMcpAuthEvent(
        self: *Client,
        session_id: []const u8,
        target: AutomaticEventTarget,
    ) void {
        const runtime = self.extensionRuntimeMcpAuth(session_id) orelse return;
        const handler = runtime.handler;
        const payload = (self.automaticEvent(target) orelse return).mcp_oauth_required;
        const parsed = std.json.parseFromSlice(
            WireMcpAuthRequest,
            self.allocator,
            payload.raw.data_json,
            .{ .allocate = .alloc_always, .ignore_unknown_fields = true },
        ) catch {
            self.setMcpAuthAutomaticHandling(target, .invalid_result);
            return;
        };
        defer {
            wipeSecret(parsed.value.requestId);
            wipeSecret(parsed.value.serverName);
            wipeSecret(parsed.value.serverUrl);
            if (parsed.value.resourceMetadata) |value| wipeSecret(value);
            if (parsed.value.wwwAuthenticateParams) |value| wipeJsonStrings(value);
            if (parsed.value.httpResponse) |value| wipeJsonStrings(value);
            if (parsed.value.staticClientConfig) |value| wipeJsonStrings(value);
            parsed.deinit();
        }
        const www_json = if (parsed.value.wwwAuthenticateParams) |value|
            std.json.Stringify.valueAlloc(self.allocator, value, .{}) catch |err| {
                self.setMcpAuthAutomaticHandling(target, .{ .delivery_failed = err });
                return;
            }
        else
            null;
        defer if (www_json) |value| {
            wipeSecret(value);
            self.allocator.free(value);
        };
        const http_json = if (parsed.value.httpResponse) |value|
            std.json.Stringify.valueAlloc(self.allocator, value, .{}) catch |err| {
                self.setMcpAuthAutomaticHandling(target, .{ .delivery_failed = err });
                return;
            }
        else
            null;
        defer if (http_json) |value| {
            wipeSecret(value);
            self.allocator.free(value);
        };
        const static_json = if (parsed.value.staticClientConfig) |value|
            std.json.Stringify.valueAlloc(self.allocator, value, .{}) catch |err| {
                self.setMcpAuthAutomaticHandling(target, .{ .delivery_failed = err });
                return;
            }
        else
            null;
        defer if (static_json) |value| {
            wipeSecret(value);
            self.allocator.free(value);
        };
        var result = handler(self.allocator, .{
            .request_id = parsed.value.requestId,
            .server_name = parsed.value.serverName,
            .server_url = parsed.value.serverUrl,
            .reason = parsed.value.reason,
            .resource_metadata = parsed.value.resourceMetadata,
            .www_authenticate_json = www_json,
            .http_response_json = http_json,
            .static_client_config_json = static_json,
        }, runtime.context) catch |err| {
            self.setMcpAuthAutomaticHandling(target, .{ .handler_failed = err });
            return;
        };
        defer switch (result) {
            .token => |*token| token.deinitSecure(self.allocator),
            .cancelled => {},
        };
        const response = switch (result) {
            .cancelled => self.call(
                RpcSuccess,
                "session.mcp.oauth.handlePendingRequest",
                .{
                    .sessionId = session_id,
                    .requestId = parsed.value.requestId,
                    .result = .{ .kind = "cancelled" },
                },
            ),
            .token => |token| blk: {
                if (token.expires_in_seconds) |expires_in_seconds| {
                    if (expires_in_seconds == 0) {
                        self.setMcpAuthAutomaticHandling(target, .invalid_result);
                        return;
                    }
                }
                break :blk self.call(
                    RpcSuccess,
                    "session.mcp.oauth.handlePendingRequest",
                    .{
                        .sessionId = session_id,
                        .requestId = parsed.value.requestId,
                        .result = .{
                            .kind = "token",
                            .accessToken = token.access_token,
                            .tokenType = token.token_type,
                            .expiresIn = token.expires_in_seconds,
                        },
                    },
                );
            },
        };
        const accepted = response catch |err| {
            self.setMcpAuthAutomaticHandling(target, .{ .delivery_failed = err });
            return;
        };
        defer accepted.deinit();
        if (!accepted.value.success) {
            self.setMcpAuthAutomaticHandling(
                target,
                .{ .delivery_failed = error.McpAuthNotAccepted },
            );
            return;
        }
        self.setMcpAuthAutomaticHandling(target, .handled);
    }

    fn findExtensionRuntime(self: *Client, session_id: []const u8) ?*SessionExtensionRuntime {
        if (self.pending_extension_runtime) |*runtime| {
            if (runtime.session_id) |id| {
                if (std.mem.eql(u8, id, session_id)) return runtime;
            }
        }
        for (self.extension_runtimes.items) |*runtime| {
            if (runtime.session_id) |id| {
                if (std.mem.eql(u8, id, session_id)) return runtime;
            }
        }
        return null;
    }

    fn findCommittedExtensionRuntime(
        self: *Client,
        session_id: []const u8,
    ) ?*SessionExtensionRuntime {
        for (self.extension_runtimes.items) |*runtime| {
            if (runtime.session_id) |id| {
                if (std.mem.eql(u8, id, session_id)) return runtime;
            }
        }
        return null;
    }

    fn extensionRuntimeHandlesMcpAuth(
        self: *Client,
        session_id: []const u8,
    ) bool {
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        defer self.extension_runtimes_mutex.unlock(self.io);
        const runtime = self.findCommittedExtensionRuntime(session_id) orelse return false;
        return !runtime.credentials_quarantined and runtime.mcp_auth_handler != null;
    }

    fn extensionRuntimeCommand(
        self: *Client,
        session_id: []const u8,
        command_name: []const u8,
    ) ?struct {
        handler: session_types.CommandHandler,
        context: ?*anyopaque,
    } {
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        defer self.extension_runtimes_mutex.unlock(self.io);
        const runtime = self.findCommittedExtensionRuntime(session_id) orelse return null;
        for (runtime.commands) |command| {
            if (!std.mem.eql(u8, command.name, command_name)) continue;
            return .{
                .handler = command.handler,
                .context = command.context,
            };
        }
        return null;
    }

    fn extensionRuntimeElicitation(
        self: *Client,
        session_id: []const u8,
    ) ?struct {
        handler: session_types.ElicitationHandler,
        context: ?*anyopaque,
    } {
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        defer self.extension_runtimes_mutex.unlock(self.io);
        const runtime = self.findCommittedExtensionRuntime(session_id) orelse return null;
        return .{
            .handler = runtime.elicitation_handler orelse return null,
            .context = runtime.elicitation_context,
        };
    }

    fn extensionRuntimeMcpAuth(
        self: *Client,
        session_id: []const u8,
    ) ?struct {
        handler: ext.McpAuthHandler,
        context: ?*anyopaque,
    } {
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        defer self.extension_runtimes_mutex.unlock(self.io);
        const runtime = self.findCommittedExtensionRuntime(session_id) orelse return null;
        if (runtime.credentials_quarantined) return null;
        return .{
            .handler = runtime.mcp_auth_handler orelse return null,
            .context = runtime.mcp_auth_context,
        };
    }

    fn applyExtensionEvent(
        self: *Client,
        session_id: []const u8,
        event: *const session_types.SessionEvent,
    ) !void {
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        defer self.extension_runtimes_mutex.unlock(self.io);
        const runtime = self.findCommittedExtensionRuntime(session_id) orelse return;
        try applyExtensionEventToRuntime(self.allocator, runtime, event);
    }

    fn applyExtensionEventToRuntime(
        allocator: std.mem.Allocator,
        runtime: *SessionExtensionRuntime,
        event: *const session_types.SessionEvent,
    ) !void {
        switch (event.*) {
            .capabilities_changed => |payload| {
                if (payload.data.ui) |ui| {
                    if (ui.canvases) |canvases| {
                        runtime.capabilities.canvases = capabilityState(canvases);
                    }
                    if (ui.mcp_apps) |mcp_apps| {
                        runtime.capabilities.mcp_apps = capabilityState(mcp_apps);
                    }
                }
            },
            .session_canvas_closed => |payload| {
                removeOpenCanvas(runtime, allocator, payload.data.instance_id);
            },
            .session_canvas_opened => |payload| {
                const canvas = try cloneTypedOpenCanvas(
                    allocator,
                    payload.data,
                );
                errdefer ext.freeOpenCanvas(allocator, canvas);
                try upsertOpenCanvas(runtime, allocator, canvas);
            },
            else => {},
        }
    }

    fn beginSessionRecord(
        self: *Client,
        session_id: ?[]u8,
        prior_record_index: ?usize,
    ) !void {
        errdefer if (session_id) |id| self.allocator.free(id);
        self.sessions_mutex.lockUncancelable(self.io);
        defer self.sessions_mutex.unlock(self.io);
        if (self.pending_session != null) {
            return error.SessionLifecycleAlreadyInProgress;
        }
        if (prior_record_index) |index| {
            const id = session_id orelse return error.SessionNotActive;
            if (index >= self.sessions.items.len or
                !self.sessions.items[index].isActive() or
                !std.mem.eql(u8, self.sessions.items[index].id.?, id))
            {
                return error.SessionNotActive;
            }
        }
        const record_index = prior_record_index orelse index: {
            for (self.sessions.items, 0..) |record, index| {
                if (record.id == null) break :index index;
            }
            try self.sessions.ensureUnusedCapacity(self.allocator, 1);
            break :index self.sessions.items.len;
        };
        if (session_id) |id|
            try self.ensureNoOtherSessionIdLocked(id, record_index);
        const generation = if (record_index < self.sessions.items.len)
            try nextSessionGeneration(self.sessions.items[record_index].generation)
        else
            1;
        self.pending_session = .{
            .id = session_id,
            .record_index = record_index,
            .generation = generation,
        };
    }

    fn rollbackSessionRecord(self: *Client) void {
        if (self.pending_session) |*pending| pending.deinit(self.allocator);
        self.pending_session = null;
    }

    fn prepareSessionCommit(
        self: *Client,
        session_id: []const u8,
        workspace_path: ?[]const u8,
    ) !void {
        self.sessions_mutex.lockUncancelable(self.io);
        defer self.sessions_mutex.unlock(self.io);
        const pending = if (self.pending_session) |*value|
            value
        else
            return error.MissingPendingSession;
        if (pending.id) |id| {
            if (!std.mem.eql(u8, id, session_id))
                return error.UnexpectedSessionId;
        } else {
            if (session_id.len == 0)
                return error.InvalidServerAssignedSessionId;
            self.ensureNoOtherSessionIdLocked(
                session_id,
                pending.record_index,
            ) catch return error.InvalidServerAssignedSessionId;
            pending.id = try self.allocator.dupe(u8, session_id);
        }
        const replacement_path = if (workspace_path) |path|
            try self.allocator.dupe(u8, path)
        else
            null;
        errdefer if (replacement_path) |path| self.allocator.free(path);
        if (pending.workspace_path) |path| self.allocator.free(path);
        pending.workspace_path = replacement_path;
    }

    fn commitSessionRecord(self: *Client) !usize {
        const commit = try self.beginSessionRecordCommit();
        return self.finishSessionRecordCommit(commit);
    }

    fn beginSessionRecordCommit(self: *Client) !SessionRecordCommit {
        self.sessions_mutex.lockUncancelable(self.io);
        const pending = self.pending_session.?;
        var prior_log: ?*event_log.EventLog = null;
        var replacing = false;
        if (pending.record_index < self.sessions.items.len) {
            const existing = &self.sessions.items[pending.record_index];
            if (existing.id) |existing_id| {
                if (!existing.isActive() or !std.mem.eql(u8, existing_id, pending.id.?)) {
                    self.sessions_mutex.unlock(self.io);
                    return error.SessionNotActive;
                }
                if (self.findEventLog(existing_id, existing.generation)) |log| {
                    if (isCurrentSessionIngress(log)) {
                        self.sessions_mutex.unlock(self.io);
                        return error.ReentrantRpcCall;
                    }
                }
                replacing = true;
                existing.replacement_pending = true;
                prior_log = self.beginCloseEventLog(existing_id, existing.generation);
            }
        }
        self.sessions_mutex.unlock(self.io);
        return .{
            .pending = pending,
            .prior_log = prior_log,
            .replacing = replacing,
        };
    }

    fn ensureNoOtherSessionIdLocked(
        self: *Client,
        session_id: []const u8,
        excluded_record_index: usize,
    ) error{SessionAlreadyActive}!void {
        for (self.sessions.items, 0..) |record, record_index| {
            if (record_index == excluded_record_index) continue;
            const id = record.id orelse continue;
            if (std.mem.eql(u8, id, session_id))
                return error.SessionAlreadyActive;
        }
    }

    fn finishSessionRecordCommit(
        self: *Client,
        commit: SessionRecordCommit,
    ) !usize {
        if (commit.prior_log) |log| log.drainAndClose();
        if (commit.replacing) {
            self.cancelFactoryJobsForSession(commit.pending.id.?);
            self.blockRuntimeCallbacks();
        }
        defer if (commit.replacing) self.unblockRuntimeCallbacks();

        self.sessions_mutex.lockUncancelable(self.io);
        defer self.sessions_mutex.unlock(self.io);
        if (commit.replacing) {
            const existing = &self.sessions.items[commit.pending.record_index];
            if (!existing.replacement_pending) return error.SessionNotActive;
            self.removeQueuedSessionEvents(existing.id.?, existing.generation);
        }
        if (self.pending_extension_runtime != null) {
            self.extension_runtimes_mutex.lockUncancelable(self.io);
            defer self.extension_runtimes_mutex.unlock(self.io);
            self.commitPreparedExtensionRuntimeLocked(commit.pending.id.?);
        }
        self.pending_session = null;
        const record = SessionRecord{
            .id = commit.pending.id.?,
            .generation = commit.pending.generation,
            .workspace_path = commit.pending.workspace_path,
        };
        if (commit.pending.record_index == self.sessions.items.len) {
            self.sessions.appendAssumeCapacity(record);
        } else {
            self.sessions.items[commit.pending.record_index].deactivate(self.allocator);
            self.sessions.items[commit.pending.record_index] = record;
        }
        return commit.pending.record_index;
    }

    fn sessionHandle(self: *Client, record_index: usize) Session {
        const record = self.sessions.items[record_index];
        std.debug.assert(record.isActive());
        return .{
            .client = self,
            .id = record.id.?,
            .record_index = record_index,
            .generation = record.generation,
        };
    }

    fn sessionForId(self: *Client, session_id: []const u8) !Session {
        return self.sessionHandle(self.findSessionIndex(session_id) orelse
            return error.SessionNotActive);
    }

    fn findSessionIndex(self: *Client, session_id: []const u8) ?usize {
        for (self.sessions.items, 0..) |session, index| {
            if (!session.isActive()) continue;
            if (session.id) |id| {
                if (std.mem.eql(u8, id, session_id)) return index;
            }
        }
        return null;
    }

    fn findSession(self: *Client, session_id: []const u8) ?*SessionRecord {
        const index = self.findSessionIndex(session_id) orelse return null;
        return &self.sessions.items[index];
    }

    fn findSessionRecordIndex(
        self: *Client,
        session_id: []const u8,
        generation: u64,
    ) ?usize {
        for (self.sessions.items, 0..) |record, index| {
            const id = record.id orelse continue;
            if (record.generation == generation and
                std.mem.eql(u8, id, session_id))
            {
                return index;
            }
        }
        return null;
    }

    fn acquireActiveEventIngress(
        self: *Client,
        session_id: []const u8,
        create_if_missing: bool,
    ) error{ OutOfMemory, TooManyRetainedSessionLogs, Canceled }!EventIngressAdmission {
        self.sessions_mutex.lockUncancelable(self.io);
        defer self.sessions_mutex.unlock(self.io);
        const record = record: {
            for (self.sessions.items) |*candidate| {
                const id = candidate.id orelse continue;
                if (!std.mem.eql(u8, id, session_id)) continue;
                if (!candidate.isActive()) return .unavailable;
                break :record candidate;
            }
            return .unknown;
        };
        var lease = if (create_if_missing)
            try self.ensureEventLogLease(session_id, record.generation)
        else
            self.acquireEventLog(
                session_id,
                record.generation,
            ) catch |err| switch (err) {
                error.SessionDisconnected => return .unavailable,
            };
        errdefer lease.deinit();
        lease.log.beginIngress() catch |err| switch (err) {
            error.SessionDisconnected => return .unavailable,
            error.Canceled => return error.Canceled,
        };
        return .{ .active = lease };
    }

    fn acquireSessionHandleIngress(
        self: *Client,
        record_index: usize,
        generation: u64,
    ) error{
        OutOfMemory,
        TooManyRetainedSessionLogs,
        Canceled,
        SessionNotActive,
    }!EventLogLease {
        self.sessions_mutex.lockUncancelable(self.io);
        defer self.sessions_mutex.unlock(self.io);
        const record = try self.activeSessionRecordLocked(record_index, generation);
        var lease = try self.ensureEventLogLease(record.id.?, generation);
        errdefer lease.deinit();
        lease.log.beginIngress() catch |err| switch (err) {
            error.SessionDisconnected => return error.SessionNotActive,
            error.Canceled => return error.Canceled,
        };
        return lease;
    }

    fn ensureSessionHandleEventLogLease(
        self: *Client,
        record_index: usize,
        generation: u64,
    ) !EventLogLease {
        self.sessions_mutex.lockUncancelable(self.io);
        defer self.sessions_mutex.unlock(self.io);
        const record = try self.activeSessionRecordLocked(record_index, generation);
        return self.ensureEventLogLease(record.id.?, generation);
    }

    fn validateSessionHandle(
        self: *Client,
        record_index: usize,
        generation: u64,
    ) !void {
        self.sessions_mutex.lockUncancelable(self.io);
        defer self.sessions_mutex.unlock(self.io);
        _ = try self.activeSessionRecordLocked(record_index, generation);
    }

    fn activeSessionRecordLocked(
        self: *Client,
        record_index: usize,
        generation: u64,
    ) !*SessionRecord {
        if (record_index >= self.sessions.items.len)
            return error.SessionNotActive;
        const record = &self.sessions.items[record_index];
        if (!record.isActive() or record.generation != generation)
            return error.SessionNotActive;
        return record;
    }

    fn removeSessionState(
        self: *Client,
        session_id: []const u8,
        generation: u64,
    ) void {
        self.cancelFactoryJobsForSession(session_id);
        self.blockRuntimeCallbacks();
        defer self.unblockRuntimeCallbacks();
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        for (self.extension_runtimes.items, 0..) |runtime, runtime_index| {
            if (runtime.session_id != null and
                std.mem.eql(u8, runtime.session_id.?, session_id))
            {
                var removed = self.extension_runtimes.orderedRemove(runtime_index);
                removed.deinit(self.allocator);
                break;
            }
        }
        self.extension_runtimes_mutex.unlock(self.io);
        self.removeQueuedSessionEvents(session_id, generation);

        var tool_index: usize = 0;
        while (tool_index < self.tools.items.len) {
            if (std.mem.eql(u8, self.tools.items[tool_index].session_id, session_id)) {
                const tool = self.tools.orderedRemove(tool_index);
                tool.deinit(self.allocator);
            } else {
                tool_index += 1;
            }
        }

        var user_input_handler_index: usize = 0;
        while (user_input_handler_index < self.user_input_handlers.items.len) {
            if (std.mem.eql(u8, self.user_input_handlers.items[user_input_handler_index].session_id, session_id)) {
                _ = self.user_input_handlers.orderedRemove(user_input_handler_index);
            } else {
                user_input_handler_index += 1;
            }
        }

        var permission_handler_index: usize = 0;
        while (permission_handler_index < self.permission_handlers.items.len) {
            if (std.mem.eql(u8, self.permission_handlers.items[permission_handler_index].session_id, session_id)) {
                _ = self.permission_handlers.orderedRemove(permission_handler_index);
            } else {
                permission_handler_index += 1;
            }
        }

        self.session_filesystems.remove(self.allocator, session_id);

        var provider_token_index: usize = 0;
        while (provider_token_index < self.provider_tokens.items.len) {
            if (std.mem.eql(
                u8,
                self.provider_tokens.items[provider_token_index].session_id,
                session_id,
            )) {
                const registered = self.provider_tokens.orderedRemove(provider_token_index);
                registered.deinit(self.allocator);
            } else {
                provider_token_index += 1;
            }
        }
    }

    fn removeQueuedSessionEvents(
        self: *Client,
        session_id: []const u8,
        generation: u64,
    ) void {
        var index: usize = 0;
        self.events_mutex.lockUncancelable(self.io);
        defer self.events_mutex.unlock(self.io);
        while (index < self.events.items.len) {
            if (self.events.items[index].generation == generation and
                std.mem.eql(u8, self.events.items[index].session_id, session_id))
            {
                if (self.events.items[index].automatic_handling_in_progress) {
                    self.events.items[index].remove_after_automatic_handling = true;
                    index += 1;
                    continue;
                }
                var event = self.events.orderedRemove(index);
                event.deinit(self.allocator);
            } else {
                index += 1;
            }
        }
    }

    fn beginSessionRemoval(
        self: *Client,
        record_index: usize,
        expected_session_id: []const u8,
        expected_generation: u64,
    ) !?SessionRemoval {
        self.sessions_mutex.lockUncancelable(self.io);
        defer self.sessions_mutex.unlock(self.io);
        if (record_index >= self.sessions.items.len)
            return error.SessionNotActive;
        const record = &self.sessions.items[record_index];
        const id = record.id orelse return error.SessionNotActive;
        if (!record.isActive() or
            record.generation != expected_generation or
            !std.mem.eql(u8, id, expected_session_id))
        {
            return error.SessionNotActive;
        }
        const owned_session_id = try self.allocator.dupe(u8, id);
        errdefer self.allocator.free(owned_session_id);
        const log = self.beginCloseEventLog(id, record.generation);
        if (log) |active_log| {
            if (isCurrentSessionIngress(active_log)) {
                record.removal = .deferred;
                self.allocator.free(owned_session_id);
                return null;
            }
        }
        record.removal = .draining;
        return .{
            .record_index = record_index,
            .session_id = owned_session_id,
            .generation = expected_generation,
            .log = log,
        };
    }

    fn finishSessionRemoval(self: *Client, removal: SessionRemoval) !void {
        defer self.allocator.free(removal.session_id);
        if (removal.log) |log| log.drainAndClose();
        self.sessions_mutex.lockUncancelable(self.io);
        defer self.sessions_mutex.unlock(self.io);
        if (removal.record_index >= self.sessions.items.len)
            return error.SessionNotActive;
        const record = &self.sessions.items[removal.record_index];
        const id = record.id orelse return error.SessionNotActive;
        if (record.removal != .draining or
            record.generation != removal.generation or
            !std.mem.eql(u8, id, removal.session_id))
        {
            return error.SessionNotActive;
        }
        self.removeSessionState(removal.session_id, removal.generation);
        record.deactivate(self.allocator);
    }

    fn removeSessionExpected(
        self: *Client,
        record_index: usize,
        expected_session_id: []const u8,
        expected_generation: u64,
    ) !void {
        const removal = try self.beginSessionRemoval(
            record_index,
            expected_session_id,
            expected_generation,
        ) orelse return;
        try self.finishSessionRemoval(removal);
    }

    fn removeSession(self: *Client, session_id: []const u8) !void {
        self.sessions_mutex.lockUncancelable(self.io);
        const record_index = self.findSessionIndex(session_id) orelse {
            self.sessions_mutex.unlock(self.io);
            return;
        };
        const generation = self.sessions.items[record_index].generation;
        const owned_session_id = self.allocator.dupe(u8, session_id) catch |err| {
            self.sessions_mutex.unlock(self.io);
            return err;
        };
        self.sessions_mutex.unlock(self.io);
        defer self.allocator.free(owned_session_id);
        try self.removeSessionExpected(
            record_index,
            owned_session_id,
            generation,
        );
    }

    fn registerOwnedSession(
        self: *Client,
        owned_session_id: []u8,
        config: session_types.SessionConfig,
        token_bindings: []const provider.TokenBinding,
    ) !void {
        if (self.hasSession(owned_session_id)) {
            self.allocator.free(owned_session_id);
            return error.SessionAlreadyActive;
        }

        try self.beginSessionRecord(owned_session_id, null);
        const record_index = try self.commitSessionRecord();
        const session_id = self.sessions.items[record_index].id.?;
        const generation = self.sessions.items[record_index].generation;
        self.registerSessionBindings(session_id, config, token_bindings) catch |err| {
            try self.removeSessionExpected(record_index, session_id, generation);
            return err;
        };
    }

    fn registerSessionBindings(
        self: *Client,
        session_id: []const u8,
        config: session_types.SessionConfig,
        token_bindings: []const provider.TokenBinding,
    ) !void {
        try self.registerToolHandlers(session_id, config.tools);
        try self.registerPermissionHandler(session_id, config);
        try self.registerUserInputHandler(
            session_id,
            config.on_user_input_request,
            config.user_input_context,
        );
        try self.registerProviderTokens(session_id, token_bindings);
    }

    fn hasSession(self: *Client, session_id: []const u8) bool {
        return self.findSessionIndex(session_id) != null;
    }

    fn registerProviderTokens(
        self: *Client,
        session_id: []const u8,
        bindings: []const provider.TokenBinding,
    ) !void {
        if (bindings.len == 0) return;
        const registered = try self.allocator.alloc(RegisteredProviderToken, bindings.len);
        var initialized: usize = 0;
        errdefer {
            for (registered[0..initialized]) |value| value.deinit(self.allocator);
            self.allocator.free(registered);
        }
        for (bindings, 0..) |binding, index| {
            registered[index] = .{
                .provider_name = try self.allocator.dupe(u8, binding.provider_name),
                .token_provider = binding.token_provider,
            };
            initialized += 1;
        }
        try self.provider_tokens.append(self.allocator, .{
            .session_id = session_id,
            .providers = registered,
        });
    }

    fn beginProviderTokens(
        self: *Client,
        session_id: []const u8,
        bindings: []const provider.TokenBinding,
    ) !void {
        if (self.pending_provider_tokens != null) return error.ProviderTokensPending;
        if (bindings.len != 0) {
            try self.provider_tokens.ensureUnusedCapacity(self.allocator, 1);
        }

        const registered = try self.allocator.alloc(RegisteredProviderToken, bindings.len);
        var initialized: usize = 0;
        errdefer {
            for (registered[0..initialized]) |value| value.deinit(self.allocator);
            self.allocator.free(registered);
        }
        for (bindings, 0..) |binding, index| {
            registered[index] = .{
                .provider_name = try self.allocator.dupe(u8, binding.provider_name),
                .token_provider = binding.token_provider,
            };
            initialized += 1;
        }
        self.pending_provider_tokens = .{
            .session_id = session_id,
            .providers = registered,
        };
    }

    fn rollbackProviderTokens(self: *Client) void {
        const registered = self.pending_provider_tokens orelse return;
        self.pending_provider_tokens = null;
        registered.deinit(self.allocator);
    }

    fn commitProviderTokens(self: *Client) void {
        const pending = self.pending_provider_tokens orelse return;
        self.pending_provider_tokens = null;

        for (self.provider_tokens.items, 0..) |registered, index| {
            if (!std.mem.eql(u8, registered.session_id, pending.session_id)) continue;
            registered.deinit(self.allocator);
            if (pending.providers.len == 0) {
                pending.deinit(self.allocator);
                _ = self.provider_tokens.orderedRemove(index);
                return;
            }
            self.provider_tokens.items[index] = pending;
            return;
        }
        if (pending.providers.len == 0) {
            pending.deinit(self.allocator);
            return;
        }
        self.provider_tokens.appendAssumeCapacity(pending);
    }

    fn findProviderToken(
        self: *Client,
        session_id: []const u8,
        provider_name: []const u8,
    ) ?provider.BearerTokenProvider {
        if (self.pending_provider_tokens) |pending| {
            if (std.mem.eql(u8, pending.session_id, session_id)) {
                for (pending.providers) |registered| {
                    if (std.mem.eql(u8, registered.provider_name, provider_name)) {
                        return registered.token_provider;
                    }
                }
                return null;
            }
        }
        for (self.provider_tokens.items) |session_providers| {
            if (!std.mem.eql(u8, session_providers.session_id, session_id)) continue;
            for (session_providers.providers) |registered| {
                if (std.mem.eql(u8, registered.provider_name, provider_name)) {
                    return registered.token_provider;
                }
            }
            return null;
        }
        return null;
    }

    fn findProviderTokenFromParams(
        self: *Client,
        params: ?std.json.Value,
    ) ?provider.BearerTokenProvider {
        const object = switch (params orelse return null) {
            .object => |object| object,
            else => return null,
        };
        const session_id = switch (object.get("sessionId") orelse return null) {
            .string => |value| value,
            else => return null,
        };
        const provider_name = switch (object.get("providerName") orelse return null) {
            .string => |value| value,
            else => return null,
        };
        return self.findProviderToken(session_id, provider_name);
    }

    fn registerToolHandlers(
        self: *Client,
        session_id: []const u8,
        definitions: []const session_types.Tool,
    ) !void {
        for (definitions) |definition| {
            const handler = definition.handler orelse continue;
            const name = try self.allocator.dupe(u8, definition.name);
            errdefer self.allocator.free(name);
            try self.tools.append(self.allocator, .{
                .session_id = session_id,
                .name = name,
                .handler = handler,
                .context = definition.context,
            });
        }
    }

    fn findToolHandler(
        self: *Client,
        session_id: []const u8,
        name: []const u8,
    ) ?ToolHandlerSnapshot {
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        defer self.extension_runtimes_mutex.unlock(self.io);
        if (self.findCommittedExtensionRuntime(session_id)) |runtime| {
            for (runtime.tools) |tool| {
                if (std.mem.eql(u8, tool.name, name)) return .{
                    .handler = tool.handler,
                    .context = tool.context,
                };
            }
        }
        for (self.tools.items) |tool| {
            if (std.mem.eql(u8, tool.session_id, session_id) and
                std.mem.eql(u8, tool.name, name))
            {
                return .{
                    .handler = tool.handler,
                    .context = tool.context,
                };
            }
        }
        return null;
    }

    fn registerUserInputHandler(
        self: *Client,
        session_id: []const u8,
        handler: ?session_types.UserInputHandler,
        context: ?*anyopaque,
    ) !void {
        const callback = handler orelse return;
        try self.user_input_handlers.append(self.allocator, .{
            .session_id = session_id,
            .handler = callback,
            .context = context,
        });
    }

    fn registerPermissionHandler(
        self: *Client,
        session_id: []const u8,
        config: anytype,
    ) !void {
        const optional_callback: ?session_types.PermissionHandler = config.on_permission_request;
        const callback = optional_callback orelse return;
        try self.permission_handlers.append(self.allocator, .{
            .session_id = session_id,
            .handler = callback,
            .managed_settings_enabled = managedSettingsEnabled(config),
            .context = if (@hasField(@TypeOf(config), "permission_context"))
                config.permission_context
            else
                null,
        });
    }

    fn findPermissionHandler(
        self: *Client,
        session_id: []const u8,
    ) ?RegisteredPermissionHandler {
        self.extension_runtimes_mutex.lockUncancelable(self.io);
        defer self.extension_runtimes_mutex.unlock(self.io);
        if (self.findCommittedExtensionRuntime(session_id)) |runtime| {
            if (runtime.permission_handler) |handler| return .{
                .session_id = session_id,
                .handler = handler,
                .managed_settings_enabled = runtime.managed_settings_enabled,
                .context = runtime.permission_context,
            };
        }
        for (self.permission_handlers.items) |registered| {
            if (std.mem.eql(u8, registered.session_id, session_id)) return registered;
        }
        return null;
    }

    fn findUserInputHandler(
        self: *Client,
        session_id: []const u8,
    ) ?RegisteredUserInputHandler {
        if (self.findExtensionRuntime(session_id)) |runtime| {
            if (runtime.user_input_handler) |handler| return .{
                .session_id = session_id,
                .handler = handler,
                .context = runtime.user_input_context,
            };
        }
        for (self.user_input_handlers.items) |registered| {
            if (std.mem.eql(u8, registered.session_id, session_id)) return registered;
        }
        return null;
    }

    fn findUserInputHandlerFromParams(
        self: *Client,
        params: ?std.json.Value,
    ) ?RegisteredUserInputHandler {
        const object = switch (params orelse return null) {
            .object => |object| object,
            else => return null,
        };
        const session_id = switch (object.get("sessionId") orelse return null) {
            .string => |value| value,
            else => return null,
        };
        return self.findUserInputHandler(session_id);
    }

    pub fn nextLifecycleEvent(self: *Client) !admin.SessionLifecycleDelivery {
        return legacyResult(
            admin.SessionLifecycleDelivery,
            self.nextLifecycleEventImpl(.legacy),
        );
    }

    pub fn nextLifecycleEventDetailed(
        self: *Client,
    ) errors.DetailedError!errors.DetailedResult(admin.SessionLifecycleDelivery) {
        return self.nextLifecycleEventImpl(.detailed);
    }

    fn nextLifecycleEventImpl(
        self: *Client,
        comptime failure_policy: FailurePolicy,
    ) errors.DetailedError!PolicyResult(failure_policy, admin.SessionLifecycleDelivery) {
        self.lifecycle_events_mutex.lockUncancelable(self.io);
        const queued = self.lifecycle_events.popDelivery();
        self.lifecycle_events_mutex.unlock(self.io);
        if (queued) |delivery| return .{ .success = delivery };
        self.ensurePump() catch |err| return .{ .failure = if (err == error.ReentrantRpcCall)
            try policyFailure(
                failure_policy,
                err,
                recordReentrant,
                .{ self.allocator, "session.lifecycle" },
            )
        else
            try policyFailure(
                failure_policy,
                err,
                recordClientIo,
                .{ self.allocator, .read, err },
            ) };
        while (true) {
            self.lifecycle_events_mutex.lockUncancelable(self.io);
            const delivery = self.lifecycle_events.popDelivery();
            if (delivery == null) self.lifecycle_event_ready.reset();
            self.lifecycle_events_mutex.unlock(self.io);
            if (delivery) |value| {
                return .{ .success = value };
            }

            self.pending_mutex.lockUncancelable(self.io);
            if (self.pump_terminal_error) |native_error| {
                if (comptime failure_policy == .detailed) {
                    if (self.pump_failure) |*failure| {
                        const owned = failure.clone(self.allocator) catch |err| {
                            self.pending_mutex.unlock(self.io);
                            return err;
                        };
                        self.pending_mutex.unlock(self.io);
                        return .{ .failure = owned };
                    }
                }
                self.pending_mutex.unlock(self.io);
                return .{ .failure = try policyFailure(
                    failure_policy,
                    native_error,
                    recordClientIo,
                    .{ self.allocator, .read, native_error },
                ) };
            }
            const transport_closed = self.transport_closed;
            self.pending_mutex.unlock(self.io);
            if (transport_closed) {
                return .{ .failure = try self.closedTransportFailure(failure_policy) };
            }

            self.lifecycle_event_ready.wait(self.io) catch |err|
                return .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordClientIo,
                    .{ self.allocator, .read, err },
                ) };
        }
    }

    fn nextLifecycleEventDirect(
        self: *Client,
        comptime failure_policy: FailurePolicy,
    ) errors.DetailedError!PolicyResult(failure_policy, admin.SessionLifecycleDelivery) {
        while (true) {
            self.lifecycle_events_mutex.lockUncancelable(self.io);
            const queued = self.lifecycle_events.popDelivery();
            self.lifecycle_events_mutex.unlock(self.io);
            if (queued) |delivery| return .{ .success = delivery };

            const body = switch (try self.readTransportFrame(failure_policy)) {
                .success => |value| value,
                .failure => |failure| return .{ .failure = failure },
            };
            var body_owned = true;
            defer if (body_owned) {
                wipeSecret(body);
                self.allocator.free(body);
            };
            const value = std.json.parseFromSlice(
                std.json.Value,
                self.allocator,
                body,
                .{},
            ) catch |err| {
                if (err == error.OutOfMemory) return error.OutOfMemory;
                return .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordInvalidJson,
                    .{ self.allocator, err },
                ) };
            };
            defer {
                wipeJsonStrings(value.value);
                value.deinit();
            }
            const inbound = switch (try parseInboundMessage(
                failure_policy,
                self.allocator,
                value.value,
            )) {
                .success => |message| message,
                .failure => |failure| return .{ .failure = failure },
            };
            switch (inbound) {
                .request => |request| {
                    var operation: errors.ClientOperation = .callback;
                    self.dispatchServerRequestTracked(
                        self.transportWriter(),
                        request.id,
                        request.method,
                        request.params,
                        &operation,
                    ) catch |err| {
                        if (err == error.OutOfMemory) return error.OutOfMemory;
                        return .{ .failure = try policyFailure(
                            failure_policy,
                            err,
                            recordClientIo,
                            .{ self.allocator, operation, err },
                        ) };
                    };
                },
                .notification => |notification| {
                    switch (try self.routeNotification(
                        failure_policy,
                        body,
                        notification.method,
                        notification.params,
                        value.value,
                    )) {
                        .success => |disposition| body_owned = switch (disposition) {
                            .reader_releases_frame => true,
                            .router_retains_frame => false,
                        },
                        .failure => |failure| return .{ .failure = failure },
                    }
                },
                .response => |response| return .{ .failure = try policyFailure(
                    failure_policy,
                    error.UnexpectedResponse,
                    recordUnexpectedResponse,
                    .{ self.allocator, 0, response.id_value },
                ) },
            }
        }
    }
    fn nextEventImpl(
        self: *Client,
        comptime failure_policy: FailurePolicy,
        session_id: []const u8,
        generation: u64,
    ) errors.DetailedError!PolicyResult(failure_policy, EventDelivery) {
        while (true) {
            self.events_mutex.lockUncancelable(self.io);
            var queued_delivery: ?EventDelivery = null;
            for (self.events.items, 0..) |queued, index| {
                if (queued.generation == generation and
                    std.mem.eql(u8, queued.session_id, session_id))
                {
                    if (queued.automatic_handling_in_progress) {
                        self.events.items[index].remove_after_automatic_handling = true;
                        continue;
                    }
                    queued_delivery = self.events.orderedRemove(index);
                    break;
                }
            }
            const queued_count = self.queuedEventCount(session_id, generation);
            self.events_mutex.unlock(self.io);
            if (queued_delivery) |delivery| return .{ .success = delivery };
            if (self.sessionEventQueueFailure(session_id)) |failure| {
                const native_error = switch (failure) {
                    .capacity_exceeded => error.EventQueueFull,
                    .allocation_failed => error.EventQueueAllocationFailed,
                    .rejection_failed => error.EventQueueRejectionFailed,
                };
                return .{ .failure = try policyFailure(
                    failure_policy,
                    native_error,
                    recordQueueFull,
                    .{
                        self.allocator,
                        session_id,
                        @as(?[]const u8, null),
                        queued_count,
                    },
                ) };
            }
            if (self.transport_closed)
                return .{ .failure = try self.closedTransportFailure(failure_policy) };

            const body = switch (try self.readTransportFrame(failure_policy)) {
                .success => |value| value,
                .failure => |failure| return .{ .failure = failure },
            };
            var body_owned = true;
            defer if (body_owned) {
                wipeSecret(body);
                self.allocator.free(body);
            };
            const value = std.json.parseFromSlice(
                std.json.Value,
                self.allocator,
                body,
                .{},
            ) catch |err| {
                if (err == error.OutOfMemory) return error.OutOfMemory;
                return .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordInvalidJson,
                    .{ self.allocator, err },
                ) };
            };
            defer {
                wipeJsonStrings(value.value);
                value.deinit();
            }
            const inbound = switch (try parseInboundMessage(
                failure_policy,
                self.allocator,
                value.value,
            )) {
                .success => |message| message,
                .failure => |failure| return .{ .failure = failure },
            };
            switch (inbound) {
                .request => |request| {
                    var operation: errors.ClientOperation = .callback;
                    self.dispatchServerRequestTracked(
                        self.transportWriter(),
                        request.id,
                        request.method,
                        request.params,
                        &operation,
                    ) catch |err| {
                        if (err == error.OutOfMemory) return error.OutOfMemory;
                        return .{ .failure = try policyFailure(
                            failure_policy,
                            err,
                            recordClientIo,
                            .{ self.allocator, operation, err },
                        ) };
                    };
                },
                .notification => |notification| {
                    switch (try self.routeNotification(
                        failure_policy,
                        body,
                        notification.method,
                        notification.params,
                        value.value,
                    )) {
                        .success => |disposition| body_owned = switch (disposition) {
                            .reader_releases_frame => true,
                            .router_retains_frame => false,
                        },
                        .failure => |failure| return .{ .failure = failure },
                    }
                },
                .response => |response| return .{ .failure = try policyFailure(
                    failure_policy,
                    error.UnexpectedResponse,
                    recordUnexpectedResponse,
                    .{ self.allocator, 0, response.id_value },
                ) },
            }
        }
    }

    fn hasQueuedSessionEvent(
        self: *Client,
        session_id: []const u8,
        generation: u64,
    ) bool {
        self.events_mutex.lockUncancelable(self.io);
        defer self.events_mutex.unlock(self.io);
        for (self.events.items) |queued| {
            if (queued.generation == generation and
                std.mem.eql(u8, queued.session_id, session_id) and
                !queued.automatic_handling_in_progress) return true;
        }
        return false;
    }

    fn nextSubscriberEvent(
        self: *Client,
        log: *event_log.EventLog,
        token: event_log.SubscriberToken,
        deadline: ?std.Io.Clock.Timestamp,
        cancellation: ?*session_types.Cancellation,
    ) !session_types.SessionEvent {
        try self.ensurePump();
        while (true) {
            switch (try log.inspect(token)) {
                .event => |event| return event,
                .overflow => return error.EventLogOverflow,
                .failure => |err| return err,
                .closed => {
                    self.reclaimClosedEventLogs();
                    return error.SessionDisconnected;
                },
                .wait => |ready| {
                    if (cancellation) |value| {
                        if (value.isCancelled()) return error.Canceled;
                    }
                    if (deadline == null and cancellation == null) {
                        try ready.wait(self.io);
                        continue;
                    }
                    const WaitResult = union(enum) {
                        ready: anyerror!void,
                        canceled: anyerror!void,
                        timeout: anyerror!void,
                    };
                    var results: [3]WaitResult = undefined;
                    var select = std.Io.Select(WaitResult).init(self.io, &results);
                    select.async(.ready, waitForEvent, .{ ready, self.io });
                    if (cancellation) |value|
                        select.async(.canceled, waitForEvent, .{ &value.event, self.io });
                    if (deadline) |value|
                        select.async(.timeout, waitForDeadline, .{ value, self.io });
                    const result = select.await() catch |err| {
                        select.cancelDiscard();
                        return err;
                    };
                    select.cancelDiscard();
                    switch (try log.inspect(token)) {
                        .event => |event| return event,
                        .overflow => return error.EventLogOverflow,
                        .failure => |err| return err,
                        .closed => return error.SessionDisconnected,
                        .wait => {},
                    }
                    if (cancellation) |value| {
                        if (value.isCancelled()) return error.Canceled;
                    }
                    switch (result) {
                        .ready => |wait_result| try wait_result,
                        .canceled => |wait_result| {
                            try wait_result;
                            return error.Canceled;
                        },
                        .timeout => |wait_result| {
                            try wait_result;
                            return error.Timeout;
                        },
                    }
                },
            }
        }
    }
};

fn waitForEvent(event: *std.Io.Event, io: std.Io) anyerror!void {
    return event.wait(io);
}

fn waitForDeadline(deadline: std.Io.Clock.Timestamp, io: std.Io) anyerror!void {
    return deadline.wait(io);
}

const ResolvedSession = struct {
    record_index: usize,
    id: []const u8,
};

pub const EventSubscriber = struct {
    lease: EventLogLease,
    token: event_log.SubscriberToken,
    active: bool = true,

    pub fn nextEvent(self: *EventSubscriber) !session_types.SessionEvent {
        if (!self.active) return error.InvalidEventSubscriber;
        return self.lease.client.nextSubscriberEvent(
            self.lease.log,
            self.token,
            null,
            null,
        );
    }

    pub fn deinit(self: *EventSubscriber) void {
        if (!self.active) return;
        self.lease.log.unsubscribe(self.token);
        self.active = false;
        self.lease.deinit();
    }
};

const ElicitationResponse = union(enum) {
    cancelled,
    result: struct {
        action: session_types.ElicitationAction,
        content: ?std.json.Value,
    },
};

pub const Session = struct {
    client: *Client,
    id: []const u8,
    record_index: usize = std.math.maxInt(usize),
    generation: u64 = 0,

    pub fn factory(self: Session) FactoryApi {
        return .{ .session = self };
    }

    pub fn factoryRun(
        self: Session,
        allocator: std.mem.Allocator,
        name: []const u8,
        options: factory_types.FactoryRunOptions,
    ) !factory_types.FactoryRun {
        if (options.limits) |limits| try factory_types.validateLimitOverrides(limits);
        const resolved = try self.resolve();
        try self.client.ensurePump();
        const args = try std.json.parseFromSlice(
            std.json.Value,
            self.client.allocator,
            if (options.args) |value| value.bytes else "{}",
            .{ .allocate = .alloc_always },
        );
        defer args.deinit();
        const parsed = try self.client.call(std.json.Value, "session.factory.run", .{
            .sessionId = resolved.id,
            .name = name,
            .args = args.value,
            .options = WireFactoryRunOptions{
                .limits = lowerFactoryLimits(options.limits),
                .notifyOnComplete = options.notify_on_complete,
                .logPhaseNames = options.log_phase_names,
                .resumeFromRunId = options.resume_from_run_id,
            },
        });
        defer parsed.deinit();
        return self.settleFactoryRun(
            allocator,
            try decodeFactoryRun(allocator, parsed.value),
        );
    }

    pub fn factoryResume(
        self: Session,
        allocator: std.mem.Allocator,
        run_id: []const u8,
        options: factory_types.FactoryResumeOptions,
    ) !factory_types.FactoryRun {
        if (options.limits) |limits| try factory_types.validateLimitOverrides(limits);
        const resolved = try self.resolve();
        try self.client.ensurePump();
        const parsed = try self.client.call(std.json.Value, "session.factory.resume", .{
            .sessionId = resolved.id,
            .runId = run_id,
            .limits = lowerFactoryLimits(options.limits),
            .notifyOnComplete = options.notify_on_complete,
            .logPhaseNames = options.log_phase_names,
        });
        defer parsed.deinit();
        const object = switch (parsed.value) {
            .object => |object| object,
            else => return error.InvalidFactoryRun,
        };
        return self.settleFactoryRun(
            allocator,
            try decodeFactoryRun(
                allocator,
                object.get("run") orelse return error.InvalidFactoryRun,
            ),
        );
    }

    fn settleFactoryRun(
        self: Session,
        allocator: std.mem.Allocator,
        initial: factory_types.FactoryRun,
    ) !factory_types.FactoryRun {
        if (initial.isTerminal()) return initial;
        var pending = initial;
        const run_id = allocator.dupe(u8, pending.run_id) catch |err| {
            pending.deinit();
            return err;
        };
        defer allocator.free(run_id);
        pending.deinit();
        return self.factoryWaitForRun(allocator, run_id, .{});
    }

    pub fn factoryGetRun(
        self: Session,
        allocator: std.mem.Allocator,
        run_id: []const u8,
    ) !factory_types.FactoryRun {
        return self.factoryGetRunCancelable(allocator, run_id, null);
    }

    fn factoryGetRunCancelable(
        self: Session,
        allocator: std.mem.Allocator,
        run_id: []const u8,
        cancellation: ?*std.Io.Event,
    ) !factory_types.FactoryRun {
        const resolved = try self.resolve();
        try self.client.ensurePump();
        const parsed = if (cancellation) |event|
            try self.client.callCancelable(std.json.Value, "session.factory.getRun", .{
                .sessionId = resolved.id,
                .runId = run_id,
            }, event, null)
        else
            try self.client.call(std.json.Value, "session.factory.getRun", .{
                .sessionId = resolved.id,
                .runId = run_id,
            });
        defer parsed.deinit();
        return decodeFactoryRun(allocator, parsed.value);
    }

    pub fn factoryWaitForRun(
        self: Session,
        allocator: std.mem.Allocator,
        run_id: []const u8,
        options: factory_types.FactoryWaitOptions,
    ) !factory_types.FactoryRun {
        if (options.poll_interval_ns == 0) return error.InvalidFactoryWaitOptions;
        if (options.cancellation) |cancellation|
            if (cancellation.isCancelled()) return error.Canceled;
        const started = std.Io.Clock.Timestamp.now(self.client.io, .awake);
        while (true) {
            var run = self.factoryGetRunCancelable(
                allocator,
                run_id,
                if (options.cancellation) |cancellation| &cancellation.event else null,
            ) catch |err| {
                if (err == error.FactoryCancelled) return error.Canceled;
                return err;
            };
            if (run.isTerminal()) return run;
            run.deinit();
            if (options.cancellation) |cancellation|
                if (cancellation.isCancelled()) return error.Canceled;
            const elapsed_ns = started.durationTo(
                std.Io.Clock.Timestamp.now(self.client.io, .awake),
            ).raw.toNanoseconds();
            if (options.timeout_ns) |timeout_ns| {
                if (elapsed_ns >= timeout_ns) return error.Timeout;
            }
            const sleep_ns = if (options.timeout_ns) |timeout_ns|
                @min(options.poll_interval_ns, timeout_ns - @as(u64, @intCast(elapsed_ns)))
            else
                options.poll_interval_ns;
            if (options.cancellation) |cancellation| {
                const WaitResult = union(enum) {
                    elapsed: anyerror!void,
                    canceled: anyerror!void,
                };
                var results: [2]WaitResult = undefined;
                var select = std.Io.Select(WaitResult).init(self.client.io, &results);
                defer select.cancelDiscard();
                select.async(.elapsed, std.Io.sleep, .{
                    self.client.io,
                    std.Io.Duration.fromNanoseconds(@intCast(sleep_ns)),
                    std.Io.Clock.awake,
                });
                select.async(.canceled, waitForEvent, .{
                    &cancellation.event,
                    self.client.io,
                });
                switch (try select.await()) {
                    .elapsed => |result| try result,
                    .canceled => |result| {
                        try result;
                        return error.Canceled;
                    },
                }
            } else {
                try std.Io.sleep(
                    self.client.io,
                    std.Io.Duration.fromNanoseconds(@intCast(sleep_ns)),
                    .awake,
                );
            }
        }
    }

    pub fn factoryListRuns(
        self: Session,
        allocator: std.mem.Allocator,
        options: factory_types.FactoryListRunsOptions,
    ) !factory_types.FactoryRunsPage {
        if (options.after_seq != null and options.before_seq != null)
            return error.InvalidFactoryCursor;
        if (options.limit) |limit| if (limit == 0 or limit > 500)
            return error.InvalidFactoryLimit;
        const resolved = try self.resolve();
        try self.client.ensurePump();
        const parsed = try self.client.call(std.json.Value, "session.factory.listRuns", .{
            .sessionId = resolved.id,
            .afterSeq = options.after_seq,
            .beforeSeq = options.before_seq,
            .limit = options.limit,
        });
        defer parsed.deinit();
        return .{ .value = try factory_types.Json.initValue(allocator, parsed.value) };
    }

