    fn resolve(self: Session) !ResolvedSession {
        if (self.record_index >= self.client.sessions.items.len)
            return error.SessionNotActive;
        const record = &self.client.sessions.items[self.record_index];
        if (!record.isActive() or record.generation != self.generation)
            return error.SessionNotActive;
        return .{ .record_index = self.record_index, .id = record.id.? };
    }

    fn resolveForPolicy(
        self: Session,
        comptime failure_policy: FailurePolicy,
    ) errors.DetailedError!PolicyResult(failure_policy, ResolvedSession) {
        const resolved = self.resolve() catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{ self.client.allocator, "session_id", err },
            ) };
        return .{ .success = resolved };
    }

    fn acquireIngressForPolicy(
        self: Session,
        comptime failure_policy: FailurePolicy,
    ) errors.DetailedError!PolicyResult(failure_policy, EventLogLease) {
        const lease = self.client.acquireSessionHandleIngress(
            self.record_index,
            self.generation,
        ) catch |err| return .{ .failure = try policyFailure(
            failure_policy,
            err,
            recordClientIo,
            .{ self.client.allocator, .callback, err },
        ) };
        return .{ .success = lease };
    }

    fn eventLog(self: Session) !EventLogLease {
        return self.client.ensureSessionHandleEventLogLease(
            self.record_index,
            self.generation,
        );
    }

    fn eventLogForPolicy(
        self: Session,
        comptime failure_policy: FailurePolicy,
    ) errors.DetailedError!PolicyResult(failure_policy, EventLogLease) {
        const lease = self.eventLog() catch |err|
            return .{ .failure = if (err == error.SessionNotActive)
                try policyFailure(
                    failure_policy,
                    err,
                    recordInvalidConfig,
                    .{ self.client.allocator, "session_id", err },
                )
            else
                try policyFailure(
                    failure_policy,
                    err,
                    recordClientIo,
                    .{ self.client.allocator, .read, err },
                ) };
        return .{ .success = lease };
    }

    pub fn subscribe(self: Session) !EventSubscriber {
        var lease = try self.eventLog();
        errdefer lease.deinit();
        const token = try lease.log.subscribe();
        errdefer lease.log.unsubscribe(token);
        try self.client.ensurePump();
        return .{
            .lease = lease,
            .token = token,
        };
    }

    pub fn send(
        self: Session,
        options: session_types.MessageOptions,
    ) ![]u8 {
        return legacyResult([]u8, self.sendImpl(.legacy, options));
    }

    pub fn sendDetailed(
        self: Session,
        options: session_types.MessageOptions,
    ) errors.DetailedError!errors.DetailedResult([]u8) {
        return self.sendImpl(.detailed, options);
    }

    fn sendImpl(
        self: Session,
        comptime failure_policy: FailurePolicy,
        options: session_types.MessageOptions,
    ) errors.DetailedError!PolicyResult(failure_policy, []u8) {
        var validation_field_buffer: [96]u8 = undefined;
        const attachments = validateMessageOptions(options) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{
                    self.client.allocator,
                    messageValidationField(options, err, &validation_field_buffer),
                    err,
                },
            ) };
        var lease = switch (try self.eventLogForPolicy(failure_policy)) {
            .success => |value| value,
            .failure => |failure| return .{ .failure = failure },
        };
        defer lease.deinit();
        const session_log = lease.log;
        const session_id = session_log.session_id;
        const receipt = session_log.reserveTurn(.raw) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordClientIo,
                .{ self.client.allocator, .read, err },
            ) };
        var receipt_owned = true;
        defer if (receipt_owned) session_log.abandonTurn(receipt);
        const owned_source = if (options.source) |source| switch (source) {
            .user, .system => null,
            .agent => |name| try std.fmt.allocPrint(
                self.client.allocator,
                "agent-{s}",
                .{name},
            ),
        } else null;
        defer if (owned_source) |source| self.client.allocator.free(source);
        const source: ?[]const u8 = if (options.source) |value| switch (value) {
            .user => "user",
            .system => "system",
            .agent => owned_source.?,
        } else null;
        const trace_context = self.client.traceContext();
        const parsed = switch (try self.client.callImpl(
            failure_policy,
            struct { messageId: []const u8 },
            "session.send",
            lowerMessage(
                session_id,
                options,
                attachments,
                source,
                trace_context,
            ),
            .{ .session = .{ .session_id = session_id } },
        )) {
            .success => |value| value,
            .failure => |failure| {
                session_log.failTurn(receipt, failure.native_error);
                receipt_owned = false;
                return .{ .failure = failure };
            },
        };
        defer parsed.deinit();
        const message_id = try self.client.allocator.dupe(u8, parsed.value.messageId);
        session_log.bindTurnMessage(receipt, message_id) catch |err| {
            self.client.allocator.free(message_id);
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordClientIo,
                .{ self.client.allocator, .read, err },
            ) };
        };
        receipt_owned = false;
        return .{ .success = message_id };
    }

    pub fn getEvents(self: Session) !session_types.SessionEventHistory {
        return legacyResult(
            session_types.SessionEventHistory,
            self.getEventsImpl(.legacy),
        );
    }

    pub fn getEventsDetailed(
        self: Session,
    ) errors.DetailedError!errors.DetailedResult(session_types.SessionEventHistory) {
        return self.getEventsImpl(.detailed);
    }

    fn getEventsImpl(
        self: Session,
        comptime failure_policy: FailurePolicy,
    ) errors.DetailedError!PolicyResult(failure_policy, session_types.SessionEventHistory) {
        const resolved = switch (try self.resolveForPolicy(failure_policy)) {
            .success => |value| value,
            .failure => |failure| return .{ .failure = failure },
        };
        const parsed = switch (try self.client.callImpl(
            failure_policy,
            admin.SessionGetMessagesResult,
            "session.getMessages",
            admin.SessionIdParams{ .sessionId = resolved.id },
            .{ .session = .{ .session_id = resolved.id } },
        )) {
            .success => |value| value,
            .failure => |failure| return .{ .failure = failure },
        };
        defer parsed.deinit();

        const events = try self.client.allocator.alloc(
            session_types.SessionEvent,
            parsed.value.events.len,
        );
        var initialized: usize = 0;
        for (parsed.value.events, events) |value, *event| {
            event.* = session_types.parseEventClassified(
                self.client.allocator,
                value,
            ) catch |err| switch (err) {
                error.OutOfMemory => {
                    for (events[0..initialized]) |*owned_event|
                        owned_event.deinit(self.client.allocator);
                    self.client.allocator.free(events);
                    return error.OutOfMemory;
                },
                error.MissingField, error.MalformedFieldType => {
                    for (events[0..initialized]) |*owned_event|
                        owned_event.deinit(self.client.allocator);
                    self.client.allocator.free(events);
                    return .{ .failure = try policyFailure(
                        failure_policy,
                        error.InvalidSessionEvent,
                        recordInvalidEvent,
                        .{
                            self.client.allocator,
                            if (err == error.MissingField)
                                errors.EnvelopeViolation.missing_params
                            else
                                errors.EnvelopeViolation.malformed_field_type,
                            value,
                        },
                    ) };
                },
            };
            initialized += 1;
        }
        return .{ .success = .{
            .allocator = self.client.allocator,
            .events = events,
        } };
    }

    pub fn sendAndWait(
        self: Session,
        options: session_types.MessageOptions,
    ) !?session_types.AssistantMessage {
        return legacyResult(
            ?session_types.AssistantMessage,
            self.sendAndWaitImpl(.legacy, options, .{}),
        );
    }

    pub fn sendAndWaitWithOptions(
        self: Session,
        options: session_types.MessageOptions,
        wait_options: session_types.WaitOptions,
    ) !?session_types.AssistantMessage {
        return legacyResult(
            ?session_types.AssistantMessage,
            self.sendAndWaitImpl(.legacy, options, wait_options),
        );
    }

    pub fn sendAndWaitDetailed(
        self: Session,
        options: session_types.MessageOptions,
    ) errors.DetailedError!errors.DetailedResult(?session_types.AssistantMessage) {
        return self.sendAndWaitImpl(.detailed, options, .{});
    }

    pub fn sendAndWaitDetailedWithOptions(
        self: Session,
        options: session_types.MessageOptions,
        wait_options: session_types.WaitOptions,
    ) errors.DetailedError!errors.DetailedResult(?session_types.AssistantMessage) {
        return self.sendAndWaitImpl(.detailed, options, wait_options);
    }

    fn sendAndWaitImpl(
        self: Session,
        comptime failure_policy: FailurePolicy,
        options: session_types.MessageOptions,
        wait_options: session_types.WaitOptions,
    ) errors.DetailedError!PolicyResult(failure_policy, ?session_types.AssistantMessage) {
        var validation_field_buffer: [96]u8 = undefined;
        const attachments = validateMessageOptions(options) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidConfig,
                .{
                    self.client.allocator,
                    messageValidationField(options, err, &validation_field_buffer),
                    err,
                },
            ) };
        self.client.validateSessionHandle(
            self.record_index,
            self.generation,
        ) catch |err| return .{ .failure = try policyFailure(
            failure_policy,
            err,
            recordInvalidConfig,
            .{ self.client.allocator, "session_id", err },
        ) };
        const deadline = if (wait_options.timeout_ns) |timeout_ns|
            std.Io.Clock.Timestamp.fromNow(self.client.io, .{
                .raw = std.Io.Duration.fromNanoseconds(@intCast(timeout_ns)),
                .clock = .awake,
            })
        else
            null;
        if (wait_options.cancellation) |cancellation| {
            if (cancellation.isCancelled()) return .{ .failure = try policyFailure(
                failure_policy,
                error.Canceled,
                recordClientIo,
                .{ self.client.allocator, .read, error.Canceled },
            ) };
        }
        var lease = switch (try self.eventLogForPolicy(failure_policy)) {
            .success => |value| value,
            .failure => |failure| return .{ .failure = failure },
        };
        defer lease.deinit();
        const session_log = lease.log;
        const receipt = session_log.reserveTurn(.waited) catch |err|
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordClientIo,
                .{ self.client.allocator, .read, err },
            ) };
        var waiter_attached = true;
        var operation_started = false;
        defer if (waiter_attached) {
            if (operation_started) {
                session_log.detachTurnWaiter(receipt);
            } else {
                session_log.abandonTurn(receipt);
            }
        };

        const owned_source = if (options.source) |source| switch (source) {
            .user, .system => null,
            .agent => |name| try std.fmt.allocPrint(
                self.client.allocator,
                "agent-{s}",
                .{name},
            ),
        } else null;
        defer if (owned_source) |source| self.client.allocator.free(source);
        const source: ?[]const u8 = if (options.source) |value| switch (value) {
            .user => "user",
            .system => "system",
            .agent => owned_source.?,
        } else null;
        const operation = self.client.startSendOperation(
            lease,
            receipt,
            options,
            attachments,
            source,
            self.client.traceContext(),
        ) catch |err| return .{ .failure = try policyFailure(
            failure_policy,
            err,
            recordClientIo,
            .{ self.client.allocator, .write, err },
        ) };
        operation_started = true;
        var detach_operation = true;
        defer if (detach_operation) self.client.detachSendOperation(operation);

        while (!operation.completed.isSet()) {
            const WaitResult = union(enum) {
                completed: anyerror!void,
                canceled: anyerror!void,
                timeout: anyerror!void,
            };
            var results: [3]WaitResult = undefined;
            var select = std.Io.Select(WaitResult).init(self.client.io, &results);
            defer select.cancelDiscard();
            select.async(.completed, waitForEvent, .{ &operation.completed, self.client.io });
            if (wait_options.cancellation) |cancellation|
                select.async(.canceled, waitForEvent, .{ &cancellation.event, self.client.io });
            if (deadline) |value|
                select.async(.timeout, waitForDeadline, .{ value, self.client.io });
            const selected = select.await() catch |err|
                return .{ .failure = try policyFailure(
                    failure_policy,
                    err,
                    recordClientIo,
                    .{ self.client.allocator, .read, err },
                ) };
            if (operation.completed.isSet()) break;
            if (wait_options.cancellation) |cancellation| {
                if (cancellation.isCancelled()) {
                    return .{ .failure = try policyFailure(
                        failure_policy,
                        error.Canceled,
                        recordClientIo,
                        .{ self.client.allocator, .read, error.Canceled },
                    ) };
                }
            }
            switch (selected) {
                .completed => |result| result catch |err|
                    return .{ .failure = try policyFailure(
                        failure_policy,
                        err,
                        recordClientIo,
                        .{ self.client.allocator, .read, err },
                    ) },
                .canceled => |result| {
                    result catch |err| return .{ .failure = try policyFailure(
                        failure_policy,
                        err,
                        recordClientIo,
                        .{ self.client.allocator, .read, err },
                    ) };
                    return .{ .failure = try policyFailure(
                        failure_policy,
                        error.Canceled,
                        recordClientIo,
                        .{ self.client.allocator, .read, error.Canceled },
                    ) };
                },
                .timeout => |result| {
                    result catch |err| return .{ .failure = try policyFailure(
                        failure_policy,
                        err,
                        recordClientIo,
                        .{ self.client.allocator, .read, err },
                    ) };
                    return .{ .failure = try policyFailure(
                        failure_policy,
                        error.Timeout,
                        recordSessionTimeout,
                        .{
                            self.client.allocator,
                            session_log.session_id,
                            wait_options.timeout_ns.?,
                        },
                    ) };
                },
            }
        }
        const completed = self.client.claimSendOperation(operation) orelse unreachable;
        detach_operation = false;
        if (completed.future) |*future| future.await(self.client.io);
        if (completed.failure) |failure| {
            completed.failure = null;
            wipeSecret(completed.request);
            self.client.allocator.free(completed.request);
            completed.log_lease.deinit();
            self.client.allocator.destroy(completed);
            if (comptime failure_policy == .detailed) return .{ .failure = failure };
            const native_error = failure.native_error;
            var owned_failure = failure;
            owned_failure.deinit();
            return .{ .failure = .{ .native_error = native_error } };
        }
        wipeSecret(completed.request);
        self.client.allocator.free(completed.request);
        completed.log_lease.deinit();
        self.client.allocator.destroy(completed);

        while (true) {
            var inspected = self.inspectTurnForPolicy(
                failure_policy,
                session_log,
                receipt,
            ) catch |err| return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordClientIo,
                .{ self.client.allocator, .read, err },
            ) };
            defer if (inspected.failure) |*failure| failure.deinit();
            switch (inspected.read) {
                .completed => |response| {
                    waiter_attached = false;
                    return .{ .success = response };
                },
                .failure => |err| {
                    if (comptime failure_policy == .detailed) {
                        if (inspected.failure) |failure| {
                            inspected.failure = null;
                            return .{ .failure = failure };
                        }
                    }
                    return .{ .failure = try policyFailure(
                        failure_policy,
                        err,
                        recordClientIo,
                        .{ self.client.allocator, .read, err },
                    ) };
                },
                .pending => |ready| {
                    const WaitResult = union(enum) {
                        ready: anyerror!void,
                        canceled: anyerror!void,
                        timeout: anyerror!void,
                    };
                    var results: [3]WaitResult = undefined;
                    var select = std.Io.Select(WaitResult).init(self.client.io, &results);
                    select.async(.ready, waitForEvent, .{ ready, self.client.io });
                    if (wait_options.cancellation) |cancellation|
                        select.async(.canceled, waitForEvent, .{ &cancellation.event, self.client.io });
                    if (deadline) |value|
                        select.async(.timeout, waitForDeadline, .{ value, self.client.io });
                    const selected = select.await() catch |err| {
                        select.cancelDiscard();
                        return .{ .failure = try policyFailure(
                            failure_policy,
                            err,
                            recordClientIo,
                            .{ self.client.allocator, .read, err },
                        ) };
                    };
                    select.cancelDiscard();
                    var latest = self.inspectTurnForPolicy(
                        failure_policy,
                        session_log,
                        receipt,
                    ) catch |err| return .{ .failure = try policyFailure(
                        failure_policy,
                        err,
                        recordClientIo,
                        .{ self.client.allocator, .read, err },
                    ) };
                    defer if (latest.failure) |*failure| failure.deinit();
                    switch (latest.read) {
                        .completed => |response| {
                            waiter_attached = false;
                            return .{ .success = response };
                        },
                        .failure => |err| {
                            if (comptime failure_policy == .detailed) {
                                if (latest.failure) |failure| {
                                    latest.failure = null;
                                    return .{ .failure = failure };
                                }
                            }
                            return .{ .failure = try policyFailure(
                                failure_policy,
                                err,
                                recordClientIo,
                                .{ self.client.allocator, .read, err },
                            ) };
                        },
                        .pending => {},
                    }
                    if (wait_options.cancellation) |cancellation| {
                        if (cancellation.isCancelled()) return .{ .failure = try policyFailure(
                            failure_policy,
                            error.Canceled,
                            recordClientIo,
                            .{ self.client.allocator, .read, error.Canceled },
                        ) };
                    }
                    switch (selected) {
                        .ready => |result| result catch |err|
                            return .{ .failure = try policyFailure(
                                failure_policy,
                                err,
                                recordClientIo,
                                .{ self.client.allocator, .read, err },
                            ) },
                        .canceled => |result| {
                            result catch |err| return .{ .failure = try policyFailure(
                                failure_policy,
                                err,
                                recordClientIo,
                                .{ self.client.allocator, .read, err },
                            ) };
                            return .{ .failure = try policyFailure(
                                failure_policy,
                                error.Canceled,
                                recordClientIo,
                                .{ self.client.allocator, .read, error.Canceled },
                            ) };
                        },
                        .timeout => |result| {
                            result catch |err| return .{ .failure = try policyFailure(
                                failure_policy,
                                err,
                                recordClientIo,
                                .{ self.client.allocator, .read, err },
                            ) };
                            return .{ .failure = try policyFailure(
                                failure_policy,
                                error.Timeout,
                                recordSessionTimeout,
                                .{
                                    self.client.allocator,
                                    session_log.session_id,
                                    wait_options.timeout_ns.?,
                                },
                            ) };
                        },
                    }
                },
            }
        }
    }

    fn inspectTurnForPolicy(
        self: Session,
        comptime failure_policy: FailurePolicy,
        session_log: *event_log.EventLog,
        receipt: turn_tracker.ReceiptToken,
    ) !event_log.DetailedReceiptRead {
        _ = self;
        return if (comptime failure_policy == .detailed)
            session_log.inspectTurnDetailed(receipt)
        else
            .{ .read = try session_log.inspectTurn(receipt) };
    }

    pub fn nextEvent(self: Session) !session_types.SessionEvent {
        var lease = try self.eventLog();
        defer lease.deinit();
        const session_id = lease.log.session_id;
        if (self.client.hasQueuedSessionEvent(session_id, self.generation)) {
            return switch (try self.nextEventDeliveryImpl(.legacy)) {
                .success => |delivery_value| {
                    var delivery = delivery_value;
                    return delivery.intoEvent(self.client.allocator);
                },
                .failure => |failure| failure.native_error,
            };
        }
        try self.client.ensurePump();
        if (self.client.hasQueuedSessionEvent(session_id, self.generation)) {
            return switch (try self.nextEventDeliveryImpl(.legacy)) {
                .success => |delivery_value| {
                    var delivery = delivery_value;
                    return delivery.intoEvent(self.client.allocator);
                },
                .failure => |failure| failure.native_error,
            };
        }
        const event = self.client.nextSubscriberEvent(
            lease.log,
            lease.log.compatibilityToken(),
            null,
            null,
        ) catch |err| {
            if (self.client.transport_closed)
                return (try self.client.closedTransportFailure(.legacy)).native_error;
            return err;
        };
        return switch (try self.processRetainedEvent(
            .legacy,
            lease.log.session_id,
            event,
        )) {
            .success => |delivery_value| {
                var delivery = delivery_value;
                return delivery.intoEvent(self.client.allocator);
            },
            .failure => |failure| failure.native_error,
        };
    }

    pub fn nextEventDetailed(
        self: Session,
    ) errors.DetailedError!errors.DetailedResult(session_types.SessionEvent) {
        var lease = switch (try self.eventLogForPolicy(.detailed)) {
            .success => |value| value,
            .failure => |failure| return .{ .failure = failure },
        };
        defer lease.deinit();
        const session_id = lease.log.session_id;
        if (self.client.hasQueuedSessionEvent(session_id, self.generation)) {
            return switch (try self.nextEventDeliveryImpl(.detailed)) {
                .success => |delivery_value| {
                    var delivery = delivery_value;
                    switch (delivery.event) {
                        .session_error => return .{ .failure = try delivery.intoFailure(
                            self.client.allocator,
                        ) },
                        else => return .{ .success = delivery.intoEvent(self.client.allocator) },
                    }
                },
                .failure => |failure| .{ .failure = failure },
            };
        }
        self.client.ensurePump() catch |err| return .{ .failure = if (err ==
            error.ReentrantRpcCall)
            try recordReentrant(self.client.allocator, "session.event")
        else
            try recordClientIo(
                self.client.allocator,
                .read,
                err,
            ) };
        if (self.client.hasQueuedSessionEvent(session_id, self.generation)) {
            return switch (try self.nextEventDeliveryImpl(.detailed)) {
                .success => |delivery_value| {
                    var delivery = delivery_value;
                    switch (delivery.event) {
                        .session_error => return .{ .failure = try delivery.intoFailure(
                            self.client.allocator,
                        ) },
                        else => return .{ .success = delivery.intoEvent(self.client.allocator) },
                    }
                },
                .failure => |failure| .{ .failure = failure },
            };
        }
        var event = self.client.nextSubscriberEvent(
            lease.log,
            lease.log.compatibilityToken(),
            null,
            null,
        ) catch |err| {
            if (try lease.log.detailedFailure()) |failure|
                return .{ .failure = failure };
            if (try self.client.clonePumpFailure()) |failure|
                return .{ .failure = failure };
            if (self.client.transport_closed)
                return .{ .failure = try self.client.closedTransportFailure(.detailed) };
            return .{ .failure = try recordClientIo(
                self.client.allocator,
                .read,
                err,
            ) };
        };
        if (event == .session_error) {
            defer event.deinit(self.client.allocator);
            return .{ .failure = try sessionFailureFromEvent(
                self.client.allocator,
                lease.log.session_id,
                event.session_error,
            ) };
        }
        return switch (try self.processRetainedEvent(
            .detailed,
            lease.log.session_id,
            event,
        )) {
            .success => |delivery_value| {
                var delivery = delivery_value;
                return .{ .success = delivery.intoEvent(self.client.allocator) };
            },
            .failure => |failure| .{ .failure = failure },
        };
    }

    fn nextEventDeliveryImpl(
        self: Session,
        comptime failure_policy: FailurePolicy,
    ) errors.DetailedError!PolicyResult(failure_policy, EventDelivery) {
        const initial = switch (try self.resolveForPolicy(failure_policy)) {
            .success => |value| value,
            .failure => |failure| return .{ .failure = failure },
        };
        const delivery = switch (try self.client.nextEventImpl(
            failure_policy,
            initial.id,
            self.generation,
        )) {
            .success => |value| value,
            .failure => |failure| return .{ .failure = failure },
        };
        return self.processEventDelivery(failure_policy, delivery);
    }

    fn processEventDelivery(
        self: Session,
        comptime failure_policy: FailurePolicy,
        delivery_value: EventDelivery,
    ) errors.DetailedError!PolicyResult(failure_policy, EventDelivery) {
        var delivery = delivery_value;
        var delivery_owned = true;
        defer if (delivery_owned) delivery.deinit(self.client.allocator);
        var ingress_lease = switch (try self.acquireIngressForPolicy(failure_policy)) {
            .success => |value| value,
            .failure => |failure| return .{ .failure = failure },
        };
        defer {
            self.client.finishSessionIngress(ingress_lease.log);
            ingress_lease.deinit();
        }
        const resolved = ResolvedSession{
            .record_index = self.record_index,
            .id = ingress_lease.log.session_id,
        };
        var ingress_scope: SessionIngressScope = undefined;
        beginSessionIngressScope(&ingress_scope, ingress_lease.log);
        defer endSessionIngressScope(&ingress_scope);
        if (delivery.event == .external_tool_requested) {
            const request = delivery.event.external_tool_requested;
            if (self.client.findToolHandler(resolved.id, request.tool_name)) |tool| {
                const result = tool.handler(
                    self.client.allocator,
                    request.arguments_json,
                    tool.context,
                ) catch |err| {
                    const delivered = try self.respondToToolErrorImpl(
                        failure_policy,
                        request.request_id,
                        @errorName(err),
                        request.tool_call_id,
                        request.tool_name,
                    );
                    switch (delivered) {
                        .failure => |failure| return .{ .failure = failure },
                        .success => {
                            if (comptime failure_policy == .detailed) {
                                return .{ .failure = try recordToolHandlerFailure(
                                    self.client.allocator,
                                    resolved.id,
                                    request.request_id,
                                    request.tool_call_id,
                                    request.tool_name,
                                    err,
                                ) };
                            }
                            delivery_owned = false;
                            return .{ .success = delivery };
                        },
                    }
                };
                defer self.client.allocator.free(result);
                switch (try self.respondToToolImpl(
                    failure_policy,
                    request.request_id,
                    result,
                    request.tool_call_id,
                    request.tool_name,
                )) {
                    .success => {},
                    .failure => |failure| return .{ .failure = failure },
                }
            }
        }
        if (delivery.event == .permission_requested) {
            const request = delivery.event.permission_requested;
            if (self.client.findPermissionHandler(resolved.id)) |handler| {
                const decision = handler.handler(
                    request,
                    .{
                        .session_id = resolved.id,
                        .managed_settings_enabled = handler.managed_settings_enabled,
                    },
                    handler.context,
                ) catch |err| {
                    if (comptime failure_policy == .legacy) {
                        delivery.event.permission_requested.automatic_handling =
                            .{ .handler_failed = err };
                        delivery_owned = false;
                        return .{ .success = delivery };
                    }

                    return .{ .failure = try recordPermissionHandlerFailure(
                        self.client.allocator,
                        resolved.id,
                        request.request_id,
                        err,
                    ) };
                };
                switch (decision) {
                    .approve_once => switch (try self.approvePermissionImpl(
                        failure_policy,
                        request.request_id,
                    )) {
                        .success => {},
                        .failure => |failure_value| {
                            if (comptime failure_policy == .legacy) {
                                delivery.event.permission_requested.automatic_handling =
                                    .{ .delivery_failed = failure_value.native_error };
                                delivery_owned = false;
                                return .{ .success = delivery };
                            }
                            return .{ .failure = failure_value };
                        },
                    },
                    .reject => |feedback| switch (try self.rejectPermissionImpl(
                        failure_policy,
                        request.request_id,
                        feedback,
                    )) {
                        .success => {},
                        .failure => |failure_value| {
                            if (comptime failure_policy == .legacy) {
                                delivery.event.permission_requested.automatic_handling =
                                    .{ .delivery_failed = failure_value.native_error };
                                delivery_owned = false;
                                return .{ .success = delivery };
                            }
                            return .{ .failure = failure_value };
                        },
                    },
                    .json => |decision_json| switch (try self.respondToPermissionJsonImpl(
                        failure_policy,
                        request.request_id,
                        decision_json,
                        null,
                    )) {
                        .success => {},
                        .failure => |failure_value| {
                            if (comptime failure_policy == .legacy) {
                                delivery.event.permission_requested.automatic_handling =
                                    .{ .delivery_failed = failure_value.native_error };
                                delivery_owned = false;
                                return .{ .success = delivery };
                            }
                            return .{ .failure = failure_value };
                        },
                    },
                    .no_result => {
                        delivery.event.permission_requested.automatic_handling = .no_result;
                        delivery_owned = false;
                        return .{ .success = delivery };
                    },
                }
                delivery.event.permission_requested.automatic_handling = .handled;
            }
        }
        delivery_owned = false;
        return .{ .success = delivery };
    }

    fn processRetainedEvent(
        self: Session,
        comptime failure_policy: FailurePolicy,
        session_id: []const u8,
        event_value: session_types.SessionEvent,
    ) errors.DetailedError!PolicyResult(failure_policy, EventDelivery) {
        var event = event_value;
        const owned_session_id = self.client.allocator.dupe(u8, session_id) catch |err| {
            event.deinit(self.client.allocator);
            return err;
        };
        return self.processEventDelivery(failure_policy, .{
            .session_id = owned_session_id,
            .event = event,
        });
    }

    pub fn capabilities(self: Session) ext.CapabilitySet {
        const resolved = self.resolve() catch return .{};
        const runtime = self.client.findExtensionRuntime(resolved.id) orelse return .{};
        return runtime.capabilities;
    }

    pub fn ui(self: Session) SessionUi {
        return .{ .session = self };
    }

    pub fn workspacePath(self: Session) !?[]const u8 {
        const resolved = try self.resolve();
        return self.client.sessions.items[resolved.record_index].workspace_path;
    }

    pub fn experimental(
        self: Session,
        comptime feature: ext.ExperimentalFeature,
    ) !switch (feature) {
        .mcp_apps => McpApps,
    } {
        const resolved = try self.resolve();
        return switch (feature) {
            .mcp_apps => blk: {
                const runtime = self.client.findExtensionRuntime(resolved.id) orelse
                    return error.UnsupportedCapability;
                if (!runtime.mcp_apps_requested)
                    return error.ExperimentalFeatureNotRequested;
                if (!runtime.capabilities.supports(.mcp_apps))
                    return error.UnsupportedCapability;
                break :blk .{ .session = self };
            },
        };
    }

    pub fn openCanvas(
        self: Session,
        allocator: std.mem.Allocator,
        request: ext.OpenCanvasRequest,
    ) !ext.OpenCanvasResult {
        const resolved = try self.resolve();
        const owned_session_id = try self.client.allocator.dupe(u8, resolved.id);
        defer self.client.allocator.free(owned_session_id);
        const supports_canvases = if (self.client.findExtensionRuntime(owned_session_id)) |runtime|
            runtime.capabilities.supports(.canvases)
        else
            return error.UnsupportedCapability;
        if (!supports_canvases) return error.UnsupportedCapability;
        const input = if (request.input_json) |json|
            try std.json.parseFromSlice(std.json.Value, self.client.allocator, json, .{})
        else
            null;
        defer if (input) |value| value.deinit();
        const parsed = try self.client.call(WireOpenCanvas, "session.canvas.open", .{
            .sessionId = owned_session_id,
            .extensionId = request.extension_id,
            .canvasId = request.canvas_id,
            .instanceId = request.instance_id,
            .input = if (input) |value| value.value else null,
        });
        defer parsed.deinit();
        const runtime = self.client.findExtensionRuntime(owned_session_id) orelse
            return error.MissingExtensionRuntime;
        const state_value = try cloneWireOpenCanvas(self.client.allocator, parsed.value);
        upsertOpenCanvas(runtime, self.client.allocator, state_value) catch |err| {
            ext.freeOpenCanvas(self.client.allocator, state_value);
            return err;
        };
        return .{
            .allocator = allocator,
            .value = try cloneWireOpenCanvas(allocator, parsed.value),
        };
    }

    pub fn closeCanvas(self: Session, instance_id: []const u8) !void {
        const resolved = try self.resolve();
        const owned_session_id = try self.client.allocator.dupe(u8, resolved.id);
        defer self.client.allocator.free(owned_session_id);
        const supports_canvases = if (self.client.findExtensionRuntime(owned_session_id)) |runtime|
            runtime.capabilities.supports(.canvases)
        else
            return error.UnsupportedCapability;
        if (!supports_canvases) return error.UnsupportedCapability;
        const parsed = try self.client.call(std.json.Value, "session.canvas.close", .{
            .sessionId = owned_session_id,
            .instanceId = instance_id,
        });
        parsed.deinit();
        const runtime = self.client.findExtensionRuntime(owned_session_id) orelse
            return error.MissingExtensionRuntime;
        removeOpenCanvas(runtime, self.client.allocator, instance_id);
    }

    pub fn invokeCanvasAction(
        self: Session,
        allocator: std.mem.Allocator,
        request: ext.InvokeCanvasActionRequest,
    ) !ext.OwnedJson {
        const resolved = try self.resolve();
        const runtime = self.client.findExtensionRuntime(resolved.id) orelse
            return error.UnsupportedCapability;
        if (!runtime.capabilities.supports(.canvases))
            return error.UnsupportedCapability;
        const input = if (request.input_json) |json|
            try std.json.parseFromSlice(std.json.Value, self.client.allocator, json, .{})
        else
            null;
        defer if (input) |value| value.deinit();
        const parsed = try self.client.call(std.json.Value, "session.canvas.action.invoke", .{
            .sessionId = resolved.id,
            .instanceId = request.instance_id,
            .actionName = request.action_name,
            .input = if (input) |value| value.value else null,
        });
        defer parsed.deinit();
        return .{
            .allocator = allocator,
            .json = try std.json.Stringify.valueAlloc(allocator, parsed.value, .{}),
        };
    }

    pub fn snapshotOpenCanvases(
        self: Session,
        allocator: std.mem.Allocator,
    ) !ext.OpenCanvasSnapshot {
        const resolved = try self.resolve();
        const runtime = self.client.findExtensionRuntime(resolved.id) orelse
            return .{ .allocator = allocator, .items = try allocator.alloc(ext.OpenCanvas, 0) };
        const items = try allocator.alloc(ext.OpenCanvas, runtime.open_canvases.items.len);
        var initialized: usize = 0;
        errdefer {
            for (items[0..initialized]) |item| ext.freeOpenCanvas(allocator, item);
            allocator.free(items);
        }
        for (runtime.open_canvases.items, 0..) |item, index| {
            items[index] = try cloneOpenCanvas(allocator, item);
            initialized += 1;
        }
        return .{ .allocator = allocator, .items = items };
    }

    pub fn snapshotEnvironmentGrants(
        self: Session,
        allocator: std.mem.Allocator,
    ) !ext.EnvironmentGrants {
        const resolved = try self.resolve();
        const runtime = self.client.findExtensionRuntime(resolved.id) orelse return .{
            .allocator = allocator,
            .items = try allocator.alloc(ext.EnvironmentGrant, 0),
        };
        const items = try allocator.alloc(
            ext.EnvironmentGrant,
            runtime.granted_environment_variables.items.len,
        );
        var initialized: usize = 0;
        errdefer {
            for (items[0..initialized]) |item| {
                allocator.free(item.name);
                wipeSecret(item.value);
                allocator.free(item.value);
            }
            allocator.free(items);
        }
        for (runtime.granted_environment_variables.items, 0..) |grant, index| {
            const name = try allocator.dupe(u8, grant.name);
            errdefer allocator.free(name);
            items[index] = .{
                .name = name,
                .value = try allocator.dupe(u8, grant.value),
            };
            initialized += 1;
        }
        return .{ .allocator = allocator, .items = items };
    }

    fn handleMcpAuthEvent(
        self: Session,
        session_id: []const u8,
        data_json: []const u8,
    ) !void {
        _ = try self.resolve();
        const runtime = self.client.findExtensionRuntime(session_id) orelse return;
        const handler = runtime.mcp_auth_handler orelse return;
        const parsed = try std.json.parseFromSlice(
            WireMcpAuthRequest,
            self.client.allocator,
            data_json,
            .{ .allocate = .alloc_always, .ignore_unknown_fields = true },
        );
        defer {
            wipeSecret(parsed.value.requestId);
            wipeSecret(parsed.value.serverName);
            wipeSecret(parsed.value.serverUrl);
            if (parsed.value.resourceMetadata) |value| wipeSecret(value);
            if (parsed.value.wwwAuthenticateParams) |value| wipeJsonStrings(value);
            if (parsed.value.httpResponse) |value| wipeJsonStrings(value);
            if (parsed.value.staticClientConfig) |value| wipeJsonStrings(value);
            parsed.deinit();
        }
        const www_json = if (parsed.value.wwwAuthenticateParams) |value|
            try std.json.Stringify.valueAlloc(self.client.allocator, value, .{})
        else
            null;
        defer if (www_json) |value| {
            wipeSecret(value);
            self.client.allocator.free(value);
        };
        const http_json = if (parsed.value.httpResponse) |value|
            try std.json.Stringify.valueAlloc(self.client.allocator, value, .{})
        else
            null;
        defer if (http_json) |value| {
            wipeSecret(value);
            self.client.allocator.free(value);
        };
        const static_json = if (parsed.value.staticClientConfig) |value|
            try std.json.Stringify.valueAlloc(self.client.allocator, value, .{})
        else
            null;
        defer if (static_json) |value| {
            wipeSecret(value);
            self.client.allocator.free(value);
        };
        var outcome = invokeMcpAuthHandler(handler, self.client.allocator, .{
            .request_id = parsed.value.requestId,
            .server_name = parsed.value.serverName,
            .server_url = parsed.value.serverUrl,
            .reason = parsed.value.reason,
            .resource_metadata = parsed.value.resourceMetadata,
            .www_authenticate_json = www_json,
            .http_response_json = http_json,
            .static_client_config_json = static_json,
        }, runtime.mcp_auth_context);
        const response = switch (outcome.result) {
            .cancelled => self.client.call(
                RpcSuccess,
                "session.mcp.oauth.handlePendingRequest",
                .{
                    .sessionId = session_id,
                    .requestId = parsed.value.requestId,
                    .result = .{ .kind = "cancelled" },
                },
            ),
            .token => |*token| blk: {
                defer token.deinitSecure(self.client.allocator);
                if (token.expires_in_seconds) |expires_in_seconds| {
                    if (expires_in_seconds == 0) {
                        outcome.handler_error = error.InvalidMcpAuthTokenExpiration;
                        break :blk self.client.call(
                            RpcSuccess,
                            "session.mcp.oauth.handlePendingRequest",
                            .{
                                .sessionId = session_id,
                                .requestId = parsed.value.requestId,
                                .result = .{ .kind = "cancelled" },
                            },
                        );
                    }
                }
                break :blk self.client.call(
                    RpcSuccess,
                    "session.mcp.oauth.handlePendingRequest",
                    .{
                        .sessionId = session_id,
                        .requestId = parsed.value.requestId,
                        .result = .{
                            .kind = "token",
                            .accessToken = token.access_token,
                            .tokenType = token.token_type,
                            .expiresIn = token.expires_in_seconds,
                        },
                    },
                );
            },
        };
        const accepted = try response;
        defer accepted.deinit();
        if (!accepted.value.success) return error.McpAuthNotAccepted;
        if (outcome.handler_error) |handler_error| return handler_error;
    }

    pub fn disconnect(self: Session) !void {
        return legacyResult(void, self.disconnectImpl(.legacy));
