    fn respondToToolResultJsonImpl(
        self: Session,
        comptime failure_policy: FailurePolicy,
        request_id: []const u8,
        result_json: []const u8,
    ) errors.DetailedError!PolicyResult(failure_policy, void) {
        var ingress_lease = switch (try self.acquireIngressForPolicy(failure_policy)) {
            .success => |value| value,
            .failure => |failure| return .{ .failure = failure },
        };
        defer {
            self.client.finishSessionIngress(ingress_lease.log);
            ingress_lease.deinit();
        }
        const resolved = ResolvedSession{
            .record_index = self.record_index,
            .id = ingress_lease.log.session_id,
        };
        const result = std.json.parseFromSlice(
            std.json.Value,
            self.client.allocator,
            result_json,
            .{},
        ) catch |err| {
            if (err == error.OutOfMemory) return error.OutOfMemory;
            return .{ .failure = try policyFailure(
                failure_policy,
                err,
                recordInvalidToolResult,
                .{ self.client.allocator, resolved.id, request_id, err },
            ) };
        };
        defer result.deinit();
        const object = switch (result.value) {
            .object => |object| object,
            else => return .{ .failure = try policyFailure(
                failure_policy,
                error.InvalidToolResult,
                recordInvalidToolResult,
                .{ self.client.allocator, resolved.id, request_id, error.InvalidToolResult },
            ) },
        };
        const text = object.get("textResultForLlm") orelse
            return .{ .failure = try policyFailure(
                failure_policy,
                error.InvalidToolResult,
                recordInvalidToolResult,
                .{ self.client.allocator, resolved.id, request_id, error.InvalidToolResult },
            ) };
        if (text != .string)
            return .{ .failure = try policyFailure(
                failure_policy,
                error.InvalidToolResult,
                recordInvalidToolResult,
                .{ self.client.allocator, resolved.id, request_id, error.InvalidToolResult },
            ) };

        const parsed = switch (try self.client.callImpl(
            failure_policy,
            struct { success: bool },
            "session.tools.handlePendingToolCall",
            .{
                .sessionId = resolved.id,
                .requestId = request_id,
                .result = result.value,
            },
            .{ .tool = .{
                .session_id = resolved.id,
                .request_id = request_id,
            } },
        )) {
            .success => |value| value,
            .failure => |failure| return .{ .failure = failure },
        };
        defer parsed.deinit();
        if (!parsed.value.success)
            return .{ .failure = try policyFailure(
                failure_policy,
                error.ToolResultNotAccepted,
                recordToolNotAccepted,
                .{ self.client.allocator, resolved.id, request_id },
            ) };
        return .{ .success = {} };
    }

    pub fn respondToToolError(
        self: Session,
        request_id: []const u8,
        message: []const u8,
    ) !void {
        return legacyResult(void, self.respondToToolErrorImpl(
            .legacy,
            request_id,
            message,
            null,
            null,
        ));
    }

    pub fn respondToToolErrorDetailed(
        self: Session,
        request_id: []const u8,
        message: []const u8,
    ) errors.DetailedError!errors.DetailedResult(void) {
        return self.respondToToolErrorImpl(.detailed, request_id, message, null, null);
    }

    fn respondToToolErrorImpl(
        self: Session,
        comptime failure_policy: FailurePolicy,
        request_id: []const u8,
        message: []const u8,
        tool_call_id: ?[]const u8,
        tool_name: ?[]const u8,
    ) errors.DetailedError!PolicyResult(failure_policy, void) {
        var ingress_lease = switch (try self.acquireIngressForPolicy(failure_policy)) {
            .success => |value| value,
            .failure => |failure| return .{ .failure = failure },
        };
        defer {
            self.client.finishSessionIngress(ingress_lease.log);
            ingress_lease.deinit();
        }
        const resolved = ResolvedSession{
            .record_index = self.record_index,
            .id = ingress_lease.log.session_id,
        };
        const parsed = switch (try self.client.callImpl(failure_policy, struct { success: bool }, "session.tools.handlePendingToolCall", .{
            .sessionId = resolved.id,
            .requestId = request_id,
            .@"error" = message,
        }, .{ .tool = .{
            .session_id = resolved.id,
            .request_id = request_id,
            .tool_call_id = tool_call_id,
            .tool_name = tool_name,
        } })) {
            .success => |value| value,
            .failure => |failure| return .{ .failure = failure },
        };
        defer parsed.deinit();
        if (!parsed.value.success)
            return .{ .failure = try policyFailure(
                failure_policy,
                error.ToolResultNotAccepted,
                recordToolNotAccepted,
                .{ self.client.allocator, resolved.id, request_id },
            ) };
        return .{ .success = {} };
    }
};

pub const FactoryApi = factory_types.FactoryApi(Session);

pub const JoinedSession = struct {
    session: Session,
    grants: ext.EnvironmentGrants,

    pub fn deinit(self: *JoinedSession) void {
        self.grants.deinit();
        self.* = undefined;
    }
};

pub const SessionUi = struct {
    session: Session,

    pub fn elicitation(
        self: SessionUi,
        params: session_types.UiElicitationParams,
    ) !session_types.UiElicitationResult {
        const schema = try std.json.parseFromSlice(
            std.json.Value,
            self.session.client.allocator,
            params.requested_schema_json,
            .{},
        );
        defer schema.deinit();
        if (schema.value != .object) return error.InvalidElicitationSchema;
        var result = try self.elicitationValue(params.message, schema.value);
        defer result.deinit();
        return .{
            .allocator = self.session.client.allocator,
            .action = result.action,
            .content_json = if (result.content) |content|
                try stringifyJsonValue(self.session.client.allocator, content)
            else
                null,
        };
    }

    pub fn confirm(self: SessionUi, message: []const u8) !bool {
        var schema: std.json.ObjectMap = .empty;
        defer schema.deinit(self.session.client.allocator);
        var properties: std.json.ObjectMap = .empty;
        defer properties.deinit(self.session.client.allocator);
        var confirmed: std.json.ObjectMap = .empty;
        defer confirmed.deinit(self.session.client.allocator);
        try confirmed.put(self.session.client.allocator, "type", .{ .string = "boolean" });
        try confirmed.put(self.session.client.allocator, "default", .{ .bool = true });
        try properties.put(self.session.client.allocator, "confirmed", .{ .object = confirmed });
        try schema.put(self.session.client.allocator, "type", .{ .string = "object" });
        try schema.put(self.session.client.allocator, "properties", .{ .object = properties });
        var required = std.json.Array.init(self.session.client.allocator);
        defer required.deinit();
        try required.append(.{ .string = "confirmed" });
        try schema.put(self.session.client.allocator, "required", .{ .array = required });
        var result = try self.elicitationValue(message, .{ .object = schema });
        defer result.deinit();
        if (result.action != .accept) return false;
        const content = result.content orelse return error.InvalidElicitationResult;
        const object = switch (content) {
            .object => |object| object,
            else => return error.InvalidElicitationResult,
        };
        return switch (object.get("confirmed") orelse return error.InvalidElicitationResult) {
            .bool => |value| value,
            else => error.InvalidElicitationResult,
        };
    }

    pub fn select(
        self: SessionUi,
        message: []const u8,
        options: []const []const u8,
    ) !?[]u8 {
        var schema: std.json.ObjectMap = .empty;
        defer schema.deinit(self.session.client.allocator);
        var properties: std.json.ObjectMap = .empty;
        defer properties.deinit(self.session.client.allocator);
        var selection: std.json.ObjectMap = .empty;
        defer selection.deinit(self.session.client.allocator);
        try selection.put(self.session.client.allocator, "type", .{ .string = "string" });
        var choices = std.json.Array.init(self.session.client.allocator);
        defer choices.deinit();
        for (options) |option| try choices.append(.{ .string = option });
        try selection.put(self.session.client.allocator, "enum", .{ .array = choices });
        try properties.put(self.session.client.allocator, "selection", .{ .object = selection });
        try schema.put(self.session.client.allocator, "type", .{ .string = "object" });
        try schema.put(self.session.client.allocator, "properties", .{ .object = properties });
        var required = std.json.Array.init(self.session.client.allocator);
        defer required.deinit();
        try required.append(.{ .string = "selection" });
        try schema.put(self.session.client.allocator, "required", .{ .array = required });

        var result = try self.elicitationValue(message, .{ .object = schema });
        defer result.deinit();
        if (result.action != .accept) return null;
        const selected = try elicitationStringField(
            self.session.client.allocator,
            result.content,
            "selection",
        );
        errdefer {
            wipeSecret(selected);
            self.session.client.allocator.free(selected);
        }
        for (options) |option| {
            if (std.mem.eql(u8, selected, option)) return selected;
        }
        return error.InvalidElicitationResult;
    }

    pub fn input(
        self: SessionUi,
        message: []const u8,
        options: session_types.UiInputOptions,
    ) !?[]u8 {
        if (options.min_length != null and options.max_length != null and
            options.min_length.? > options.max_length.?)
        {
            return error.InvalidElicitationSchema;
        }
        if (options.default) |value| {
            if (!uiInputValueIsValid(value, options))
                return error.InvalidElicitationSchema;
        }
        var schema: std.json.ObjectMap = .empty;
        defer schema.deinit(self.session.client.allocator);
        var properties: std.json.ObjectMap = .empty;
        defer properties.deinit(self.session.client.allocator);
        var field: std.json.ObjectMap = .empty;
        defer field.deinit(self.session.client.allocator);
        try field.put(self.session.client.allocator, "type", .{ .string = "string" });
        if (options.title) |value| try field.put(
            self.session.client.allocator,
            "title",
            .{ .string = value },
        );
        if (options.description) |value| try field.put(
            self.session.client.allocator,
            "description",
            .{ .string = value },
        );
        if (options.min_length) |value| try field.put(
            self.session.client.allocator,
            "minLength",
            .{ .integer = std.math.cast(i64, value) orelse
                return error.InvalidElicitationSchema },
        );
        if (options.max_length) |value| try field.put(
            self.session.client.allocator,
            "maxLength",
            .{ .integer = std.math.cast(i64, value) orelse
                return error.InvalidElicitationSchema },
        );
        if (options.format) |value| try field.put(
            self.session.client.allocator,
            "format",
            .{ .string = @tagName(value) },
        );
        if (options.default) |value| try field.put(
            self.session.client.allocator,
            "default",
            .{ .string = value },
        );
        try properties.put(self.session.client.allocator, "value", .{ .object = field });
        try schema.put(self.session.client.allocator, "type", .{ .string = "object" });
        try schema.put(self.session.client.allocator, "properties", .{ .object = properties });
        var required = std.json.Array.init(self.session.client.allocator);
        defer required.deinit();
        try required.append(.{ .string = "value" });
        try schema.put(self.session.client.allocator, "required", .{ .array = required });

        var result = try self.elicitationValue(message, .{ .object = schema });
        defer result.deinit();
        if (result.action != .accept) return null;
        const value = try elicitationStringField(
            self.session.client.allocator,
            result.content,
            "value",
        );
        errdefer {
            wipeSecret(value);
            self.session.client.allocator.free(value);
        }
        if (!uiInputValueIsValid(value, options))
            return error.InvalidElicitationResult;
        return value;
    }

    fn elicitationValue(
        self: SessionUi,
        message: []const u8,
        requested_schema: std.json.Value,
    ) !OwnedUiElicitationResult {
        const resolved = try self.session.resolve();
        const runtime = self.session.client.findExtensionRuntime(resolved.id) orelse
            return error.UnsupportedCapability;
        if (!runtime.capabilities.supports(.elicitation))
            return error.UnsupportedCapability;
        var parsed = switch (try self.session.client.callImpl(
            .legacy,
            std.json.Value,
            "session.ui.elicitation",
            .{
                .sessionId = resolved.id,
                .message = message,
                .requestedSchema = requested_schema,
            },
            .{ .session = .{ .session_id = resolved.id } },
        )) {
            .success => |value| value,
            .failure => |failure| return failure.native_error,
        };
        errdefer {
            wipeJsonStrings(parsed.value);
            parsed.deinit();
        }
        const object = switch (parsed.value) {
            .object => |value| value,
            else => return error.InvalidElicitationResult,
        };
        const action_string = jsonRequiredString(object, "action") catch
            return error.InvalidElicitationResult;
        const action = std.meta.stringToEnum(
            session_types.ElicitationAction,
            action_string,
        ) orelse return error.InvalidElicitationResult;
        const content = if (object.get("content")) |content| blk: {
            if (!isValidElicitationContent(content))
                return error.InvalidElicitationResult;
            break :blk content;
        } else null;
        return .{
            .response = parsed,
            .action = action,
            .content = content,
        };
    }
};

const OwnedUiElicitationResult = struct {
    response: std.json.Parsed(std.json.Value),
    action: session_types.ElicitationAction,
    content: ?std.json.Value,

    fn deinit(self: *OwnedUiElicitationResult) void {
        wipeJsonStrings(self.response.value);
        self.response.deinit();
        self.* = undefined;
    }
};

fn elicitationStringField(
    allocator: std.mem.Allocator,
    content: ?std.json.Value,
    name: []const u8,
) ![]u8 {
    const content_value = content orelse return error.InvalidElicitationResult;
    const object = switch (content_value) {
        .object => |value| value,
        else => return error.InvalidElicitationResult,
    };
    const value = jsonRequiredString(object, name) catch
        return error.InvalidElicitationResult;
    return allocator.dupe(u8, value);
}

fn uiInputValueIsValid(
    value: []const u8,
    options: session_types.UiInputOptions,
) bool {
    const length = std.unicode.utf8CountCodepoints(value) catch return false;
    if (options.min_length) |minimum| {
        if (length < minimum) return false;
    }
    if (options.max_length) |maximum| {
        if (length > maximum) return false;
    }
    const format = options.format orelse return true;
    return switch (format) {
        .email => isValidEmail(value),
        .uri => isValidUri(value),
        .date => isValidDate(value),
        .@"date-time" => isValidDateTime(value),
    };
}

fn isValidEmail(value: []const u8) bool {
    if (value.len > 254) return false;
    const separator = std.mem.indexOfScalar(u8, value, '@') orelse return false;
    if (separator == 0 or separator + 1 == value.len) return false;
    if (std.mem.indexOfScalarPos(u8, value, separator + 1, '@') != null) return false;
    const local = value[0..separator];
    const domain = value[separator + 1 ..];
    if (local.len > 64 or domain.len > 253) return false;
    if (local[0] == '.' or local[local.len - 1] == '.' or
        domain[0] == '.' or domain[domain.len - 1] == '.' or
        std.mem.indexOf(u8, local, "..") != null or
        std.mem.indexOf(u8, domain, "..") != null)
    {
        return false;
    }
    for (local) |byte| {
        if (!isEmailAtomByte(byte) and byte != '.') return false;
    }
    var labels = std.mem.splitScalar(u8, domain, '.');
    while (labels.next()) |label| {
        if (label.len == 0 or label.len > 63 or
            !std.ascii.isAlphanumeric(label[0]) or
            !std.ascii.isAlphanumeric(label[label.len - 1]))
        {
            return false;
        }
        if (label.len > 2) {
            for (label[1 .. label.len - 1]) |byte| {
                if (!std.ascii.isAlphanumeric(byte) and byte != '-') return false;
            }
        }
    }
    return true;
}

fn isEmailAtomByte(byte: u8) bool {
    if (std.ascii.isAlphanumeric(byte)) return true;
    return switch (byte) {
        '!',
        '#',
        '$',
        '%',
        '&',
        '\'',
        '*',
        '+',
        '-',
        '/',
        '=',
        '?',
        '^',
        '_',
        '`',
        '{',
        '|',
        '}',
        '~',
        => true,
        else => false,
    };
}

fn isValidUri(value: []const u8) bool {
    const uri = std.Uri.parse(value) catch return false;
    return uri.scheme.len != 0;
}

fn isValidDate(value: []const u8) bool {
    if (value.len != 10 or value[4] != '-' or value[7] != '-') return false;
    const year = parseFixedDecimal(value[0..4]) orelse return false;
    const month = parseFixedDecimal(value[5..7]) orelse return false;
    const day = parseFixedDecimal(value[8..10]) orelse return false;
    if (month < 1 or month > 12 or day < 1) return false;
    return day <= uiDaysInMonth(year, month);
}

fn isValidDateTime(value: []const u8) bool {
    if (value.len < 20 or !isValidDate(value[0..10])) return false;
    if (value[10] != 'T' and value[10] != 't') return false;
    if (value[13] != ':' or value[16] != ':') return false;
    const hour = parseFixedDecimal(value[11..13]) orelse return false;
    const minute = parseFixedDecimal(value[14..16]) orelse return false;
    const second = parseFixedDecimal(value[17..19]) orelse return false;
    if (hour > 23 or minute > 59 or second > 60) return false;
    var index: usize = 19;
    if (index < value.len and value[index] == '.') {
        index += 1;
        const fraction_start = index;
        while (index < value.len and std.ascii.isDigit(value[index])) : (index += 1) {}
        if (index == fraction_start) return false;
    }
    var offset_minutes: i32 = 0;
    if (index == value.len - 1 and (value[index] == 'Z' or value[index] == 'z')) {
        return second != 60 or isValidLeapSecond(value, hour, minute, offset_minutes);
    }
    if (index + 6 != value.len or
        (value[index] != '+' and value[index] != '-') or
        value[index + 3] != ':')
    {
        return false;
    }
    const offset_hour = parseFixedDecimal(value[index + 1 .. index + 3]) orelse return false;
    const offset_minute = parseFixedDecimal(value[index + 4 .. index + 6]) orelse return false;
    if (offset_hour > 23 or offset_minute > 59) return false;
    offset_minutes = @as(i32, offset_hour) * 60 + offset_minute;
    if (value[index] == '-') offset_minutes = -offset_minutes;
    return second != 60 or isValidLeapSecond(value, hour, minute, offset_minutes);
}

fn parseFixedDecimal(value: []const u8) ?u16 {
    var result: u16 = 0;
    for (value) |byte| {
        if (!std.ascii.isDigit(byte)) return null;
        result = result * 10 + (byte - '0');
    }
    return result;
}

fn uiDaysInMonth(year: u16, month: u16) u16 {
    const leap = @mod(year, 4) == 0 and
        (@mod(year, 100) != 0 or @mod(year, 400) == 0);
    const month_lengths = [_]u8{
        31, if (leap) 29 else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31,
    };
    return month_lengths[month - 1];
}

fn isValidLeapSecond(
    value: []const u8,
    hour: u16,
    minute: u16,
    offset_minutes: i32,
) bool {
    var year = parseFixedDecimal(value[0..4]) orelse return false;
    var month = parseFixedDecimal(value[5..7]) orelse return false;
    var day = parseFixedDecimal(value[8..10]) orelse return false;
    var utc_minute = @as(i32, hour) * 60 + minute - offset_minutes;
    if (utc_minute < 0) {
        utc_minute += 24 * 60;
        if (day > 1) {
            day -= 1;
        } else if (month > 1) {
            month -= 1;
            day = uiDaysInMonth(year, month);
        } else {
            if (year == 0) return false;
            year -= 1;
            month = 12;
            day = 31;
        }
    } else if (utc_minute >= 24 * 60) {
        utc_minute -= 24 * 60;
        if (day < uiDaysInMonth(year, month)) {
            day += 1;
        } else if (month < 12) {
            month += 1;
            day = 1;
        } else {
            if (year == 9999) return false;
            year += 1;
            month = 1;
            day = 1;
        }
    }
    return utc_minute == 23 * 60 + 59 and
        ((month == 6 and day == 30) or (month == 12 and day == 31));
}

test "UI input validation enforces lengths and every supported format" {
    try std.testing.expect(uiInputValueIsValid("42", .{}));
    try std.testing.expect(uiInputValueIsValid("é", .{
        .min_length = 1,
        .max_length = 1,
    }));
    try std.testing.expect(!uiInputValueIsValid("é", .{ .max_length = 0 }));
    try std.testing.expect(uiInputValueIsValid("user@example.com", .{ .format = .email }));
    try std.testing.expect(!uiInputValueIsValid("not-an-email", .{ .format = .email }));
    try std.testing.expect(!uiInputValueIsValid("a..b@example.com", .{ .format = .email }));
    try std.testing.expect(!uiInputValueIsValid("a@-", .{ .format = .email }));
    try std.testing.expect(!uiInputValueIsValid("a@foo-.com", .{ .format = .email }));
    try std.testing.expect(!uiInputValueIsValid("a(b)@example.com", .{ .format = .email }));
    try std.testing.expect(!uiInputValueIsValid("a,b@example.com", .{ .format = .email }));
    try std.testing.expect(!uiInputValueIsValid("\"a\"@example.com", .{ .format = .email }));
    try std.testing.expect(!uiInputValueIsValid("ü@example.com", .{ .format = .email }));
    try std.testing.expect(!uiInputValueIsValid("a@exämple.com", .{ .format = .email }));
    const max_local = ([_]u8{'a'} ** 64) ++ "@example.com";
    const oversized_local = ([_]u8{'a'} ** 65) ++ "@example.com";
    try std.testing.expect(uiInputValueIsValid(max_local[0..], .{ .format = .email }));
    try std.testing.expect(!uiInputValueIsValid(oversized_local[0..], .{ .format = .email }));
    const max_label = "a@" ++ ([_]u8{'b'} ** 63) ++ ".com";
    const oversized_label = "a@" ++ ([_]u8{'b'} ** 64) ++ ".com";
    try std.testing.expect(uiInputValueIsValid(max_label[0..], .{ .format = .email }));
    try std.testing.expect(!uiInputValueIsValid(oversized_label[0..], .{ .format = .email }));
    const max_address =
        ([_]u8{'a'} ** 64) ++ "@" ++
        ([_]u8{'b'} ** 63) ++ "." ++
        ([_]u8{'c'} ** 63) ++ "." ++
        ([_]u8{'d'} ** 61);
    const oversized_address = max_address ++ "d";
    try std.testing.expectEqual(@as(usize, 254), max_address.len);
    try std.testing.expect(uiInputValueIsValid(max_address[0..], .{ .format = .email }));
    try std.testing.expect(!uiInputValueIsValid(oversized_address[0..], .{ .format = .email }));
    try std.testing.expect(uiInputValueIsValid(
        "https://127.0.0.1:8080/path",
        .{ .format = .uri },
    ));
    try std.testing.expect(!uiInputValueIsValid(
        "example.com/path",
        .{ .format = .uri },
    ));
    try std.testing.expect(uiInputValueIsValid("2024-02-29", .{ .format = .date }));
    try std.testing.expect(!uiInputValueIsValid("2023-02-29", .{ .format = .date }));
    try std.testing.expect(uiInputValueIsValid(
        "2024-07-01T01:59:60.5+02:00",
        .{ .format = .@"date-time" },
    ));
    try std.testing.expect(!uiInputValueIsValid(
        "2024-02-29 23:59:59",
        .{ .format = .@"date-time" },
    ));
    try std.testing.expect(!uiInputValueIsValid(
        "2024-01-15T12:34:60Z",
        .{ .format = .@"date-time" },
    ));
}

test "session UI lowers confirm select and input exactly" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const response_bodies = [_][]const u8{
        \\{"jsonrpc":"2.0","id":1,"result":{"action":"accept","content":{"confirmed":true}}}
        ,
        \\{"jsonrpc":"2.0","id":2,"result":{"action":"accept","content":{"selection":"two"}}}
        ,
        \\{"jsonrpc":"2.0","id":3,"result":{"action":"accept","content":{"value":"hello@example.com"}}}
        ,
    };
    var response_bytes: std.Io.Writer.Allocating = .init(allocator);
    defer response_bytes.deinit();
    for (response_bodies) |body| {
        try response_bytes.writer.print("Content-Length: {d}\r\n\r\n{s}", .{ body.len, body });
    }
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "responses",
        .data = response_bytes.written(),
    });
    const response_file = try tmp.dir.openFile(
        std.testing.io,
        "responses",
        .{ .mode = .read_only },
    );
    defer response_file.close(std.testing.io);
    var reader_buffer: [4096]u8 = undefined;
    var reader = response_file.readerStreaming(std.testing.io, &reader_buffer);

    const request_file = try tmp.dir.createFile(std.testing.io, "requests", .{});
    defer request_file.close(std.testing.io);
    var writer_buffer: [8192]u8 = undefined;
    var writer = request_file.writer(std.testing.io, &writer_buffer);

    var client = Client{
        .allocator = allocator,
        .io = std.testing.io,
        .child = null,
        .reader = &reader,
        .writer = &writer,
        .reader_buffer = &.{},
        .writer_buffer = &.{},
    };
    defer {
        for (client.extension_runtimes.items) |*runtime| runtime.deinit(allocator);
        client.extension_runtimes.deinit(allocator);
        for (client.sessions.items) |*record| record.deinit(allocator);
        client.sessions.deinit(allocator);
    }
    var runtime = try SessionExtensionRuntime.init(
        allocator,
        "ui-session",
        session_types.CreateSessionConfig{},
        &.{},
    );
    runtime.capabilities.elicitation = .supported;
    try client.extension_runtimes.append(allocator, runtime);
    try client.beginSessionRecord(try allocator.dupe(u8, "ui-session"), null);
    const ui = client.sessionHandle(try client.commitSessionRecord()).ui();

    try std.testing.expect(try ui.confirm("Proceed?"));
    const selected = (try ui.select("Choose", &.{ "one", "two" })).?;
    defer allocator.free(selected);
    try std.testing.expectEqualStrings("two", selected);
    const input = (try ui.input("Value", .{
        .title = "Name",
        .description = "Enter a name",
        .min_length = 1,
        .max_length = 20,
        .format = .email,
        .default = "a@example.com",
    })).?;
    defer allocator.free(input);
    try std.testing.expectEqualStrings("hello@example.com", input);

    try writer.interface.flush();
    const requests = try tmp.dir.readFileAlloc(
        std.testing.io,
        "requests",
        allocator,
        .limited(64 * 1024),
    );
    defer allocator.free(requests);
    var request_reader = std.Io.Reader.fixed(requests);
    const confirm_body = try json_rpc.readFrame(allocator, &request_reader);
    defer allocator.free(confirm_body);
    const select_body = try json_rpc.readFrame(allocator, &request_reader);
    defer allocator.free(select_body);
    const input_body = try json_rpc.readFrame(allocator, &request_reader);
    defer allocator.free(input_body);

    try std.testing.expectEqualStrings(
        \\{"jsonrpc":"2.0","id":1,"method":"session.ui.elicitation","params":{"sessionId":"ui-session","message":"Proceed?","requestedSchema":{"type":"object","properties":{"confirmed":{"type":"boolean","default":true}},"required":["confirmed"]}}}
    , confirm_body);
    try std.testing.expectEqualStrings(
        \\{"jsonrpc":"2.0","id":2,"method":"session.ui.elicitation","params":{"sessionId":"ui-session","message":"Choose","requestedSchema":{"type":"object","properties":{"selection":{"type":"string","enum":["one","two"]}},"required":["selection"]}}}
    , select_body);
    try std.testing.expectEqualStrings(
        \\{"jsonrpc":"2.0","id":3,"method":"session.ui.elicitation","params":{"sessionId":"ui-session","message":"Value","requestedSchema":{"type":"object","properties":{"value":{"type":"string","title":"Name","description":"Enter a name","minLength":1,"maxLength":20,"format":"email","default":"a@example.com"}},"required":["value"]}}}
    , input_body);
}

test "session UI rejects invalid defaults and returned values" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const invalid_email_response =
        \\{"jsonrpc":"2.0","id":1,"result":{"action":"accept","content":{"value":"not-an-email"}}}
    ;
    const invalid_content_response =
        \\{"jsonrpc":"2.0","id":2,"result":{"action":"accept","content":{"value":{"nested":true}}}}
    ;
    const responses = try std.fmt.allocPrint(
        allocator,
        "Content-Length: {d}\r\n\r\n{s}Content-Length: {d}\r\n\r\n{s}",
        .{
            invalid_email_response.len,
            invalid_email_response,
            invalid_content_response.len,
            invalid_content_response,
        },
    );
    defer allocator.free(responses);
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "responses", .data = responses });
    const response_file = try tmp.dir.openFile(
        std.testing.io,
        "responses",
        .{ .mode = .read_only },
    );
    defer response_file.close(std.testing.io);
    var reader_buffer: [1024]u8 = undefined;
    var reader = response_file.readerStreaming(std.testing.io, &reader_buffer);
    const request_file = try tmp.dir.createFile(std.testing.io, "requests", .{});
    defer request_file.close(std.testing.io);
    var writer_buffer: [2048]u8 = undefined;
    var writer = request_file.writer(std.testing.io, &writer_buffer);
    var client = Client{
        .allocator = allocator,
        .io = std.testing.io,
        .child = null,
        .reader = &reader,
        .writer = &writer,
        .reader_buffer = &.{},
        .writer_buffer = &.{},
    };
    defer {
        for (client.extension_runtimes.items) |*runtime| runtime.deinit(allocator);
        client.extension_runtimes.deinit(allocator);
        for (client.sessions.items) |*record| record.deinit(allocator);
        client.sessions.deinit(allocator);
    }
    var runtime = try SessionExtensionRuntime.init(
        allocator,
        "ui-session",
        session_types.CreateSessionConfig{},
        &.{},
    );
    runtime.capabilities.elicitation = .supported;
    try client.extension_runtimes.append(allocator, runtime);
    try client.beginSessionRecord(try allocator.dupe(u8, "ui-session"), null);
    const ui = client.sessionHandle(try client.commitSessionRecord()).ui();

    try std.testing.expectError(
        error.InvalidElicitationSchema,
        ui.input("Email", .{
            .format = .email,
            .default = "not-an-email",
        }),
    );
    try std.testing.expectError(
        error.InvalidElicitationResult,
        ui.input("Email", .{ .format = .email }),
    );
    try std.testing.expectError(
        error.InvalidElicitationResult,
        ui.elicitation(.{
            .message = "Nested",
            .requested_schema_json =
            \\{"type":"object","properties":{"value":{"type":"string"}}}
            ,
        }),
    );

    try writer.interface.flush();
    const requests = try tmp.dir.readFileAlloc(
        std.testing.io,
        "requests",
        allocator,
        .limited(4096),
    );
    defer allocator.free(requests);
    var request_reader = std.Io.Reader.fixed(requests);
    const body = try json_rpc.readFrame(allocator, &request_reader);
    defer allocator.free(body);
    const nested_body = try json_rpc.readFrame(allocator, &request_reader);
    defer allocator.free(nested_body);
    try std.testing.expectEqualStrings(
        \\{"jsonrpc":"2.0","id":1,"method":"session.ui.elicitation","params":{"sessionId":"ui-session","message":"Email","requestedSchema":{"type":"object","properties":{"value":{"type":"string","format":"email"}},"required":["value"]}}}
    , body);
    try std.testing.expectEqualStrings(
        \\{"jsonrpc":"2.0","id":2,"method":"session.ui.elicitation","params":{"sessionId":"ui-session","message":"Nested","requestedSchema":{"type":"object","properties":{"value":{"type":"string"}}}}}
    , nested_body);
}

test "session UI handles are generation safe" {
    const allocator = std.testing.allocator;
    var client = Client{
        .allocator = allocator,
        .io = undefined,
    };
    defer {
        if (client.pending_session) |*pending| pending.deinit(allocator);
        for (client.sessions.items) |*record| record.deinit(allocator);
        client.sessions.deinit(allocator);
    }

    try client.beginSessionRecord(try allocator.dupe(u8, "session"), null);
    const first_index = try client.commitSessionRecord();
    const stale_ui = client.sessionHandle(first_index).ui();

    try client.beginSessionRecord(
        try allocator.dupe(u8, client.sessions.items[first_index].id.?),
        first_index,
    );
    _ = try client.commitSessionRecord();

    try std.testing.expectError(error.SessionNotActive, stale_ui.confirm("Proceed?"));
}

pub const McpApps = struct {
    session: Session,

    fn ensureSupported(self: McpApps) !ResolvedSession {
        const resolved = try self.session.resolve();
        const runtime = self.session.client.findExtensionRuntime(resolved.id) orelse
            return error.UnsupportedCapability;
        if (!runtime.mcp_apps_requested)
            return error.ExperimentalFeatureNotRequested;
        if (!runtime.capabilities.supports(.mcp_apps))
            return error.UnsupportedCapability;
        return resolved;
    }

    pub fn listTools(
        self: McpApps,
        allocator: std.mem.Allocator,
        server_name: []const u8,
        origin_server_name: []const u8,
    ) !ext.OwnedJson {
        const resolved = try self.ensureSupported();
        const parsed = try self.session.client.call(
            std.json.Value,
            "session.mcp.apps.listTools",
            .{
                .sessionId = resolved.id,
                .serverName = server_name,
                .originServerName = origin_server_name,
            },
        );
        defer parsed.deinit();
        return .{
            .allocator = allocator,
            .json = try std.json.Stringify.valueAlloc(allocator, parsed.value, .{}),
        };
    }

    pub fn callTool(
        self: McpApps,
        allocator: std.mem.Allocator,
        request: ext.McpAppToolCall,
    ) !ext.OwnedJson {
        const resolved = try self.ensureSupported();
        const arguments = try std.json.parseFromSlice(
            std.json.Value,
            self.session.client.allocator,
            request.arguments_json,
            .{},
        );
        defer arguments.deinit();
        if (arguments.value != .object) return error.InvalidMcpAppToolArguments;
        const parsed = try self.session.client.call(
            std.json.Value,
            "session.mcp.apps.callTool",
            .{
                .sessionId = resolved.id,
                .serverName = request.server_name,
                .toolName = request.tool_name,
                .arguments = arguments.value,
                .originServerName = request.origin_server_name,
            },
        );
        defer parsed.deinit();
        return .{
            .allocator = allocator,
            .json = try std.json.Stringify.valueAlloc(allocator, parsed.value, .{}),
        };
    }

    pub fn readResource(
        self: McpApps,
        allocator: std.mem.Allocator,
        server_name: []const u8,
        uri: []const u8,
    ) !ext.OwnedJson {
        const resolved = try self.ensureSupported();
        const parsed = try self.session.client.call(
            std.json.Value,
            "session.mcp.apps.readResource",
            .{
                .sessionId = resolved.id,
                .serverName = server_name,
                .uri = uri,
            },
        );
        defer parsed.deinit();
        return .{
            .allocator = allocator,
            .json = try std.json.Stringify.valueAlloc(allocator, parsed.value, .{}),
        };
    }
};

fn stringifyRpcParams(
    allocator: std.mem.Allocator,
    params: ?std.json.Value,
) !?[]u8 {
    const value = params orelse return null;
    return @as(?[]u8, try std.json.Stringify.valueAlloc(allocator, value, .{}));
}

const FilesystemError = struct {
    code: SessionFilesystemErrorCode,
    message: []const u8,
};

const SessionFilesystemErrorCode = enum {
    ENOENT,
    UNKNOWN,
};

const WireReadFileResult = struct {
    content: []const u8,
    @"error": ?FilesystemError = null,
};

const WireStatResult = struct {
    isFile: bool,
    isDirectory: bool,
    size: u64,
    mtime: []const u8,
    birthtime: []const u8,
    @"error": ?FilesystemError = null,
};

const WireReadDirectoryResult = struct {
    entries: []const []const u8,
    @"error": ?FilesystemError = null,
};

const WireFilesystemEntries = struct {
    entries: []const runtime_types.SessionFilesystemEntry,

    pub fn jsonStringify(self: WireFilesystemEntries, writer: anytype) !void {
        try writer.beginObject();
        try writer.objectField("entries");
        try writer.beginArray();
        for (self.entries) |entry| {
            try writer.write(.{
                .name = entry.name,
                .type = @tagName(entry.entry_type),
            });
        }
        try writer.endArray();
        try writer.endObject();
    }
};

const WireSqliteQueryResult = struct {
    value: runtime_types.SessionFilesystemSqliteQueryResult,

    pub fn jsonStringify(self: WireSqliteQueryResult, writer: anytype) !void {
        try writer.beginObject();
        try writer.objectField("columns");
        try writer.write(self.value.columns);
        try writer.objectField("rows");
        try writer.write(self.value.rows);
        try writer.objectField("rowsAffected");
        try writer.write(self.value.rows_affected);
        if (self.value.last_insert_rowid) |row_id| {
            try writer.objectField("lastInsertRowid");
            try writer.write(row_id);
        }
        try writer.endObject();
    }
};

const WireSqliteTransactionResult = struct {
    value: runtime_types.SessionFilesystemSqliteTransactionResult,

    pub fn jsonStringify(self: WireSqliteTransactionResult, writer: anytype) !void {
        try writer.beginObject();
        try writer.objectField("results");
        try writer.beginArray();
        for (self.value.results) |result| {
            try writer.write(WireSqliteQueryResult{ .value = result });
        }
        try writer.endArray();
        if (self.value.@"error") |failure| {
            try writer.objectField("error");
            try writer.write(.{
                .errorClass = @tagName(failure.error_class),
                .message = failure.message,
            });
        }
        try writer.endObject();
    }
};

fn filesystemError(err: anyerror) FilesystemError {
    return .{
        .code = if (err == error.FileNotFound) .ENOENT else .UNKNOWN,
        .message = @errorName(err),
    };
}

fn validateObjectFields(
    object: std.json.ObjectMap,
    allowed_fields: []const []const u8,
) !void {
    var iterator = object.iterator();
    while (iterator.next()) |entry| {
        var allowed = false;
        for (allowed_fields) |field| {
            if (std.mem.eql(u8, entry.key_ptr.*, field)) {
                allowed = true;
                break;
            }
        }
        if (!allowed) return error.InvalidField;
    }
}

fn jsonOptionalU32(object: std.json.ObjectMap, name: []const u8) !?u32 {
    return switch (object.get(name) orelse return null) {
        .integer => |value| std.math.cast(u32, value) orelse error.InvalidField,
        else => error.InvalidField,
    };
}

fn jsonOptionalNonNullBool(object: std.json.ObjectMap, name: []const u8) !?bool {
    return switch (object.get(name) orelse return null) {
        .bool => |value| value,
        else => error.InvalidField,
    };
}

fn parseSqliteQueryType(value: ?std.json.Value) !runtime_types.SessionFilesystemSqliteQueryType {
    const string = switch (value orelse return error.MissingField) {
        .string => |item| item,
        else => return error.InvalidField,
    };
    return std.meta.stringToEnum(
        runtime_types.SessionFilesystemSqliteQueryType,
        string,
    ) orelse error.InvalidField;
}

test "session filesystem enums use pinned wire values" {
    try std.testing.expectEqualStrings(
        "posix",
        @tagName(runtime_types.SessionFilesystemConventions.posix),
    );
    try std.testing.expectEqualStrings(
        "directory",
        @tagName(runtime_types.SessionFilesystemEntryType.directory),
    );
    try std.testing.expectEqual(
        runtime_types.SessionFilesystemSqliteQueryType.exec,
        try parseSqliteQueryType(.{ .string = "exec" }),
    );
    try std.testing.expectEqual(
        runtime_types.SessionFilesystemSqliteQueryType.query,
        try parseSqliteQueryType(.{ .string = "query" }),
    );
    try std.testing.expectEqual(
        runtime_types.SessionFilesystemSqliteQueryType.run,
        try parseSqliteQueryType(.{ .string = "run" }),
    );

    const allocator = std.testing.allocator;
    const transaction_json = try std.json.Stringify.valueAlloc(
        allocator,
        WireSqliteTransactionResult{ .value = .{
            .@"error" = .{
                .error_class = .postCommitAmbiguous,
                .message = "unknown commit state",
            },
        } },
        .{},
    );
    defer allocator.free(transaction_json);
    try std.testing.expect(std.mem.indexOf(
        u8,
        transaction_json,
        "\"errorClass\":\"postCommitAmbiguous\"",
    ) != null);

    const filesystem_error_json = try std.json.Stringify.valueAlloc(
        allocator,
        filesystemError(error.FileNotFound),
        .{},
    );
    defer allocator.free(filesystem_error_json);
    try std.testing.expect(std.mem.indexOf(
        u8,
        filesystem_error_json,
        "\"code\":\"ENOENT\"",
    ) != null);
}

fn parseSqliteStatements(
    allocator: std.mem.Allocator,
    value: ?std.json.Value,
) !std.ArrayList(runtime_types.SessionFilesystemSqliteStatement) {
    const array = switch (value orelse return error.MissingField) {
        .array => |item| item,
        else => return error.InvalidField,
    };
    var result: std.ArrayList(runtime_types.SessionFilesystemSqliteStatement) = .empty;
    errdefer result.deinit(allocator);
    try result.ensureTotalCapacity(allocator, array.items.len);
    for (array.items) |item| {
        const object = switch (item) {
            .object => |entry| entry,
            else => return error.InvalidField,
        };
        try validateObjectFields(object, &.{ "queryType", "query", "params" });
        if (object.get("params")) |params| {
            if (params != .object) return error.InvalidField;
        }
        result.appendAssumeCapacity(.{
            .query_type = try parseSqliteQueryType(object.get("queryType")),
            .query = try jsonRequiredString(object, "query"),
            .params = try jsonOptionalObjectValue(object, "params"),
        });
    }
    return result;
}

fn jsonOptionalObjectValue(
    object: std.json.ObjectMap,
    name: []const u8,
) !?std.json.Value {
    return switch (object.get(name) orelse return null) {
        .object => |value| .{ .object = value },
        else => error.InvalidField,
    };
}

fn validStrings(values: []const []const u8) bool {
    for (values) |value| {
        if (!std.unicode.utf8ValidateSlice(value)) return false;
    }
    return true;
}

fn validFilesystemEntries(
    entries: []const runtime_types.SessionFilesystemEntry,
) bool {
    for (entries) |entry| {
        if (!std.unicode.utf8ValidateSlice(entry.name)) return false;
    }
    return true;
}

fn wipeStrings(values: []const []const u8) void {
    for (values) |value| wipeSecret(value);
}

fn wipeFilesystemEntries(
    entries: []const runtime_types.SessionFilesystemEntry,
) void {
    for (entries) |entry| wipeSecret(entry.name);
}

fn wipeOwnedJsonStrings(value: std.json.Value) void {
    switch (value) {
        .string, .number_string => |string| wipeSecret(string),
        .array => |array| for (array.items) |item| wipeOwnedJsonStrings(item),
        .object => |object| {
            var iterator = object.iterator();
            while (iterator.next()) |entry| {
                wipeSecret(entry.key_ptr.*);
                wipeOwnedJsonStrings(entry.value_ptr.*);
            }
        },
        else => {},
    }
}

fn wipeSqliteQueryResult(
    result: runtime_types.SessionFilesystemSqliteQueryResult,
) void {
    wipeStrings(result.columns);
    for (result.rows) |row| wipeOwnedJsonStrings(row);
}

fn wipeSqliteTransactionResult(
    result: runtime_types.SessionFilesystemSqliteTransactionResult,
) void {
    for (result.results) |item| wipeSqliteQueryResult(item);
    if (result.@"error") |failure| wipeSecret(failure.message);
}

test "session filesystem structured results wipe owned strings" {
    const allocator = std.testing.allocator;

    const directory = try std.json.parseFromSlice(
        runtime_types.SessionFilesystemReadDirectoryResult,
        allocator,
        "{\"entries\":[\"directory-secret\"]}",
        .{ .allocate = .alloc_always },
    );
    wipeStrings(directory.value.entries);
    try std.testing.expect(std.mem.allEqual(u8, directory.value.entries[0], 0));
    directory.deinit();

    const typed_directory = try std.json.parseFromSlice(
        runtime_types.SessionFilesystemReadDirectoryWithTypesResult,
        allocator,
        "{\"entries\":[{\"name\":\"typed-secret\",\"entry_type\":\"file\"}]}",
        .{ .allocate = .alloc_always },
    );
    wipeFilesystemEntries(typed_directory.value.entries);
    try std.testing.expect(std.mem.allEqual(
        u8,
        typed_directory.value.entries[0].name,
        0,
    ));
    typed_directory.deinit();

    const query = try std.json.parseFromSlice(
        runtime_types.SessionFilesystemSqliteQueryResult,
        allocator,
        "{\"columns\":[\"column-secret\"],\"rows\":[{\"row-secret\":\"value-secret\"}]}",
        .{ .allocate = .alloc_always },
    );
    wipeSqliteQueryResult(query.value);
    try std.testing.expect(std.mem.allEqual(u8, query.value.columns[0], 0));
    const row = query.value.rows[0].object;
    var row_iterator = row.iterator();
    const row_entry = row_iterator.next().?;
    try std.testing.expect(std.mem.allEqual(u8, row_entry.key_ptr.*, 0));
    try std.testing.expect(std.mem.allEqual(u8, row_entry.value_ptr.string, 0));
    query.deinit();

    const transaction = try std.json.parseFromSlice(
        runtime_types.SessionFilesystemSqliteTransactionResult,
        allocator,
        "{\"results\":[],\"error\":{\"error_class\":\"fatal\",\"message\":\"transaction-secret\"}}",
        .{ .allocate = .alloc_always },
    );
    wipeSqliteTransactionResult(transaction.value);
    try std.testing.expect(std.mem.allEqual(
        u8,
        transaction.value.@"error".?.message,
        0,
    ));
    transaction.deinit();
}

fn validDateTime(value: []const u8) bool {
    if (value.len < 20 or
        value[4] != '-' or
        value[7] != '-' or
        (value[10] != 'T' and value[10] != 't') or
        value[13] != ':' or
        value[16] != ':')
    {
        return false;
    }
    const year = parseDateTimeDigits(value[0..4]) orelse return false;
    const month = parseDateTimeDigits(value[5..7]) orelse return false;
    const day = parseDateTimeDigits(value[8..10]) orelse return false;
    const hour = parseDateTimeDigits(value[11..13]) orelse return false;
    const minute = parseDateTimeDigits(value[14..16]) orelse return false;
    const second = parseDateTimeDigits(value[17..19]) orelse return false;
    if (month < 1 or month > 12 or hour > 23 or minute > 59 or second > 60)
        return false;
    if (day < 1 or day > daysInMonth(year, month)) return false;

    var index: usize = 19;
    if (index < value.len and value[index] == '.') {
        index += 1;
        const fraction_start = index;
        while (index < value.len and std.ascii.isDigit(value[index])) : (index += 1) {}
        if (index == fraction_start) return false;
    }
    if (index >= value.len) return false;
    var offset_minutes: i32 = 0;
    if (value[index] == 'Z' or value[index] == 'z') {
        if (index + 1 != value.len) return false;
    } else {
        if ((value[index] != '+' and value[index] != '-') or index + 6 != value.len)
            return false;
        if (value[index + 3] != ':') return false;
        const offset_hour = parseDateTimeDigits(value[index + 1 .. index + 3]) orelse
            return false;
        const offset_minute = parseDateTimeDigits(value[index + 4 .. index + 6]) orelse
            return false;
        if (offset_hour > 23 or offset_minute > 59) return false;
        offset_minutes = @as(i32, offset_hour) * 60 + offset_minute;
        if (value[index] == '-') offset_minutes = -offset_minutes;
    }
    if (second != 60) return true;

    var utc_year = year;
    var utc_month = month;
    var utc_day = day;
    var utc_minutes = @as(i32, hour) * 60 + minute - offset_minutes;
    if (utc_minutes < 0) {
        utc_minutes += 24 * 60;
        if (utc_day > 1) {
            utc_day -= 1;
        } else {
            if (utc_month > 1) {
                utc_month -= 1;
            } else {
                if (utc_year == 0) return false;
                utc_year -= 1;
                utc_month = 12;
            }
            utc_day = daysInMonth(utc_year, utc_month);
        }
    } else if (utc_minutes >= 24 * 60) {
        utc_minutes -= 24 * 60;
        const month_days = daysInMonth(utc_year, utc_month);
        if (utc_day < month_days) {
            utc_day += 1;
        } else {
            utc_day = 1;
            if (utc_month < 12) {
                utc_month += 1;
            } else {
                if (utc_year == 9999) return false;
                utc_year += 1;
                utc_month = 1;
            }
        }
    }
    return utc_minutes == 23 * 60 + 59 and
        isLeapSecondDate(utc_year, utc_month, utc_day);
}

fn parseDateTimeDigits(value: []const u8) ?u16 {
    var result: u16 = 0;
    for (value) |character| {
        if (!std.ascii.isDigit(character)) return null;
        result = result * 10 + character - '0';
    }
    return result;
}

fn daysInMonth(year: u16, month: u16) u16 {
    return switch (month) {
        1, 3, 5, 7, 8, 10, 12 => 31,
        4, 6, 9, 11 => 30,
        2 => if (year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)) 29 else 28,
        else => unreachable,
    };
}

fn isLeapSecondDate(year: u16, month: u16, day: u16) bool {
    const date = @as(u32, year) * 10_000 + @as(u32, month) * 100 + day;
    return switch (date) {
        19720630,
        19721231,
        19731231,
        19741231,
        19751231,
        19761231,
        19771231,
        19781231,
        19791231,
        19810630,
        19820630,
        19830630,
        19850630,
        19871231,
        19891231,
        19901231,
        19920630,
        19930630,
        19940630,
        19951231,
        19970630,
        19981231,
        20051231,
        20081231,
        20120630,
        20150630,
        20161231,
        => true,
        else => false,
    };
}

test "session filesystem timestamps require RFC 3339 values" {
    for ([_][]const u8{
        "2026-09-13T00:00:00Z",
        "2016-12-31t23:59:60.123z",
        "2017-01-01T01:59:60+02:00",
        "2016-12-31T16:59:60-07:00",
        "2026-09-13T00:00:00+14:00",
        "2026-09-13T00:00:00-07:30",
    }) |value| {
        try std.testing.expect(validDateTime(value));
    }
    for ([_][]const u8{
        "2026-99-99T99:99:99garbageZ",
        "2025-02-29T00:00:00Z",
        "2026-04-31T00:00:00Z",
        "2026-09-13T24:00:00Z",
        "2026-09-13T00:60:00Z",
        "2026-09-13T00:00:61Z",
        "2024-02-29T23:59:60Z",
        "2024-06-30T23:59:60Z",
        "2024-06-30T22:59:60Z",
        "2024-07-01T01:59:60+01:00",
        "2026-09-13T00:00:00.Z",
        "2026-09-13T00:00:00+24:00",
        "2026-09-13T00:00:00+00:60",
        "2026-09-13T00:00:00",
    }) |value| {
        try std.testing.expect(!validDateTime(value));
    }
}

fn validSqliteRows(rows: []const std.json.Value) bool {
    for (rows) |row| {
        if (row != .object) return false;
    }
    return true;
}

fn validSqliteQueryResult(
    result: runtime_types.SessionFilesystemSqliteQueryResult,
) bool {
    return validStrings(result.columns) and validSqliteRows(result.rows);
}

fn validSqliteTransactionResult(
    result: runtime_types.SessionFilesystemSqliteTransactionResult,
    statement_count: usize,
) bool {
    if (result.@"error") |failure| {
        return result.results.len == 0 and
            std.unicode.utf8ValidateSlice(failure.message);
    }
    if (result.results.len != statement_count) return false;
    for (result.results) |item| {
        if (!validSqliteQueryResult(item)) return false;
    }
    return true;
}

fn jsonRequiredString(object: std.json.ObjectMap, name: []const u8) ![]const u8 {
    return switch (object.get(name) orelse return error.MissingField) {
        .string => |value| value,
        else => error.InvalidField,
    };
}

fn jsonRequiredValue(object: std.json.ObjectMap, name: []const u8) !std.json.Value {
    return object.get(name) orelse error.MissingField;
}

fn jsonOptionalString(object: std.json.ObjectMap, name: []const u8) !?[]const u8 {
    return switch (object.get(name) orelse return null) {
        .string => |value| value,
        .null => null,
        else => error.InvalidField,
    };
}

fn jsonRequiredBool(object: std.json.ObjectMap, name: []const u8) !bool {
    return switch (object.get(name) orelse return error.MissingField) {
        .bool => |value| value,
        else => error.InvalidField,
    };
}

fn jsonOptionalBool(object: std.json.ObjectMap, name: []const u8) !?bool {
    return switch (object.get(name) orelse return null) {
        .bool => |value| value,
        .null => null,
        else => error.InvalidField,
    };
}

fn parseHookBase(input: std.json.ObjectMap) !ext.HookBaseInput {
    const timestamp = switch (input.get("timestamp") orelse return error.MissingField) {
        .integer => |value| value,
        else => return error.InvalidField,
    };
    return .{
        .runtime_session_id = try jsonRequiredString(input, "sessionId"),
        .timestamp_ms = timestamp,
        .working_directory = try jsonRequiredString(input, "cwd"),
    };
}

