    var client = Client{
        .allocator = allocator,
        .io = std.testing.io,
        .transport = .{ .fixture = .{
            .reader = &reader,
            .writer = &writer,
            .reader_buffer = &.{},
            .writer_buffer = &.{},
        } },
    };
    defer deinitTestClientRegistries(&client);

    var provider_context = ProviderTokenTestContext{
