        .limited(64),
    );
    defer allocator.free(pid_text);
    const pid = try std.fmt.parseInt(std.posix.pid_t, pid_text, 10);
    try std.testing.expectError(error.ProcessNotFound, std.posix.kill(pid, .CONT));
}

