const GatedSessionRemoval = struct {
    client: *Client,
    ready: *std.Io.Event,
    started: *std.Io.Event,
    record_index: usize,
    session_id: []const u8,
    generation: u64,
    result: ?anyerror = null,

    fn run(context: *@This()) void {
        context.ready.wait(context.client.io) catch |err| {
            context.result = err;
            context.started.set(context.client.io);
            return;
        };
        context.client.removeSessionExpected(
            context.record_index,
            context.session_id,
            context.generation,
        ) catch |err| {
            context.result = err;
        };
        context.started.set(context.client.io);
    }
};

const DrainingSessionRemoval = struct {
    client: *Client,
    started: *std.Io.Event,
    record_index: usize,
    session_id: []const u8,
    generation: u64,
    result: ?anyerror = null,

    fn run(context: *@This()) void {
        const removal = context.client.beginSessionRemoval(
            context.record_index,
            context.session_id,
            context.generation,
        ) catch |err| {
            context.result = err;
            context.started.set(context.client.io);
            return;
        } orelse {
            context.started.set(context.client.io);
            return;
        };
        context.started.set(context.client.io);
        context.client.finishSessionRemoval(removal) catch |err| {
            context.result = err;
        };
    }
};

