    var writer = request_file.writer(std.testing.io, &writer_buffer);
    var client = Client{
        .allocator = allocator,
        .io = std.testing.io,
        .child = null,
        .reader = &reader,
        .writer = &writer,
        .reader_buffer = &.{},
        .writer_buffer = &.{},
    };
    return switch (try client.callImpl(
        .detailed,
        std.json.Value,
        method,
        .{ .sessionId = "missing-session", .requestId = "request-1" },
