    const drained = try client.callRpc(std.json.Value, "test.inspect", .{});
    defer drained.deinit();
    try std.testing.expectEqual(@as(usize, 0), client.abandoned_response_ids.items.len);
}

test "factory combinators propagate nested RPC failures" {
    const callbacks = struct {
        fn task(
            allocator: std.mem.Allocator,
            branch: *factory_types.FactoryBranch,
            _: ?*anyopaque,
        ) !?factory_types.Json {
            return branch.agent(allocator, "fail", .{});
        }

        fn run(
            allocator: std.mem.Allocator,
            context: *factory_types.FactoryContext,
            _: ?*anyopaque,
        ) !?factory_types.Json {
            const results = try context.parallel(allocator, &.{
                .{ .run = task },
            });
            defer factory_types.deinitOptionalJsonSlice(allocator, results);
            return null;
        }
    };

    const allocator = std.testing.allocator;
    const fake_runtime = try fakeRuntimePath(allocator);
    defer allocator.free(fake_runtime);
    var client = try Client.init(allocator, std.testing.io, .{
        .connection = .{ .stdio = .{
            .path = "node",
            .args = &.{ fake_runtime, "--exercise-factory-agent-failure" },
        } },
    });
    defer client.deinit();
    var joined = try client.joinParentSession("factory-session", .{
        .extensions = .{
            .factories = &.{.{
                .meta = .{
                    .name = "fail-agent",
                    .description = "Propagates agent RPC failure.",
                },
                .run = callbacks.run,
            }},
        },
    });
    defer joined.deinit();

    const inspection = try client.callRpc(std.json.Value, "test.inspect", .{});
    defer inspection.deinit();
    const response = inspection.value.object.get("factoryResult").?.object;
    try std.testing.expectEqual(
        @as(i64, -32000),
        response.get("error").?.object.get("code").?.integer,
    );
    try std.testing.expectEqualStrings(
        "FactoryTransportFailure",
        response.get("error").?.object.get("message").?.string,
    );
}

test "custom agent validation precedes lifecycle state and RPC writes" {
    const allocator = std.testing.allocator;
    var client = Client{
        .allocator = allocator,
        .io = undefined,
    };
    const duplicate = &.{
        session_types.CustomAgentConfig{ .name = "same", .prompt = "One." },
        session_types.CustomAgentConfig{ .name = "same", .prompt = "Two." },
    };
    const unknown = &.{
        session_types.CustomAgentConfig{ .name = "known", .prompt = "Known." },
    };

    try std.testing.expectError(
        error.DuplicateCustomAgentName,
        client.createSession(.{ .custom_agents = duplicate }),
    );
    try std.testing.expectError(
        error.DuplicateCustomAgentName,
        client.resumeSession("s1", .{ .custom_agents = duplicate }),
    );
    try std.testing.expectError(
        error.UnknownCustomAgent,
        client.createSession(.{
            .custom_agents = unknown,
            .agent = .{ .custom_agent = "missing" },
        }),
    );
    try std.testing.expectError(
        error.UnknownCustomAgent,
        client.resumeSession("s1", .{
            .custom_agents = unknown,
            .agent = .{ .custom_agent = "missing" },
        }),
    );
    try std.testing.expectError(
        error.UnknownCustomAgent,
        client.joinSession("s1", .{
            .custom_agents = unknown,
            .agent = .{ .custom_agent = "missing" },
        }),
    );
    try std.testing.expectError(
        error.UnknownCustomAgent,
        client.joinParentSession("s1", .{
            .custom_agents = unknown,
            .agent = .{ .custom_agent = "missing" },
        }),
    );
    try std.testing.expectError(
        error.InvalidMcpServer,
        client.createSession(.{
            .custom_agents = &.{.{
                .name = "broken",
                .prompt = "Broken.",
                .mcp_servers = &.{.{
                    .name = "server",
                    .config = .{ .stdio = .{ .command = "" } },
                }},
            }},
        }),
    );
    try std.testing.expectEqual(@as(u64, 1), client.next_request_id);
    try std.testing.expectEqual(@as(usize, 0), client.sessions.items.len);
    try std.testing.expectEqual(@as(usize, 0), client.extension_runtimes.items.len);
    try std.testing.expect(client.pending_extension_runtime == null);
}

