    try expectDeleteTestState(&client, "delete-session", true);

    try writer.interface.flush();
    try expectRequestBodies(allocator, &tmp, &.{
        "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"session.delete\",\"params\":{\"sessionId\":\"delete-session\"}}",
    });
